INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.explicit_information', 'vr', '{"id":"vr.explicit_information","label":"Finding explicit information","description":"Locate and accurately paraphrase details stated in the passage, including dates, lists and comparisons.","lessonRoute":"LearnVRLesson","lessonId":"detail-questions","tip":"Choose an anchor word, find its sentence, then check the surrounding lines before selecting your answer."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.recognising_contradictions', 'vr', '{"id":"vr.recognising_contradictions","label":"Recognising contradictions","description":"Identify passage evidence that directly conflicts with a statement rather than treating missing information as false.","lessonRoute":"LearnVRLesson","lessonId":"tfct","tip":"For False, point to the exact evidence that makes the statement impossible. Missing evidence alone is not enough."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.unsupported_claims', 'vr', '{"id":"vr.unsupported_claims","label":"Spotting unsupported claims","description":"Recognise when the passage leaves a claim unresolved, including unstated comparisons, intentions and historical firsts.","lessonRoute":"LearnVRLesson","lessonId":"outside-knowledge","tip":"Ask whether both the statement and its opposite could fit the passage. If they could, the information is missing."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.inference', 'vr', '{"id":"vr.inference","label":"Drawing supported inferences","description":"Combine passage facts or apply a stated relationship to reach a conclusion without adding outside assumptions.","lessonRoute":"LearnVRLesson","lessonId":"inference","tip":"Write the two passage facts that support your conclusion. Remove any step that needs an unstated assumption."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.qualifiers_and_scope', 'vr', '{"id":"vr.qualifiers_and_scope","label":"Reading qualifiers and scope","description":"Preserve the strength, extent and time frame of claims such as some, most, all, only, may and always.","lessonRoute":"LearnVRLesson","lessonId":"reading-precisely","tip":"Compare the strength of the wording in the question and passage. Some does not prove all, and may does not mean always."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.author_perspective', 'vr', '{"id":"vr.author_perspective","label":"Understanding viewpoints","description":"Distinguish the narrator’s position from reported opinions and identify the tone or stance of a named source.","lessonRoute":"LearnVRLesson","lessonId":"author-opinion","tip":"Track who holds each view. A claim attributed to a researcher is not automatically the narrator’s conclusion."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.main_idea_and_purpose', 'vr', '{"id":"vr.main_idea_and_purpose","label":"Main idea and purpose","description":"Identify the passage’s central message and explain why an example, contrast or detail is included.","lessonRoute":"LearnVRLesson","lessonId":"multiple-choice","tip":"Summarise each paragraph in a few words, then choose the option that captures its role without adding a new claim."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.evaluating_evidence', 'vr', '{"id":"vr.evaluating_evidence","label":"Evaluating evidence","description":"Assess what observations support, challenge or leave uncertain about an explanation, including the impact of new findings.","lessonRoute":"LearnVRLesson","lessonId":"inference","tip":"Separate an observation from the explanation built on it. Ask what the new evidence actually changes, and what it leaves unresolved."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('vr.meaning_in_context', 'vr', '{"id":"vr.meaning_in_context","label":"Meaning in context","description":"Interpret a word, reference or phrase using the surrounding passage rather than its everyday meaning alone.","lessonRoute":"LearnVRLesson","lessonId":"rare-stems","tip":"Read the whole sentence and its neighbours. Substitute the proposed meaning or referent and check that the logic still works."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0814-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0814-4a01-9f11-000000000002'::uuid, 'vr.qualifiers_and_scope', '{"id":"c4a1b8e2-0814-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0814-4a01-9f11-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage states krill ''would make it one of the most abundant animal species on Earth by weight'', which does not claim it is the single most abundant.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"e01cd5df1d6e8005d1e34f68b34f42c24cc0e01916114c9f70cda05d5f2a6789"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0814-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0814-4a01-9f11-000000000003'::uuid, 'vr.evaluating_evidence', '{"id":"c4a1b8e2-0814-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0814-4a01-9f11-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states that ''more recent research has cast doubt on this interpretation'' and that the expected surplus ''does not appear to have materialised consistently''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"a68bf15b404014060d1a8ed3a5317ee6a1bfac12209716af77ad7312c1d6fdd9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0814-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0814-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0814-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0814-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that regulatory limits are set ''substantially below estimated sustainable yields'', directly supporting the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"c8086a70c6ad3c5be21469ca0c1b480458b72c5b7b140742d81d4b5ebb7c48a7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0814-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0814-4a01-9f11-000000000005'::uuid, 'vr.recognising_contradictions', '{"id":"c4a1b8e2-0814-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0814-4a01-9f11-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that juvenile krill ''rely on the algae growing on the underside of pack ice for winter feeding'', which directly contradicts the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"2678ae6715beeb824e5d2d41cb828bf7a84aa427770727c8635bd561ef8923ec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d33ececf-0786-4f4d-b128-bf777682d06a', 'vr', 'practice', 'd33ececf-0786-4f4d-b128-bf777682d06a'::uuid, 'vr.explicit_information', '{"id":"d33ececf-0786-4f4d-b128-bf777682d06a","mode":"practice","parentId":"9c9ef7f7-2fca-486f-b90c-00f78fb134ca","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage distinguishes alignment from propulsion and states that the bacteria swim using flagella.","difficulty":"normal","format":"mc","answer":"Flagella","options":["The passive pull of the magnetosome chain","The oxic-anoxic interface","Greigite released outside the cell","Flagella"],"contentHash":"cf0fd43e6d32a4e76f2dc60117267e106e95e6195554e926ef904f0921ef65fa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:db290e7c-526d-4627-8140-5c4d664fe539', 'vr', 'practice', 'db290e7c-526d-4627-8140-5c4d664fe539'::uuid, 'vr.explicit_information', '{"id":"db290e7c-526d-4627-8140-5c4d664fe539","mode":"practice","parentId":"9c9ef7f7-2fca-486f-b90c-00f78fb134ca","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The second paragraph gives this dimensional reduction as the benefit.","difficulty":"normal","format":"mc","answer":"It reduces movement from a three-dimensional search to one mainly along a field line","options":["It identifies the oxygen concentration without any chemical sensing","It makes every cell swim north regardless of location","It reduces movement from a three-dimensional search to one mainly along a field line","It supplies energy by dissolving the mineral crystals"],"contentHash":"a63df05a84e6915df6f38ffc9a95d082fa8beb7d037c7c25e889276079fb400e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:211bf6d8-c34f-4b8a-aa52-98fd7dd3053a', 'vr', 'practice', '211bf6d8-c34f-4b8a-aa52-98fd7dd3053a'::uuid, 'vr.inference', '{"id":"211bf6d8-c34f-4b8a-aa52-98fd7dd3053a","mode":"practice","parentId":"9c9ef7f7-2fca-486f-b90c-00f78fb134ca","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage separates flagellar propulsion and chemical sensing from the chain''s combined magnetic alignment.","difficulty":"hard","format":"mc","answer":"It could still swim and sense chemicals, but its magnetic alignment would likely be less effective","options":["It would align normally but lose all ability to propel itself","It would become unable to form any iron-bearing crystal","It could still swim and sense chemicals, but its magnetic alignment would likely be less effective","It would necessarily reverse its preferred oxygen level"],"contentHash":"51f9b563a4c49a31ad1c8a57009002af3f252d4f14a116be620839b4adf93cca"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:4cb4979d-4555-4b94-8458-22a0631eae6b', 'vr', 'practice', '4cb4979d-4555-4b94-8458-22a0631eae6b'::uuid, 'vr.explicit_information', '{"id":"4cb4979d-4555-4b94-8458-22a0631eae6b","mode":"practice","parentId":"9c9ef7f7-2fca-486f-b90c-00f78fb134ca","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly says the two systems work together: magnetic fields orient while chemical sensing affects swimming decisions.","difficulty":"normal","format":"mc","answer":"They cooperate, with one providing alignment and the other helping guide behavioural choice","options":["They cooperate, with one providing alignment and the other helping guide behavioural choice","They are alternative systems, and each species possesses only one","They are identical names for movement caused by flagella","They operate only in bacteria living near the magnetic equator"],"contentHash":"a5bc50ba0c3cf25508098270e4c30493f9c18c64a9dbb2618d2207a1f49a7042"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f004-1004-4004-8004-000000000002', 'vr', 'practice', 'c7a1f004-1004-4004-8004-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f004-1004-4004-8004-000000000002","mode":"practice","parentId":"c7a1f004-1004-4004-8004-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the phenomenon ''remained largely outside mainstream physics until the mid-twentieth century, partly because no reliable method existed for generating or observing it under controlled conditions.''","difficulty":"normal","format":"mc","answer":"There was no reliable way to produce or observe the phenomenon under controlled conditions","options":["Physicists did not consider eyewitness accounts to be scientifically credible","There was no reliable way to produce or observe the phenomenon under controlled conditions","Ball lightning had not yet been reported in Western countries","The phenomenon was believed to be a cultural myth"],"contentHash":"f0abc0a6652d7cb6a5617f4ca75e59900cc90899718c03ca1c66359892231520"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f004-1004-4004-8004-000000000003', 'vr', 'practice', 'c7a1f004-1004-4004-8004-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f004-1004-4004-8004-000000000003","mode":"practice","parentId":"c7a1f004-1004-4004-8004-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''The first widely accepted spectroscopic analysis of a natural ball lightning event was published in 2014 by researchers at Northwest Normal University in Lanzhou, China.''","difficulty":"normal","format":"mc","answer":"It was the first widely accepted spectroscopic analysis of a natural ball lightning event","options":["It was the first time ball lightning had been created in a laboratory","It was the first widely accepted spectroscopic analysis of a natural ball lightning event","It disproved the oxidising nanoparticle hypothesis","It confirmed that ball lightning contains no silicon"],"contentHash":"ef7a4037e057cb9f4ddb7fc1f41c484e54ae3215cf1cf5b065673cde6454142b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f004-1004-4004-8004-000000000004', 'vr', 'practice', 'c7a1f004-1004-4004-8004-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f004-1004-4004-8004-000000000004","mode":"practice","parentId":"c7a1f004-1004-4004-8004-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":["vr.evaluating_evidence"],"confidence":"high","rationale":"The passage explicitly states the hypothesis ''does not readily explain reports of ball lightning appearing inside buildings, sometimes passing through closed windows''.","difficulty":"normal","format":"mc","answer":"Ball lightning appearing inside a building and passing through a closed window","options":["A typical duration of a few seconds","A sulphurous odour reported after the phenomenon ends","Ball lightning appearing inside a building and passing through a closed window","Minimal heat sensation reported by nearby observers"],"contentHash":"97691b2de01a11a622bded4c370eeede165d15a046bfbdec52ce8047e516c34b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f004-1004-4004-8004-000000000005', 'vr', 'practice', 'c7a1f004-1004-4004-8004-000000000005'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1f004-1004-4004-8004-000000000005","mode":"practice","parentId":"c7a1f004-1004-4004-8004-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the hypothesis struggles to explain ball lightning ''persisting for durations well beyond a minute''.","difficulty":"hard","format":"mc","answer":"It would present an additional challenge, as such long durations are already noted as difficult for the hypothesis to explain","options":["It would confirm the hypothesis","It would have no effect, as duration is not relevant to the hypothesis","It would present an additional challenge, as such long durations are already noted as difficult for the hypothesis to explain","It would disprove all competing hypotheses"],"contentHash":"d1f82a10c6d2a2a7fec0ddc4a2c53b07c20b342ee8fc404d286d33a268cbb22f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0809-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0809-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0809-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0809-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states gill rakers ''trap plankton while allowing water to exit through the gill slits''.","difficulty":"normal","format":"mc","answer":"To trap plankton while allowing water to pass through the gill slits","options":["To produce enzymes that digest plankton in the mouth","To trap plankton while allowing water to pass through the gill slits","To detect the electrical signals emitted by prey","To filter salt from seawater before it enters the digestive tract"],"contentHash":"671fe3bd888fce31bdcfe9f4a3d26c30b78388bea969215a741b59827b7311cb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0809-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0809-4a01-9f11-000000000003'::uuid, 'vr.evaluating_evidence', '{"id":"c4a1b8e2-0809-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0809-4a01-9f11-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states satellite tracking showed individuals ''migrate over considerable distances'' and ''continue to feed'', leading to general rejection of the earlier hibernation hypothesis.","difficulty":"normal","format":"mc","answer":"It revealed that basking sharks migrate long distances and continue feeding in winter","options":["It confirmed the earlier hypothesis that basking sharks hibernate in deep water","It revealed that basking sharks migrate long distances and continue feeding in winter","It showed that basking sharks remain in the same coastal areas throughout the year","It demonstrated that only juvenile basking sharks migrate in winter"],"contentHash":"efa4d5b4fa4206caa5adabef47bc11bd814484986a7f43c5a1ccf9d89373a8ba"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0809-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0809-4a01-9f11-000000000004'::uuid, 'vr.meaning_in_context', '{"id":"c4a1b8e2-0809-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0809-4a01-9f11-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the hibernation hypothesis was widely believed ''until the late 1990s'', and ''subsequently'' satellite tracking showed otherwise — that is, after the late 1990s.","difficulty":"hard","format":"mc","answer":"After the late 1990s, when the hibernation hypothesis was already established","options":["Before the late 1990s, when the hibernation hypothesis was widely accepted","During the late 1990s, when satellite tracking was first developed","After the late 1990s, when the hibernation hypothesis was already established","During the eighteenth and nineteenth centuries of the fishing era"],"contentHash":"e32c7ab478d1a690bb24d1ea9bffb8bcb78c0e2f4b65ef6130fa52c096ab8e46"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0809-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0809-4a01-9f11-000000000005'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0809-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0809-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states they were ''extensively fished...","difficulty":"normal","format":"mc","answer":"The large oil content of basking shark livers made them a commercially valuable catch","options":["The flesh of basking sharks was a highly valued delicacy in European markets","The large oil content of basking shark livers made them a commercially valuable catch","Basking sharks were commonly caught incidentally while fishing for other species","The cartilage of basking sharks was used in traditional medicinal preparations"],"contentHash":"2bbff078aa2bd4e0741b0b926f6755590df511ed0ac7b4270c36df706bfea050"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1008-4a08-9a08-000000000002', 'vr', 'practice', 'c1d2e3f4-1008-4a08-9a08-000000000002'::uuid, 'vr.main_idea_and_purpose', '{"id":"c1d2e3f4-1008-4a08-9a08-000000000002","mode":"practice","parentId":"c1d2e3f4-1008-4a08-9a08-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The paragraph opens with ''Some bioluminescence is produced by symbiotic bacteria rather than by the host animal itself'', and the Hawaiian bobtail squid is introduced with ''for instance'' — marking it as an illustrative example of that claim.","difficulty":"normal","format":"mc","answer":"To illustrate a case in which bioluminescence is produced by bacteria rather than by the animal itself","options":["To demonstrate that all deep-sea bioluminescence depends on symbiotic bacteria","To illustrate a case in which bioluminescence is produced by bacteria rather than by the animal itself","To prove that quorum sensing is unique to marine bacteria","To argue that counter-illumination is a less effective strategy than burglar alarm defence"],"contentHash":"55311673c19239f07a8cd0be7bdd6ae40f24f7ed62357fb0e9b5205801ed28c6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1008-4a08-9a08-000000000003', 'vr', 'practice', 'c1d2e3f4-1008-4a08-9a08-000000000003'::uuid, 'vr.explicit_information', '{"id":"c1d2e3f4-1008-4a08-9a08-000000000003","mode":"practice","parentId":"c1d2e3f4-1008-4a08-9a08-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the strategy as ''sudden flashes or clouds of luminescent material to startle or distract attackers'' where ''the flash may also attract larger predators that then target the attacker''.","difficulty":"normal","format":"mc","answer":"A flash or cloud of luminescent material that startles an attacker and may also attract larger predators","options":["A strategy in which prey emit light to confuse predators by matching downwelling light","A flash or cloud of luminescent material that startles an attacker and may also attract larger predators","The use of light-producing organs to attract mates from a distance","A continuous glow that illuminates the seafloor for foraging"],"contentHash":"163160e0b128dfc9f9c79701112c9531a4e61626c7ba3d27b310ce2b0d62f4d9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1008-4a08-9a08-000000000004', 'vr', 'practice', 'c1d2e3f4-1008-4a08-9a08-000000000004'::uuid, 'vr.evaluating_evidence', '{"id":"c1d2e3f4-1008-4a08-9a08-000000000004","mode":"practice","parentId":"c1d2e3f4-1008-4a08-9a08-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the ''specific molecular variants differ between lineages, suggesting that bioluminescence has evolved independently many times''.","difficulty":"hard","format":"mc","answer":"It would weaken the suggestion that bioluminescence has evolved independently many times","options":["It would have no effect, since the passage does not address molecular structure","It would strengthen the claim that bioluminescence is restricted to deep-sea species","It would prove that all bioluminescent organisms share a common ancestor","It would weaken the suggestion that bioluminescence has evolved independently many times"],"contentHash":"a6975379b573ed150aefd5398ac784de026dc9eb85ad4d9ce1fe5e5a2d65e5ac"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1008-4a08-9a08-000000000005', 'vr', 'practice', 'c1d2e3f4-1008-4a08-9a08-000000000005'::uuid, 'vr.inference', '{"id":"c1d2e3f4-1008-4a08-9a08-000000000005","mode":"practice","parentId":"c1d2e3f4-1008-4a08-9a08-000000000001","primarySkillId":"vr.inference","secondarySkillIds":["vr.qualifiers_and_scope"],"confidence":"high","rationale":"The passage states that ''by 1,000 metres virtually no solar light remains'' and that organisms at those depths ''produce their own light through bioluminescence''.","difficulty":"hard","format":"mc","answer":"Below 1,000 metres, bioluminescence is effectively the only significant source of light in the water column","options":["Below 1,000 metres, bioluminescence is effectively the only significant source of light in the water column","Anglerfish use counter-illumination to conceal themselves from predators below","Quorum sensing allows bacteria to produce light efficiently even at very low population densities","All luciferase enzymes are chemically identical across different species"],"contentHash":"c0b4720410939f55b02a2379094aeba2238be23ab4b4ee864e9add26542684f5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d26f137c-d687-41e6-8cef-be04c3b5c366', 'vr', 'practice', 'd26f137c-d687-41e6-8cef-be04c3b5c366'::uuid, 'vr.recognising_contradictions', '{"id":"d26f137c-d687-41e6-8cef-be04c3b5c366","mode":"practice","parentId":"2ce4672d-1921-4669-bfe8-8228e7d280d1","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly says a solid panel diverts much of the airflow around itself, while an open mesh lets more fog pass through its collecting area.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"4549131bcd64cfc9518a2df3f95d42fc34f9bf7066af107de235274354ff07e7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d66695e8-722b-485d-8bbb-adcd35f4eb7a', 'vr', 'practice', 'd66695e8-722b-485d-8bbb-adcd35f4eb7a'::uuid, 'vr.explicit_information', '{"id":"d66695e8-722b-485d-8bbb-adcd35f4eb7a","mode":"practice","parentId":"2ce4672d-1921-4669-bfe8-8228e7d280d1","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly lists strand thickness, the size of the gaps between strands, and the coating on the strands as the three features examined.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"0fe8c173f13cb0367938cfed9bbbf5942671af7d14810ae791cc261289877431"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:913ef3de-1793-473a-97d1-59cc056be21a', 'vr', 'practice', '913ef3de-1793-473a-97d1-59cc056be21a'::uuid, 'vr.unsupported_claims', '{"id":"913ef3de-1793-473a-97d1-59cc056be21a","mode":"practice","parentId":"2ce4672d-1921-4669-bfe8-8228e7d280d1","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"Several meshes in series are discussed as a possible way to intercept water left in the airflow.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"225cd7421787c7e6ee59e803c9dd2c0de319f21498ecaa045901a8df1f498eec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:717397ca-99be-4ced-9ad8-4d3f1fbfbd83', 'vr', 'practice', '717397ca-99be-4ced-9ad8-4d3f1fbfbd83'::uuid, 'vr.explicit_information', '{"id":"717397ca-99be-4ced-9ad8-4d3f1fbfbd83","mode":"practice","parentId":"2ce4672d-1921-4669-bfe8-8228e7d280d1","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"It explicitly states that a mesh cannot collect droplets that never reach it, so improved design does not remove the dependence on local fog and wind.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"65d78c89f5d764aac287c91cf0406456d76fe7283405be0a4176729e82581863"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f015-1015-4015-8015-000000000002', 'vr', 'practice', 'c7a1f015-1015-4015-8015-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f015-1015-4015-8015-000000000002","mode":"practice","parentId":"c7a1f015-1015-4015-8015-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that cephalopods can match visual backgrounds with striking speed and effectiveness, and notes that ''cephalopods are, by all available evidence, colour-blind'', presenting this as a striking paradox.","difficulty":"normal","format":"mc","answer":"It occurs despite cephalopods being colour-blind","options":["It works in darkness as well as in light","It occurs despite cephalopods being colour-blind","It is slower than the camouflage of other animals","It relies on a single type of skin cell"],"contentHash":"77a4aae02e5573497148f586e7deaea7adeb86cf21a04218fcf41b277de28e36"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f015-1015-4015-8015-000000000003', 'vr', 'practice', 'c7a1f015-1015-4015-8015-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f015-1015-4015-8015-000000000003","mode":"practice","parentId":"c7a1f015-1015-4015-8015-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that chromatophores are ''pigment-filled sacs surrounded by radial muscles.","difficulty":"hard","format":"mc","answer":"Displaying or hiding pigment through the contraction of radial muscles","options":["Reflecting ambient light to produce iridescent appearances","Scattering light to produce white appearances","Displaying or hiding pigment through the contraction of radial muscles","Detecting light wavelengths directly through opsins"],"contentHash":"cbb51b347049c4e7d21567fcb3cd8a504af8b401431c62938ae1f36267551fec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f015-1015-4015-8015-000000000004', 'vr', 'practice', 'c7a1f015-1015-4015-8015-000000000004'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1f015-1015-4015-8015-000000000004","mode":"practice","parentId":"c7a1f015-1015-4015-8015-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Independent experimental work has shown that isolated patches of cephalopod skin do respond to light, but whether this constitutes true colour detection remains contested.''","difficulty":"normal","format":"mc","answer":"Experimental work supports skin light-sensitivity, but whether it involves true colour detection remains contested","options":["It has been conclusively proven","It has been conclusively disproven","Experimental work supports skin light-sensitivity, but whether it involves true colour detection remains contested","It has not yet been tested experimentally"],"contentHash":"ad8886b10c739154d7f666d12b966d2d8f1e42f58501c1edf8e5d90b5980f3b3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f015-1015-4015-8015-000000000005', 'vr', 'practice', 'c7a1f015-1015-4015-8015-000000000005'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f015-1015-4015-8015-000000000005","mode":"practice","parentId":"c7a1f015-1015-4015-8015-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces the behavioural hypothesis as an ''alternative'' and explicitly notes it ''would not require true colour vision but would rely on exceptional sensitivity to brightness contrast and pattern.''","difficulty":"normal","format":"mc","answer":"To present an alternative explanation that does not require the skin to detect colour directly","options":["To disprove the opsin hypothesis","To present an alternative explanation that does not require the skin to detect colour directly","To argue that cuttlefish behaviour is fundamentally different from octopus behaviour","To demonstrate that cephalopods are aware of their own camouflage"],"contentHash":"350e3fdb7876889ee71e9c829dfc8db8637aee07208f7fe32fcc23c73843352d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7b', 'vr', 'practice', '6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7b'::uuid, 'vr.explicit_information', '{"id":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7b","mode":"practice","parentId":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states cochineal was ''second in value only to silver'', meaning silver was the more valuable export.","difficulty":"normal","format":"mc","answer":"Silver","options":["Cochineal dye","Silver","Prickly pear cactus","Red military uniforms"],"contentHash":"5147676aa106ede50ae3cc90d2c5e3658bdac3d25f7c64ff074984cedac51bb2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7c', 'vr', 'practice', '6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7c'::uuid, 'vr.meaning_in_context', '{"id":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7c","mode":"practice","parentId":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7a","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"medium","rationale":"The contrast ''not by espionage but by geography'' indicates the monopoly fell because insects could be transplanted to other colonial territories, shifting emphasis from stealing secrets to relocating living insects.","difficulty":"hard","format":"mc","answer":"Because the smuggling succeeded by exploiting colonial territorial reach rather than through covert information-gathering","options":["Because Thiéry de Menonville did not conceal his activities from Spanish officials","Because the smuggling succeeded by exploiting colonial territorial reach rather than through covert information-gathering","Because the Spanish authorities voluntarily released the insects to Saint-Domingue","Because Oaxaca was geographically isolated from other Spanish territories"],"contentHash":"28d7ab659ff64e932dc23c9a6b05b7fc651c2eb0dc6c09bbe3694939016e2891"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7d', 'vr', 'practice', '6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7d'::uuid, 'vr.explicit_information', '{"id":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7d","mode":"practice","parentId":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Indigenous peoples produced ''textiles of an intense red that European dyers could not at the time replicate'', directly supporting this inference.","difficulty":"normal","format":"mc","answer":"They were unable to produce a red of equivalent brilliance","options":["They used insect-based red dyes of comparable intensity","They were unable to produce a red of equivalent brilliance","They traded regularly with Mesoamerican producers","They imported cochineal through intermediaries"],"contentHash":"7ed78fce1073b035720066513a0980abbcad17543d67442d0af5dafde21b51ae"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7e', 'vr', 'practice', '6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7e'::uuid, 'vr.explicit_information', '{"id":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7e","mode":"practice","parentId":"6c1d64f5-0b7a-4d4e-c8f9-5a9b1d4e6f7a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the industry ''collapsed abruptly after 1856, when the discovery of synthetic aniline dyes provided cheaper and more consistent reds.''","difficulty":"normal","format":"mc","answer":"The discovery of synthetic aniline dyes","options":["The loss of Spain''s colonial territories","The discovery of synthetic aniline dyes","A disease outbreak that killed the insects","The decline of red military uniforms"],"contentHash":"aa9c600b62bcc0bcb18d34b16caacc16724501ecc5c5092f8b0bb2111834760a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:8786f7cc-0b3b-4c9c-b714-796df0d77baf', 'vr', 'practice', '8786f7cc-0b3b-4c9c-b714-796df0d77baf'::uuid, 'vr.explicit_information', '{"id":"8786f7cc-0b3b-4c9c-b714-796df0d77baf","mode":"practice","parentId":"a9d469f6-033a-430e-a420-ad3753f65b7b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The opening paragraph states that the concave surface concentrated reflected sound at a focal point.","difficulty":"normal","format":"mc","answer":"It reflected sound towards a focal point","options":["It converted sound directly into radio waves","It reflected sound towards a focal point","It electronically amplified every coastal noise","It forced aircraft to fly along a predictable route"],"contentHash":"70a00b028f5cc0a351b0b2a4c00312434c44cfa1c8baf44d6b7808e9df951c03"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c0080d87-2be9-4cfc-ad7c-20e62e928395', 'vr', 'practice', 'c0080d87-2be9-4cfc-ad7c-20e62e928395'::uuid, 'vr.explicit_information', '{"id":"c0080d87-2be9-4cfc-ad7c-20e62e928395","mode":"practice","parentId":"a9d469f6-033a-430e-a420-ad3753f65b7b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"Faster aircraft shortened the response time after detection, directly reducing the value of the same range.","difficulty":"normal","format":"mc","answer":"Aircraft crossed the remaining distance more quickly","options":["Concrete became unable to reflect sound","Aircraft crossed the remaining distance more quickly","Coastal waves stopped producing background noise","Operators ceased to use trained hearing"],"contentHash":"1054793957062e8e1988901884bb736f7b4d354475e70c813e89719d88719384"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2dd9c15a-77f7-4d63-b452-ac713d9519fe', 'vr', 'practice', '2dd9c15a-77f7-4d63-b452-ac713d9519fe'::uuid, 'vr.inference', '{"id":"2dd9c15a-77f7-4d63-b452-ac713d9519fe","mode":"practice","parentId":"a9d469f6-033a-430e-a420-ad3753f65b7b","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"A larger collector might gather more sound and extend detection, addressing the other three aims.","difficulty":"hard","format":"mc","answer":"The decreasing response time caused by faster aircraft","options":["The decreasing response time caused by faster aircraft","The need to gather more sound from a target direction","The difficulty of detecting relatively faint engine noise","The wish to obtain warning from a greater distance"],"contentHash":"e6ed72df9f7781c5389492000a6c88c9e756b3a24b8c74e21071f828c8caa901"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:53a0a9d8-89de-4bc4-b58a-9b86213ff6f9', 'vr', 'practice', '53a0a9d8-89de-4bc4-b58a-9b86213ff6f9'::uuid, 'vr.main_idea_and_purpose', '{"id":"53a0a9d8-89de-4bc4-b58a-9b86213ff6f9","mode":"practice","parentId":"a9d469f6-033a-430e-a420-ad3753f65b7b","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The conclusion distinguishes passive acoustic detection from radar''s transmitted radio waves.","difficulty":"normal","format":"mc","answer":"They detected passively through sound and belonged to a distinct technical approach","options":["They were built only after radar had entered routine service","They transmitted stronger radio signals than early radar sets","They detected passively through sound and belonged to a distinct technical approach","They were intended exclusively to guide ships rather than detect aircraft"],"contentHash":"b912b7caeb6d0ba5f515cfd30e77e5e981c8d3c227d29fa725fd35fe1ae36de5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0602-4a02-9d02-000000000201', 'vr', 'practice', 'c7a1e4b2-0602-4a02-9d02-000000000201'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1e4b2-0602-4a02-9d02-000000000201","mode":"practice","parentId":"c7a1e4b2-0602-4a02-9d02-000000000002","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage describes cuneiform as ''among the earliest known forms of written expression'', which permits the existence of other equally early or earlier scripts.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"eb9225da5e319fc7530dd6d3b061c360554c3efd374f19e2d35a4cdd92bfc4dd"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0602-4a02-9d02-000000000202', 'vr', 'practice', 'c7a1e4b2-0602-4a02-9d02-000000000202'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0602-4a02-9d02-000000000202","mode":"practice","parentId":"c7a1e4b2-0602-4a02-9d02-000000000002","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that kiln-firing rendered tablets ''substantially more resistant to damage'' than sun-drying, which contradicts the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"4fe3eb821604fed091c7c2f607d789a47507e34032e6048ef653e53e5c295644"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0602-4a02-9d02-000000000203', 'vr', 'practice', 'c7a1e4b2-0602-4a02-9d02-000000000203'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0602-4a02-9d02-000000000203","mode":"practice","parentId":"c7a1e4b2-0602-4a02-9d02-000000000002","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states early cuneiform was used ''predominantly for administrative purposes'' and that literary, legal, and scientific uses came ''only later'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"a405096e379b211b7609464d7fc7cde749d15e44e13353086d23c1ca8a94aa8c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0602-4a02-9d02-000000000204', 'vr', 'practice', 'c7a1e4b2-0602-4a02-9d02-000000000204'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0602-4a02-9d02-000000000204","mode":"practice","parentId":"c7a1e4b2-0602-4a02-9d02-000000000002","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that decipherment ''rested heavily on trilingual inscriptions'' such as the Behistun Inscription, which allowed scholars to match texts in different languages to reconstruct sign values.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"eb6a852f25fe9e41f181ef5eccfbb753c75c61fdff51a5e937223ae053502ab8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
