INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2fb8771b-ad3d-413b-af0c-fa6b585ed564', 'vr', 'practice', '2fb8771b-ad3d-413b-af0c-fa6b585ed564'::uuid, 'vr.unsupported_claims', '{"id":"2fb8771b-ad3d-413b-af0c-fa6b585ed564","mode":"practice","parentId":"cd520cf5-93e8-452f-847f-d0775a298a56","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The text says timber burned but does not identify who lit the fire.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"5da4f9cb4e9992fbb2845588ac184f20149d6b373005465a553a80ccebd670a6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:618fbfcf-eb85-4baf-a831-1a1c5d13ee57', 'vr', 'practice', '618fbfcf-eb85-4baf-a831-1a1c5d13ee57'::uuid, 'vr.evaluating_evidence', '{"id":"618fbfcf-eb85-4baf-a831-1a1c5d13ee57","mode":"practice","parentId":"cd520cf5-93e8-452f-847f-d0775a298a56","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The cavities show that timber once passed through the wall and help explain how burning fused the rock.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"9726f4591204a386a9de5638b57456ffee665dc573f76c2075e364d5c1474631"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0610-4a10-9d10-000000001001', 'vr', 'practice', 'c7a1e4b2-0610-4a10-9d10-000000001001'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0610-4a10-9d10-000000001001","mode":"practice","parentId":"c7a1e4b2-0610-4a10-9d10-000000000010","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly explains that during glacial periods, oxygen-16-rich evaporated water ''is locked up in continental ice sheets, leaving the ocean relatively enriched in oxygen-18''.","difficulty":"normal","format":"mc","answer":"Lighter oxygen-16 is preferentially locked up in continental ice, leaving the ocean enriched in oxygen-18","options":["Foraminifera deliberately select heavier isotopes during glacial periods","Lighter oxygen-16 is preferentially locked up in continental ice, leaving the ocean enriched in oxygen-18","Glacial periods increase the total amount of oxygen-18 in the Earth''s crust","Cold water absorbs more oxygen-18 from the atmosphere"],"contentHash":"d2010eeb97690166a7710d4305005614608208a8c9d0d2acccf11d05dce77af9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0610-4a10-9d10-000000001002', 'vr', 'practice', 'c7a1e4b2-0610-4a10-9d10-000000001002'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0610-4a10-9d10-000000001002","mode":"practice","parentId":"c7a1e4b2-0610-4a10-9d10-000000000010","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that comparing species of both types ''allows scientists to distinguish vertical differences in ancient oceans'' — directly capturing the distinction between surface and deep conditions.","difficulty":"normal","format":"mc","answer":"To reconstruct differences in conditions between the ocean surface and its depths","options":["To determine the age of sediment layers","To identify new species of foram","To reconstruct differences in conditions between the ocean surface and its depths","To correct for measurement errors in isotopic analysis"],"contentHash":"acb6ab7199d9f8ed3b4aab6c2937cf40b7f871858c4378ef54f77eb874953f01"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0610-4a10-9d10-000000001003', 'vr', 'practice', 'c7a1e4b2-0610-4a10-9d10-000000001003'::uuid, 'vr.meaning_in_context', '{"id":"c7a1e4b2-0610-4a10-9d10-000000001003","mode":"practice","parentId":"c7a1e4b2-0610-4a10-9d10-000000000010","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''certain foram species modify the chemistry of the water immediately surrounding their shells as they grow, a phenomenon known as the vital effect, which can introduce biases''.","difficulty":"normal","format":"mc","answer":"A bias arising because some foram species modify the chemistry of surrounding water during shell growth","options":["The process by which forams preferentially absorb oxygen-18","A bias arising because some foram species modify the chemistry of surrounding water during shell growth","The tendency of deep-sea currents to distort foram distributions","The effect of glacial ice sheets on seawater composition"],"contentHash":"db60f56f6d54b7b525a3ccce0f59d339a39e43b2cbb7a0a9c4054efe976060e6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0610-4a10-9d10-000000001004', 'vr', 'practice', 'c7a1e4b2-0610-4a10-9d10-000000001004'::uuid, 'vr.inference', '{"id":"c7a1e4b2-0610-4a10-9d10-000000001004","mode":"practice","parentId":"c7a1e4b2-0610-4a10-9d10-000000000010","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage identifies the vital effect as a source of bias in isotopic measurement that ''must be corrected for'', and earlier identifies isotopic measurements as the basis for reconstructing temperature, salinity, and ice volume.","difficulty":"hard","format":"mc","answer":"The accuracy of temperature and ice-volume reconstructions from foram isotopes","options":["The ability to identify individual foram species from sediment cores","The accuracy of temperature and ice-volume reconstructions from foram isotopes","The durability of foram shells during burial","The ratio of planktonic to benthic forams in ancient sediments"],"contentHash":"f15cb433ca92c622dc4e567d6f3cdb1732765f916fbbd583f310cda435384199"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0003-4003-8003-000000000002', 'vr', 'practice', 'f1a2b3c4-0003-4003-8003-000000000002'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0003-4003-8003-000000000002","mode":"practice","parentId":"f1a2b3c4-0003-4003-8003-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Svartvik''s analysis ''contributed to the posthumous pardon of Evans, who had been executed in 1950''.","difficulty":"normal","format":"mc","answer":"Evans received a posthumous pardon after having been executed in 1950","options":["Evans was acquitted at his original trial in 1968","Evans received a posthumous pardon after having been executed in 1950","Svartvik identified the true author of the confession","The confession was determined to be partially authentic"],"contentHash":"21d25a70bd716b3903de69258162ed97dbd985a3df24e83fe5502d3eebab3c20"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0003-4003-8003-000000000003', 'vr', 'practice', 'f1a2b3c4-0003-4003-8003-000000000003'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0003-4003-8003-000000000003","mode":"practice","parentId":"f1a2b3c4-0003-4003-8003-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists ''sentence length distribution, function-word frequency, and idiosyncratic spelling or punctuation'' as features of authorship attribution.","difficulty":"normal","format":"mc","answer":"Regional dialect variation","options":["Sentence length distribution","Frequency of function words","Regional dialect variation","Idiosyncratic spelling"],"contentHash":"04c1161a8e1b9b9bd623b5ef65ee86c9dc092875a1beee2554f8e45db26d892a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0003-4003-8003-000000000004', 'vr', 'practice', 'f1a2b3c4-0003-4003-8003-000000000004'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0003-4003-8003-000000000004","mode":"practice","parentId":"f1a2b3c4-0003-4003-8003-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''most courts require corroborating evidence before admitting either type'' of voice identification.","difficulty":"normal","format":"mc","answer":"Courts generally require supporting evidence before admitting it","options":["It is rejected by most courts as unreliable","Acoustic analysis alone is sufficient for conviction","Courts generally require supporting evidence before admitting it","It has replaced traditional forensic linguistics in many jurisdictions"],"contentHash":"6ff4226c3414f68cd6f9e8f96617b6900dbd49e768496e5d4f49818814bdf0ee"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0003-4003-8003-000000000005', 'vr', 'practice', 'f1a2b3c4-0003-4003-8003-000000000005'::uuid, 'vr.main_idea_and_purpose', '{"id":"f1a2b3c4-0003-4003-8003-000000000005","mode":"practice","parentId":"f1a2b3c4-0003-4003-8003-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes David recognising ''characteristic phrases'' and alerting authorities, which shows how familiarity with an individual''s writing style can aid identification.","difficulty":"normal","format":"mc","answer":"To illustrate how personal familiarity with a writer''s style can assist linguistic identification","options":["To criticise the reliability of forensic linguistic evidence","To illustrate how personal familiarity with a writer''s style can assist linguistic identification","To show that forensic linguists often rely on family testimony","To demonstrate that the Unabomber case was solved without expert analysis"],"contentHash":"27bd6bdde73e9bd3a0e7950bf72bb6751741e7bd90a657bd113a446cda64dd50"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f017-1017-4017-8017-000000000002', 'vr', 'practice', 'c7a1f017-1017-4017-8017-000000000002'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1f017-1017-4017-8017-000000000002","mode":"practice","parentId":"c7a1f017-1017-4017-8017-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage describes the British Columbia and southern Alaska glass sponge reefs as rising from the seabed ''in water as shallow as 90 metres'', showing some glass sponges live shallower than 200 metres.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"3e6a9e22f6b59106c694bffbb911e02ba6421fc043d1f90123fd3e9f906ee603"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
