INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:1b6c19e0-5a2f-4c9d-b3e4-0f4a6c9d1e2d', 'vr', 'practice', '1b6c19e0-5a2f-4c9d-b3e4-0f4a6c9d1e2d'::uuid, 'vr.explicit_information', '{"id":"1b6c19e0-5a2f-4c9d-b3e4-0f4a6c9d1e2d","mode":"practice","parentId":"1b6c19e0-5a2f-4c9d-b3e4-0f4a6c9d1e2f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Several of the most important oil-bearing basins in the Pacific were dated largely through radiolarian analysis in the late twentieth century'', directly supporting the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"ffe7cdc4093468936a9ca5080fcede2f25f32cb3e8767daa65640179eec8af16"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3e4c3304-0c69-43c7-adb3-b396641c5da2', 'vr', 'practice', '3e4c3304-0c69-43c7-adb3-b396641c5da2'::uuid, 'vr.explicit_information', '{"id":"3e4c3304-0c69-43c7-adb3-b396641c5da2","mode":"practice","parentId":"5481075c-3b52-4edf-9b93-ff6c31daf0be","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly calls the mattang a schematic teaching device for general swell interaction.","difficulty":"normal","format":"mc","answer":"To teach general patterns of swell interaction around an island","options":["To teach general patterns of swell interaction around an island","To show every atoll in the Marshall Islands at a fixed scale","To record the daily position of a canoe during a voyage","To provide a code that any navigator could read without instruction"],"contentHash":"ce1a9b9112fc9617f3e7d2121d3b780c7ceb2c36af4a48d8431ce3c69444f5bb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:faf6ee57-b8ac-490b-a2ad-89a01234d112', 'vr', 'practice', 'faf6ee57-b8ac-490b-a2ad-89a01234d112'::uuid, 'vr.explicit_information', '{"id":"faf6ee57-b8ac-490b-a2ad-89a01234d112","mode":"practice","parentId":"5481075c-3b52-4edf-9b93-ff6c31daf0be","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The first paragraph states that atolls alter swells and that this can be felt through the canoe.","difficulty":"normal","format":"mc","answer":"The island altered swells and therefore changed the canoe''s motion","options":["Shell markers floated from the island towards the canoe","The island altered swells and therefore changed the canoe''s motion","The chart predicted the island''s appearance from the stars alone","The navigator measured the island''s coastline against a fixed scale"],"contentHash":"16c9afabbda8a99632c69bda960072d72d89823a8a24ee03cd90732c81c57f32"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:4c7e33e9-a75d-4970-b3f3-31ae28df59d2', 'vr', 'practice', '4c7e33e9-a75d-4970-b3f3-31ae28df59d2'::uuid, 'vr.inference', '{"id":"4c7e33e9-a75d-4970-b3f3-31ae28df59d2","mode":"practice","parentId":"5481075c-3b52-4edf-9b93-ff6c31daf0be","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The chart was studied during apprenticeship, then its principles were recalled while the navigator read the sea directly.","difficulty":"hard","format":"mc","answer":"Their value depended on learning that could later be applied without consulting the object","options":["Their makers considered ocean swells too changeable to be represented","They were ceremonial objects with no navigational relevance","Their value depended on learning that could later be applied without consulting the object","Navigators lacked a safe way to carry lightweight objects in canoes"],"contentHash":"b833a94beae2c3dcac6bbc46f27afbfeb98e610215c10da740ef131c2daaa167"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3348272b-1c70-4654-ad98-e36eb6fb6181', 'vr', 'practice', '3348272b-1c70-4654-ad98-e36eb6fb6181'::uuid, 'vr.main_idea_and_purpose', '{"id":"3348272b-1c70-4654-ad98-e36eb6fb6181","mode":"practice","parentId":"5481075c-3b52-4edf-9b93-ff6c31daf0be","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The final paragraph contrasts a self-contained museum object with a practice involving instruction, memory and bodily attention.","difficulty":"normal","format":"mc","answer":"A chart may look self-contained although its use relied on teaching, memory and bodily skill","options":["A chart may look fragile although it was originally made from metal","A chart may appear abstract although every line reproduced a measured coastline","A chart may seem ancient although all surviving examples were made recently for tourists","A chart may look self-contained although its use relied on teaching, memory and bodily skill"],"contentHash":"65f1e146df8ee8b7ff806350109be7fa2bca05691ce825c31795a4548815d45e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f001-1001-4001-8001-000000000002', 'vr', 'practice', 'c7a1f001-1001-4001-8001-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f001-1001-4001-8001-000000000002","mode":"practice","parentId":"c7a1f001-1001-4001-8001-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''modern cement, which is designed to resist chemical reactions with its environment'' contrasts with Roman concrete, which ''actively incorporated seawater into its structure'' to allow mineral growth that strengthened it.","difficulty":"normal","format":"mc","answer":"Roman concrete incorporates seawater to strengthen itself while Portland cement is designed to resist reaction with it","options":["Roman concrete repels seawater while Portland cement absorbs it","Roman concrete incorporates seawater to strengthen itself while Portland cement is designed to resist reaction with it","Roman concrete and Portland cement both react with seawater but at different rates","Roman concrete uses freshwater in its mix whereas Portland cement uses seawater"],"contentHash":"e042806a88f7cff03022941dbd3435e7fbe02df45e6af278a13656e7effd698c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f001-1001-4001-8001-000000000003', 'vr', 'practice', 'c7a1f001-1001-4001-8001-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f001-1001-4001-8001-000000000003","mode":"practice","parentId":"c7a1f001-1001-4001-8001-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Pliny''s observation that structures became stronger over time and explicitly states that ''Recent analysis of cores drilled from the harbour at Portus Cosanus in Tuscany has confirmed Pliny''s observation in mineralogical terms.'' This is why he is cited.","difficulty":"normal","format":"mc","answer":"To show that an ancient observation of the concrete''s behaviour has been confirmed by modern scientific analysis","options":["To establish that the chemistry of pozzolana was fully understood in ancient Rome","To credit him with inventing the pozzolanic reaction","To show that an ancient observation of the concrete''s behaviour has been confirmed by modern scientific analysis","To argue that Roman writers were more reliable than modern materials scientists"],"contentHash":"192e8c30f32de1bcc984f5b06eeb1015bab9b6bb610e29f9b9b29f5528f5994f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f001-1001-4001-8001-000000000004', 'vr', 'practice', 'c7a1f001-1001-4001-8001-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f001-1001-4001-8001-000000000004","mode":"practice","parentId":"c7a1f001-1001-4001-8001-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Roman concrete sets slowly and is not suitable for applications requiring rapid strength development, such as high-rise construction.'' This directly links slow setting to unsuitability for high-rises.","difficulty":"normal","format":"mc","answer":"Its slow setting time delays the achievement of structural strength","options":["It is weaker than Portland cement in all applications","Its slow setting time delays the achievement of structural strength","The volcanic ash required is toxic to workers","It cannot be produced in sufficient quantities outside Italy"],"contentHash":"99e4a9f5bf93fdac17e3e2dd29b1b88296a5f13c7528d209ba87a2f8288d94f1"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f001-1001-4001-8001-000000000005', 'vr', 'practice', 'c7a1f001-1001-4001-8001-000000000005'::uuid, 'vr.explicit_information', '{"id":"c7a1f001-1001-4001-8001-000000000005","mode":"practice","parentId":"c7a1f001-1001-4001-8001-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage cites the geographic restriction of the ash, inconsistent results from alternative materials, and slow setting time as obstacles.","difficulty":"hard","format":"mc","answer":"Modern builders lack the engineering knowledge of Roman architects","options":["The volcanic ash required is geographically restricted","Alternative pozzolanic materials do not reliably produce the same mineral growth","The slow setting time restricts the range of applications","Modern builders lack the engineering knowledge of Roman architects"],"contentHash":"7235010dc17b4354de56a155fde51e1dfe99ab64554e5a62bf7633d7d352bc32"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f007-1007-4007-8007-000000000002', 'vr', 'practice', 'c7a1f007-1007-4007-8007-000000000002'::uuid, 'vr.meaning_in_context', '{"id":"c7a1f007-1007-4007-8007-000000000002","mode":"practice","parentId":"c7a1f007-1007-4007-8007-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states seagrasses occupy ''less than 0.2 per cent of the ocean floor'' but ''account for approximately ten per cent of organic carbon burial in marine sediments.'' ''Disproportionate'' captures this mismatch between area occupied and burial contribution.","difficulty":"normal","format":"mc","answer":"They occupy a very small area of the seabed but account for a much larger share of marine carbon burial","options":["They store more carbon than terrestrial forests per unit area","They occupy a very small area of the seabed but account for a much larger share of marine carbon burial","Their carbon storage is unevenly distributed among different seagrass species","They sequester carbon faster than any other marine ecosystem"],"contentHash":"76a58c776429c9224096cf9c583c7ab1fc0e09d28c6b87840597dcd2da877362"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f007-1007-4007-8007-000000000003', 'vr', 'practice', 'c7a1f007-1007-4007-8007-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f007-1007-4007-8007-000000000003","mode":"practice","parentId":"c7a1f007-1007-4007-8007-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces Posidonia oceanica as the species found in Mediterranean meadows with carbon stores ''over 6,000 years in age'', noting it ''grows at rates of only about one centimetre per year but whose mats can persist for millennia.''","difficulty":"normal","format":"mc","answer":"To provide an example of a slow-growing species whose carbon stores can persist for thousands of years","options":["To illustrate a fast-growing seagrass species used in restoration","To contrast Mediterranean and Caribbean seagrass species","To provide an example of a slow-growing species whose carbon stores can persist for thousands of years","To argue that restoration of Posidonia oceanica is straightforward"],"contentHash":"85df5cc34822f38ba1faf3eea85dcd22911adb4552fad7ac4d13fc39dacee980"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f007-1007-4007-8007-000000000004', 'vr', 'practice', 'c7a1f007-1007-4007-8007-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f007-1007-4007-8007-000000000004","mode":"practice","parentId":"c7a1f007-1007-4007-8007-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists coastal development, dredging, nutrient runoff and mechanical damage from boats as causes.","difficulty":"hard","format":"mc","answer":"Rising sea temperatures","options":["Nutrient runoff promoting algal overgrowth","Damage from boat anchors and propellers","Rising sea temperatures","Coastal development and dredging"],"contentHash":"68611b1939ef4d8f7a40f45746022581ab6b940945d857e7a6846cd4e22f2c32"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f007-1007-4007-8007-000000000005', 'vr', 'practice', 'c7a1f007-1007-4007-8007-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f007-1007-4007-8007-000000000005","mode":"practice","parentId":"c7a1f007-1007-4007-8007-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage describes ''mixed results'' across projects, notes Chesapeake Bay successes contrasted with Mediterranean difficulties, and states that even optimistic restoration could ''offset only a small fraction of annual losses.''","difficulty":"normal","format":"mc","answer":"Restoration success varies with species and location, and is unlikely to offset global losses in the near term","options":["Restoration efforts have been universally successful","Restoration success varies with species and location, and is unlikely to offset global losses in the near term","Mediterranean restoration efforts have exceeded expectations","Restoration efforts should focus on tropical species rather than Mediterranean ones"],"contentHash":"0fc1dd79224c33ba1bf301c8e583d119910b80c3c5102e6b4b692c68dc189f72"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0805-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0805-4a01-9f11-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"c4a1b8e2-0805-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0805-4a01-9f11-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''slime moulds are not, despite their common name, true moulds or fungi'' and places them within the Amoebozoa.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"973a1c41e890f22324a680ba0bc60166b1a05a06371c83c182cd6b85713cfdb7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0805-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0805-4a01-9f11-000000000003'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0805-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0805-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Physarum as existing ''as a single, multi-nucleate cell'', which directly supports the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"c5200b365a909a92a3826698f333037af397c05f99b8bce06a2fdf49c3fd096d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0805-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0805-4a01-9f11-000000000004'::uuid, 'vr.qualifiers_and_scope', '{"id":"c4a1b8e2-0805-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0805-4a01-9f11-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"low","rationale":"Ambiguous key: ''comparable efficiency'' does not rule out slightly greater efficiency, so the asserted contradiction is not established.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"excludedReason":"Ambiguous key: ''comparable efficiency'' does not rule out slightly greater efficiency, so the asserted contradiction is not established.","contentHash":"73ec8034b65768e610171af253f491e55bd1ddd32da3e02ad7c7ff74a5c78417"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0805-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0805-4a01-9f11-000000000005'::uuid, 'vr.qualifiers_and_scope', '{"id":"c4a1b8e2-0805-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0805-4a01-9f11-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage explicitly notes that ''some researchers have argued that the results should not be described using cognitive vocabulary'' while others disagree.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"e63bb876a5d1398e73154a5fe75c34d3713848e0aa849a25a0ad7d8346c9eb50"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1002-4a02-9a02-000000000002', 'vr', 'practice', 'c1d2e3f4-1002-4a02-9a02-000000000002'::uuid, 'vr.evaluating_evidence', '{"id":"c1d2e3f4-1002-4a02-9a02-000000000002","mode":"practice","parentId":"c1d2e3f4-1002-4a02-9a02-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states that even the predigestion tolerance evidence ''remains inconclusive'' for non-coeliac wheat sensitivity, and explicitly ''does not extend to those with coeliac disease''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"c50bd53a05e1b8a9fd85d988135d6b21cfeba9b3ae1ed716335edc8cd9fb0fe5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1002-4a02-9a02-000000000003', 'vr', 'practice', 'c1d2e3f4-1002-4a02-9a02-000000000003'::uuid, 'vr.inference', '{"id":"c1d2e3f4-1002-4a02-9a02-000000000003","mode":"practice","parentId":"c1d2e3f4-1002-4a02-9a02-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that firm, cool-fermented starters produce more acetic acid (sharper, vinegar-like), while wet, warm-fermented starters favour lactic acid (milder).","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"38fe44c93974c35cf4dd17e65f628487e50de8ca10fabca37e9ccc8a582cc9e6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1002-4a02-9a02-000000000004', 'vr', 'practice', 'c1d2e3f4-1002-4a02-9a02-000000000004'::uuid, 'vr.qualifiers_and_scope', '{"id":"c1d2e3f4-1002-4a02-9a02-000000000004","mode":"practice","parentId":"c1d2e3f4-1002-4a02-9a02-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage describes the LAB population as ''typically dominated by heterofermentative species such as Lactobacillus sanfranciscensis'', which indicates it is one common example but does not claim it is the most common bacterium worldwide.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"2e72ebc1c67239737bf3350cba55f61d594179c0f8f9cb615702efe7c84dffc8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1002-4a02-9a02-000000000005', 'vr', 'practice', 'c1d2e3f4-1002-4a02-9a02-000000000005'::uuid, 'vr.recognising_contradictions', '{"id":"c1d2e3f4-1002-4a02-9a02-000000000005","mode":"practice","parentId":"c1d2e3f4-1002-4a02-9a02-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states commercial baker''s yeast ''is a monoculture selected for rapid leavening'', which contradicts both ''multiple yeast species'' and ''selected for flavour complexity''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"60e52ecbe3b69356c97e352595d147fbe6c5bc57ed0b2cc1ae4db99d5d3fe221"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:71a9b50b-0e74-412f-934b-9edbf80abcdc', 'vr', 'practice', '71a9b50b-0e74-412f-934b-9edbf80abcdc'::uuid, 'vr.author_perspective', '{"id":"71a9b50b-0e74-412f-934b-9edbf80abcdc","mode":"practice","parentId":"d20f9784-dffe-4168-b296-368705bb93fd","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The author sets out the hypothesis, gives the critics'' objection, then gives the supporters'' response, and closes by noting a separate complication from blind listening tests.","difficulty":"normal","format":"mc","answer":"Balanced, presenting it alongside competing considerations without endorsing a conclusion","options":["Strongly supportive of it as the definitive explanation","Dismissive of it as obviously incorrect","Balanced, presenting it alongside competing considerations without endorsing a conclusion","Hostile toward the climatologists who proposed it"],"contentHash":"626bb00c8fbeb9be8b8d644da08d3ac756d331d5aa8375137fde72c6c4ed3b55"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2d06c3cc-b9cc-41a3-815a-c01f70ed669f', 'vr', 'practice', '2d06c3cc-b9cc-41a3-815a-c01f70ed669f'::uuid, 'vr.evaluating_evidence', '{"id":"2d06c3cc-b9cc-41a3-815a-c01f70ed669f","mode":"practice","parentId":"d20f9784-dffe-4168-b296-368705bb93fd","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states critics pointed out that ''other luthiers working in the same period and using wood from the same forests did not produce instruments of comparable quality'' and that ''if climate were the dominant factor, one would expect the effect to be more widespread''.","difficulty":"normal","format":"mc","answer":"That other luthiers using the same wood did not achieve the same results, suggesting climate alone is insufficient","options":["That the Maunder Minimum did not actually occur","That other luthiers using the same wood did not achieve the same results, suggesting climate alone is insufficient","That Stradivari''s violins have been shown to sound worse than modern instruments","That dendrochronological methods are unreliable"],"contentHash":"696e7a2bf85b5f538f862c442e858c5380c48000c0086a236c208d3d151b5cbc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:206bffbe-536a-4c95-a673-fe11712565df', 'vr', 'practice', '206bffbe-536a-4c95-a673-fe11712565df'::uuid, 'vr.meaning_in_context', '{"id":"206bffbe-536a-4c95-a673-fe11712565df","mode":"practice","parentId":"d20f9784-dffe-4168-b296-368705bb93fd","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"low","rationale":"The phrase ''the perceived superiority'' refers back to Stradivari''s reputed tonal superiority — the topic the blind listening tests call into question.","difficulty":"hard","format":"mc","answer":"The tonal quality that violinists claim to hear in Stradivari instruments","options":["The tonal quality that violinists claim to hear in Stradivari instruments","The Maunder Minimum''s effect on wood density","The disagreement between critics and supporters","The varnish used by Stradivari"],"excludedReason":"The stem asks for the referent of ''it'', but that word is absent from the quoted clause and final passage sentence.","contentHash":"b74c470a6dcadada364205b42df51e8077244eb4f871487a9135199cbfcf7472"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:cbf218c2-80a3-4e70-85df-51bcc971dc24', 'vr', 'practice', 'cbf218c2-80a3-4e70-85df-51bcc971dc24'::uuid, 'vr.evaluating_evidence', '{"id":"cbf218c2-80a3-4e70-85df-51bcc971dc24","mode":"practice","parentId":"d20f9784-dffe-4168-b296-368705bb93fd","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The author flags the blind-test finding as a ''complication'' that raises doubt about whether the superiority is objective.","difficulty":"hard","format":"mc","answer":"It would remove one complication the author raises about whether the superiority is objective","options":["It would prove the climate hypothesis correct","It would remove one complication the author raises about whether the superiority is objective","It would confirm that the varnish is the most important factor","It would contradict the critics'' argument about other luthiers"],"contentHash":"2a257b9813c68de07e25c57832ddf02b43fc33ebce8a6354708a074d3f5c1c37"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0615-4a15-9d15-000000001501', 'vr', 'practice', 'c7a1e4b2-0615-4a15-9d15-000000001501'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0615-4a15-9d15-000000001501","mode":"practice","parentId":"c7a1e4b2-0615-4a15-9d15-000000000015","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''A frequent objective was the preservation of visible hierarchical distinctions at a time when economic change increasingly enabled commoners to acquire goods associated with aristocratic status.''","difficulty":"normal","format":"mc","answer":"To preserve visible distinctions between social ranks","options":["To generate tax revenue from luxury goods","To preserve visible distinctions between social ranks","To promote trade between city-states","To limit imports of foreign textiles"],"contentHash":"ae68d13976997b9aec1bc17c0ab99a37dee6d134acbdf875223ea4e98315629d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0615-4a15-9d15-000000001502', 'vr', 'practice', 'c7a1e4b2-0615-4a15-9d15-000000001502'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0615-4a15-9d15-000000001502","mode":"practice","parentId":"c7a1e4b2-0615-4a15-9d15-000000000015","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that provisions and severity of enforcement ''varied considerably'' and that English enforcement was ''inconsistent at best''.","difficulty":"normal","format":"mc","answer":"Sumptuary legislation was enforced uniformly across Europe","options":["The 1363 English statute regulated meal composition as well as dress","Italian sumptuary laws often focused on wedding expenditure","Sumptuary legislation was enforced uniformly across Europe","Some Italian households paid fines as a routine cost of ceremony"],"contentHash":"e4b0daac3318546ddf1e7dfaa2354c315e16238b15d8d1ea8b6b7af5156dedfd"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0615-4a15-9d15-000000001503', 'vr', 'practice', 'c7a1e4b2-0615-4a15-9d15-000000001503'::uuid, 'vr.author_perspective', '{"id":"c7a1e4b2-0615-4a15-9d15-000000001503","mode":"practice","parentId":"c7a1e4b2-0615-4a15-9d15-000000000015","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces Italian sumptuary measures with ''Scholars have interpreted these measures variously'' and lists three competing interpretations — an evenhanded presentation of differing scholarly views.","difficulty":"normal","format":"mc","answer":"Scholars have proposed several distinct interpretations of the laws'' purposes","options":["The laws were primarily motivated by religious reform","The laws were motivated chiefly by economic considerations","Scholars have proposed several distinct interpretations of the laws'' purposes","The laws had no consistent purpose and were therefore ineffective"],"contentHash":"b93ebf30a6c07b22ff99e46e88108afff61fdee5cd4aa0665f87f2eee85ce827"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0615-4a15-9d15-000000001504', 'vr', 'practice', 'c7a1e4b2-0615-4a15-9d15-000000001504'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1e4b2-0615-4a15-9d15-000000001504","mode":"practice","parentId":"c7a1e4b2-0615-4a15-9d15-000000000015","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the absence of systematic penalty records suggests enforcement was inconsistent at best''.","difficulty":"hard","format":"mc","answer":"It would challenge the passage''s characterisation of English enforcement as inconsistent","options":["It would confirm the passage''s statement that English sumptuary laws were routinely enforced","It would challenge the passage''s characterisation of English enforcement as inconsistent","It would support the passage''s discussion of Italian wedding legislation","It would show that the 1363 Statute had no effect on commoner behaviour"],"contentHash":"6e996f7972bb370b2690c3c45ce3463722a1029bf4a5894e254209f3752b95d9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0616-4a16-9d16-000000001601', 'vr', 'practice', 'c7a1e4b2-0616-4a16-9d16-000000001601'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0616-4a16-9d16-000000001601","mode":"practice","parentId":"c7a1e4b2-0616-4a16-9d16-000000000016","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Osmobiosis and anoxybiosis are associated with salinity extremes and oxygen deprivation respectively'', linking osmobiosis to salinity.","difficulty":"normal","format":"mc","answer":"Osmobiosis","options":["Anhydrobiosis","Cryobiosis","Osmobiosis","Anoxybiosis"],"contentHash":"ec8da5c66650bf8bb8ea1b62fbcb10a9328f634aeec79f0a31006a1c71d8a9fe"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0616-4a16-9d16-000000001602', 'vr', 'practice', 'c7a1e4b2-0616-4a16-9d16-000000001602'::uuid, 'vr.author_perspective', '{"id":"c7a1e4b2-0616-4a16-9d16-000000001602","mode":"practice","parentId":"c7a1e4b2-0616-4a16-9d16-000000000016","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage presents applications as ''possible'' and ''speculative'', and notes ''significant technical barriers would need to be overcome before any translation to human medicine could be contemplated'' — a cautious and sceptical stance rather than dismissal or enthusiasm.","difficulty":"hard","format":"mc","answer":"Cautiously interested but sceptical of near-term application","options":["Dismissive of any possible medical relevance","Confident that applications will soon reach human medicine","Cautiously interested but sceptical of near-term application","Neutral with no position expressed"],"contentHash":"974d8a4906c87189ae58a76e6136de25e2b9b8f715b0752d408843aee2f92623"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0616-4a16-9d16-000000001603', 'vr', 'practice', 'c7a1e4b2-0616-4a16-9d16-000000001603'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0616-4a16-9d16-000000001603","mode":"practice","parentId":"c7a1e4b2-0616-4a16-9d16-000000000016","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes survival of extreme temperatures, high pressures, and lethal radiation doses, and describes cryptobiosis as allowing survival under conditions that would ''rapidly kill almost any active life form'' — directly supporting the option.","difficulty":"normal","format":"mc","answer":"Tardigrades can survive conditions that would kill most other animals","options":["Tardigrades in cryptobiosis have detectable but reduced metabolic activity","TDPs are the only molecular mechanism underlying tardigrade resilience","Tardigrades can survive conditions that would kill most other animals","Cryptobiosis is irreversible once induced"],"contentHash":"dd91ba72a326d5dc18900d4e257c0db0f35464a3f3d058f56a69097ee15bbad1"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0616-4a16-9d16-000000001604', 'vr', 'practice', 'c7a1e4b2-0616-4a16-9d16-000000001604'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0616-4a16-9d16-000000001604","mode":"practice","parentId":"c7a1e4b2-0616-4a16-9d16-000000000016","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes TDPs play ''a role'' but ''other mechanisms contribute'', and frames the molecular basis as ''an active area of research'' — indicating that the complete picture is still being investigated.","difficulty":"normal","format":"mc","answer":"To indicate that the full molecular basis of resilience is not yet established","options":["To argue that TDPs are unimportant","To indicate that the full molecular basis of resilience is not yet established","To suggest that tardigrades cannot survive without TDPs","To contrast tardigrades with other invertebrates"],"contentHash":"fcfde1c1156ae281b0f71c8198a0ddb94d8ea986d52bd790af71a13f1059a387"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2003-4b03-9b03-000000000002', 'vr', 'practice', 'd2e3f4a5-2003-4b03-9b03-000000000002'::uuid, 'vr.explicit_information', '{"id":"d2e3f4a5-2003-4b03-9b03-000000000002","mode":"practice","parentId":"d2e3f4a5-2003-4b03-9b03-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states directly that ''Aquileia became the principal centre for amber working in the Roman world''.","difficulty":"normal","format":"mc","answer":"Aquileia, on the Adriatic","options":["Carnuntum, on the Danube","Aquileia, on the Adriatic","Mycenae, in Greece","The Kaliningrad region on the Baltic coast"],"contentHash":"59bd6a526b365cf3e97ae11bf3c00bc4f9be7dfe654d180baadeec9be6602b86"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2003-4b03-9b03-000000000003', 'vr', 'practice', 'd2e3f4a5-2003-4b03-9b03-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"d2e3f4a5-2003-4b03-9b03-000000000003","mode":"practice","parentId":"d2e3f4a5-2003-4b03-9b03-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage emphasises the multiple-branch structure of the routes, the reach of amber as early as the second millennium BCE, and the reliance on archaeological context for dating.","difficulty":"hard","format":"mc","answer":"Amber travelled along a network of routes linking the Baltic and Mediterranean for millennia, with chronology established through contextual evidence","options":["Baltic amber was more valuable than gold in the Mediterranean world","The Amber Road operated only during the Roman imperial period","Amber travelled along a network of routes linking the Baltic and Mediterranean for millennia, with chronology established through contextual evidence","Genetic studies have definitively proved that Baltic and Mediterranean populations were in sustained contact"],"contentHash":"a0caad1f36ea54521b2588ae7e74f5358ba721e628b981ad596d32f54c8d20c5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2003-4b03-9b03-000000000004', 'vr', 'practice', 'd2e3f4a5-2003-4b03-9b03-000000000004'::uuid, 'vr.meaning_in_context', '{"id":"d2e3f4a5-2003-4b03-9b03-000000000004","mode":"practice","parentId":"d2e3f4a5-2003-4b03-9b03-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":["vr.evaluating_evidence"],"confidence":"high","rationale":"The sentence poses exactly this question: ''the extent to which the amber trade itself drove such contact, rather than being carried along by other movements, remains contested''.","difficulty":"hard","format":"mc","answer":"Whether the amber trade was the cause, rather than a consequence, of population contact","options":["Whether genetic studies on human remains have been conducted at all","Whether the amber trade was the cause, rather than a consequence, of population contact","Whether Baltic amber ever reached the Aegean","Whether Pliny the Elder''s speculations about amber''s origin were accurate"],"contentHash":"ece4c5e722993f839b435396da21915f35a9272e3f412517172f67b3a5a8b73d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2003-4b03-9b03-000000000005', 'vr', 'practice', 'd2e3f4a5-2003-4b03-9b03-000000000005'::uuid, 'vr.explicit_information', '{"id":"d2e3f4a5-2003-4b03-9b03-000000000005","mode":"practice","parentId":"d2e3f4a5-2003-4b03-9b03-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists amber''s appeals as ''its warmth to the touch, its apparent ability to attract small objects when rubbed, and its suitability for carving into ornaments and amulets''.","difficulty":"normal","format":"mc","answer":"Its apparent ability to attract small objects when rubbed","options":["Its resistance to fire","Its use as a currency standardised across the Baltic","Its transparency, which allowed it to be used in optical instruments","Its apparent ability to attract small objects when rubbed"],"contentHash":"b2d25d2cc4f6e03f04e9d75d9da1328a5a3ffff1fe25867733f2862675551ca9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0001-4001-8001-000000000002', 'vr', 'practice', 'f1a2b3c4-0001-4001-8001-000000000002'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0001-4001-8001-000000000002","mode":"practice","parentId":"f1a2b3c4-0001-4001-8001-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''in 1902, archaeologist Valerios Stais, examining the object at the National Archaeological Museum in Athens, identified gear wheels embedded in the encrustation''.","difficulty":"normal","format":"mc","answer":"Valerios Stais, examining the object at the museum in 1902","options":["The sponge divers who originally recovered it in 1901","Valerios Stais, examining the object at the museum in 1902","Researchers using X-ray tomography in the early 2000s","Astronomers associated with the school of Hipparchus"],"contentHash":"11d85631e5f8b88952d855f8bdfa11c9d8109080069e0c331cd9af601c87974d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0001-4001-8001-000000000003', 'vr', 'practice', 'f1a2b3c4-0001-4001-8001-000000000003'::uuid, 'vr.qualifiers_and_scope', '{"id":"f1a2b3c4-0001-4001-8001-000000000003","mode":"practice","parentId":"f1a2b3c4-0001-4001-8001-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''technology of similar mechanical sophistication does not reappear in the surviving historical record until the astronomical clocks of medieval Europe, more than a thousand years later''.","difficulty":"normal","format":"mc","answer":"The mechanical sophistication of the Antikythera Mechanism was not matched for over a millennium in surviving records","options":["Hellenistic engineers routinely produced mechanisms as complex as the Antikythera device","The mechanical sophistication of the Antikythera Mechanism was not matched for over a millennium in surviving records","The Antikythera Mechanism was used primarily to schedule the Olympic Games","Medieval European clockmakers based their designs on recovered Greek devices"],"contentHash":"ebded41c35a73f5bacd6a3a0c5d560efe6c78d3ba01d2d51f4468dd2064f5173"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0001-4001-8001-000000000004', 'vr', 'practice', 'f1a2b3c4-0001-4001-8001-000000000004'::uuid, 'vr.main_idea_and_purpose', '{"id":"f1a2b3c4-0001-4001-8001-000000000004","mode":"practice","parentId":"f1a2b3c4-0001-4001-8001-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage says ''some scholars have suggested'' the mechanism came from a workshop associated with Hipparchus''s school ''though this attribution remains disputed''.","difficulty":"hard","format":"mc","answer":"To illustrate a proposed but contested theory about where the device was made","options":["To confirm the origin of the Antikythera Mechanism","To illustrate a proposed but contested theory about where the device was made","To argue that Rhodes was the centre of Hellenistic astronomy","To contrast Hipparchus''s methods with those of the mechanism''s designer"],"contentHash":"29a172fd2c9a0b31210c176f8d40632218e42ea5a5c44921edc5429ea6e82a7f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0001-4001-8001-000000000005', 'vr', 'practice', 'f1a2b3c4-0001-4001-8001-000000000005'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0001-4001-8001-000000000005","mode":"practice","parentId":"f1a2b3c4-0001-4001-8001-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the mechanism ''is generally dated by its accompanying pottery to between 150 and 100 BCE''.","difficulty":"normal","format":"mc","answer":"Pottery recovered alongside it from the shipwreck","options":["Radiocarbon analysis of the wooden case","The style of the bronze gears","Pottery recovered alongside it from the shipwreck","Historical records of Hipparchus''s workshop"],"contentHash":"843df35466a01b9ba1d53801d83128b0e916cb32934951685f9c329164dc446c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0601-4a01-9d01-000000000101', 'vr', 'practice', 'c7a1e4b2-0601-4a01-9d01-000000000101'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0601-4a01-9d01-000000000101","mode":"practice","parentId":"c7a1e4b2-0601-4a01-9d01-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly contrasts the two, stating the Antonine Wall ''was built principally from turf blocks laid on a stone foundation'' while referring to Hadrian''s Wall as its ''stone-faced predecessor''.","difficulty":"normal","format":"mc","answer":"The Antonine Wall was built primarily of turf on a stone foundation, whereas Hadrian''s Wall was stone-faced","options":["The Antonine Wall was longer and built to a higher specification","The Antonine Wall was built primarily of turf on a stone foundation, whereas Hadrian''s Wall was stone-faced","The Antonine Wall lacked any accompanying road or ditch","The Antonine Wall was constructed entirely by auxiliary troops rather than legions"],"contentHash":"47b4bff8dba455ace2e7f812749cf4f503135ab8f53593c38ac73b08a5000802"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0601-4a01-9d01-000000000102', 'vr', 'practice', 'c7a1e4b2-0601-4a01-9d01-000000000102'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0601-4a01-9d01-000000000102","mode":"practice","parentId":"c7a1e4b2-0601-4a01-9d01-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the slabs as ''Unusually among Roman frontier works'' and notes the surviving twenty are ''among the richest epigraphic records of Roman military construction anywhere in the empire'', framing them as a distinctive and historically valuable feature.","difficulty":"hard","format":"mc","answer":"To highlight an unusual feature of the wall that provides valuable historical evidence","options":["To argue that the Antonine Wall was more important militarily than Hadrian''s Wall","To illustrate the unusual density of forts along the frontier","To highlight an unusual feature of the wall that provides valuable historical evidence","To demonstrate that the wall was built more quickly than expected"],"contentHash":"7d167bc37dde9eea1c4fad8658f4fa6ed9d879ec5417854229b4aa2bd852442f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0601-4a01-9d01-000000000103', 'vr', 'practice', 'c7a1e4b2-0601-4a01-9d01-000000000103'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1e4b2-0601-4a01-9d01-000000000103","mode":"practice","parentId":"c7a1e4b2-0601-4a01-9d01-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the reasons ''remain debated among historians'' and lists ''competing theories'', indicating no consensus has been reached.","difficulty":"normal","format":"mc","answer":"The precise reason is uncertain, with several competing explanations proposed","options":["It was abandoned because the northern tribes were definitively defeated","Historians agree that strategic overextension was the primary cause","The precise reason is uncertain, with several competing explanations proposed","The wall was abandoned immediately after its completion in 154 CE"],"contentHash":"50168d241337daace16a3f912ad92a71d87489940709f36243120213b0db7c39"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0601-4a01-9d01-000000000104', 'vr', 'practice', 'c7a1e4b2-0601-4a01-9d01-000000000104'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1e4b2-0601-4a01-9d01-000000000104","mode":"practice","parentId":"c7a1e4b2-0601-4a01-9d01-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the wall was ''abandoned within roughly two decades of its completion'' and the garrison withdrew.","difficulty":"hard","format":"mc","answer":"It would complicate the claim that the wall was abandoned within roughly two decades of completion","options":["It would confirm that the wall was the most important frontier in the empire","It would complicate the claim that the wall was abandoned within roughly two decades of completion","It would support the theory that the wall was abandoned due to tribal pressure","It would reinforce the passage''s point about the density of forts"],"contentHash":"188979f5f5b3d9a908d45d59965594c7cff53b0dc3de883c33b70d25d7ea4c49"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f009-1009-4009-8009-000000000002', 'vr', 'practice', 'c7a1f009-1009-4009-8009-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f009-1009-4009-8009-000000000002","mode":"practice","parentId":"c7a1f009-1009-4009-8009-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that deposits form in part because ''the region''s extreme aridity prevents the water-soluble salts from being leached away.''","difficulty":"normal","format":"mc","answer":"The extreme aridity of the region prevents the soluble salts from being washed away","options":["Volcanic activity in the region continually deposits fresh nitrate","The extreme aridity of the region prevents the soluble salts from being washed away","Bacterial processes in Atacama soils produce nitrate at unusually high rates","Ocean currents carry nitrate-rich water into the desert"],"contentHash":"3efcd41461e631f7af1f31353be4c361640f19fd56bed57556b751fe924a60fc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f009-1009-4009-8009-000000000003', 'vr', 'practice', 'c7a1f009-1009-4009-8009-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f009-1009-4009-8009-000000000003","mode":"practice","parentId":"c7a1f009-1009-4009-8009-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The Haber-Bosch process...","difficulty":"normal","format":"mc","answer":"The development of the Haber-Bosch process, which provided a cheaper alternative source of fixed nitrogen","options":["Depletion of the Atacama deposits","The First World War disrupting export routes","The development of the Haber-Bosch process, which provided a cheaper alternative source of fixed nitrogen","Labour unrest in the oficinas during the 1920s"],"contentHash":"affc6fec1e4b6c24d6372d4b655723f6f01659e6ad723b1d30649d3d577591ed"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f009-1009-4009-8009-000000000004', 'vr', 'practice', 'c7a1f009-1009-4009-8009-000000000004'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f009-1009-4009-8009-000000000004","mode":"practice","parentId":"c7a1f009-1009-4009-8009-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Two of them, Humberstone and Santa Laura, were inscribed as UNESCO World Heritage Sites in 2005, on the grounds of their industrial and social history.''","difficulty":"normal","format":"mc","answer":"As examples of former oficinas now recognised as World Heritage Sites for their industrial and social history","options":["As examples of oficinas that were never abandoned","As examples of former oficinas now recognised as World Heritage Sites for their industrial and social history","To contrast successful with unsuccessful mining operations","To illustrate the architectural style of nineteenth-century Chilean mining towns"],"contentHash":"092f5e6df0f2db0e3d641d36fa2a87a2889af2e7c0525c444f86e2479a11f114"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f009-1009-4009-8009-000000000005', 'vr', 'practice', 'c7a1f009-1009-4009-8009-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f009-1009-4009-8009-000000000005","mode":"practice","parentId":"c7a1f009-1009-4009-8009-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states nitrate exports ''accounted for over half of Chilean government revenue through a specific export tax'' before the collapse.","difficulty":"hard","format":"mc","answer":"Chilean government revenue declined significantly after the collapse of the nitrate industry","options":["Chilean government revenue declined significantly after the collapse of the nitrate industry","The Atacama Desert receives less rainfall than any other desert on Earth","Haber-Bosch ammonia is more expensive than Atacama nitrate","All oficinas had been abandoned by the end of the 1920s"],"contentHash":"fc32f6dcb85e63dc49dacc70f7fd9b0bd21f7c88b37b9bdf88efbb6dbe866e57"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0617-4a17-9d17-000000001701', 'vr', 'practice', 'c7a1e4b2-0617-4a17-9d17-000000001701'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0617-4a17-9d17-000000001701","mode":"practice","parentId":"c7a1e4b2-0617-4a17-9d17-000000000017","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the fairs were held ''on the Scanian coast of what is now southern Sweden''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"13706b2cb6e135c215e9c53116038471859f94073039ff6237ba99d341dc465a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0617-4a17-9d17-000000001702', 'vr', 'practice', 'c7a1e4b2-0617-4a17-9d17-000000001702'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0617-4a17-9d17-000000001702","mode":"practice","parentId":"c7a1e4b2-0617-4a17-9d17-000000000017","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage contrasts Dutch ''onboard gutting techniques'' with the ''shore-based Hanseatic methods'', indicating Dutch processing happened at sea, not at Hanseatic fitters.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"c64be4f65a44f95212e7b2d969870fa6657d6252a1f3dcc7332fb1196f96aed7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0617-4a17-9d17-000000001703', 'vr', 'practice', 'c7a1e4b2-0617-4a17-9d17-000000001703'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0617-4a17-9d17-000000001703","mode":"practice","parentId":"c7a1e4b2-0617-4a17-9d17-000000000017","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage offers ''changes in ocean currents or salinity'' as possible reasons for the shoals moving away, but does not mention overfishing as a cause.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"7eff40166454f954b9e6a4390e6884f256247a2aa3f7c7e6bfe4ef22e2f4c227"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0617-4a17-9d17-000000001704', 'vr', 'practice', 'c7a1e4b2-0617-4a17-9d17-000000001704'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0617-4a17-9d17-000000001704","mode":"practice","parentId":"c7a1e4b2-0617-4a17-9d17-000000000017","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the Danish crown ...","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"d3ccbf47952dba20662673a1534a31b2fa88cb5788ce4a7412b50ba84bcb59fe"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1f', 'vr', 'practice', '0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1f'::uuid, 'vr.author_perspective', '{"id":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1f","mode":"practice","parentId":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1e","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the figure ''carries no crown and is not labelled by name'' and that ''some historians argue that the arrow-struck figure may be a different soldier''.","difficulty":"hard","format":"mc","answer":"The traditional identification of the arrow-struck figure as Harold is open to reasonable dispute","options":["The tapestry shows unambiguously that Harold was killed by an arrow to the eye","The traditional identification of the arrow-struck figure as Harold is open to reasonable dispute","Modern scholars agree that Harold is the falling figure cut down by a mounted Norman","The Latin inscriptions in this section clearly label which figure is Harold"],"contentHash":"5664276d06d556e602ac67f47214197f832976c4e136537122e4a5c495f411be"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d20', 'vr', 'practice', '0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d20'::uuid, 'vr.main_idea_and_purpose', '{"id":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d20","mode":"practice","parentId":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1e","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The author explicitly states the distinction ''is more than pedantic: the labour-intensive and relatively inexpensive character of embroidery has implications for where and why the work was produced.''","difficulty":"normal","format":"mc","answer":"Because the production method has implications for where and why the work was made","options":["To correct a common misconception without further significance","Because the production method has implications for where and why the work was made","To suggest that the work should be renamed by art historians","Because embroidery is more durable than woven tapestry"],"contentHash":"e7f41a7f9e537e9041f6196d15637d34d73bead92a7c92e658bb3a87e70d04e5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d21', 'vr', 'practice', '0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d21'::uuid, 'vr.explicit_information', '{"id":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d21","mode":"practice","parentId":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1e","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The consensus today is that the tapestry was commissioned by Odo, Bishop of Bayeux''.","difficulty":"normal","format":"mc","answer":"Odo, Bishop of Bayeux","options":["Queen Matilda and her ladies-in-waiting","William the Conqueror himself","Odo, Bishop of Bayeux","Anglo-Saxon embroiderers in Canterbury"],"contentHash":"8b5d96899b656b93545af77b26aca33806c7eafa2d957171f4739b01c106d836"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d22', 'vr', 'practice', '0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d22'::uuid, 'vr.evaluating_evidence', '{"id":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d22","mode":"practice","parentId":"0a5b28d9-4f1e-4b8c-a2d3-9e3f5b8c0d1e","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage supports English production with ''Anglo-Saxon embroiderers, whose craft was highly esteemed across contemporary Europe''.","difficulty":"hard","format":"mc","answer":"It would weaken the reasoning offered for locating its production in England","options":["It would confirm the passage''s argument that the tapestry was made in England","It would weaken the reasoning offered for locating its production in England","It would disprove the attribution of the commission to Odo","It would have no relevance to any of the passage''s claims"],"contentHash":"e0fe4e0bd59747b18d1529ddbdb724ec35d902ed6d96e9101a81fdaffe5f9f25"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0004-4004-8004-000000000002', 'vr', 'practice', 'f1a2b3c4-0004-4004-8004-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"f1a2b3c4-0004-4004-8004-000000000002","mode":"practice","parentId":"f1a2b3c4-0004-4004-8004-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that in its original form the scale ''related wind strength to the amount of sail a fully rigged frigate could carry in particular conditions, rather than to any numerical measurement of wind speed''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"24649e7840fcc1cf5d29b4264ed38da40d015fe4d8487ba8c1b38bfec3348f26"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0004-4004-8004-000000000003', 'vr', 'practice', 'f1a2b3c4-0004-4004-8004-000000000003'::uuid, 'vr.inference', '{"id":"f1a2b3c4-0004-4004-8004-000000000003","mode":"practice","parentId":"f1a2b3c4-0004-4004-8004-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states Beaufort ''retired from the Admiralty in 1855 and died two years later''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"e9d19772c4805aec51e951e41dce8e503919e165f8dfaa2d0a70716bd52debf0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0004-4004-8004-000000000004', 'vr', 'practice', 'f1a2b3c4-0004-4004-8004-000000000004'::uuid, 'vr.recognising_contradictions', '{"id":"f1a2b3c4-0004-4004-8004-000000000004","mode":"practice","parentId":"f1a2b3c4-0004-4004-8004-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the extensions ''were never widely adopted outside Taiwan and mainland China'' and that the World Meteorological Organization ''continues to use the original scale of 0 to 12 for international reporting''.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"07653aebaedb3437dd6c5d8832d46e486568de380c8ec53f8eb24102d49bedd7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0004-4004-8004-000000000005', 'vr', 'practice', 'f1a2b3c4-0004-4004-8004-000000000005'::uuid, 'vr.qualifiers_and_scope', '{"id":"f1a2b3c4-0004-4004-8004-000000000005","mode":"practice","parentId":"f1a2b3c4-0004-4004-8004-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage states that in 1906 Simpson ''extended the scale to land-based observation'', but does not confirm he was the first to do so.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"82edacdc3b44d08952c786f8ce70a4aeb3780ad4d6a57716739d65602d6d0fa4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0807-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0807-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0807-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0807-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly states that takshif were guides ''employed for specific segments of the route'' whose knowledge of landmarks and water sources was indispensable.","difficulty":"normal","format":"mc","answer":"Local guides employed for specific segments of the route","options":["Senior merchants who negotiated prices at trading centres","Owners of the pack camels used in the caravans","Local guides employed for specific segments of the route","Soldiers hired to protect caravans from bandits"],"contentHash":"75b017e535c153f590441a73f35c9c76a28f38802e695617fdc09dac55c49981"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0807-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0807-4a01-9f11-000000000003'::uuid, 'vr.author_perspective', '{"id":"c4a1b8e2-0807-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0807-4a01-9f11-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes that ''historians have cautioned that such accounts may reflect rhetorical flourishes rather than strict commercial practice'', indicating qualified scepticism rather than full acceptance or rejection.","difficulty":"hard","format":"mc","answer":"As accounts whose literal accuracy has been questioned by later historians","options":["As reliable contemporary evidence of precise commercial practice","As accounts whose literal accuracy has been questioned by later historians","As fabrications invented by European visitors to discredit African trade","As evidence that gold was less valuable than salt in the interior"],"contentHash":"e52a510b794551cf26dcf74af38eb953c89067629f6b2e44d4245d3cd3d2c4ff"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0807-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0807-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0807-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0807-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''regions producing gold often lacked accessible salt deposits'', directly supporting the option.","difficulty":"normal","format":"mc","answer":"Gold-producing regions often lacked accessible sources of salt","options":["Salt was used as a form of currency throughout the region","Gold-producing regions often lacked accessible sources of salt","Salt was the only commodity accepted at Timbuktu for the purchase of slaves","Salt could be refined into more valuable compounds by inland traders"],"contentHash":"abce882ea64418d5a7aecf2fa9fdc4cb700d15db4ac02150cb24e8007808510b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0807-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0807-4a01-9f11-000000000005'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0807-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0807-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly attributes the decline to the opening of maritime routes and the availability of salt through Atlantic commerce.","difficulty":"normal","format":"mc","answer":"The opening of maritime routes around the West African coast","options":["Depletion of the Taghaza salt deposits in the sixteenth century","The loss of Berber political influence in the northern oases","The opening of maritime routes around the West African coast","A long-term decline in the gold production of the forest regions"],"contentHash":"e384cb8511777433ed2f9676bd3622b3dfd9234404bfc2914ef40739c6eb8f8b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e70', 'vr', 'practice', '5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e70'::uuid, 'vr.explicit_information', '{"id":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e70","mode":"practice","parentId":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e6f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''British mathematicians, out of loyalty to Newton, continued using his less tractable fluxion notation for more than a century'' while Continental mathematicians built upon Leibniz''s more flexible system — explicitly linking this to the productivity gap.","difficulty":"normal","format":"mc","answer":"Loyalty to Newton kept British mathematicians using a less flexible notation","options":["A shortage of trained mathematicians at British universities","Loyalty to Newton kept British mathematicians using a less flexible notation","Leibniz''s notation was officially banned in British institutions","Babbage''s reform movement failed to gain support at Cambridge"],"contentHash":"c6446d26eb8d866a0a667054651e74c3d15db4b4fe2805b77712e7d2e10a2e51"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e71', 'vr', 'practice', '5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e71'::uuid, 'vr.explicit_information', '{"id":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e71","mode":"practice","parentId":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e6f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Modern historians generally accept that the two mathematicians worked independently'', directly answering the question.","difficulty":"normal","format":"mc","answer":"The two men arrived at their methods independently of one another","options":["Newton invented the calculus first and Leibniz drew on his unpublished work","Leibniz invented the calculus and Newton''s fluxions were a later imitation","The two men arrived at their methods independently of one another","The dispute cannot be resolved because the relevant evidence is lost"],"contentHash":"59a1b0b1bb23b58758d5cf183a6429b9c08f0b2e0b8410776274361437363f71"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e72', 'vr', 'practice', '5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e72'::uuid, 'vr.inference', '{"id":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e72","mode":"practice","parentId":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e6f","primarySkillId":"vr.inference","secondarySkillIds":["vr.author_perspective"],"confidence":"medium","rationale":"The passage notes the committee was ''chaired by Newton himself'' and ruled in his favour ''unsurprisingly'' — signalling the author views it as a predictable consequence of that conflict of interest.","difficulty":"hard","format":"mc","answer":"Compromised by a conflict of interest","options":["A balanced and impartial verdict accepted by most later scholars","Compromised by a conflict of interest","The formal beginning of the priority dispute","Written jointly by Newton and Leibniz''s supporters"],"contentHash":"7427611d447eb347b6c3fdc919a769c54f53caa92906973902e586f77db606f0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e73', 'vr', 'practice', '5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e73'::uuid, 'vr.explicit_information', '{"id":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e73","mode":"practice","parentId":"5b0c73e4-9a6f-4c3d-b7e8-4f8a0c3d5e6f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Newton''s notation survives mainly in physics, where a dot over a variable still denotes a derivative with respect to time.''","difficulty":"normal","format":"mc","answer":"Is still used in physics for time derivatives","options":["Has been completely abandoned in all fields","Is still used in physics for time derivatives","Was adopted by Continental mathematicians after Newton''s death","Was preferred by Leibniz in his later work"],"contentHash":"1607b4cb021dcae5d016284048784a91ab98d2fd8f208dcf1c3649b92a76019e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0007-4007-8007-000000000002', 'vr', 'practice', 'f1a2b3c4-0007-4007-8007-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"f1a2b3c4-0007-4007-8007-000000000002","mode":"practice","parentId":"f1a2b3c4-0007-4007-8007-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Riquet was ''a tax collector by profession rather than a trained engineer'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"2730633ff247bd199ddec6c8fb52bc2e3f3d962fe54ddd0086e8906e8e46c0fb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0007-4007-8007-000000000003', 'vr', 'practice', 'f1a2b3c4-0007-4007-8007-000000000003'::uuid, 'vr.recognising_contradictions', '{"id":"f1a2b3c4-0007-4007-8007-000000000003","mode":"practice","parentId":"f1a2b3c4-0007-4007-8007-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Riquet ''died in October 1680, six months before the canal opened for commercial traffic''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"50ad6024333d6b64373a57312a84a7ab652b2af4282f381244c5399d9c840342"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0007-4007-8007-000000000004', 'vr', 'practice', 'f1a2b3c4-0007-4007-8007-000000000004'::uuid, 'vr.unsupported_claims', '{"id":"f1a2b3c4-0007-4007-8007-000000000004","mode":"practice","parentId":"f1a2b3c4-0007-4007-8007-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Riquet was ''a tax collector by profession rather than a trained engineer'' and refers to ''several years of informal surveying'' of streams and catchments, but does not indicate whether he had worked on any other canal projects beforehand.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"ce7304cc85b8678b2f36419df0d338648ee2feb68e942ed2f43af0e75d5443de"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0007-4007-8007-000000000005', 'vr', 'practice', 'f1a2b3c4-0007-4007-8007-000000000005'::uuid, 'vr.inference', '{"id":"f1a2b3c4-0007-4007-8007-000000000005","mode":"practice","parentId":"f1a2b3c4-0007-4007-8007-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the canal ''remained profitable until the expansion of the French railway network in the mid-nineteenth century made barge transport increasingly uncompetitive''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"329477be25f185fd3ad1643f005ceafded5cc2a81b07bbd1fbd4e6c3c0441bc7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
