INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f008-1008-4008-8008-000000000002', 'vr', 'practice', 'c7a1f008-1008-4008-8008-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f008-1008-4008-8008-000000000002","mode":"practice","parentId":"c7a1f008-1008-4008-8008-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the stele was discovered at Susa in present-day Iran, ''where it had been taken as war booty by the Elamites around 1150 BCE''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"28d8caee526f0e05e8ad04e9276ce397de2c0eae022bdd61a59e413c6829a427"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f008-1008-4008-8008-000000000003', 'vr', 'practice', 'c7a1f008-1008-4008-8008-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f008-1008-4008-8008-000000000003","mode":"practice","parentId":"c7a1f008-1008-4008-8008-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes how striking out the eye of an awīlum was punishable by the loss of the perpetrator''s own eye, whereas the same act committed against a muškēnum was punishable only by a monetary fine.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"124103808ca3503da3cddb2e3d12eaf103f737e717f74972aa9a50cda932da0e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f008-1008-4008-8008-000000000004', 'vr', 'practice', 'c7a1f008-1008-4008-8008-000000000004'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f008-1008-4008-8008-000000000004","mode":"practice","parentId":"c7a1f008-1008-4008-8008-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that ''The Code does not define the criteria by which a person was classified into each group'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"7594a49010a16340d70de038102d7cbcdde81d4025989256b6a37b0465c9c340"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f008-1008-4008-8008-000000000005', 'vr', 'practice', 'c7a1f008-1008-4008-8008-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f008-1008-4008-8008-000000000005","mode":"practice","parentId":"c7a1f008-1008-4008-8008-000000000001","primarySkillId":"vr.inference","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"medium","rationale":"The passage states the Code ''imposes strict liability on builders whose structures collapse and kill occupants, without reference to fault or intent''.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"d7c30a876520cd7ee24081bea9cd700ad27205009230eb2057b3c12021d17c57"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2009-4b09-9b09-000000000002', 'vr', 'practice', 'd2e3f4a5-2009-4b09-9b09-000000000002'::uuid, 'vr.author_perspective', '{"id":"d2e3f4a5-2009-4b09-9b09-000000000002","mode":"practice","parentId":"d2e3f4a5-2009-4b09-9b09-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Serafini has confirmed the script is ''asemic — shaped to resemble writing without encoding any specific meaning''.","difficulty":"normal","format":"mc","answer":"It is shaped to resemble writing but carries no semantic content","options":["It encodes a cipher that requires specialist training to decode","It is shaped to resemble writing but carries no semantic content","It is a form of Italian shorthand used in industrial design","Its meaning has been lost because the author refuses to release his notes"],"contentHash":"fef8d4cd3afe4a58ee167873f41a64c074619fd5e237c51dce8ea1b958fb2ca9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2009-4b09-9b09-000000000003', 'vr', 'practice', 'd2e3f4a5-2009-4b09-9b09-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"d2e3f4a5-2009-4b09-9b09-000000000003","mode":"practice","parentId":"d2e3f4a5-2009-4b09-9b09-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage establishes the Codex''s date (1981), its asemic script (Serafini''s position), and its partially cracked base-21 numbering.","difficulty":"normal","format":"mc","answer":"A 1981 illustrated work whose script is described by its author as meaningless and whose numbering system has been partially deciphered","options":["A 1981 illustrated work whose script is described by its author as meaningless and whose numbering system has been partially deciphered","A medieval manuscript that has resisted all decipherment attempts","A pseudoscientific encyclopedia that Serafini intended as a scientific reference","A novel translated from an invented language back into Italian"],"contentHash":"ca4c7f7903d29e2c63d6830557072c8d573bfedbb0fbdd89669d574dcc023fb8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2009-4b09-9b09-000000000004', 'vr', 'practice', 'd2e3f4a5-2009-4b09-9b09-000000000004'::uuid, 'vr.evaluating_evidence', '{"id":"d2e3f4a5-2009-4b09-9b09-000000000004","mode":"practice","parentId":"d2e3f4a5-2009-4b09-9b09-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"medium","rationale":"The passage presents Serafini''s view (asemic, no semantic content) alongside linguists'' findings of some patterns, which Serafini describes as incidental.","difficulty":"hard","format":"mc","answer":"It would tend to undermine Serafini''s stated position that the script is asemic","options":["It would have no effect, because Serafini''s claim is unrelated to the script''s properties","It would tend to undermine Serafini''s stated position that the script is asemic","It would prove that Serafini deliberately deceived his readers","It would show that the Codex was written before 1981"],"contentHash":"aed21d507283dd41b36eb6adea2275e12fcb76d0d494ef6ca7f46eaa5e70aa73"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2009-4b09-9b09-000000000005', 'vr', 'practice', 'd2e3f4a5-2009-4b09-9b09-000000000005'::uuid, 'vr.explicit_information', '{"id":"d2e3f4a5-2009-4b09-9b09-000000000005","mode":"practice","parentId":"d2e3f4a5-2009-4b09-9b09-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the glossary was described by Serafini himself ''as playful rather than authoritative'' — meaning it was not intended as a definitive reading.","difficulty":"hard","format":"mc","answer":"The ''decodex'' glossary was not intended as a definitive translation","options":["The ''decodex'' glossary was not intended as a definitive translation","The 2013 edition of the Codex is rarer than the 1981 first edition","Serafini has retracted his statement that the script is asemic","All illustrations in the Codex depict real but rare organisms"],"contentHash":"2595d451008191078158548ef3642180f3cb552d7ba6e09670e6810288f3ee60"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0609-4a09-9d09-000000000901', 'vr', 'practice', 'c7a1e4b2-0609-4a09-9d09-000000000901'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0609-4a09-9d09-000000000901","mode":"practice","parentId":"c7a1e4b2-0609-4a09-9d09-000000000009","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Congress was called ''in response to the Treaty of San Stefano'' and notes the alarm of Britain and Austria-Hungary, framing the Congress as a mechanism for recalibrating the settlement.","difficulty":"normal","format":"mc","answer":"To revise terms imposed by the Treaty of San Stefano that alarmed other European powers","options":["To end the Russo-Turkish War","To revise terms imposed by the Treaty of San Stefano that alarmed other European powers","To formally annex Bosnia and Herzegovina into Austria-Hungary","To grant Cyprus independence from Ottoman rule"],"contentHash":"5db1252805d9e6e24d4f581c78ea7c10b7063b4b840d1450f31de2e9a4b0c8a2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0609-4a09-9d09-000000000902', 'vr', 'practice', 'c7a1e4b2-0609-4a09-9d09-000000000902'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0609-4a09-9d09-000000000902","mode":"practice","parentId":"c7a1e4b2-0609-4a09-9d09-000000000009","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Britain ''secured the administration of Cyprus through a separate convention concluded shortly before the Congress met'' — administration rather than formal sovereignty, and crucially through a separate convention rather than the Treaty of Berlin.","difficulty":"hard","format":"mc","answer":"The formal transfer of Cyprus to British sovereignty","options":["Full independence for Serbia and Montenegro","The authorisation of Austrian administration of Bosnia and Herzegovina under the Treaty","The formal transfer of Cyprus to British sovereignty","The division of the proposed Bulgarian state into three zones"],"contentHash":"6814317599edc4e897c0638baa38fc9349af0013088fef0af330d3305e484915"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0609-4a09-9d09-000000000903', 'vr', 'practice', 'c7a1e4b2-0609-4a09-9d09-000000000903'::uuid, 'vr.author_perspective', '{"id":"c7a1e4b2-0609-4a09-9d09-000000000903","mode":"practice","parentId":"c7a1e4b2-0609-4a09-9d09-000000000009","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage presents ''some historians'' arguing the Congress postponed conflict while ''others argue'' it left unresolved tensions — an evenhanded framing of historiographical disagreement rather than an endorsement of either view.","difficulty":"normal","format":"mc","answer":"Historians disagree about whether the Congress postponed or contributed to later regional instability","options":["The Congress was a clear diplomatic failure whose effects were destructive","The Congress was universally praised as the foundation of lasting peace","Historians disagree about whether the Congress postponed or contributed to later regional instability","The Congress had no significant long-term consequences"],"contentHash":"e79c365b6936422c34201c53f2427986a3de9e879a4a70ff67fe4fb10a677330"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0609-4a09-9d09-000000000904', 'vr', 'practice', 'c7a1e4b2-0609-4a09-9d09-000000000904'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0609-4a09-9d09-000000000904","mode":"practice","parentId":"c7a1e4b2-0609-4a09-9d09-000000000009","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes Austria-Hungary was permitted ''to occupy and administer'' Bosnia while ''sovereignty formally remained with the Ottoman Empire until 1908'' — highlighting a gap between administrative control and formal sovereignty.","difficulty":"hard","format":"mc","answer":"To distinguish between the administrative and formal arrangements established at the Congress","options":["To argue that Austria-Hungary had no real authority in Bosnia before 1908","To distinguish between the administrative and formal arrangements established at the Congress","To indicate that the Ottoman Empire had ceased to exist by 1908","To suggest that Russia blocked Austrian annexation at the Congress"],"contentHash":"5b97ed6d1a8f0d11df916863edbeab8e892377a0edf80a3726620dee9c221a96"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0605-4a05-9d05-000000000501', 'vr', 'practice', 'c7a1e4b2-0605-4a05-9d05-000000000501'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0605-4a05-9d05-000000000501","mode":"practice","parentId":"c7a1e4b2-0605-4a05-9d05-000000000005","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states tin was extracted ''initially through streaming ...","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"6889edeea020b786873d259f52be33d1d5852971c6523b9ae40b539ce96d002b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0605-4a05-9d05-000000000502', 'vr', 'practice', 'c7a1e4b2-0605-4a05-9d05-000000000502'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0605-4a05-9d05-000000000502","mode":"practice","parentId":"c7a1e4b2-0605-4a05-9d05-000000000005","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''By the medieval period, Cornish tin was regulated under the Stannary system''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"d4eff31029fdb693b9b30dba4dbe4010f55406a51904b5e71f62f103c045f2b8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0605-4a05-9d05-000000000503', 'vr', 'practice', 'c7a1e4b2-0605-4a05-9d05-000000000503'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0605-4a05-9d05-000000000503","mode":"practice","parentId":"c7a1e4b2-0605-4a05-9d05-000000000005","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage attributes decline to the discovery of ''large tin deposits in Malaya and Bolivia'' which ''progressively undercut Cornish prices'' — an economic rather than geological cause.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"0d74182414c0489ece41a5ae307e94797dd506394a787e9faeea01ca85c33722"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0605-4a05-9d05-000000000504', 'vr', 'practice', 'c7a1e4b2-0605-4a05-9d05-000000000504'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0605-4a05-9d05-000000000504","mode":"practice","parentId":"c7a1e4b2-0605-4a05-9d05-000000000005","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage identifies Ictis with ''St Michael''s Mount or a similar tidal island'' but makes no claim about relative size.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"e0d81e7ca4ef192398d4f14694846977dc14a81d0d40183a4f45e638e86fb87e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:23fdf305-2961-4c68-a008-f4d600919662', 'vr', 'practice', '23fdf305-2961-4c68-a008-f4d600919662'::uuid, 'vr.unsupported_claims', '{"id":"23fdf305-2961-4c68-a008-f4d600919662","mode":"practice","parentId":"628f27b8-3c9f-482f-b303-8c7dce1f97af","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"low","rationale":"Unsupported False key: the passage identifies who commissioned the early pen, not the inventor or the inventor''s nationality.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"excludedReason":"Unsupported False key: the passage identifies who commissioned the early pen, not the inventor or the inventor''s nationality.","contentHash":"b8c97f45416d8de14c3e4416ae45080e62545cfc6c33d135896f428f53d7c223"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:6859990a-2fff-4e17-aa58-0d1e68916db4', 'vr', 'practice', '6859990a-2fff-4e17-aa58-0d1e68916db4'::uuid, 'vr.explicit_information', '{"id":"6859990a-2fff-4e17-aa58-0d1e68916db4","mode":"practice","parentId":"628f27b8-3c9f-482f-b303-8c7dce1f97af","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Waterman''s feed system allowed ink to flow ''without flooding the paper or drying out during use'' and that ''earlier reservoir pens had struggled with one of these two failures''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"e76bc44c767c479eada02cdd66af5a51afa240efbf1ae3b96530ffed86840c33"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:a6c4a23c-4e61-4ae0-8310-d2dd1690761f', 'vr', 'practice', 'a6c4a23c-4e61-4ae0-8310-d2dd1690761f'::uuid, 'vr.recognising_contradictions', '{"id":"a6c4a23c-4e61-4ae0-8310-d2dd1690761f","mode":"practice","parentId":"628f27b8-3c9f-482f-b303-8c7dce1f97af","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''converter systems allow cartridge pens to draw ink from a bottle'', directly contradicting the claim that cartridge pens cannot use bottled ink.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"83caae0bc17cad1fda19523d841509c857e064204c4255134d5d6894d1e78fce"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f65dd325-0a55-4981-9c4a-24dd1c8030d3', 'vr', 'practice', 'f65dd325-0a55-4981-9c4a-24dd1c8030d3'::uuid, 'vr.unsupported_claims', '{"id":"f65dd325-0a55-4981-9c4a-24dd1c8030d3","mode":"practice","parentId":"628f27b8-3c9f-482f-b303-8c7dce1f97af","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes that fountain pen use declined after the introduction of ballpoint pens, but it does not compare the reliability of the two types.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"7500ff294b2eb5f2db495a84504a8b88d12258edf8b71762b5e72da80556e73f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f019-1019-4019-8019-000000000002', 'vr', 'practice', 'c7a1f019-1019-4019-8019-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f019-1019-4019-8019-000000000002","mode":"practice","parentId":"c7a1f019-1019-4019-8019-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Pasteur was initially commissioned to investigate spoilage in the French wine industry, not dairy products, and his early publications addressed fermentation faults in wine and beer.''","difficulty":"normal","format":"mc","answer":"The French wine industry","options":["The dairy industry","The French wine industry","The meat preservation industry","The brewing industry in Germany"],"contentHash":"412120e07784fb0eeb961b2f9555356520bc01298f72515b9ff0fe5f5175cc34"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f019-1019-4019-8019-000000000003', 'vr', 'practice', 'c7a1f019-1019-4019-8019-000000000003'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1f019-1019-4019-8019-000000000003","mode":"practice","parentId":"c7a1f019-1019-4019-8019-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Pasteur''s temperatures ''were below those needed for sterilisation, which meant some organisms survived but population levels were reduced to the point where spoilage was significantly delayed'', implying sterilisation achieves complete elimination whereas pasteurisation does not.","difficulty":"normal","format":"mc","answer":"Pasteurisation reduces microbial populations substantially but does not necessarily eliminate all organisms, whereas sterilisation aims for complete elimination","options":["Pasteurisation uses higher temperatures than sterilisation","Pasteurisation reduces microbial populations substantially but does not necessarily eliminate all organisms, whereas sterilisation aims for complete elimination","Pasteurisation and sterilisation are the same process under different names","Sterilisation is used only for dairy products"],"contentHash":"b07ef0342a7153fda3a6f24a31d46eb768b9c6d24039764bab2680fbf1585c37"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f019-1019-4019-8019-000000000004', 'vr', 'practice', 'c7a1f019-1019-4019-8019-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f019-1019-4019-8019-000000000004","mode":"practice","parentId":"c7a1f019-1019-4019-8019-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the adoption of pasteurisation in milk ''was a matter of public health rather than commercial preservation'' and specifically mentions Mycobacterium bovis and bovine tuberculosis transmitted through contaminated milk.","difficulty":"normal","format":"mc","answer":"To reduce the transmission of pathogens such as Mycobacterium bovis to consumers","options":["To extend the shelf life of milk for commercial advantage","To reduce the transmission of pathogens such as Mycobacterium bovis to consumers","To standardise the flavour of milk across different producers","To comply with international trade agreements"],"contentHash":"97fc446b6ce32a45759511b3c5699351e0a642e76049f58cd4d24422bb801a24"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f019-1019-4019-8019-000000000005', 'vr', 'practice', 'c7a1f019-1019-4019-8019-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f019-1019-4019-8019-000000000005","mode":"practice","parentId":"c7a1f019-1019-4019-8019-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states ultra-high-temperature processing ''produces a product that can be stored without refrigeration'', which is the only method described as yielding room-temperature-stable milk.","difficulty":"hard","format":"mc","answer":"Ultra-high-temperature processing","options":["The holder or batch method","High-temperature short-time processing","Ultra-high-temperature processing","Any of the three methods, as all produce shelf-stable milk"],"contentHash":"e6ac50e4ef43b865d5bafef425376871e6ce69abf61e86a85716fc5db3bd00a8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0804-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0804-4a01-9f11-000000000002'::uuid, 'vr.evaluating_evidence', '{"id":"c4a1b8e2-0804-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0804-4a01-9f11-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly states that ''the mercury column fell measurably as altitude increased'' and that this was ''consistent with Torricelli''s pressure hypothesis''.","difficulty":"normal","format":"mc","answer":"It showed that the mercury column fell as altitude increased, consistent with reduced air pressure","options":["It showed that the mercury column remained at the same height regardless of altitude","It demonstrated that a true vacuum could be created above the mercury","It showed that the mercury column fell as altitude increased, consistent with reduced air pressure","It confirmed that the space above the mercury contained a subtle invisible substance"],"contentHash":"09ff7f8aa391d015c2be2b34d3173f4b07d5745ac67ab93ea7f12902a44b3ac4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0804-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0804-4a01-9f11-000000000003'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0804-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0804-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the aneroid design ''permitted the construction of portable and robust instruments'' used in ''meteorology, aviation, and mountaineering''.","difficulty":"normal","format":"mc","answer":"It was portable and robust, allowing use in mobile applications","options":["It was capable of measuring a wider range of pressures","It was more accurate than mercury-based instruments","It did not rely on the controversial assumption of a vacuum","It was portable and robust, allowing use in mobile applications"],"contentHash":"491aaace46a05b85f15577a671ebb1e8f3dfe3a221e9a4fdd6443754b4517b88"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0804-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0804-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0804-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0804-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Torricelli ''had briefly served as secretary to Galileo Galilei in the final months of the astronomer''s life''.","difficulty":"normal","format":"mc","answer":"Torricelli briefly served as Galileo''s secretary near the end of Galileo''s life","options":["Torricelli had been Galileo''s student throughout Galileo''s career","Torricelli briefly served as Galileo''s secretary near the end of Galileo''s life","Torricelli developed the barometer under Galileo''s direct supervision","Torricelli and Galileo collaborated closely on the problem of atmospheric pressure"],"contentHash":"5f9f1b8a00082fdf12460a139d7d4d908f2b116cbae18198d66ea864d7211a83"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0804-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0804-4a01-9f11-000000000005'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0804-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0804-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Aristotelian natural philosophers as rejecting Torricelli''s interpretation on the grounds that nature abhorred a vacuum, and notes this debate was ''substantially resolved'' only after Pascal''s experiment.","difficulty":"hard","format":"mc","answer":"It is presented as a background intellectual tradition that initially impeded acceptance of Torricelli''s interpretation","options":["It is presented as the framework that Torricelli himself used to interpret his apparatus","It is presented as a background intellectual tradition that initially impeded acceptance of Torricelli''s interpretation","It is presented as the dominant influence on Pascal''s experimental methodology","It is presented as having been fully discredited by the invention of the aneroid barometer"],"contentHash":"59095c48ce4a6621a67de3db6e0d3ed830c03e834a527af822e22c47ebe12ec8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0603-4a03-9d03-000000000301', 'vr', 'practice', 'c7a1e4b2-0603-4a03-9d03-000000000301'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0603-4a03-9d03-000000000301","mode":"practice","parentId":"c7a1e4b2-0603-4a03-9d03-000000000003","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''No clock then available could maintain the accuracy required over a long sea voyage, during which changes in temperature, humidity, and the motion of the vessel disturbed the regularity of the mechanism.''","difficulty":"normal","format":"mc","answer":"Existing clocks could not maintain accuracy under shipboard conditions","options":["Sailors lacked the training to read clocks accurately","Existing clocks could not maintain accuracy under shipboard conditions","Clocks were too expensive to be installed on most vessels","Local time could not be estimated accurately from the sun at sea"],"contentHash":"b6f0209366c33e432d20164f4385fe655aa2ca00a907da27ca5592f333dd347f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0603-4a03-9d03-000000000302', 'vr', 'practice', 'c7a1e4b2-0603-4a03-9d03-000000000302'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0603-4a03-9d03-000000000302","mode":"practice","parentId":"c7a1e4b2-0603-4a03-9d03-000000000003","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Board ''initially favoured an alternative approach known as the lunar distance method'', and that ''Harrison received partial payments but did not receive formal acknowledgement of the prize in the manner he had sought''.","difficulty":"hard","format":"mc","answer":"It favoured a rival method and gave Harrison only partial payments","options":["It fully supported Harrison and awarded him the prize immediately","It favoured a rival method and gave Harrison only partial payments","It rejected Harrison''s designs as technically unworkable","It referred the matter directly to King George III without review"],"contentHash":"ac8f0ec1ef96a455a701b380e013b5db56b057d799cc70c7a42b33b567f8f0a6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0603-4a03-9d03-000000000303', 'vr', 'practice', 'c7a1e4b2-0603-4a03-9d03-000000000303'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0603-4a03-9d03-000000000303","mode":"practice","parentId":"c7a1e4b2-0603-4a03-9d03-000000000003","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes Maskelyne was a member of the Board and that the Board favoured the lunar distance method, but it does not state that Maskelyne personally withheld prize money.","difficulty":"hard","format":"mc","answer":"Maskelyne personally withheld Harrison''s prize money","options":["Harrison''s H4 was completed in 1759","The lunar distance method relied on the moon''s angular distance from fixed stars","Harrison''s earlier designs were larger than H4","Maskelyne personally withheld Harrison''s prize money"],"contentHash":"04ca750316027f0c6ed5781f8c5e20057a0c0400e29a8f42ae12085e9926c008"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0603-4a03-9d03-000000000304', 'vr', 'practice', 'c7a1e4b2-0603-4a03-9d03-000000000304'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0603-4a03-9d03-000000000304","mode":"practice","parentId":"c7a1e4b2-0603-4a03-9d03-000000000003","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage opens by describing the longitude problem, explains why it was difficult, and describes Harrison''s efforts and the institutional resistance he encountered — a narrative arc centred on a technical problem and its solution.","difficulty":"normal","format":"mc","answer":"An account of a technical problem in navigation and the prolonged effort to solve it","options":["An account of a technical problem in navigation and the prolonged effort to solve it","A biography of John Harrison and his family life","A critique of the Board of Longitude''s administrative practices","A comparison of the lunar distance method with modern navigation"],"contentHash":"31f6cd4bc298ef272705877d37752d64df0f6f3142140257a09acf4e0a31791f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0813-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0813-4a01-9f11-000000000002'::uuid, 'vr.meaning_in_context', '{"id":"c4a1b8e2-0813-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0813-4a01-9f11-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly defines phossy jaw as a condition ''in which the jawbone became necrotic'', associated with workers handling white phosphorus.","difficulty":"normal","format":"mc","answer":"A condition in which the jawbone became necrotic, associated with white phosphorus exposure","options":["A disease caused by inhaling smoke from burning match heads","A condition in which the jawbone became necrotic, associated with white phosphorus exposure","A disfiguring rash caused by red phosphorus","A respiratory disease affecting children working in match factories"],"contentHash":"4fefb3f1f6fa6db9e054b773981615357684d4063ac860c2aa9082a21dfa1d12"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0813-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0813-4a01-9f11-000000000003'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0813-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0813-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Walker''s matches ''could fail to ignite entirely, or could instead project burning fragments a considerable distance, causing clothing fires''.","difficulty":"normal","format":"mc","answer":"They could fail to ignite, or could project burning fragments and cause injury","options":["They required a specialised striking surface that was not widely available","They could fail to ignite, or could project burning fragments and cause injury","They contained white phosphorus and caused widespread occupational disease","They were prohibitively expensive compared with alternative ignition methods"],"contentHash":"c3065412ef8cbbed62f38b186cef7f010bf139fa3be581d85e894ef9c001bc6e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0813-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0813-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0813-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0813-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states later designs ''incorporated waterproof coatings that ignited as part of the striking reaction, eliminating the scraping step''.","difficulty":"normal","format":"mc","answer":"They incorporated waterproof coatings that ignited as part of the striking reaction, eliminating the need to scrape","options":["They used red phosphorus instead of white phosphorus in the match head","They were effective even after submersion in seawater for several days","They incorporated waterproof coatings that ignited as part of the striking reaction, eliminating the need to scrape","They were substantially cheaper to manufacture than conventional matches"],"contentHash":"db484c63ec7e8de8e9da1d4bfcd5635dffa858d2ee8e83b8b11a48dd451d3524"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0813-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0813-4a01-9f11-000000000005'::uuid, 'vr.inference', '{"id":"c4a1b8e2-0813-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0813-4a01-9f11-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states red phosphorus ''had been discovered in 1844 and was already displacing white phosphorus in more carefully regulated markets'', before the 1906 Berne Convention.","difficulty":"hard","format":"mc","answer":"Red phosphorus was already replacing white phosphorus in regulated markets before the Berne Convention","options":["Red phosphorus was discovered after the Berne Convention banned white phosphorus","Waterproof matches were developed principally in response to civilian demand","The Berne Convention ended the use of white phosphorus in all countries worldwide","Red phosphorus was already replacing white phosphorus in regulated markets before the Berne Convention"],"contentHash":"170dba9ddc3f6860f96148acaefd6bb9817fc52ef244e1a31936209630c6ea3d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f014-1014-4014-8014-000000000002', 'vr', 'practice', 'c7a1f014-1014-4014-8014-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f014-1014-4014-8014-000000000002","mode":"practice","parentId":"c7a1f014-1014-4014-8014-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the name ''zipper'' ''was coined by the B.F.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"6918a252e8f0d726dbc573408310042d40a9cdbce41090c0a16dc69ee6608a51"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f014-1014-4014-8014-000000000003', 'vr', 'practice', 'c7a1f014-1014-4014-8014-000000000003'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f014-1014-4014-8014-000000000003","mode":"practice","parentId":"c7a1f014-1014-4014-8014-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"low","rationale":"Key conflict: the passage identifies Howe''s 1851 patent as a clothing closure, contradicting the sewing-machine claim rather than leaving it unknown.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"excludedReason":"Key conflict: the passage identifies Howe''s 1851 patent as a clothing closure, contradicting the sewing-machine claim rather than leaving it unknown.","contentHash":"125abd10dde201daf5df2d94fb5f90cfa2954ea5b0524e24f4166d56bae92674"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
