INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0009-4009-8009-000000000004', 'vr', 'practice', 'f1a2b3c4-0009-4009-8009-000000000004'::uuid, 'vr.author_perspective', '{"id":"f1a2b3c4-0009-4009-8009-000000000004","mode":"practice","parentId":"f1a2b3c4-0009-4009-8009-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage says ''advocates have argued'' the layout lowers RSI risk, but this is presented as a claim by proponents rather than an established fact.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"67aac3b5afa280576e8d4fafd818f887ce6af904ea416cf3139b6ae9903a9243"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0009-4009-8009-000000000005', 'vr', 'practice', 'f1a2b3c4-0009-4009-8009-000000000005'::uuid, 'vr.author_perspective', '{"id":"f1a2b3c4-0009-4009-8009-000000000005","mode":"practice","parentId":"f1a2b3c4-0009-4009-8009-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"medium","rationale":"The passage states David cited QWERTY as an example of path dependence, where an arbitrary choice becomes locked in ''even when alternatives might be more efficient''.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"fba7efeaa53fca4a0814a44e2e324b4af74034f288e3513967e7a838f72bc7b6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0815-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0815-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0815-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0815-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states their principal technique was ''to prevent spread by demolishing buildings in the path of the fire to create gaps'', since direct extinguishing methods were of limited effectiveness.","difficulty":"normal","format":"mc","answer":"Demolishing buildings in the path of the fire to create firebreaks","options":["Directing high-pressure water from pumps onto the centre of the blaze","Demolishing buildings in the path of the fire to create firebreaks","Evacuating residents from threatened areas before the fire reached them","Excavating trenches to starve the fire of combustible material"],"contentHash":"cf97c62ae92adc883943b6c460cb0de8da273c1063ce5c2f57c74fc28f4f0972"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0815-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0815-4a01-9f11-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0815-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0815-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage states tattoos were ''partly intended to be visible when the jackets were removed after action, conferring a form of social prestige''.","difficulty":"normal","format":"mc","answer":"Tattoos were visible when jackets were removed, conferring a form of social prestige","options":["Tattoos served as identification marks that replaced written records of service","Tattoos were visible when jackets were removed, conferring a form of social prestige","Tattoos were believed to provide spiritual protection against burns","Tattoos concealed scars from previous encounters with fire"],"contentHash":"dacd246d743b5b06856ee3a1be150e32aa4d2e2dc6ce729e12e597b6ce9cb65c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0815-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0815-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0815-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0815-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that ''the banners carried by each company were placed atop buildings to claim a structure for demolition''.","difficulty":"normal","format":"mc","answer":"To be placed atop buildings to claim a structure for demolition","options":["To signal instructions silently between members of the same company","To identify the company to passers-by and recruit new members","To be placed atop buildings to claim a structure for demolition","To display the names of firefighters who had died in earlier fires"],"contentHash":"ef33db810235c3ed23f32fe4f0220c8e2d1fecd545575ead062154b6b20ea860"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0815-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0815-4a01-9f11-000000000005'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0815-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0815-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage moves from describing the city''s vulnerability to fire, to the emergence of brigades, to their methods, composition, and visible culture.","difficulty":"hard","format":"mc","answer":"Frequent fires in Edo prompted the development of distinctive brigades whose methods, composition, and culture reflected the conditions of the city","options":["The Meireki fire was the single most destructive event in the Edo period","Frequent fires in Edo prompted the development of distinctive brigades whose methods, composition, and culture reflected the conditions of the city","Fire brigades in Edo were hampered by samurai-townsman rivalries that prevented effective response","Edo period fire brigades were primarily decorative institutions that achieved little in practice"],"contentHash":"b77838625bcfbf6087e0252ba4efbe6c1a043e53a90e87b3b9a9fd9f53bdb9d4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0614-4a14-9d14-000000001401', 'vr', 'practice', 'c7a1e4b2-0614-4a14-9d14-000000001401'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1e4b2-0614-4a14-9d14-000000001401","mode":"practice","parentId":"c7a1e4b2-0614-4a14-9d14-000000000014","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states royal forests ''were legal jurisdictions rather than continuous woodland'' and included ''open heath, grazing land, and settlements'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"f79f795281db8c72b54798788bd3a202245c62733a3b2c31a780022a3b208d8e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
