INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0614-4a14-9d14-000000001403', 'vr', 'practice', 'c7a1e4b2-0614-4a14-9d14-000000001403'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0614-4a14-9d14-000000001403","mode":"practice","parentId":"c7a1e4b2-0614-4a14-9d14-000000000014","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Corporation ''acquired commoner rights through a strategic purchase'' and subsequently sponsored the legal case after Willingale''s death.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"9961aa096db392684dc7087a5b0af5c2e47faac2b40061607441d411638e2ebe"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0614-4a14-9d14-000000001404', 'vr', 'practice', 'c7a1e4b2-0614-4a14-9d14-000000001404'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1e4b2-0614-4a14-9d14-000000001404","mode":"practice","parentId":"c7a1e4b2-0614-4a14-9d14-000000000014","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage describes the 1882 dedication as ''a turning point in the public conservation of open land'' but does not identify the 1878 Act as the first such legislation.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"89397dfaf24f770f5b8e97b1efa3f1685d99150f03addbf9874c792aaf11832d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f006-1006-4006-8006-000000000002', 'vr', 'practice', 'c7a1f006-1006-4006-8006-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f006-1006-4006-8006-000000000002","mode":"practice","parentId":"c7a1f006-1006-4006-8006-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''The earliest known extant book printed with metal movable type, the Jikji, was produced in 1377 at Heungdeok Temple in present-day Cheongju.''","difficulty":"normal","format":"mc","answer":"The Jikji, printed at Heungdeok Temple in 1377","options":["Gutenberg''s 42-line Bible, printed in 1451","The Jikji, printed at Heungdeok Temple in 1377","A Goryeo dynasty text from the early thirteenth century","A manuscript produced during the reign of King Sejong"],"contentHash":"d30641e015928400772b23347929aa13ab58fc03b02223d2f34956e52bf2c4ce"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f006-1006-4006-8006-000000000003', 'vr', 'practice', 'c7a1f006-1006-4006-8006-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f006-1006-4006-8006-000000000003","mode":"practice","parentId":"c7a1f006-1006-4006-8006-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the wax method ''limited the pressure that could be applied, which meant print runs were shorter and the impression was typically lighter than on European books of a comparable date.''","difficulty":"normal","format":"mc","answer":"The wax bed used to hold Korean type limited the pressure that could be applied during printing","options":["Korean type degraded more quickly than European type","The wax bed used to hold Korean type limited the pressure that could be applied during printing","Korean printing used inferior paper","Korean printers lacked skilled labour"],"contentHash":"1d4890f34d1e69e269d4c129e5f2734dc3931eb24c5f38b9a385c6501e9309f7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f006-1006-4006-8006-000000000004', 'vr', 'practice', 'c7a1f006-1006-4006-8006-000000000004'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f006-1006-4006-8006-000000000004","mode":"practice","parentId":"c7a1f006-1006-4006-8006-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage establishes Korean chronological priority and then explains that ''technical and linguistic differences help explain why Korean movable type, despite its chronological priority, did not produce the explosive growth in published works that followed Gutenberg''s innovation in Europe.''","difficulty":"hard","format":"mc","answer":"Korean movable type predated Gutenberg''s but did not have the same transformative effect due to technical and linguistic factors","options":["Gutenberg''s press was technologically inferior to the Korean system","Korean movable type predated Gutenberg''s but did not have the same transformative effect due to technical and linguistic factors","King Sejong''s alphabet was the most important innovation in Korean printing history","The commercial printing industry arose independently in Korea and Europe"],"contentHash":"369377f632f10c386565bd04e5e079ee15b6cbd7961fa32399c1e384e09944b9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f006-1006-4006-8006-000000000005', 'vr', 'practice', 'c7a1f006-1006-4006-8006-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f006-1006-4006-8006-000000000005","mode":"practice","parentId":"c7a1f006-1006-4006-8006-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states that Chinese characters used in formal Korean documents ''numbered in the tens of thousands, requiring an enormous inventory of type for any substantial printing project'', which implies a far larger inventory than an alphabetic system of a few dozen letters.","difficulty":"normal","format":"mc","answer":"The inventory of type required for printing Chinese characters was substantially larger than that required for printing a European alphabet","options":["Hangul was never used in printing during the fifteenth century","A single Korean print shop in the Goryeo dynasty required fewer type pieces than a European print shop of the same period","The inventory of type required for printing Chinese characters was substantially larger than that required for printing a European alphabet","Korean printers in the thirteenth century had access to the same metal alloys as Gutenberg"],"contentHash":"c1afb32185a9266103d9f4a1db7329344d8e6f3966448b67931a71f4a6b0aca7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0808-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0808-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0808-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0808-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the device as having eight dragon heads around its circumference, with a ball dropping from ''the dragon facing the direction of the tremor'' into a bronze toad below, which directly supports the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"8208c7c2219079a7af0db2ef2dcf6231a9040b21f20e588be7971dbf7c5696fa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0808-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0808-4a01-9f11-000000000003'::uuid, 'vr.recognising_contradictions', '{"id":"c4a1b8e2-0808-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0808-4a01-9f11-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the internal mechanism has not survived and modern reconstructions remain speculative'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"6d3d1951f881a06ac356f17d0db211f18676a4bc80f6557b20141f48aa145606"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0808-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0808-4a01-9f11-000000000004'::uuid, 'vr.qualifiers_and_scope', '{"id":"c4a1b8e2-0808-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0808-4a01-9f11-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage describes the instrument as the work of ''a group of British scientists working in Japan'', including Milne, Ewing, and Gray.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"68057b0954cb9114854a485629f1c9f557a8dcf3cbe5c8fd42d5e65bc1226817"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0808-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0808-4a01-9f11-000000000005'::uuid, 'vr.unsupported_claims', '{"id":"c4a1b8e2-0808-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0808-4a01-9f11-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the 1880 seismograph as producing a record of ground motion on smoked paper but says nothing about its use, or lack of use, for earthquake prediction.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"343ed69bfce503ce798dc8d61b64c0a7536fb0432e6f61a0b7e6b33c7b55651f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0607-4a07-9d07-000000000701', 'vr', 'practice', 'c7a1e4b2-0607-4a07-9d07-000000000701'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0607-4a07-9d07-000000000701","mode":"practice","parentId":"c7a1e4b2-0607-4a07-9d07-000000000007","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the vertical circle ''appeared intermittently in designs during the seventeenth century but became standard only with the work of Jesse Ramsden in the late eighteenth century''.","difficulty":"normal","format":"mc","answer":"A vertical circle for altitude measurement","options":["A magnetic compass","A horizontal angle scale","A vertical circle for altitude measurement","A telescopic sight"],"contentHash":"fa8ba0c8add4d3db221b0dfc63f2f0474d4ecf1991391fadc5112a20a7dbe4d8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0607-4a07-9d07-000000000702', 'vr', 'practice', 'c7a1e4b2-0607-4a07-9d07-000000000702'::uuid, 'vr.meaning_in_context', '{"id":"c7a1e4b2-0607-4a07-9d07-000000000702","mode":"practice","parentId":"c7a1e4b2-0607-4a07-9d07-000000000007","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage discusses the Great Trigonometrical Survey immediately before the phrase, and it is that Survey whose ''principal triangulation'' is meaningful in context.","difficulty":"normal","format":"mc","answer":"The Great Trigonometrical Survey of India","options":["The theodolite","The nineteenth century","The Great Trigonometrical Survey of India","The firm of Troughton and Simms"],"contentHash":"9fdf836148a78b8f64845c8842fa4ed12995b71248c162bfd0c40a2b7b4ef9cf"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0607-4a07-9d07-000000000703', 'vr', 'practice', 'c7a1e4b2-0607-4a07-9d07-000000000703'::uuid, 'vr.inference', '{"id":"c7a1e4b2-0607-4a07-9d07-000000000703","mode":"practice","parentId":"c7a1e4b2-0607-4a07-9d07-000000000007","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage links Ramsden''s dividing engine — ''a machine for marking the precise graduations on circular scales'' — directly to accuracy ''within a few seconds of arc'', indicating that such graduation advances enabled precision.","difficulty":"hard","format":"mc","answer":"Precise angular measurements depended on advances in scale graduation","options":["Ramsden invented the theodolite","Transit theodolites were invented in the eighteenth century","Precise angular measurements depended on advances in scale graduation","The Great Trigonometrical Survey of India used lightweight portable theodolites"],"contentHash":"23ad8bee67f092afa88bdbcfff980d40d9e8902a2750f36cc0a96ea3f3d50f5e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0607-4a07-9d07-000000000704', 'vr', 'practice', 'c7a1e4b2-0607-4a07-9d07-000000000704'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0607-4a07-9d07-000000000704","mode":"practice","parentId":"c7a1e4b2-0607-4a07-9d07-000000000007","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes the instruments ''weighed over half a tonne each and required teams of bearers for transport'', presented alongside the scale of the Indian survey — a detail that underscores the logistical demands of the work.","difficulty":"normal","format":"mc","answer":"To illustrate the practical challenges of large-scale surveying in the field","options":["To show that nineteenth-century theodolites were impractical for any survey work","To illustrate the practical challenges of large-scale surveying in the field","To argue that Troughton and Simms made inferior instruments compared with Ramsden","To explain why the Survey took so long to complete"],"contentHash":"56d57fff95b77207b2ea3fa21b64346c14d0a67268817a679cd22486cd6e8b82"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1006-4a06-9a06-000000000002', 'vr', 'practice', 'c1d2e3f4-1006-4a06-9a06-000000000002'::uuid, 'vr.main_idea_and_purpose', '{"id":"c1d2e3f4-1006-4a06-9a06-000000000002","mode":"practice","parentId":"c1d2e3f4-1006-4a06-9a06-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The final sentence explicitly frames these examples as applications where ''the basic principle...","difficulty":"normal","format":"mc","answer":"To demonstrate that Fresnel''s underlying optical principle remains in current use despite being superseded in lighthouses","options":["To argue that Fresnel lenses should be reintroduced in lighthouses","To demonstrate that Fresnel''s underlying optical principle remains in current use despite being superseded in lighthouses","To criticise modern lighthouse design for abandoning Fresnel optics","To show that Fresnel himself anticipated these later applications"],"contentHash":"a73ed64241d6d60d58aed221e33974631fcbca153ccfac52bc31297a5560b7e8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1006-4a06-9a06-000000000003', 'vr', 'practice', 'c1d2e3f4-1006-4a06-9a06-000000000003'::uuid, 'vr.explicit_information', '{"id":"c1d2e3f4-1006-4a06-9a06-000000000003","mode":"practice","parentId":"c1d2e3f4-1006-4a06-9a06-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Fresnel lens ''weighed a fraction of the plano-convex alternative and, crucially, transmitted a far greater proportion of the lamp''s light to the horizon''.","difficulty":"normal","format":"mc","answer":"It was lighter and transmitted more of the lamp''s light to the horizon","options":["It was cheaper to manufacture using local materials","It allowed ships to detect lighthouses during the day as well as at night","It was lighter and transmitted more of the lamp''s light to the horizon","It eliminated the need for a fuel-burning lamp at the focal point"],"contentHash":"6ed1980068d6fbdc3ef5e3c85039b3487d2414faba8e263ea4822adbde5f4a0c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1006-4a06-9a06-000000000004', 'vr', 'practice', 'c1d2e3f4-1006-4a06-9a06-000000000004'::uuid, 'vr.inference', '{"id":"c1d2e3f4-1006-4a06-9a06-000000000004","mode":"practice","parentId":"c1d2e3f4-1006-4a06-9a06-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage establishes that Fresnel''s design was introduced in France in 1822, that it was technically superior, and that British lighthouses (administered by Trinity House) ''did not adopt Fresnel optics widely until the 1830s'' — a gap of at least several years.","difficulty":"hard","format":"mc","answer":"It delayed adopting a technically superior lens for several years after its introduction in France","options":["It opposed Fresnel''s design on scientific grounds","It was the French authority responsible for lighthouse manufacture","It delayed adopting a technically superior lens for several years after its introduction in France","It invented the rotating beacons that eventually replaced Fresnel optics"],"contentHash":"c9ebffd758c6e52ba7dad46daf505d7f019a3f0251cc9a1f4a22c5f4f75243a9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1006-4a06-9a06-000000000005', 'vr', 'practice', 'c1d2e3f4-1006-4a06-9a06-000000000005'::uuid, 'vr.explicit_information', '{"id":"c1d2e3f4-1006-4a06-9a06-000000000005","mode":"practice","parentId":"c1d2e3f4-1006-4a06-9a06-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states: ''Fresnel classified his lenses into six orders according to focal length''.","difficulty":"normal","format":"mc","answer":"Into six orders according to focal length","options":["By the material from which they were manufactured","Into six orders according to focal length","By the intensity of the light source they were paired with","Into three categories for coastal, harbour, and buoy use"],"contentHash":"8dd4b8e18465567d4ad0cf0428a169d2a226207cff70d5e977c36651234fe89a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0820-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0820-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0820-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0820-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''some species have developed narrow, sharp beaks suited to extracting insects from bark'', directly supporting the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"966427ddc18d91a4e3f95dfe50214fa368756a1dd7a03aedd08af4817d226915"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0820-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0820-4a01-9f11-000000000003'::uuid, 'vr.recognising_contradictions', '{"id":"c4a1b8e2-0820-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0820-4a01-9f11-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that average beak depth ''increased detectably'' following the drought, as small soft seeds were unavailable and only larger harder seeds remained.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"062b6429b9d2058a6ad9c4e865174a9e5ea0c735534fd13a1a26c973259cb6ba"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0820-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0820-4a01-9f11-000000000004'::uuid, 'vr.unsupported_claims', '{"id":"c4a1b8e2-0820-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0820-4a01-9f11-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states BMP4 influences beak depth and ALX1 has been linked to beak shape, but provides no comparison of the strength of their effects.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"a494bee9f54001b7d16781468f60783a6e77155af295127f9f566e6613f5e95a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0820-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0820-4a01-9f11-000000000005'::uuid, 'vr.recognising_contradictions', '{"id":"c4a1b8e2-0820-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0820-4a01-9f11-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that hybridisation ''long considered rare, has also been documented'', directly contradicting the claim that it has never been documented.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"93b74c23741986af7de6c4116aba37dcad626c562b016596e7647f82664ff73b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0818-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0818-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0818-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0818-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the canal ''was conceived primarily as a grain-transport route'' to feed the northern capitals dependent on southern rice surpluses.","difficulty":"normal","format":"mc","answer":"To transport grain from the south to feed the northern capitals and armies","options":["To provide an economic boost to the Yangtze river regions","To transport grain from the south to feed the northern capitals and armies","To move soldiers rapidly between the capital and southern rebel regions","To facilitate the trade of luxury goods such as silk and porcelain"],"contentHash":"2165ad87f38f29c42956133a890e643d75dded7b0e684d7578ae26b2fcbfef54"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0818-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0818-4a01-9f11-000000000003'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0818-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0818-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the pound lock is ''sometimes attributed to the Song engineer Qiao Weiyue around 984 CE, several centuries before the form is documented in Europe''.","difficulty":"normal","format":"mc","answer":"It is sometimes attributed to a Song engineer several centuries before it is documented in Europe","options":["It was invented in Europe and introduced to China by Jesuit missionaries","Its attribution to Qiao Weiyue is disputed by most modern historians","It is sometimes attributed to a Song engineer several centuries before it is documented in Europe","It was the single innovation that enabled the canal to cross the Yellow River"],"contentHash":"5b8b53c9a3ffa2c1ec372efc2c5dd85e71e2016f3d38e2ab5998318520c8df8a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0818-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0818-4a01-9f11-000000000004'::uuid, 'vr.author_perspective', '{"id":"c4a1b8e2-0818-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0818-4a01-9f11-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Yang''s reign ''is often remembered in the traditional historiography as extravagant and ruinous''.","difficulty":"normal","format":"mc","answer":"His reign is often characterised as extravagant and ruinous in traditional accounts","options":["He is remembered as a visionary administrator whose projects were later vindicated","His reign is often characterised as extravagant and ruinous in traditional accounts","Traditional sources credit him with personally designing significant portions of the canal","His reputation has been rehabilitated by recent archaeological discoveries"],"contentHash":"81a90e7b7900ea087187a868cda6c73af5d6e8c2ae73960d28b4e492c6bd69d3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0818-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0818-4a01-9f11-000000000005'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0818-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0818-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly states the canal''s main route ''was progressively displaced by coastal shipping and railways'' in the nineteenth century.","difficulty":"normal","format":"mc","answer":"It was progressively displaced by coastal shipping and railways","options":["Silting of the Yellow River made maintenance economically unviable","The fall of the imperial state eliminated central demand for southern grain","It was progressively displaced by coastal shipping and railways","Local populations diverted canal water for irrigation, reducing its navigability"],"contentHash":"b6fe8ffeabd574212047e800bbd1bbdf5d4338fb6f2dbc8d521c0e9d31fccde6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0612-4a12-9d12-000000001201', 'vr', 'practice', 'c7a1e4b2-0612-4a12-9d12-000000001201'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0612-4a12-9d12-000000001201","mode":"practice","parentId":"c7a1e4b2-0612-4a12-9d12-000000000012","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Under Sher Shah Suri ...","difficulty":"normal","format":"mc","answer":"Sher Shah Suri","options":["Chandragupta Maurya","The Mughal emperors","Sher Shah Suri","The British colonial administration"],"contentHash":"35c73a067fc4f3b0692435bea4ecaae042a57fb1d331f20a6e792151f143fc4e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0612-4a12-9d12-000000001202', 'vr', 'practice', 'c7a1e4b2-0612-4a12-9d12-000000001202'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0612-4a12-9d12-000000001202","mode":"practice","parentId":"c7a1e4b2-0612-4a12-9d12-000000000012","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the road''s origins, reconstruction under Sher Shah, maintenance under the Mughals, widening under the British, and continued contemporary use — a pattern of successive adaptation over a long period.","difficulty":"normal","format":"mc","answer":"The road has ancient origins and has been successively adapted by different rulers into a continuously used route","options":["The road was created by the British in the nineteenth century for colonial administration","The road has ancient origins and has been successively adapted by different rulers into a continuously used route","The road fell out of use after the Mughal period and was only recently reopened","The road''s precise original alignment has been entirely lost"],"contentHash":"62894fc79deba2c169a78bfd98d0b4a8128e439f58b7344bd25ea4cfadc0779a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0612-4a12-9d12-000000001203', 'vr', 'practice', 'c7a1e4b2-0612-4a12-9d12-000000001203'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0612-4a12-9d12-000000001203","mode":"practice","parentId":"c7a1e4b2-0612-4a12-9d12-000000000012","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces Kim as the most famous example of the road featuring ''prominently in South Asian literature'', using it to illustrate the cultural dimension of the road''s history.","difficulty":"normal","format":"mc","answer":"To illustrate the road''s cultural presence in South Asian literature","options":["To argue that British writers were most responsible for the road''s preservation","To illustrate the road''s cultural presence in South Asian literature","To explain the origin of the name ''Grand Trunk Road''","To suggest that the road was little used in the nineteenth century"],"contentHash":"62492219b0bac6204fa3de74b45720cb30432e57f820787b97312fe52f71bae2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0612-4a12-9d12-000000001204', 'vr', 'practice', 'c7a1e4b2-0612-4a12-9d12-000000001204'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0612-4a12-9d12-000000001204","mode":"practice","parentId":"c7a1e4b2-0612-4a12-9d12-000000000012","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that no unified designation has been secured ''in part because the road crosses multiple modern states whose heritage coordination is limited'', directly supporting the inference.","difficulty":"hard","format":"mc","answer":"A unified UNESCO heritage designation is complicated by the road''s transnational character","options":["A unified UNESCO heritage designation is complicated by the road''s transnational character","The Mughals built the first version of the road","The original route has been entirely replaced by modern motorways","Kipling''s description of the road is considered historically inaccurate"],"contentHash":"de4db7fb9a02a743e94a88b083d3a9f9f11ed1c687810526b6aa80eac2f763fe"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1010-4a10-9a10-000000000002', 'vr', 'practice', 'c1d2e3f4-1010-4a10-9a10-000000000002'::uuid, 'vr.qualifiers_and_scope', '{"id":"c1d2e3f4-1010-4a10-9a10-000000000002","mode":"practice","parentId":"c1d2e3f4-1010-4a10-9a10-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states the farmers were ''many of them veterans of the First World War'', making prior military service a directly supported claim.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"14c572785b4da60bf0b7218ac28383929c6dc337b06c5eae6fde0faa2a51e93c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1010-4a10-9a10-000000000003', 'vr', 'practice', 'c1d2e3f4-1010-4a10-9a10-000000000003'::uuid, 'vr.inference', '{"id":"c1d2e3f4-1010-4a10-9a10-000000000003","mode":"practice","parentId":"c1d2e3f4-1010-4a10-9a10-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the second phase claimed around 986 birds killed with approximately 9,860 rounds expended.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"2edc0a1943b381d05fb78386bae7ac3086fc0daaa98bbd962b3f0578e52bd09d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1010-4a10-9a10-000000000004', 'vr', 'practice', 'c1d2e3f4-1010-4a10-9a10-000000000004'::uuid, 'vr.recognising_contradictions', '{"id":"c1d2e3f4-1010-4a10-9a10-000000000004","mode":"practice","parentId":"c1d2e3f4-1010-4a10-9a10-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''further deployments were refused'' and that the government ''instead implemented a bounty system'', directly contradicting the claim that soldiers were deployed on later occasions.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"470fdc399e29886ccc522805f4f95ead3ec11d5b23be06054f58725476e7a75e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c1d2e3f4-1010-4a10-9a10-000000000005', 'vr', 'practice', 'c1d2e3f4-1010-4a10-9a10-000000000005'::uuid, 'vr.unsupported_claims', '{"id":"c1d2e3f4-1010-4a10-9a10-000000000005","mode":"practice","parentId":"c1d2e3f4-1010-4a10-9a10-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage reports the number of bounties paid in 1934 (approximately 57,000) but provides no information about the cost of the bounty system or comparative financial analysis with the military operation.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"7db9b43c97920a6b1c7e048b1fcd943f28a2413a893232d4bc2f316d3ffd8543"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5cdf0975-407b-4a07-83ba-e02b40292366', 'vr', 'practice', '5cdf0975-407b-4a07-83ba-e02b40292366'::uuid, 'vr.explicit_information', '{"id":"5cdf0975-407b-4a07-83ba-e02b40292366","mode":"practice","parentId":"af06bf07-62df-4608-9fdc-fe21252be553","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists three specific faults: walls too thin, excessive manganese, and no safety testing.","difficulty":"normal","format":"mc","answer":"The tank had been welded rather than riveted","options":["The tank walls were too thin","The steel contained excessive manganese","No safety testing was carried out before the tank was filled","The tank had been welded rather than riveted"],"contentHash":"22d3eae1c5712d02a9fcd184f009056ccca89709cf024704a5b77cb26158f8f3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:4c6247cf-93a3-41e9-9709-0364116c3d7a', 'vr', 'practice', '4c6247cf-93a3-41e9-9709-0364116c3d7a'::uuid, 'vr.explicit_information', '{"id":"4c6247cf-93a3-41e9-9709-0364116c3d7a","mode":"practice","parentId":"af06bf07-62df-4608-9fdc-fe21252be553","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the court ''ultimately rejected this defence'', where ''this defence'' refers to the bomb claim.","difficulty":"normal","format":"mc","answer":"The company''s bomb defence was not accepted by the court","options":["Anarchists were eventually proven to have planted a bomb at the tank","The company''s bomb defence was not accepted by the court","The lawsuit concluded within a year of being filed","Most of the witnesses were employees of United States Industrial Alcohol"],"contentHash":"19fb551b5da1aa95d200049532d49070b72409febe1163fc95f18bdfc8f88886"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c5d48c67-e6ec-4ed1-9efa-c1db6f13b2c8', 'vr', 'practice', 'c5d48c67-e6ec-4ed1-9efa-c1db6f13b2c8'::uuid, 'vr.main_idea_and_purpose', '{"id":"c5d48c67-e6ec-4ed1-9efa-c1db6f13b2c8","mode":"practice","parentId":"af06bf07-62df-4608-9fdc-fe21252be553","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The witness count is presented alongside the six-year duration and the note that engineering evidence was decisive — together suggesting the case''s unusual scale.","difficulty":"normal","format":"mc","answer":"To indicate that the case was unusually long and complex","options":["To indicate that the case was unusually long and complex","To suggest that witness evidence was more important than engineering evidence","To argue that the trial was unfair to the defendant","To demonstrate that public interest in the case was exceptionally high"],"contentHash":"4e022121281df5670ae606f93d7c61d79e6be958e302c890ddc627c488631d13"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9e58ee80-dd77-426b-b3fc-07762aa0d821', 'vr', 'practice', '9e58ee80-dd77-426b-b3fc-07762aa0d821'::uuid, 'vr.explicit_information', '{"id":"9e58ee80-dd77-426b-b3fc-07762aa0d821","mode":"practice","parentId":"af06bf07-62df-4608-9fdc-fe21252be553","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that before the disaster ''no such uniform requirements existed in Massachusetts, and similar gaps were common in other states''.","difficulty":"hard","format":"mc","answer":"Requirements for engineer approval were absent or inconsistent across states","options":["All states required licensed engineer approval for such structures","Massachusetts had stricter rules than most other states","Requirements for engineer approval were absent or inconsistent across states","Federal regulations prohibited the private storage of large volumes of molasses"],"contentHash":"994da0c9340234702e9c113e01095b8296feda5265e47bd8c6723741ae3aef03"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f005-1005-4005-8005-000000000002', 'vr', 'practice', 'c7a1f005-1005-4005-8005-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f005-1005-4005-8005-000000000002","mode":"practice","parentId":"c7a1f005-1005-4005-8005-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Act was prompted by Peru''s monopoly on high-quality guano that ''had driven prices to unaffordable levels for American farmers'' and that guano was in demand for intensive American agriculture.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"00b03559b0bea7cfab7564658c740fa1231bdf77f1e05e5efce6bcd1120698b6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f005-1005-4005-8005-000000000003', 'vr', 'practice', 'c7a1f005-1005-4005-8005-000000000003'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f005-1005-4005-8005-000000000003","mode":"practice","parentId":"c7a1f005-1005-4005-8005-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that ''formal annexation was not automatic'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"1ba11e2f3afdb3398e8042a0ecb89824cfae96aa8259b4ec906fe747fabd4808"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f005-1005-4005-8005-000000000004', 'vr', 'practice', 'c7a1f005-1005-4005-8005-000000000004'::uuid, 'vr.unsupported_claims', '{"id":"c7a1f005-1005-4005-8005-000000000004","mode":"practice","parentId":"c7a1f005-1005-4005-8005-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the labourers'' harsh working conditions and dubious contracts but provides no information about their pay relative to mainland workers.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"10e1a718bd584a8445084016dfe284f64b2ea87c7c4bfc7e4e458b62f9557845"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f005-1005-4005-8005-000000000005', 'vr', 'practice', 'c7a1f005-1005-4005-8005-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f005-1005-4005-8005-000000000005","mode":"practice","parentId":"c7a1f005-1005-4005-8005-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states that ''no claim has been recognised under it since 1903.'' Given the passage''s present-day framing and over a century since 1903, the statement logically follows.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"537d2b9e14d491ab035438550c53262fe89bdf7a0b9eb8cdaeea0995b988d609"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
