INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0606-4a06-9d06-000000000602', 'vr', 'practice', 'c7a1e4b2-0606-4a06-9d06-000000000602'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0606-4a06-9d06-000000000602","mode":"practice","parentId":"c7a1e4b2-0606-4a06-9d06-000000000006","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage links Catholic observance directly to demand, stating stockfish ''commanded high prices in Catholic southern Europe, where religious observance required substantial fish consumption''.","difficulty":"normal","format":"mc","answer":"To explain the high demand for stockfish in southern Europe","options":["To argue that the Hanseatic League was religiously motivated","To explain the high demand for stockfish in southern Europe","To contrast Norwegian and German religious practice","To explain why merchants at Bryggen remained unmarried"],"contentHash":"565b7d29c5387c74da58adb0c33d3e69cf2d7199731cbdfcad7b1546dd1bab1e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
