INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3ed35f67-8657-45a6-88c9-a6d2fff5b936', 'vr', 'practice', '3ed35f67-8657-45a6-88c9-a6d2fff5b936'::uuid, 'vr.unsupported_claims', '{"id":"3ed35f67-8657-45a6-88c9-a6d2fff5b936","mode":"practice","parentId":"e948989a-8074-4199-a707-0d68eb935746","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage mentions that local-time confusion led to collisions in some cases but does not compare the numbers of such incidents between Britain and North America.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"6f7bb1b504bef3de611176f6ce08ed83e46a867fefb7c43eb4791ef8a39443f8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0618-4a18-9d18-000000001801', 'vr', 'practice', 'c7a1e4b2-0618-4a18-9d18-000000001801'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0618-4a18-9d18-000000001801","mode":"practice","parentId":"c7a1e4b2-0618-4a18-9d18-000000000018","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the ordinary had a large front wheel, but that ''its high riding position made falls frequent and often severe''.","difficulty":"normal","format":"mc","answer":"Its high riding position made falls frequent and severe","options":["Its chain drive was unreliable","Its high riding position made falls frequent and severe","Its wheels were too small to achieve useful speed","It was prohibitively expensive"],"contentHash":"49ed8f711999eaf06d75e406059adc9892e4c0300833bfb8576408bc9851bc0b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0618-4a18-9d18-000000001802', 'vr', 'practice', 'c7a1e4b2-0618-4a18-9d18-000000001802'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0618-4a18-9d18-000000001802","mode":"practice","parentId":"c7a1e4b2-0618-4a18-9d18-000000000018","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the development of the safety frame, the pneumatic tyre, their combined effect on accessibility and comfort, mass-market adoption in the 1890s, and the continuity of the basic layout to the present — which the option captures.","difficulty":"normal","format":"mc","answer":"The safety bicycle, combined with the pneumatic tyre, established the basic design of the modern bicycle and drove its mass adoption","options":["The safety bicycle, combined with the pneumatic tyre, established the basic design of the modern bicycle and drove its mass adoption","Dunlop''s pneumatic tyre was the single invention responsible for the bicycle''s success","Women''s cycling in the 1890s was the primary driver of bicycle design changes","The penny-farthing was abandoned because its manufacturers went out of business"],"contentHash":"8d6694f7a1cd5b37148b6a4c6e227ed24fe72335e323dc7d098ea9ee39828190"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0618-4a18-9d18-000000001803', 'vr', 'practice', 'c7a1e4b2-0618-4a18-9d18-000000001803'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0618-4a18-9d18-000000001803","mode":"practice","parentId":"c7a1e4b2-0618-4a18-9d18-000000000018","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the ''essential layout established by the safety bicycle of the 1880s has remained largely unchanged to the present day''.","difficulty":"normal","format":"mc","answer":"The essential layout of modern bicycles derives from the safety bicycle of the 1880s","options":["Dunlop invented the safety bicycle in 1885","Derailleur gears were a feature of Starley''s original Rover","The essential layout of modern bicycles derives from the safety bicycle of the 1880s","Penny-farthings remained competitive with safety bicycles through the 1890s"],"contentHash":"ee789d7ca847aa90551de1251be39c18b08464d8604f01ccbb8637d7dee3a7af"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0618-4a18-9d18-000000001804', 'vr', 'practice', 'c7a1e4b2-0618-4a18-9d18-000000001804'::uuid, 'vr.author_perspective', '{"id":"c7a1e4b2-0618-4a18-9d18-000000001804","mode":"practice","parentId":"c7a1e4b2-0618-4a18-9d18-000000000018","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.qualifiers_and_scope"],"confidence":"medium","rationale":"The passage states the adoption of bicycles by women ''has been credited by some historians with contributing to broader changes in women''s clothing and public activity'', using hedged attribution (''some historians'', ''contributing to'') rather than a direct assertion of causation.","difficulty":"hard","format":"mc","answer":"The passage attributes the claim only to some historians, not to an established fact","options":["This claim is directly supported by the passage","This claim is contradicted by the passage","The passage attributes the claim only to some historians, not to an established fact","The passage makes no mention of women''s clothing"],"contentHash":"440b76956744f3bf0f627d1db7be5a023f6b799074208b19a942c26f449b5c10"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0816-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0816-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0816-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0816-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the jenny''s yarn ''was generally too weak to serve as warp, meaning that cotton cloth made entirely from jenny-spun yarn was of limited quality''.","difficulty":"normal","format":"mc","answer":"It was generally too weak to serve as warp, limiting the quality of all-jenny cloth","options":["It was too fine to be used in hand weaving","It was generally too weak to serve as warp, limiting the quality of all-jenny cloth","It could not be dyed using conventional methods","It required reprocessing before being used in any textile application"],"contentHash":"fdc007a7bcfbb2fe08c420cb43b8455843a43c0831fabb498f7e58fbfe3f335e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0816-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0816-4a01-9f11-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0816-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0816-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The water frame is introduced immediately after the discussion of the jenny''s weakness-as-warp limitation, with explicit reference to how it produced stronger warp yarn and enabled all-cotton fabrics.","difficulty":"normal","format":"mc","answer":"To explain how a limitation of the jenny was overcome by a different machine, enabling all-cotton fabrics","options":["To demonstrate that Hargreaves'' jenny was a direct imitation of Arkwright''s earlier design","To explain how a limitation of the jenny was overcome by a different machine, enabling all-cotton fabrics","To argue that Arkwright''s legal disputes with Hargreaves undermined both inventors","To show that mechanisation produced yarn of lower quality than hand spinning"],"contentHash":"ce62ad3b461ca9a93d18d16665002be8057ee99fbc25fc67d504cb9f5cb20a88"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0816-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0816-4a01-9f11-000000000004'::uuid, 'vr.inference', '{"id":"c4a1b8e2-0816-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0816-4a01-9f11-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes attacks on Hargreaves'' workshop ''in 1768'' — two years before the 1770 patent.","difficulty":"hard","format":"mc","answer":"The machine-breaking associated with the jenny preceded Hargreaves'' 1770 patent","options":["Hargreaves invented the jenny specifically in response to a shortage of hand spinners","The jenny''s patent provided Hargreaves with substantial royalties throughout his career","The machine-breaking associated with the jenny preceded Hargreaves'' 1770 patent","Samuel Crompton''s mule was superior to the water frame for warp production"],"contentHash":"fe92c7c4ba3c2e65839d1466a7f43d040c38c5ab9857c46165e3c9199e044092"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0816-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0816-4a01-9f11-000000000005'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0816-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0816-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly states that the mule ''combined features of both machines and eventually displaced the jenny in all but niche applications''.","difficulty":"normal","format":"mc","answer":"The mule combined features of the jenny and the water frame and eventually displaced the jenny","options":["The mule was a smaller, simpler version of the jenny","The mule combined features of the jenny and the water frame and eventually displaced the jenny","The mule was designed specifically to replicate hand-spinning quality","The mule preceded the jenny and inspired its development"],"contentHash":"18be5fee0784ad3cdb2558ff7f9fb096e4bca974a0199ed51ceb26a3c0e57663"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0806-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0806-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0806-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0806-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the discontinuity ''apparently reflecting a change in rock properties caused by heat and pressure rather than a change in composition''.","difficulty":"normal","format":"mc","answer":"It reflected a change in rock properties caused by heat and pressure, not a compositional boundary","options":["It represented the boundary between granitic and basaltic crust, as had been expected","It reflected a change in rock properties caused by heat and pressure, not a compositional boundary","It was an artefact of the instruments used to collect the seismic data","It marked the transition from crust to upper mantle"],"contentHash":"fd1d05dd1ab89f3ab148d70136b7a11c7a836dfcbfd307131fe44dd8ce33eda8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0806-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0806-4a01-9f11-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0806-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0806-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"Project Mohole is introduced in the opening paragraph as background to the Kola project, situating it within a period of ''intense competition between the Soviet Union and the United States in scientific achievement''.","difficulty":"normal","format":"mc","answer":"To provide context for the Soviet decision to pursue the Kola project","options":["To provide context for the Soviet decision to pursue the Kola project","To contrast the scientific methods used by American and Soviet drilling teams","To explain why temperature was a more serious obstacle than expected","To demonstrate that earlier drilling projects had reached similar depths"],"contentHash":"e33cfd6d48773cd14f7b9d56c45bccf23dc4184df424510e1f40b2af7c868ec7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0806-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0806-4a01-9f11-000000000004'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0806-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0806-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states temperature was ''the principal obstacle'' and describes how the rock behaved plastically, causing the hole to partially close around the drill string whenever drilling was paused.","difficulty":"normal","format":"mc","answer":"Temperature caused the rock to behave plastically, closing the borehole when drilling paused","options":["The drill string could not be manufactured to the required length","Funding for the project was withdrawn following the dissolution of the Soviet Union","Temperature caused the rock to behave plastically, closing the borehole when drilling paused","The project had reached the planned target depth set at its inception"],"contentHash":"070e16625e21997a8a6b1c52aff7da6d15886efc14757cbdffc367de6e182601"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0806-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0806-4a01-9f11-000000000005'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0806-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0806-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the borehole ''remained for decades the deepest artificial hole on Earth'', directly supporting this inference.","difficulty":"hard","format":"mc","answer":"The Kola borehole held the record for deepest artificial hole for several decades","options":["The Kola borehole remains the deepest hole ever drilled on Earth by any measure","No hole of any kind has ever been drilled deeper than the Kola borehole","The Kola borehole held the record for deepest artificial hole for several decades","The plankton fossils recovered from the borehole were of previously unknown species"],"contentHash":"d1cd893c7194c62d1c9617ee658255dbcaef8e1450ff0cce8e0517d8503451d2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2001-4b01-9b01-000000000002', 'vr', 'practice', 'd2e3f4a5-2001-4b01-9b01-000000000002'::uuid, 'vr.explicit_information', '{"id":"d2e3f4a5-2001-4b01-9b01-000000000002","mode":"practice","parentId":"d2e3f4a5-2001-4b01-9b01-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the Epic of Gilgamesh tablet''s decipherment was ''by the British Museum assistant George Smith in 1872''.","difficulty":"normal","format":"mc","answer":"George Smith","options":["Austen Henry Layard","Hormuzd Rassam","George Smith","Ashurbanipal himself"],"contentHash":"5baf894f48e00eaaf1eee816fdad880d74ae01a3c3b15763651412f52c91df91"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2001-4b01-9b01-000000000003', 'vr', 'practice', 'd2e3f4a5-2001-4b01-9b01-000000000003'::uuid, 'vr.meaning_in_context', '{"id":"d2e3f4a5-2001-4b01-9b01-000000000003","mode":"practice","parentId":"d2e3f4a5-2001-4b01-9b01-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage explains the irony directly: ''the fire hardened the clay tablets, preserving them when many softer materials of the ancient world were lost''.","difficulty":"normal","format":"mc","answer":"Because the fire that destroyed the palace preserved the clay tablets rather than destroying them","options":["Because Ashurbanipal had personally ordered the fire as a final act of defiance","Because the fire that destroyed the palace preserved the clay tablets rather than destroying them","Because the Medes and Babylonians were later praised for their preservation work","Because the library was rebuilt on the same site shortly afterwards"],"contentHash":"3aea53ee5ff7073a36b797bce715d7911d5afb4b0e53139d70b8518c6f1d00af"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2001-4b01-9b01-000000000004', 'vr', 'practice', 'd2e3f4a5-2001-4b01-9b01-000000000004'::uuid, 'vr.inference', '{"id":"d2e3f4a5-2001-4b01-9b01-000000000004","mode":"practice","parentId":"d2e3f4a5-2001-4b01-9b01-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Ashurbanipal sent scribes ''to copy or confiscate texts''.","difficulty":"hard","format":"mc","answer":"Ashurbanipal acquired some texts for his library without their owners'' consent","options":["Ashurbanipal acquired some texts for his library without their owners'' consent","Most Assyrian kings were literate and kept private libraries","The British Museum has completed translations of all tablets in the collection","The Epic of Gilgamesh was composed during Ashurbanipal''s reign"],"contentHash":"405a53576bb3cf5bc85c79ab36fd45feea2187ce35b769b6882d9e5988fcbda0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:d2e3f4a5-2001-4b01-9b01-000000000005', 'vr', 'practice', 'd2e3f4a5-2001-4b01-9b01-000000000005'::uuid, 'vr.meaning_in_context', '{"id":"d2e3f4a5-2001-4b01-9b01-000000000005","mode":"practice","parentId":"d2e3f4a5-2001-4b01-9b01-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes lexical lists as ''pairing Sumerian and Akkadian terms'', which indicates a concern with vocabulary — matching words in one language to their equivalents in another.","difficulty":"hard","format":"mc","answer":"Vocabulary and the meaning of words","options":["Legal statutes and royal decrees","Vocabulary and the meaning of words","Astronomical observations and calendars","Medical diagnoses and remedies"],"contentHash":"982664a80f135eb7ca57d82f784907f63c62eaee427fd95b97fa4004878443cc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f013-1013-4013-8013-000000000002', 'vr', 'practice', 'c7a1f013-1013-4013-8013-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f013-1013-4013-8013-000000000002","mode":"practice","parentId":"c7a1f013-1013-4013-8013-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The last written communication from Greenland, a record of a wedding at the church of Hvalsey in the Eastern Settlement, is dated 1408.''","difficulty":"normal","format":"mc","answer":"A record of a wedding at Hvalsey in 1408","options":["A trade agreement with Iceland from 1420","A record of a wedding at Hvalsey in 1408","A letter describing the abandonment of the Western Settlement","An inventory of livestock dated 1400"],"contentHash":"f766f51f02fbbe6bc7ac233da783916f71fb25726dbc35198151b54da054ae74"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f013-1013-4013-8013-000000000003', 'vr', 'practice', 'c7a1f013-1013-4013-8013-000000000003'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1f013-1013-4013-8013-000000000003","mode":"practice","parentId":"c7a1f013-1013-4013-8013-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that research since 2010 ''has complicated the simple climate-collapse narrative'' and that some researchers ''favour a multi-factor explanation, in which cooling contributed to but did not single-handedly cause the abandonment.''","difficulty":"normal","format":"mc","answer":"It has complicated the simple climate-collapse narrative, suggesting multiple contributing factors","options":["It has confirmed that climate cooling was the sole cause","It has shown that the settlers did not change their practices in response to conditions","It has complicated the simple climate-collapse narrative, suggesting multiple contributing factors","It has conclusively identified competition with the Thule Inuit as the primary cause"],"contentHash":"71c3e72d907c12abca2f2ebf009b285e6c141a2b1e781725be89ca0d82fe4e20"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f013-1013-4013-8013-000000000004', 'vr', 'practice', 'c7a1f013-1013-4013-8013-000000000004'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f013-1013-4013-8013-000000000004","mode":"practice","parentId":"c7a1f013-1013-4013-8013-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage cites declining European demand for walrus ivory ''in favour of African elephant ivory'' as one of the proposed explanations for the colonies'' collapse, framing it as an economic pressure on the settlements.","difficulty":"normal","format":"mc","answer":"To illustrate one factor that may have eroded the economic basis of the Greenland colonies","options":["To suggest that Norse settlers began trading with African merchants","To illustrate one factor that may have eroded the economic basis of the Greenland colonies","To argue that walrus ivory was of superior quality to elephant ivory","To explain the origins of the Medieval Warm Period"],"contentHash":"08a6bd4c6ca7aebd38cbc41a1deb503c153b5f97daf73c37bade9cd5c74e4e99"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f013-1013-4013-8013-000000000005', 'vr', 'practice', 'c7a1f013-1013-4013-8013-000000000005'::uuid, 'vr.explicit_information', '{"id":"c7a1f013-1013-4013-8013-000000000005","mode":"practice","parentId":"c7a1f013-1013-4013-8013-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states isotopic analysis ''suggests a dietary shift towards marine resources in the later centuries of the settlement, indicating the settlers adapted their practices as conditions changed.''","difficulty":"hard","format":"mc","answer":"The Norse settlers were capable of modifying their diet as environmental conditions changed","options":["The Eastern Settlement was abandoned before the Western Settlement","The Norse settlers relied entirely on dairy farming throughout their four centuries in Greenland","The Norse population in Greenland was larger in the fourteenth century than in the eleventh","The Norse settlers were capable of modifying their diet as environmental conditions changed"],"contentHash":"6d54daedca65ebaaeeba8ee709ac0c475a17d5a24e8aa11ba6b5a7d90e44f42d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0611-4a11-9d11-000000001101', 'vr', 'practice', 'c7a1e4b2-0611-4a11-9d11-000000001101'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0611-4a11-9d11-000000001101","mode":"practice","parentId":"c7a1e4b2-0611-4a11-9d11-000000000011","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes distinct routes: eastbound used a northern route with the Kuroshio and North Pacific currents, while westbound travelled ''further south'' with the trade winds.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"ef26e9b4e8d9233548c4ca4e9e0b8564f0fb1dc31114d1c0e5ca1b1557086a92"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0611-4a11-9d11-000000001102', 'vr', 'practice', 'c7a1e4b2-0611-4a11-9d11-000000001102'::uuid, 'vr.inference', '{"id":"c7a1e4b2-0611-4a11-9d11-000000001102","mode":"practice","parentId":"c7a1e4b2-0611-4a11-9d11-000000000011","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states smuggling ''was endemic and enforcement inconsistent'', and describes the galleons as ''imperfect conduits for a far larger informal trade'' — indicating the restrictions failed to eliminate unauthorised commerce.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"42a1111a22ae6393fa116d217366823a0266f8bbf5c1af9fdb32d4aca155842e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0611-4a11-9d11-000000001103', 'vr', 'practice', 'c7a1e4b2-0611-4a11-9d11-000000001103'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1e4b2-0611-4a11-9d11-000000001103","mode":"practice","parentId":"c7a1e4b2-0611-4a11-9d11-000000000011","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage attributes the end of the trade to ''Mexican independence movements and the disruption of Spanish imperial administration'' rendering the system unsustainable, not to a collapse in Chinese demand.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"169ce1e4860525379979304012b5df2791fad6048e3fa722b0da9d88765ce3c8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0611-4a11-9d11-000000001104', 'vr', 'practice', 'c7a1e4b2-0611-4a11-9d11-000000001104'::uuid, 'vr.unsupported_claims', '{"id":"c7a1e4b2-0611-4a11-9d11-000000001104","mode":"practice","parentId":"c7a1e4b2-0611-4a11-9d11-000000000011","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage identifies both locations as principal sources of silver but makes no claim about the relative quantities mined at each.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"8dcdbb59b5ca0795ac119bfe216ee6a196d78327bc8b78594535bda3e6f75f69"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f012-1012-4012-8012-000000000002', 'vr', 'practice', 'c7a1f012-1012-4012-8012-000000000002'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1f012-1012-4012-8012-000000000002","mode":"practice","parentId":"c7a1f012-1012-4012-8012-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''The location of spawning has been inferred from the distribution of the smallest captured leptocephali, which become progressively smaller the closer one samples to the Sargasso.''","difficulty":"normal","format":"mc","answer":"The pattern of decreasing leptocephalus size approaching the Sargasso","options":["Direct observation of spawning adults by Johannes Schmidt","The pattern of decreasing leptocephalus size approaching the Sargasso","Genetic comparison of Sargasso eels with European river eels","Satellite tagging of adult eels during their return migration"],"contentHash":"92fdc7750aff4ef43d147aa932d90b4be41b17073d42c4489ad7deafb0d9f9ea"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f012-1012-4012-8012-000000000003', 'vr', 'practice', 'c7a1f012-1012-4012-8012-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f012-1012-4012-8012-000000000003","mode":"practice","parentId":"c7a1f012-1012-4012-8012-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Because all European eels...","difficulty":"normal","format":"mc","answer":"All European eels descend from a single Sargasso population, so mortality in the oceanic phase cannot be addressed by river measures","options":["Local measures cannot legally be imposed on rivers that cross national borders","All European eels descend from a single Sargasso population, so mortality in the oceanic phase cannot be addressed by river measures","Local measures have been shown to be ineffective in practice","European eels do not use rivers as part of their life cycle"],"contentHash":"205a2818fea9a30735a13b126bacdbedaf5e0948fd96e16bef3d68e6ebe78610"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f012-1012-4012-8012-000000000004', 'vr', 'practice', 'c7a1f012-1012-4012-8012-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f012-1012-4012-8012-000000000004","mode":"practice","parentId":"c7a1f012-1012-4012-8012-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists dams, parasitic infections, climate-driven current shifts, and overfishing as suspected causes.","difficulty":"hard","format":"mc","answer":"Pollution from agricultural runoff","options":["Overfishing of the glass eel stage","Barriers to river migration such as dams","Pollution from agricultural runoff","Climate-driven shifts in Atlantic currents"],"contentHash":"b2d6e73335c34121a627c0dc4cf53e5844be6aa98153a0d1a02e3bb0e8bed10f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f012-1012-4012-8012-000000000005', 'vr', 'practice', 'c7a1f012-1012-4012-8012-000000000005'::uuid, 'vr.meaning_in_context', '{"id":"c7a1f012-1012-4012-8012-000000000005","mode":"practice","parentId":"c7a1f012-1012-4012-8012-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces the term directly: ''the resulting larvae — flat, transparent, leaf-shaped creatures known as leptocephali''.","difficulty":"normal","format":"mc","answer":"The larval stage of eels, described as flat and leaf-shaped","options":["The adult spawning eels in the Sargasso Sea","The larval stage of eels, described as flat and leaf-shaped","The glass eel stage arriving at European coasts","A species of eel distinct from Anguilla anguilla"],"contentHash":"77450305e135b5f66c421dc4378c475fcae8e8af0ace97a8d339d9051067578c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:ab611ec0-ded2-4ddc-ae2b-bfa7dc2a059e', 'vr', 'practice', 'ab611ec0-ded2-4ddc-ae2b-bfa7dc2a059e'::uuid, 'vr.qualifiers_and_scope', '{"id":"ab611ec0-ded2-4ddc-ae2b-bfa7dc2a059e","mode":"practice","parentId":"cd3afeec-2ea3-4fcf-9c60-8b51a3a505fe","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage says CFCs were chosen partly because they were ''non-toxic at ground level'' — a qualified claim.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"29522ba10af21004fa7d316f813e33ff880e3f837b3ce43faae06393e099e003"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:5b0e087a-e0c7-44eb-8c9c-b02d94118871', 'vr', 'practice', '5b0e087a-e0c7-44eb-8c9c-b02d94118871'::uuid, 'vr.recognising_contradictions', '{"id":"5b0e087a-e0c7-44eb-8c9c-b02d94118871","mode":"practice","parentId":"cd3afeec-2ea3-4fcf-9c60-8b51a3a505fe","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states hydrofluorocarbons are ''not ozone-depleting'' but are ''potent greenhouse gases''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"fb50035fd664b764ae5dac6a2fb1c04c36f43419dd6461d17b32004b51220890"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:fe563663-abc1-4978-b753-f99a7e69120d', 'vr', 'practice', 'fe563663-abc1-4978-b753-f99a7e69120d'::uuid, 'vr.qualifiers_and_scope', '{"id":"fe563663-abc1-4978-b753-f99a7e69120d","mode":"practice","parentId":"cd3afeec-2ea3-4fcf-9c60-8b51a3a505fe","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage explicitly states that ''developed and developing countries operate on different phase-out timetables'', which contradicts the claim of a single schedule.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"cfc62f9fdea540267d316ad940b70faef3ece3d75ffff6d720fbf8c17ec955a7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:de542799-8e3c-4e15-9750-664bebb27ac0', 'vr', 'practice', 'de542799-8e3c-4e15-9750-664bebb27ac0'::uuid, 'vr.qualifiers_and_scope', '{"id":"de542799-8e3c-4e15-9750-664bebb27ac0","mode":"practice","parentId":"cd3afeec-2ea3-4fcf-9c60-8b51a3a505fe","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage states the ozone hole is projected to return to pre-1980 size by around 2066 but also notes ''considerable annual variation'' influenced by temperature and volcanic activity.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"ba663df94a7fa357d100805493b328768e754ef3c619d463f8566e7405804394"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0619-4a19-9d19-000000001901', 'vr', 'practice', 'c7a1e4b2-0619-4a19-9d19-000000001901'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0619-4a19-9d19-000000001901","mode":"practice","parentId":"c7a1e4b2-0619-4a19-9d19-000000000019","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Nomadic mobility was shaped by seasonal fodder availability'' and describes the alternation between winter and summer pastures.","difficulty":"normal","format":"mc","answer":"Availability of fodder in different seasons and locations","options":["Conflicts with neighbouring sedentary states","Availability of fodder in different seasons and locations","Tax obligations imposed by sedentary empires","Trade routes along the Silk Road"],"contentHash":"68d78364568c0cc2b067c8b11cfb7cf9c6495c24be91a448abb610948090e7a5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0619-4a19-9d19-000000001902', 'vr', 'practice', 'c7a1e4b2-0619-4a19-9d19-000000001902'::uuid, 'vr.author_perspective', '{"id":"c7a1e4b2-0619-4a19-9d19-000000001902","mode":"practice","parentId":"c7a1e4b2-0619-4a19-9d19-000000000019","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states traditional scholarship ''often framed nomadic and sedentary societies as fundamentally antagonistic'' while more recent research ''has emphasised the interdependence of the two systems''.","difficulty":"normal","format":"mc","answer":"Older scholarship framed the relationship as antagonistic; newer research emphasises interdependence","options":["Older scholarship saw nomads as benign traders; newer research sees them as aggressive raiders","Older scholarship framed the relationship as antagonistic; newer research emphasises interdependence","Older scholarship focused on horses; newer research focuses on cattle","Older scholarship relied on isotopic analysis; newer research relies on textual sources"],"contentHash":"4758bbefbcb35725366ca5eefee15b0a56ed4ee2e45a00b58ebcd71613199aff"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0619-4a19-9d19-000000001903', 'vr', 'practice', 'c7a1e4b2-0619-4a19-9d19-000000001903'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0619-4a19-9d19-000000001903","mode":"practice","parentId":"c7a1e4b2-0619-4a19-9d19-000000000019","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists isotopic analysis among the evidence types (''archaeology, textual sources in multiple languages, and most recently on isotopic analysis'') on which the revised interpretations rely.","difficulty":"normal","format":"mc","answer":"To illustrate the kind of new evidence supporting revised interpretations of steppe societies","options":["To argue that traditional textual sources have been discredited","To show that nomads consumed primarily plant-based diets","To illustrate the kind of new evidence supporting revised interpretations of steppe societies","To explain why the horse was first domesticated in the western steppe"],"contentHash":"6c497eb9640b3ac39b09beea1d3ee673e965e02c45e5ba070a38345c47eff825"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0619-4a19-9d19-000000001904', 'vr', 'practice', 'c7a1e4b2-0619-4a19-9d19-000000001904'::uuid, 'vr.inference', '{"id":"c7a1e4b2-0619-4a19-9d19-000000001904","mode":"practice","parentId":"c7a1e4b2-0619-4a19-9d19-000000000019","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage places horse domestication in ''the fourth millennium BCE'' and the Scythians in ''the first millennium BCE'' — a gap of at least two millennia, making the inference well supported.","difficulty":"hard","format":"mc","answer":"Horse domestication preceded the rise of the Scythians by at least two millennia","options":["Horse domestication preceded the rise of the Scythians by at least two millennia","Nomadic societies did not engage in any form of trade with sedentary states","Bactrian camels were the most important livestock across the entire steppe","The Xiongnu were the first nomadic confederation of the Eurasian steppe"],"contentHash":"311eb332b58e69c0e2e2e855f17a129854d8c0341dae836538fc269f4c9567b4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:a4e59b87-3118-46d8-a24c-98a5b88fb2d6', 'vr', 'practice', 'a4e59b87-3118-46d8-a24c-98a5b88fb2d6'::uuid, 'vr.explicit_information', '{"id":"a4e59b87-3118-46d8-a24c-98a5b88fb2d6","mode":"practice","parentId":"ffaed46d-2196-4c86-bd57-d9d9ea585af6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that decipherments typically rely on bilingual inscriptions or large text corpora, and that ''with only the disc to work from, neither approach is available''.","difficulty":"normal","format":"mc","answer":"Neither a bilingual inscription nor a large corpus of related text exists","options":["The symbols are too faded to read clearly","The disc is held in a museum that restricts access","Neither a bilingual inscription nor a large corpus of related text exists","No archaeologist has been willing to attempt a decipherment"],"contentHash":"6e20414bb3595c4b9c5df98208b2e9c6b5b646eac75754bf16d880d030ad715a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0877af49-3418-4e10-a3e3-909482fe9b0d', 'vr', 'practice', '0877af49-3418-4e10-a3e3-909482fe9b0d'::uuid, 'vr.author_perspective', '{"id":"0877af49-3418-4e10-a3e3-909482fe9b0d","mode":"practice","parentId":"ffaed46d-2196-4c86-bd57-d9d9ea585af6","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The forgery hypothesis appears in a list of proposals, is described with its reasoning, and is said not to have been widely accepted.","difficulty":"hard","format":"mc","answer":"Presenting it as one hypothesis among several and noting it has not gained wide acceptance","options":["Endorsing it as the most likely explanation","Presenting it as one hypothesis among several and noting it has not gained wide acceptance","Rejecting it outright as baseless","Claiming it has been definitively disproved by thermoluminescence dating"],"contentHash":"b77d391c81557068d9cbc58bb673f25ae25a09abec57136906934f07fa7f731e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c99d1d09-60a4-46c5-9937-6c5151c21b9f', 'vr', 'practice', 'c99d1d09-60a4-46c5-9937-6c5151c21b9f'::uuid, 'vr.explicit_information', '{"id":"c99d1d09-60a4-46c5-9937-6c5151c21b9f","mode":"practice","parentId":"ffaed46d-2196-4c86-bd57-d9d9ea585af6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage specifies that ''the symbols were impressed into the wet clay using individual stamps before firing — making the disc, in one reasonable interpretation, the earliest known example of movable-type printing''.","difficulty":"normal","format":"mc","answer":"Individual stamps were used to impress the symbols into wet clay before firing","options":["It was printed using a metal press","Individual stamps were used to impress the symbols into wet clay before firing","It contains more symbols than any other Minoan artefact","It was produced in multiple identical copies"],"contentHash":"b1cac7a6f7d9d8cc7336df5d86eddf736727fe63d6cca64407077f83c850efd0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:eb3c58f9-82e9-4388-b3dc-87adc9d4629a', 'vr', 'practice', 'eb3c58f9-82e9-4388-b3dc-87adc9d4629a'::uuid, 'vr.evaluating_evidence', '{"id":"eb3c58f9-82e9-4388-b3dc-87adc9d4629a","mode":"practice","parentId":"ffaed46d-2196-4c86-bd57-d9d9ea585af6","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage identifies the isolation of the script — no other objects bearing the same signs — as a serious problem because decipherment typically relies on larger corpora.","difficulty":"hard","format":"mc","answer":"One of the two main obstacles to decipherment, described in the passage, would be partially addressed","options":["The disc''s script would be immediately decipherable","The forgery hypothesis would be strengthened","One of the two main obstacles to decipherment, described in the passage, would be partially addressed","Thermoluminescence dating would no longer be needed"],"contentHash":"f63893072122473d86d719fca969b8b38ea964d352c81e35c227793758a28140"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0613-4a13-9d13-000000001301', 'vr', 'practice', 'c7a1e4b2-0613-4a13-9d13-000000001301'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0613-4a13-9d13-000000001301","mode":"practice","parentId":"c7a1e4b2-0613-4a13-9d13-000000000013","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''This property arises from the surface tension of the soapy liquid, which acts to reduce the film''s interfacial energy.''","difficulty":"normal","format":"mc","answer":"Because surface tension acts to reduce the film''s interfacial energy","options":["Because the wire frame constrains their shape geometrically","Because surface tension acts to reduce the film''s interfacial energy","Because soap molecules chemically bond to form the smallest surface","Because air pressure on both sides of the film equalises"],"contentHash":"783ccd371b7ca9c9f9585b2c498c8ddc92444d44bcc0a97949527171c5964284"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0613-4a13-9d13-000000001302', 'vr', 'practice', 'c7a1e4b2-0613-4a13-9d13-000000001302'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0613-4a13-9d13-000000001302","mode":"practice","parentId":"c7a1e4b2-0613-4a13-9d13-000000000013","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage uses the tetrahedron as a reference: the 109.5 degrees between tetrahedral bond directions matches the angle at which four soap-film edges meet at a vertex.","difficulty":"normal","format":"mc","answer":"To identify the exact angle at which four film edges meet at a vertex","options":["To argue that soap films resemble crystalline structures","To identify the exact angle at which four film edges meet at a vertex","To suggest that soap bubbles are always tetrahedral","To explain why some soap films fail to meet Plateau''s laws"],"contentHash":"bf862572493eec0df451c2dbbf4b3df24de7c383fc83a6f70f285b10dd4fdb9c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0613-4a13-9d13-000000001303', 'vr', 'practice', 'c7a1e4b2-0613-4a13-9d13-000000001303'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0613-4a13-9d13-000000001303","mode":"practice","parentId":"c7a1e4b2-0613-4a13-9d13-000000000013","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states soap-film vertical deflection ''is governed by the same mathematical equation as the stress distribution'' in torsion problems, and that ''the equivalence was exploited in structural design'' — directly supporting the option.","difficulty":"hard","format":"mc","answer":"Soap films can be used to solve problems that are mathematically equivalent to those in structural engineering","options":["Soap films are useful only as educational demonstrations","Plateau''s laws were proven mathematically before they were observed experimentally","Soap films can be used to solve problems that are mathematically equivalent to those in structural engineering","The colours of soap bubbles are caused by chemical reactions within the film"],"contentHash":"3eb5f7bf210f7a5a61883e3222c58ab86ec4033952b80b9992a9b50f62817061"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0613-4a13-9d13-000000001304', 'vr', 'practice', 'c7a1e4b2-0613-4a13-9d13-000000001304'::uuid, 'vr.evaluating_evidence', '{"id":"c7a1e4b2-0613-4a13-9d13-000000001304","mode":"practice","parentId":"c7a1e4b2-0613-4a13-9d13-000000000013","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states Taylor proved Plateau''s laws ''followed necessarily from the minimisation condition''.","difficulty":"hard","format":"mc","answer":"The claim that Plateau''s laws follow necessarily from the minimisation condition","options":["The existence of minimal surfaces","The claim that Plateau''s laws follow necessarily from the minimisation condition","The use of thin-film interference in explaining bubble colours","The experimental methods used by Plateau in the nineteenth century"],"contentHash":"59e1549328df2125a9d4fe30243cc729d696671f788b9bd19dc36703a739fce0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f020-1020-4020-8020-000000000002', 'vr', 'practice', 'c7a1f020-1020-4020-8020-000000000002'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f020-1020-4020-8020-000000000002","mode":"practice","parentId":"c7a1f020-1020-4020-8020-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Pitkern ''draws a majority of its vocabulary from eighteenth-century nautical English, with a substantial minority of terms from Tahitian'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"bb4edfaf8ff046e09d158b1050e5e4cc0a3826a6a201f8e7a9a8bc38a2ca7899"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f020-1020-4020-8020-000000000003', 'vr', 'practice', 'c7a1f020-1020-4020-8020-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f020-1020-4020-8020-000000000003","mode":"practice","parentId":"c7a1f020-1020-4020-8020-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes ''a related community on Norfolk Island that descends from Pitcairners resettled there in 1856''.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"8b20d43f6f55ac64f5e8c117152260a3f601c8de457f573ec8cedf9d76cb6a7f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f020-1020-4020-8020-000000000004', 'vr', 'practice', 'c7a1f020-1020-4020-8020-000000000004'::uuid, 'vr.qualifiers_and_scope', '{"id":"c7a1f020-1020-4020-8020-000000000004","mode":"practice","parentId":"c7a1f020-1020-4020-8020-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states the two varieties ''remain mutually intelligible to a significant extent'', contradicting the claim that speakers cannot understand one another at all.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"cc75e062e7eea40433b9555c2b8219584a699a8f471058ae8f702453163e33b9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f020-1020-4020-8020-000000000005', 'vr', 'practice', 'c7a1f020-1020-4020-8020-000000000005'::uuid, 'vr.explicit_information', '{"id":"c7a1f020-1020-4020-8020-000000000005","mode":"practice","parentId":"c7a1f020-1020-4020-8020-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Its origins are unusually well documented, since the identities and linguistic backgrounds of its original speakers are known with precision — a contrast with most creole languages, whose formation is typically inferred from indirect evidence.''","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"074c199aca7eac433d9eb5e57462a11bd1ce0925a085aeab3c6ad8e83ff1d938"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3b', 'vr', 'practice', '2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3b'::uuid, 'vr.explicit_information', '{"id":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3b","mode":"practice","parentId":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the economic case for the latter proved overwhelmingly superior'', with ''the latter'' referring to electrical and digital communications.","difficulty":"normal","format":"mc","answer":"The economic superiority of electrical and digital communications","options":["The physical deterioration of the underground tube infrastructure","The rising cost of steam-powered pumping stations","The economic superiority of electrical and digital communications","A shift in postal regulation that restricted commercial messaging"],"contentHash":"f99f61118bc6480a38f6615acd84e8ebee7aa2487406e2460973d26b7737fab9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3c', 'vr', 'practice', '2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3c'::uuid, 'vr.meaning_in_context', '{"id":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3c","mode":"practice","parentId":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3a","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The sentence immediately preceding ''the latter'' contrasts pneumatic networks with ''electrical and, later, digital communications''.","difficulty":"hard","format":"mc","answer":"Electrical and digital communications","options":["City-wide pneumatic networks","Short-distance in-building tube systems","Electrical and digital communications","Hospital pharmacies and casinos"],"contentHash":"fa7a871fee11cb9b144fd64571402698344cdfa2e87599f57e08c78c7533488b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3d', 'vr', 'practice', '2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3d'::uuid, 'vr.explicit_information', '{"id":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3d","mode":"practice","parentId":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the London network ''carried letters between the main sorting offices rather than serving as a public-facing messaging service'', whereas the Parisian system ''allowed any citizen to send a pneumatic telegram''.","difficulty":"normal","format":"mc","answer":"The Parisian system was open to the public, while London''s served only internal postal operations","options":["The Parisian system used steam-powered pumps while London used electric ones","The Parisian system was open to the public, while London''s served only internal postal operations","The Parisian system closed earlier than London''s","The London network was significantly larger in total length"],"contentHash":"b8091465442859691687295194d14e3c0661488547c604dde337744ca0542574"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3e', 'vr', 'practice', '2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3e'::uuid, 'vr.explicit_information', '{"id":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3e","mode":"practice","parentId":"2c7d0af1-6b3a-4d0e-c4f5-1a5b7d0e2f3a","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage mentions hospitals, casinos, banks, and supermarkets as surviving applications.","difficulty":"normal","format":"mc","answer":"Carrying personal correspondence between city neighbourhoods","options":["Moving medicines within hospitals","Transferring cash within banks and casinos","Carrying personal correspondence between city neighbourhoods","Moving items within supermarkets"],"contentHash":"f2ff6fd872d5cb371b474c849a7e9c1af9ac07b89926346631827298a04e79a0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0810-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0810-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0810-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0810-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''supply to private connections could be reduced or cut entirely'' while supply to public fountains was intended to continue as long as water remained.","difficulty":"normal","format":"mc","answer":"Private connections could be cut to preserve flow to public fountains","options":["Houses with inscribed pipes had first priority, with remaining supply going to public uses","The largest bath complexes received the entirety of the remaining supply","Private connections could be cut to preserve flow to public fountains","Supply was reduced equally across all users until normal flow was restored"],"contentHash":"28a690582be97fed255d6450928e9a79cca22d77e0ab113f3b9b0a9ad998ca8a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0810-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0810-4a01-9f11-000000000003'::uuid, 'vr.author_perspective', '{"id":"c4a1b8e2-0810-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0810-4a01-9f11-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that Vitruvius ''recommended earthenware pipes on health grounds, but this advice does not appear to have been widely followed''.","difficulty":"normal","format":"mc","answer":"He recommended earthenware pipes on health grounds, but the advice was not widely adopted","options":["He considered lead plumbing safe provided the water flowed continuously","He recommended earthenware pipes on health grounds, but the advice was not widely adopted","He advocated for lead plumbing as superior to all available alternatives","He wrote no extant works discussing the health effects of lead"],"contentHash":"7abffddb3638dfeaa8d8dbd4ba3044f366067312038b1396896f2e00e2b81df4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0810-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0810-4a01-9f11-000000000004'::uuid, 'vr.evaluating_evidence', '{"id":"c4a1b8e2-0810-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0810-4a01-9f11-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''the mineral crust rapidly deposited by hard water on the interior of the pipes may have significantly reduced contact between the water and the lead''.","difficulty":"normal","format":"mc","answer":"A mineral crust may have formed on the interior of the pipes, limiting water-lead contact","options":["Skeletal remains from Pompeii showed no measurable lead at all","The Serino aqueduct supplied water directly without passing through lead pipes","A mineral crust may have formed on the interior of the pipes, limiting water-lead contact","Vitruvius''s earthenware recommendation was followed in most Roman cities"],"contentHash":"dd86153d801ee3181cea99f178fe8499b36f0107b1ea830799c453eb5d4ea085"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0810-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0810-4a01-9f11-000000000005'::uuid, 'vr.inference', '{"id":"c4a1b8e2-0810-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0810-4a01-9f11-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes ''a pragmatic hierarchy of priority'' in the system''s design, with flow-cutting arrangements protecting public fountains.","difficulty":"hard","format":"mc","answer":"The water distribution system reflected deliberate choices about which uses were essential","options":["Lead poisoning was the principal cause of death among Pompeiian residents","The stamped inscription mentioning penalties for tampering was found at Pompeii itself","The water distribution system reflected deliberate choices about which uses were essential","The Serino aqueduct was the only source of water entering the city"],"contentHash":"c6e603b8ff8e3031bf37b08a286d07e6718f30b2c33351f10a6c33099671f0b1"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0e', 'vr', 'practice', '9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0e'::uuid, 'vr.qualifiers_and_scope', '{"id":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0e","mode":"practice","parentId":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0d","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage says the Camargue has ''the only population...","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"c07c3232cfae55d54a96e46ab5c8dfb79eefa907491e29ed905d7a1b86e6123a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0f', 'vr', 'practice', '9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0f'::uuid, 'vr.unsupported_claims', '{"id":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0f","mode":"practice","parentId":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0d","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"low","rationale":"Unsupported False key: large-scale introduction in the twentieth century does not rule out earlier small-scale rice cultivation.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"excludedReason":"Unsupported False key: large-scale introduction in the twentieth century does not rule out earlier small-scale rice cultivation.","contentHash":"63c4dfb22214d5f8734c93a65887860cdb58d0c5c4ca1332d941dc2900b958c0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c10', 'vr', 'practice', '9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c10'::uuid, 'vr.inference', '{"id":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c10","mode":"practice","parentId":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0d","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states sea-level rise erodes the coast ''while upstream dams on the Rhône have reduced the sediment load needed to rebuild the coast''.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"d8bfbdcdd010f44ab0ed7ce9a89f5a1f1f298c925bbe5b2162326bebbc934429"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c11', 'vr', 'practice', '9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c11'::uuid, 'vr.unsupported_claims', '{"id":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c11","mode":"practice","parentId":"9f4a37c8-3e0d-4a7b-f1c2-8d2e4a7b9c0d","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the park was designated in 1970 and ''whether this will be enough to preserve the Camargue''s particular ecological character...","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"63cab3db4dcbad0c61179870abc2c6197983eb8dcee2baabebcc1ce9a3effcac"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:86d56d93-9195-4128-b5f8-2af662d8d28e', 'vr', 'practice', '86d56d93-9195-4128-b5f8-2af662d8d28e'::uuid, 'vr.explicit_information', '{"id":"86d56d93-9195-4128-b5f8-2af662d8d28e","mode":"practice","parentId":"2aa9b2ce-eedc-4437-b85f-ea47e67d4b39","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that Morosini ''negotiated a surrender on terms that allowed the remaining garrison and civilian population to leave with their possessions''.","difficulty":"normal","format":"mc","answer":"The garrison would be permitted to leave the city with their possessions","options":["The garrison would be permitted to leave the city with their possessions","The city would be returned to Venice after fifty years","The Ottoman forces would pay an indemnity to Venice","The city would be demilitarised but retained by Venice"],"contentHash":"2b88c740d13d2010724da3be7073320bb952a63f6f1a27e9df4c622d6b039ba4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0e654734-ef30-43c9-a9cb-02a747655f30', 'vr', 'practice', '0e654734-ef30-43c9-a9cb-02a747655f30'::uuid, 'vr.explicit_information', '{"id":"0e654734-ef30-43c9-a9cb-02a747655f30","mode":"practice","parentId":"2aa9b2ce-eedc-4437-b85f-ea47e67d4b39","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the fortifications were ''adapted from Italian military-engineering principles'' and ''designed to resist gunpowder artillery''.","difficulty":"normal","format":"mc","answer":"They were adapted from Italian engineering and designed to resist gunpowder artillery","options":["They were built quickly in response to the Ottoman threat in 1648","They were adapted from Italian engineering and designed to resist gunpowder artillery","They were ineffective and contributed to the city''s fall","They were constructed by French and German military engineers"],"contentHash":"c94b6b4acfd8f72182433c8920f0f6034c2b5f27f905bf3d48342f14ff2cbcb2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:0cdf3e86-1755-408a-bcee-6798651a8da1', 'vr', 'practice', '0cdf3e86-1755-408a-bcee-6798651a8da1'::uuid, 'vr.explicit_information', '{"id":"0cdf3e86-1755-408a-bcee-6798651a8da1","mode":"practice","parentId":"2aa9b2ce-eedc-4437-b85f-ea47e67d4b39","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly lists ''disease, desertion, and combat losses'' as the factors that reduced the defenders.","difficulty":"normal","format":"mc","answer":"Famine within the city","options":["Disease","Desertion","Combat losses","Famine within the city"],"contentHash":"da9180b322064ca3d33c53633b39ebeb4101cb092caa67a43911609dc27a8e75"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:a5201290-48ca-4962-93d6-fa22908f8948', 'vr', 'practice', 'a5201290-48ca-4962-93d6-fa22908f8948'::uuid, 'vr.author_perspective', '{"id":"a5201290-48ca-4962-93d6-fa22908f8948","mode":"practice","parentId":"2aa9b2ce-eedc-4437-b85f-ea47e67d4b39","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage gives a range of contemporary estimates for Ottoman losses (100,000–200,000) and immediately qualifies this by noting that ''modern estimates are generally lower''.","difficulty":"hard","format":"mc","answer":"Cautious, noting contemporary figures alongside the fact that modern estimates are generally lower","options":["Firm endorsement of the contemporary Ottoman estimates as accurate","Cautious, noting contemporary figures alongside the fact that modern estimates are generally lower","Dismissive of all sources as unreliable","Focused exclusively on Venetian losses"],"contentHash":"0a953da20e75ad3a27d59c6c951dbef9f239a90b089ba465a77f29a7651f801e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:a4ad08a9-5ffe-48bc-85ee-fcd8d7fb9384', 'vr', 'practice', 'a4ad08a9-5ffe-48bc-85ee-fcd8d7fb9384'::uuid, 'vr.explicit_information', '{"id":"a4ad08a9-5ffe-48bc-85ee-fcd8d7fb9384","mode":"practice","parentId":"a060d0bd-1ee4-4960-b444-3fcbf6f65e6b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that Theophrastus ''noted that transplanted specimens refused to take root'' and that Roman writers echoed the complaint.","difficulty":"normal","format":"mc","answer":"Transplanted specimens reportedly failed to take root outside the Cyrenaican coast","options":["Cyrenean authorities banned the export of live plants","Transplanted specimens reportedly failed to take root outside the Cyrenaican coast","The climate of the wider Mediterranean was too cold for the plant","Roman tax-farmers deliberately destroyed plants grown outside Cyrene"],"contentHash":"def3237a9419f65eca7e31b9e5919ef651b339eb58b4031b52eff3e2f2eacb67"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:83014d15-353c-411a-aefb-914add68156b', 'vr', 'practice', '83014d15-353c-411a-aefb-914add68156b'::uuid, 'vr.main_idea_and_purpose', '{"id":"83014d15-353c-411a-aefb-914add68156b","mode":"practice","parentId":"a060d0bd-1ee4-4960-b444-3fcbf6f65e6b","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces the coin detail immediately after stating that silphium was ''so central to Cyrene''s economy'' — the coin reference supports that point.","difficulty":"normal","format":"mc","answer":"To demonstrate the centrality of silphium to the city''s economy","options":["To suggest that Cyrene had no other significant industries","To demonstrate the centrality of silphium to the city''s economy","To argue that the plant was more valuable than gold in Cyrene","To indicate that the coins were traded internationally"],"contentHash":"a4014a59b36699abaea375edaf56f9099fcf11ad98720fb8946ef64a68e80e5e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3818ada3-e71e-4cd8-910f-101ddbe847cc', 'vr', 'practice', '3818ada3-e71e-4cd8-910f-101ddbe847cc'::uuid, 'vr.inference', '{"id":"3818ada3-e71e-4cd8-910f-101ddbe847cc","mode":"practice","parentId":"a060d0bd-1ee4-4960-b444-3fcbf6f65e6b","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that Pliny wrote only a single stalk had been found in his lifetime and that it was sent as a ''curiosity'' to Nero — this supports the inference that the plant had become remarkably scarce.","difficulty":"normal","format":"mc","answer":"By Pliny''s era, silphium had become so scarce that a single specimen was considered remarkable","options":["Pliny the Elder personally searched for silphium during his lifetime","By Pliny''s era, silphium had become so scarce that a single specimen was considered remarkable","Emperor Nero ordered the cultivation of silphium in imperial gardens","Silphium was more effective as a medicine than as a seasoning"],"contentHash":"253c228c3bef9a94849cb27f3277ec60136be7358250d8057291973ad2b505a9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:25fe796d-9d33-49c3-aa8d-2f016893c5c1', 'vr', 'practice', '25fe796d-9d33-49c3-aa8d-2f016893c5c1'::uuid, 'vr.evaluating_evidence', '{"id":"25fe796d-9d33-49c3-aa8d-2f016893c5c1","mode":"practice","parentId":"a060d0bd-1ee4-4960-b444-3fcbf6f65e6b","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly says ''whether silphium truly became extinct or merely retreated into obscurity remains uncertain''.","difficulty":"hard","format":"mc","answer":"It would be consistent with the passage''s stated uncertainty about whether silphium is truly extinct","options":["It would confirm Pliny''s claim that the plant was destroyed by overgrazing","It would contradict the passage''s assertion that silphium is definitely extinct","It would be consistent with the passage''s stated uncertainty about whether silphium is truly extinct","It would prove that modern botanists were correct to propose climate shifts as a cause of its decline"],"contentHash":"349dcaf955400267dcd8fd58d3806a072c5c9e3bc8ac717cc30849f3f84131a6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0801-4a01-9f11-000000000002', 'vr', 'practice', 'c4a1b8e2-0801-4a01-9f11-000000000002'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0801-4a01-9f11-000000000002","mode":"practice","parentId":"c4a1b8e2-0801-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the hongi expeditions as ''annual inspections'' conducted to enforce the monopoly, with cultivation permitted only under company supervision and unauthorised trees destroyed.","difficulty":"normal","format":"mc","answer":"To enforce the VOC''s clove monopoly by inspecting for unauthorised cultivation","options":["To transport cloves from the Moluccas to European markets","To enforce the VOC''s clove monopoly by inspecting for unauthorised cultivation","To establish new clove plantations on islands outside the Moluccas","To collect taxes from local sultanates allied with the VOC"],"contentHash":"af40ed8e67ec21d071380cc090859d032632441683695d1cf2c2e05e458c5751"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0801-4a01-9f11-000000000003', 'vr', 'practice', 'c4a1b8e2-0801-4a01-9f11-000000000003'::uuid, 'vr.explicit_information', '{"id":"c4a1b8e2-0801-4a01-9f11-000000000003","mode":"practice","parentId":"c4a1b8e2-0801-4a01-9f11-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly attributes the leverage to the ''geographical confinement of the species'', noting that prior to the eighteenth century cloves grew only on five small islands.","difficulty":"normal","format":"mc","answer":"The clove tree grew only on a small number of islands, limiting global supply","options":["The cloves produced in the Moluccas were of higher quality than those grown elsewhere","The VOC maintained a military fleet capable of blocking rival trade routes","The clove tree grew only on a small number of islands, limiting global supply","European demand for cloves grew faster than demand for any other spice"],"contentHash":"fa24981050245b29bc87f56224979760b8849233eb47b9fb49185657ab2aa941"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0801-4a01-9f11-000000000004', 'vr', 'practice', 'c4a1b8e2-0801-4a01-9f11-000000000004'::uuid, 'vr.main_idea_and_purpose', '{"id":"c4a1b8e2-0801-4a01-9f11-000000000004","mode":"practice","parentId":"c4a1b8e2-0801-4a01-9f11-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"Poivre is introduced immediately after the statement that ''the monopoly was eventually broken in 1770'', and his smuggling of seedlings to Mauritius is presented as the mechanism by which this occurred.","difficulty":"normal","format":"mc","answer":"To explain how the VOC''s monopoly was ultimately broken","options":["To illustrate the botanical diversity of the French colonial empire","To explain how the VOC''s monopoly was ultimately broken","To demonstrate the scientific sophistication of eighteenth-century horticulture","To contrast French and Dutch approaches to colonial administration"],"contentHash":"050c9568c45d541a8137767feaa6fc7b517217fec57f76aefec8bdfc2a282245"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c4a1b8e2-0801-4a01-9f11-000000000005', 'vr', 'practice', 'c4a1b8e2-0801-4a01-9f11-000000000005'::uuid, 'vr.evaluating_evidence', '{"id":"c4a1b8e2-0801-4a01-9f11-000000000005","mode":"practice","parentId":"c4a1b8e2-0801-4a01-9f11-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the monopoly was broken in 1770 by Poivre''s smuggling of seedlings, with cultivation subsequently spreading from Mauritius to Zanzibar.","difficulty":"hard","format":"mc","answer":"It would directly contradict the passage''s claim that Poivre''s action broke the monopoly in 1770","options":["It would have no effect, as the passage does not claim Poivre was the first to move cloves outside the Moluccas","It would directly contradict the passage''s claim that Poivre''s action broke the monopoly in 1770","It would strengthen the passage''s claim about the geographical confinement of the species","It would undermine the passage''s claim that Zanzibar became the largest clove producer by the mid-nineteenth century"],"contentHash":"747c5b35eab9535eb825f80034a3d1fccf31d68a5690824212088ae45ff56902"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4e', 'vr', 'practice', '3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4e'::uuid, 'vr.explicit_information', '{"id":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4e","mode":"practice","parentId":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the tar ''was rendered in enormous earthen kilns...","difficulty":"normal","format":"mc","answer":"In the interior regions of Österbotten in present-day western Finland","options":["In the city of Stockholm by chartered craftsmen","In the interior regions of Österbotten in present-day western Finland","Along the coast of northern Sweden near shipping ports","In the longleaf pine forests of North Carolina"],"contentHash":"5254cb4e9c82928050077e63324943478f8a39352ee945811fc870598b808212"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4f', 'vr', 'practice', '3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4f'::uuid, 'vr.main_idea_and_purpose', '{"id":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4f","mode":"practice","parentId":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4d","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The author juxtaposes quality concerns with ''it was sufficiently cheaper that by the mid-eighteenth century the Baltic monopoly had permanently lost its dominant position.'' The quality concession strengthens the claim that price drove the market shift.","difficulty":"hard","format":"mc","answer":"To emphasise that price, rather than quality, determined the shift in sourcing","options":["To explain why Finnish producers continued to dominate Baltic markets","To suggest that the British and Dutch merchants made a commercial error","To emphasise that price, rather than quality, determined the shift in sourcing","To indicate that longleaf pines produced a fundamentally different substance"],"contentHash":"71fc3f622584b83edcec2efcbf6d208e9b06282d29701c84151ccb0cfc90871a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c50', 'vr', 'practice', '3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c50'::uuid, 'vr.inference', '{"id":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c50","mode":"practice","parentId":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4d","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states producers ''received only a fraction of the final export price'' under a monopoly that ''fixed prices and restricted who could trade'' — both indicating weak bargaining power.","difficulty":"normal","format":"mc","answer":"Finnish producers had limited bargaining power during the monopoly period","options":["The Stockholm Tar Company paid producers the same price as it charged exporters","Finnish producers had limited bargaining power during the monopoly period","Pine tar was primarily used in the construction of kilns and wooden channels","The Great Northern War began in 1715 and ended Swedish tar exports"],"contentHash":"7c7e6698de8af52e7715efda950d43fe4b26967515d4db3a7d391e25954fad82"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c51', 'vr', 'practice', '3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c51'::uuid, 'vr.explicit_information', '{"id":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c51","mode":"practice","parentId":"3f8a91c2-7e4d-4a1b-9c5e-2d6f8a1b3c4d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists waterproofing hulls, preserving ropes, and sealing rigging as tar''s uses.","difficulty":"normal","format":"mc","answer":"Treating the timber used in kiln construction","options":["Waterproofing wooden hulls","Preserving ropes against seawater","Treating the timber used in kiln construction","Sealing rigging"],"contentHash":"05d69e62fd17d8283055d0198ecd0640aa2bcb28412c038e335cef5d8b217997"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f016-1016-4016-8016-000000000002', 'vr', 'practice', 'c7a1f016-1016-4016-8016-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f016-1016-4016-8016-000000000002","mode":"practice","parentId":"c7a1f016-1016-4016-8016-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Palestine, owing to its religious significance and the complexity of competing claims, was to be placed under international administration.''","difficulty":"normal","format":"mc","answer":"Under international administration, owing to religious significance and competing claims","options":["Under direct French administration","Under direct British administration","Under international administration, owing to religious significance and competing claims","As part of an independent Arab state"],"contentHash":"c33507a4c842de40f40b7ca3a978555074bc4c32f083360e39e75160ec87fbf4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f016-1016-4016-8016-000000000003', 'vr', 'practice', 'c7a1f016-1016-4016-8016-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f016-1016-4016-8016-000000000003","mode":"practice","parentId":"c7a1f016-1016-4016-8016-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the terms ''were not made public until after the Russian Revolution, when the Bolshevik government released the text from the tsarist archives in November 1917.''","difficulty":"normal","format":"mc","answer":"Publication by the Bolshevik government after the Russian Revolution","options":["A leak from the British Foreign Office","Publication by the Bolshevik government after the Russian Revolution","A speech by Sir Mark Sykes to the British Parliament","Documents recovered by Arab forces during the Arab Revolt"],"contentHash":"6c0ba3bbedc737fae2aec559df03d5e8ccb0f14158854ca17f9ddf0cddcd24d8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f016-1016-4016-8016-000000000004', 'vr', 'practice', 'c7a1f016-1016-4016-8016-000000000004'::uuid, 'vr.author_perspective', '{"id":"c7a1f016-1016-4016-8016-000000000004","mode":"practice","parentId":"c7a1f016-1016-4016-8016-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''the broad outlines of the modern Middle Eastern state system are often traced to the agreement''s framework, although historians debate the extent to which later boundaries were genuinely shaped by it as opposed to merely resembling it.''","difficulty":"hard","format":"mc","answer":"The broad outlines of the current system are often traced to Sykes-Picot, though historians debate the strength of the link","options":["The modern boundaries correspond precisely to those drawn by Sykes-Picot","The Sykes-Picot boundaries are widely regarded as the direct and undisputed basis for current borders","The broad outlines of the current system are often traced to Sykes-Picot, though historians debate the strength of the link","The current state system is entirely unrelated to the agreement"],"contentHash":"d4a1227470efab65d790e133646a7c4ce400c266d2016e77b40f165c8f786f61"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f016-1016-4016-8016-000000000005', 'vr', 'practice', 'c7a1f016-1016-4016-8016-000000000005'::uuid, 'vr.explicit_information', '{"id":"c7a1f016-1016-4016-8016-000000000005","mode":"practice","parentId":"c7a1f016-1016-4016-8016-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the McMahon-Hussein correspondence as having ''appeared to promise support for an independent Arab state across much of the region'' and says the publication of Sykes-Picot caused embarrassment because its terms ''were inconsistent with'' those commitments.","difficulty":"normal","format":"mc","answer":"Inconsistent with the terms of the Sykes-Picot Agreement","options":["Fully consistent with the terms of the Sykes-Picot Agreement","Made after the Sykes-Picot Agreement was concluded","Inconsistent with the terms of the Sykes-Picot Agreement","Made public at the same time as the Sykes-Picot Agreement"],"contentHash":"66dd6d295dfe71278449228f851b6e17009599b19d70ec95e00d4c38498e4139"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f018-1018-4018-8018-000000000002', 'vr', 'practice', 'c7a1f018-1018-4018-8018-000000000002'::uuid, 'vr.explicit_information', '{"id":"c7a1f018-1018-4018-8018-000000000002","mode":"practice","parentId":"c7a1f018-1018-4018-8018-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the death toll was ''most attributable to famine, disease, and displacement rather than direct combat.''","difficulty":"normal","format":"mc","answer":"Famine, disease, and displacement","options":["Direct combat between opposing armies","Famine, disease, and displacement","Execution of rebels by the Qing government","Foreign military intervention"],"contentHash":"c6026d42e5cc1e3a44a3d9a725449d39cc546dc3f8f44c7c0ebeef2ee69e74ef"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f018-1018-4018-8018-000000000003', 'vr', 'practice', 'c7a1f018-1018-4018-8018-000000000003'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1f018-1018-4018-8018-000000000003","mode":"practice","parentId":"c7a1f018-1018-4018-8018-000000000001","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces Hong''s background — including the failed examinations — as part of a biographical context preceding his visions in 1837, leading into the founding of the Society of God-Worshippers.","difficulty":"normal","format":"mc","answer":"To explain the context of his personal background before his visions and the founding of the movement","options":["To establish that Hong was uneducated","To explain the context of his personal background before his visions and the founding of the movement","To contrast Hong with Zeng Guofan","To argue that the civil service system caused the rebellion"],"contentHash":"77e34c29620c5a3a033a43b721db130fdb49155fd0d0992639d1510c867af88d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f018-1018-4018-8018-000000000004', 'vr', 'practice', 'c7a1f018-1018-4018-8018-000000000004'::uuid, 'vr.explicit_information', '{"id":"c7a1f018-1018-4018-8018-000000000004","mode":"practice","parentId":"c7a1f018-1018-4018-8018-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''In practice, enforcement of these policies varied considerably'', indicating uneven application.","difficulty":"normal","format":"mc","answer":"They were proclaimed but applied unevenly in practice","options":["They were uniformly enforced throughout Taiping-held territory","They were proclaimed but applied unevenly in practice","They had no impact on daily life in the Heavenly Kingdom","They were imposed only after the fall of Nanjing"],"contentHash":"73371b8cd823d0b94812757ce9263f38e7672eea2a4893b503b899e142ab3b3b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f018-1018-4018-8018-000000000005', 'vr', 'practice', 'c7a1f018-1018-4018-8018-000000000005'::uuid, 'vr.inference', '{"id":"c7a1f018-1018-4018-8018-000000000005","mode":"practice","parentId":"c7a1f018-1018-4018-8018-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the court ''authorised provincial officials — most notably Zeng Guofan in Hunan — to raise militia forces loyal to local commanders'', supporting the inference that these forces were provincially drawn and commanded.","difficulty":"hard","format":"mc","answer":"Zeng Guofan''s forces were drawn from and loyal to provincial rather than central authority","options":["The Qing regular Banner armies were sufficient to suppress the rebellion on their own","Zeng Guofan''s forces were drawn from and loyal to provincial rather than central authority","Hong Xiuquan led the final defence of Nanjing in person","Foot-binding was reintroduced in the Heavenly Kingdom after its early years"],"contentHash":"35fb950c4fed552182afe2b473c4a575c6b8f0494f3deec2ebf6bf44ce4c88b3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f002-1002-4002-8002-000000000002', 'vr', 'practice', 'c7a1f002-1002-4002-8002-000000000002'::uuid, 'vr.unsupported_claims', '{"id":"c7a1f002-1002-4002-8002-000000000002","mode":"practice","parentId":"c7a1f002-1002-4002-8002-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Tasman Glacier is the ''largest'' glacier in New Zealand and gives its length, but ''largest'' does not necessarily mean ''longest'' — size could refer to area or volume.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"0dcae9ff949ccf6bae16da5f3eaafcca70106ac41a209656a83b32f23ead8bb8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f002-1002-4002-8002-000000000003', 'vr', 'practice', 'c7a1f002-1002-4002-8002-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f002-1002-4002-8002-000000000003","mode":"practice","parentId":"c7a1f002-1002-4002-8002-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states that Tasman Lake ''did not exist before the 1970s'', so its formation occurred after that point.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"94090c03aea65f2698a6689946a002ab00ae0a246b5675513415579a0545e982"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f002-1002-4002-8002-000000000004', 'vr', 'practice', 'c7a1f002-1002-4002-8002-000000000004'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f002-1002-4002-8002-000000000004","mode":"practice","parentId":"c7a1f002-1002-4002-8002-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that ''Temperate glaciers are more sensitive to changes in air temperature than polar glaciers'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"3211285d1eb262277e04d688761187eb1a03223446f7dd23df3c00d1b630c4f6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f002-1002-4002-8002-000000000005', 'vr', 'practice', 'c7a1f002-1002-4002-8002-000000000005'::uuid, 'vr.recognising_contradictions', '{"id":"c7a1f002-1002-4002-8002-000000000005","mode":"practice","parentId":"c7a1f002-1002-4002-8002-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the net effect of the debris cover has been to ''moderate, but not prevent, the retreat''.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"8be516df2765e9406cbd140ee418fddf87390568ecd6d731bd2787d04ae2e3a9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:8e64794e-861e-4517-a8db-da4e967e63a2', 'vr', 'practice', '8e64794e-861e-4517-a8db-da4e967e63a2'::uuid, 'vr.explicit_information', '{"id":"8e64794e-861e-4517-a8db-da4e967e63a2","mode":"practice","parentId":"e3075813-ac78-489a-ad70-ad1857366808","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage says the Sun appeared beside different towers and gaps as its rising position moved, allowing the system to indicate many dates through the year.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"91c0f50fa4cf3086fb8cf0a282ff1a4113a7bd4a907a20f1fc0184dac0f6192d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:9ea052e8-37a4-4be5-a7b5-9bcb19ac2b29', 'vr', 'practice', '9ea052e8-37a4-4be5-a7b5-9bcb19ac2b29'::uuid, 'vr.recognising_contradictions', '{"id":"9ea052e8-37a4-4be5-a7b5-9bcb19ac2b29","mode":"practice","parentId":"e3075813-ac78-489a-ad70-ad1857366808","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The western point survives clearly, whereas the eastern point is less visible above ground and is known from its foundations.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"cfcd78fb1926ef36f3134294bdeb31739c25beb64f7c3fdb23214934a35fc0c7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:a228d533-d875-4fa5-8d12-9d49a09f05fe', 'vr', 'practice', 'a228d533-d875-4fa5-8d12-9d49a09f05fe'::uuid, 'vr.unsupported_claims', '{"id":"a228d533-d875-4fa5-8d12-9d49a09f05fe","mode":"practice","parentId":"e3075813-ac78-489a-ad70-ad1857366808","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage suggests controlled access and a possible connection between specialist knowledge and authority, but it states that the institution and the identities of the calendar readers are unknown.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"cea078bf69208f0ee2b73aa33116010e26890a077d3ec52024c17ea8ecc94851"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:b42d90d5-f9be-46d0-9cbe-9f6c2e89343b', 'vr', 'practice', 'b42d90d5-f9be-46d0-9cbe-9f6c2e89343b'::uuid, 'vr.recognising_contradictions', '{"id":"b42d90d5-f9be-46d0-9cbe-9f6c2e89343b","mode":"practice","parentId":"e3075813-ac78-489a-ad70-ad1857366808","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage assigns sunrise observations to the western point and corresponding sunset observations to the eastern point.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"4228c0825c134d7639d3ae3d3a665ec1a6fdbca6d9b5abdef5d8ddf9adec1a3d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f003-1003-4003-8003-000000000002', 'vr', 'practice', 'c7a1f003-1003-4003-8003-000000000002'::uuid, 'vr.author_perspective', '{"id":"c7a1f003-1003-4003-8003-000000000002","mode":"practice","parentId":"c7a1f003-1003-4003-8003-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''most modern scholars regard it as a choreographed demonstration rather than a typical day''s work, but the underlying logistical achievement is not disputed.'' This matches the correct option directly.","difficulty":"normal","format":"mc","answer":"It is regarded as a staged demonstration, although the underlying capability is not disputed","options":["It is generally dismissed as a fabrication","It is accepted as an accurate reflection of routine Arsenal output","It is regarded as a staged demonstration, although the underlying capability is not disputed","It has been confirmed by archaeological evidence"],"contentHash":"fbcc2adf74ea6d6a3c192d1a0d41aacf07f3b0a91802d7691976fda23e9e1fba"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f003-1003-4003-8003-000000000003', 'vr', 'practice', 'c7a1f003-1003-4003-8003-000000000003'::uuid, 'vr.explicit_information', '{"id":"c7a1f003-1003-4003-8003-000000000003","mode":"practice","parentId":"c7a1f003-1003-4003-8003-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the Corderie as ''a dedicated ropewalk of exceptional length...","difficulty":"normal","format":"mc","answer":"To produce continuous lengths of rope without joins","options":["To season timber for ship hulls","To cast cannons to fit standardised gun ports","To produce continuous lengths of rope without joins","To house the arsenalotti workforce"],"contentHash":"c95b233817d06bedff2565698ada78d2631fe22c2e966abd7ba1a1fefbcbb6aa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f003-1003-4003-8003-000000000004', 'vr', 'practice', 'c7a1f003-1003-4003-8003-000000000004'::uuid, 'vr.inference', '{"id":"c7a1f003-1003-4003-8003-000000000004","mode":"practice","parentId":"c7a1f003-1003-4003-8003-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that standardisation ''enabled parts to be manufactured independently, stored, and fitted to any hull of the appropriate class.'' This implies parts could be produced and stored before a specific hull was built.","difficulty":"hard","format":"mc","answer":"Standardised components could be prepared before a specific ship''s construction began","options":["The Arsenal was the first place in history where division of labour was used","Industrial Revolution engineers studied the Venetian Arsenal as a model","The Arsenal''s decline was caused by labour disputes among the arsenalotti","Standardised components could be prepared before a specific ship''s construction began"],"contentHash":"1082884ea4f2d33841348a45efc9c8a50fe8e577c87ef60faa0c7d29d42b26f8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1f003-1003-4003-8003-000000000005', 'vr', 'practice', 'c7a1f003-1003-4003-8003-000000000005'::uuid, 'vr.meaning_in_context', '{"id":"c7a1f003-1003-4003-8003-000000000005","mode":"practice","parentId":"c7a1f003-1003-4003-8003-000000000001","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage introduces the term directly: ''it employed around 16,000 workers, known as arsenalotti''.","difficulty":"normal","format":"mc","answer":"The workers employed at the Arsenal","options":["The ships produced at the Arsenal","The workers employed at the Arsenal","The managers overseeing Arsenal production","The military units stationed at the Arsenal"],"contentHash":"8447d7bdf3994e51da96ef3c99ddca3b66833960560d005cc6759aa5476eb333"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:7d2e55a6-1c8b-4e5f-d9a0-6b0c2e5f7a8c', 'vr', 'practice', '7d2e55a6-1c8b-4e5f-d9a0-6b0c2e5f7a8c'::uuid, 'vr.recognising_contradictions', '{"id":"7d2e55a6-1c8b-4e5f-d9a0-6b0c2e5f7a8c","mode":"practice","parentId":"7d2e55a6-1c8b-4e5f-d9a0-6b0c2e5f7a8b","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the connection between the Indonesian eruption and the bizarre European weather was not established at the time'', directly contradicting the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"3e6acce8cb3a42c2e8892bdcdf3143f585229e12ce85c62181e788925ed99d73"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
