INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0002-4002-8002-000000000002', 'vr', 'practice', 'f1a2b3c4-0002-4002-8002-000000000002'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0002-4002-8002-000000000002","mode":"practice","parentId":"f1a2b3c4-0002-4002-8002-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the flame-like colour patterns ''are now known to have been caused by a mosaic virus'', directly supporting the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"3c3ab4897513731950991e188dfa623cf42def1aec40cdb05c99e3fe7632cdf5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0002-4002-8002-000000000003', 'vr', 'practice', 'f1a2b3c4-0002-4002-8002-000000000003'::uuid, 'vr.author_perspective', '{"id":"f1a2b3c4-0002-4002-8002-000000000003","mode":"practice","parentId":"f1a2b3c4-0002-4002-8002-000000000001","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage explicitly refers to Goldgar''s argument that ''the long-standing narrative of nationwide ruin is exaggerated'' and that ''few bankruptcies in the period can be directly attributed to tulip speculation''.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"5ba4f394705873e753f72a8c0b8ce93a29e0227b159758bc734a47c9e709e096"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0002-4002-8002-000000000004', 'vr', 'practice', 'f1a2b3c4-0002-4002-8002-000000000004'::uuid, 'vr.recognising_contradictions', '{"id":"f1a2b3c4-0002-4002-8002-000000000004","mode":"practice","parentId":"f1a2b3c4-0002-4002-8002-000000000001","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states tulips ''had been introduced to the Low Countries from the Ottoman Empire in the late sixteenth century'', which contradicts the claim that they were native.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"bdd03092b8cf47be7fe510b953c2ee92106a29c86c6d5e7c5edb91688fa88355"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0002-4002-8002-000000000005', 'vr', 'practice', 'f1a2b3c4-0002-4002-8002-000000000005'::uuid, 'vr.qualifiers_and_scope', '{"id":"f1a2b3c4-0002-4002-8002-000000000005","mode":"practice","parentId":"f1a2b3c4-0002-4002-8002-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage says the market collapsed ''reportedly when'' a Haarlem auction failed, which presents it as an associated event but does not establish it as the sole cause.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"5be22e2a7472a92fb8dd7a459c7600475831fc0bc159c08aea4554c938eefc65"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0008-4008-8008-000000000002', 'vr', 'practice', 'f1a2b3c4-0008-4008-8008-000000000002'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0008-4008-8008-000000000002","mode":"practice","parentId":"f1a2b3c4-0008-4008-8008-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the official justification was the prevention of fires''.","difficulty":"normal","format":"mc","answer":"To reduce the risk of fires in Venice","options":["To allow easier supervision of the industry''s techniques","To reduce the risk of fires in Venice","To permit glassmakers'' daughters to marry into the nobility","To compete with English lead crystal producers"],"contentHash":"5166e12bb9e3a1b735a2e681f18706c58027ed87ca2b551f0a7d9c81d5706a03"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0008-4008-8008-000000000003', 'vr', 'practice', 'f1a2b3c4-0008-4008-8008-000000000003'::uuid, 'vr.inference', '{"id":"f1a2b3c4-0008-4008-8008-000000000003","mode":"practice","parentId":"f1a2b3c4-0008-4008-8008-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that glassmakers ''enjoyed unusual privileges'' and specifically notes the marriage right ''denied to almost all other artisans''.","difficulty":"normal","format":"mc","answer":"They held legal privileges that distinguished them from most other craftspeople","options":["They were considered inferior to other artisans","They held legal privileges that distinguished them from most other craftspeople","They were granted full Venetian citizenship regardless of origin","They were permitted to travel freely throughout Europe"],"contentHash":"d8efcb6ed3f71ad14f63593474fa63c5e94f4bee0096e2310a6e9be9cce516cc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0008-4008-8008-000000000004', 'vr', 'practice', 'f1a2b3c4-0008-4008-8008-000000000004'::uuid, 'vr.explicit_information', '{"id":"f1a2b3c4-0008-4008-8008-000000000004","mode":"practice","parentId":"f1a2b3c4-0008-4008-8008-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''despite these measures, some craftsmen did emigrate, and Venetian glassmaking methods spread gradually to France, Bohemia, and England''.","difficulty":"normal","format":"mc","answer":"Despite the restrictions, some craftsmen emigrated and spread the techniques abroad","options":["The restrictions completely prevented emigration","The restrictions were effective only until the eighteenth century","Despite the restrictions, some craftsmen emigrated and spread the techniques abroad","The restrictions led to the complete collapse of foreign glass industries"],"contentHash":"83917da2929fdcbcb7bc3339f5fa56079997d1e11c6aa0d9ca6337bfce19667b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:f1a2b3c4-0008-4008-8008-000000000005', 'vr', 'practice', 'f1a2b3c4-0008-4008-8008-000000000005'::uuid, 'vr.evaluating_evidence', '{"id":"f1a2b3c4-0008-4008-8008-000000000005","mode":"practice","parentId":"f1a2b3c4-0008-4008-8008-000000000001","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"medium","rationale":"The passage describes filigrana and millefiori as ''traditional techniques'' that were ''revived'' on Murano.","difficulty":"hard","format":"mc","answer":"It would complicate the description of these techniques as traditional to Murano","options":["It would invalidate the claim that Murano''s industry declined in the eighteenth century","It would complicate the description of these techniques as traditional to Murano","It would confirm the assassination policy was ineffective","It would prove the Austrian administration was responsible for the revival"],"contentHash":"52fb20ec27f25d84a6ab4da402eafcd23dc9c5e7cf1eb3b14960a4d332816f1f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0604-4a04-9d04-000000000401', 'vr', 'practice', 'c7a1e4b2-0604-4a04-9d04-000000000401'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0604-4a04-9d04-000000000401","mode":"practice","parentId":"c7a1e4b2-0604-4a04-9d04-000000000004","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the first stage ''is dominated by mobile scavengers such as hagfish, sleeper sharks, and amphipods''.","difficulty":"normal","format":"mc","answer":"Hagfish","options":["Osedax worms","Hagfish","Chemosynthetic bacteria","Polychaete worms colonising sediment"],"contentHash":"2da16042b4c4cc42cc68d1d5ee7faae4bea8d21238f2c8b52bed8c563b97bf0b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0604-4a04-9d04-000000000402', 'vr', 'practice', 'c7a1e4b2-0604-4a04-9d04-000000000402'::uuid, 'vr.main_idea_and_purpose', '{"id":"c7a1e4b2-0604-4a04-9d04-000000000402","mode":"practice","parentId":"c7a1e4b2-0604-4a04-9d04-000000000004","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly links the detail to the claim that Osedax ''may be older than the evolutionary origin of whales themselves'', using the breadth of host skeletons as supporting evidence.","difficulty":"normal","format":"mc","answer":"To support the suggestion that the genus may predate whales","options":["To argue that Osedax should be reclassified as a fish parasite","To explain why whale falls last for decades","To support the suggestion that the genus may predate whales","To illustrate how chemosynthetic bacteria function"],"contentHash":"886c32768ce34963f8bab59a8d727b9499375c94c67857befe83ff314deffc0b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0604-4a04-9d04-000000000403', 'vr', 'practice', 'c7a1e4b2-0604-4a04-9d04-000000000403'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0604-4a04-9d04-000000000403","mode":"practice","parentId":"c7a1e4b2-0604-4a04-9d04-000000000004","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that sulphophilic communities ''resembling those found at hydrothermal vents'' develop on whale falls, directly indicating ecological similarity.","difficulty":"normal","format":"mc","answer":"Whale falls share ecological features with hydrothermal vents","options":["The sulphophilic stage depends on oxygen-rich conditions near the carcass","Osedax digests bone lipids directly using its own enzymes","Whale falls share ecological features with hydrothermal vents","Whale falls cannot persist for more than a decade"],"contentHash":"aa3a16fb910a9462fa536712f395118e73dec552eab282f9db3438eeea947bf6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c7a1e4b2-0604-4a04-9d04-000000000404', 'vr', 'practice', 'c7a1e4b2-0604-4a04-9d04-000000000404'::uuid, 'vr.explicit_information', '{"id":"c7a1e4b2-0604-4a04-9d04-000000000404","mode":"practice","parentId":"c7a1e4b2-0604-4a04-9d04-000000000004","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage lists size, depth, and ambient temperature as influencing factors.","difficulty":"hard","format":"mc","answer":"The species of whale","options":["The size of the whale","The depth at which the carcass settles","The ambient temperature","The species of whale"],"contentHash":"00211783f1ba40888b9650b481d2822f561252f9d931cf1bf1655852ccc5fa85"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:629c51ee-482f-45e2-b55c-b61f72080f31', 'vr', 'practice', '629c51ee-482f-45e2-b55c-b61f72080f31'::uuid, 'vr.explicit_information', '{"id":"629c51ee-482f-45e2-b55c-b61f72080f31","mode":"practice","parentId":"89052d68-8561-471c-ab88-da03c30ea209","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The first paragraph gives flow and binding as gum arabic''s functions.","difficulty":"normal","format":"mc","answer":"It improves flow and helps bind the ink to the writing surface","options":["It supplies the iron ions that oxidise cellulose","It removes excess acid during deacidification","It improves flow and helps bind the ink to the writing surface","It changes damaged brown ink back to bluish black"],"contentHash":"de067932a94738aa9e6a5cc4bb05f0631727e10b2dd7df63e58aa2c6beb1b98a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:efbde862-806c-47da-8245-7703abce14ce', 'vr', 'practice', 'efbde862-806c-47da-8245-7703abce14ce'::uuid, 'vr.explicit_information', '{"id":"efbde862-806c-47da-8245-7703abce14ce","mode":"practice","parentId":"89052d68-8561-471c-ab88-da03c30ea209","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly links moisture with migration of iron ions and acids.","difficulty":"normal","format":"mc","answer":"It allows reactive iron and acids to migrate into nearby paper","options":["It allows reactive iron and acids to migrate into nearby paper","It converts gum arabic directly into sulphuric acid","It makes tannins reproduce throughout the paper fibres","It permanently strengthens cellulose around the written line"],"contentHash":"1eaac33458d861aac8c0e4499fb535e6d2a543f3f5171415fe7105aa9ff3948d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:e2819377-d42f-4e75-b651-72c17c83488f', 'vr', 'practice', 'e2819377-d42f-4e75-b651-72c17c83488f'::uuid, 'vr.inference', '{"id":"e2819377-d42f-4e75-b651-72c17c83488f","mode":"practice","parentId":"89052d68-8561-471c-ab88-da03c30ea209","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage identifies redistribution of soluble material as a risk requiring prior testing.","difficulty":"hard","format":"mc","answer":"Water could redistribute soluble damaging compounds through the sheet","options":["Water always erases iron gall ink immediately and completely","Aqueous treatment can address acidity but never oxidation","Indicator papers work only after a manuscript has been washed","Water could redistribute soluble damaging compounds through the sheet"],"contentHash":"bf6ac121009fcb30bf43f355b0a99675b98ce86c26d116cd3a0b2fe3cee7c058"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:14d01a0f-dc44-4da3-8416-b39394c60047', 'vr', 'practice', '14d01a0f-dc44-4da3-8416-b39394c60047'::uuid, 'vr.main_idea_and_purpose', '{"id":"14d01a0f-dc44-4da3-8416-b39394c60047","mode":"practice","parentId":"89052d68-8561-471c-ab88-da03c30ea209","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage presents conservation as case-specific risk management using assessment, possible chemical treatment, support and storage.","difficulty":"normal","format":"mc","answer":"Assess each object and balance chemical, physical and preventive measures","options":["Reinforce every damaged sheet because support stops the underlying chemistry","Assess each object and balance chemical, physical and preventive measures","Apply the same deacidification formula to every manuscript","Avoid stable dry storage once chemical treatment has been completed"],"contentHash":"b0ef1a39d8677e1f3b0856bb750867c65f7b391af94954c65fbb4b63eaed0000"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:10d52d04-0f6e-49b8-9a95-df8f9d2f96b9', 'vr', 'practice', '10d52d04-0f6e-49b8-9a95-df8f9d2f96b9'::uuid, 'vr.meaning_in_context', '{"id":"10d52d04-0f6e-49b8-9a95-df8f9d2f96b9","mode":"practice","parentId":"2ec286c7-0754-4e7c-b994-202d18e04bc1","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines the head as a height difference after the pond retains high-tide water while the sea falls.","difficulty":"normal","format":"mc","answer":"A difference between stored pond water and the falling sea","options":["The millstones lifting seawater into the pond","A river flowing constantly over the wheel","Waves striking the wheel directly","A difference between stored pond water and the falling sea"],"contentHash":"1cf178f3a07583cd26dc45b0e2c5e832719a9d99366b5cae406598e4f7288b5e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:fc79e195-a26e-4611-bb2d-89899f95de36', 'vr', 'practice', 'fc79e195-a26e-4611-bb2d-89899f95de36'::uuid, 'vr.explicit_information', '{"id":"fc79e195-a26e-4611-bb2d-89899f95de36","mode":"practice","parentId":"2ec286c7-0754-4e7c-b994-202d18e04bc1","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The pond has already filled, but the passage says the sea outside must fall enough to create a useful height difference.","difficulty":"normal","format":"mc","answer":"The outside sea must fall enough to give the stored water a useful height advantage.","options":["The next incoming tide must refill the pond before each use.","The outside sea must fall enough to give the stored water a useful height advantage.","The sea must rise high enough to cover the mill wheel.","The miller must release all stored water before the wheel starts."],"contentHash":"38c760760649cd5ad61625218b59133c0074cd5cfc9445c91a97f34744751741"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:e285562a-5ee4-4af5-951a-43579930a57e', 'vr', 'practice', 'e285562a-5ee4-4af5-951a-43579930a57e'::uuid, 'vr.main_idea_and_purpose', '{"id":"e285562a-5ee4-4af5-951a-43579930a57e","mode":"practice","parentId":"2ec286c7-0754-4e7c-b994-202d18e04bc1","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The example combines a dam and sluice gear with a wheel and millstones.","difficulty":"normal","format":"mc","answer":"That tidal water management and familiar milling machinery operated together","options":["That tide mills had no machinery in common with river mills","That the dam served only as a bridge across the inlet","That tidal water management and familiar milling machinery operated together","That every tide mill used exactly the same set of millstones"],"contentHash":"4ce84d7551540ea2369fd5713329b180beb84cacc3d20086936de0fd7f0deea7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:practice:c66ec54c-2c9b-432b-889c-0a82115d993c', 'vr', 'practice', 'c66ec54c-2c9b-432b-889c-0a82115d993c'::uuid, 'vr.inference', '{"id":"c66ec54c-2c9b-432b-889c-0a82115d993c","mode":"practice","parentId":"2ec286c7-0754-4e7c-b994-202d18e04bc1","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"Closed gates retain pond water while the sea falls, so the height difference may increase.","difficulty":"hard","format":"mc","answer":"The difference in water levels can grow before the miller releases pond water.","options":["The difference in water levels can grow before the miller releases pond water.","The wheel must turn at a constant speed as the tide falls.","The pond immediately empties into the estuary.","The next incoming tide can no longer refill the pond."],"contentHash":"600895ca45b1e3464a58e5f4dff833cf86126ae0a792d6eb30be922014b420c0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e5bb3d0f-e0b2-4eaa-8937-06b9dc83ff20', 'vr', 'timed', 'e5bb3d0f-e0b2-4eaa-8937-06b9dc83ff20'::uuid, 'vr.meaning_in_context', '{"id":"e5bb3d0f-e0b2-4eaa-8937-06b9dc83ff20","mode":"timed","parentId":"44557a3b-7b63-433e-b730-d349a71f2338","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''any straight line drawn on a Mercator map represents a line of constant compass bearing, called a rhumb line or loxodrome.'' The correct option directly paraphrases this definition.","difficulty":"normal","format":"mc","answer":"A straight line on a Mercator map representing a course of constant compass bearing","options":["The curved path taken by a ship navigating between two points on a globe","A straight line on a Mercator map representing a course of constant compass bearing","The boundary between regions of accurate and distorted representation on a map projection","A line of latitude used to measure distance from the equator on navigational charts"],"contentHash":"68ff1ed061d9069b14fd30d0f31e639d54cd2383527f50048b5731ca89d458c5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fdeca80f-bab6-4834-8dad-1edbe8ccc9f6', 'vr', 'timed', 'fdeca80f-bab6-4834-8dad-1edbe8ccc9f6'::uuid, 'vr.explicit_information', '{"id":"fdeca80f-bab6-4834-8dad-1edbe8ccc9f6","mode":"timed","parentId":"44557a3b-7b63-433e-b730-d349a71f2338","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Greenland appears roughly comparable in size to Africa on a standard Mercator map, when in reality Africa is approximately fourteen times larger.'' The correct option accurately reflects both the mapped appearance and the true size relationship.","difficulty":"normal","format":"mc","answer":"Africa appears approximately the same size as Greenland on the Mercator map, but is actually fourteen times larger","options":["Africa appears approximately the same size as Greenland on the Mercator map, but is actually fourteen times larger","Africa appears much larger than Greenland on the Mercator map, consistent with its true size","Greenland appears smaller than Africa on the Mercator map, accurately reflecting their true size difference","Africa appears twice the size of Greenland on the Mercator map, but is actually seven times larger"],"contentHash":"ea04b2606036972883e676788b765b042ac8326f21b9918e8e55f16ebc6acef5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b472be7b-ad1a-4afc-a1d6-80cce8059d74', 'vr', 'timed', 'b472be7b-ad1a-4afc-a1d6-80cce8059d74'::uuid, 'vr.author_perspective', '{"id":"b472be7b-ad1a-4afc-a1d6-80cce8059d74","mode":"timed","parentId":"44557a3b-7b63-433e-b730-d349a71f2338","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Critics argued this had ideological consequences, inflating the apparent size of Europe and North America — the seats of colonial power — relative to equatorial Africa, Asia, and Latin America.'' The other options introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"That it had ideological consequences by inflating the apparent size of colonial powers relative to equatorial regions","options":["That it made navigation unnecessarily complicated for students unfamiliar with compass bearings","That it had ideological consequences by inflating the apparent size of colonial powers relative to equatorial regions","That it was technically inferior to the Peters projection in every measurable respect","That it had been superseded by satellite mapping technology and was therefore historically obsolete"],"contentHash":"45e9ba25a9786c37f6780a2442534d2874e8b9a83a2e8307ac2c677884a4f315"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:df0e4638-44df-4f6a-9002-6cd47d645a8a', 'vr', 'timed', 'df0e4638-44df-4f6a-9002-6cd47d645a8a'::uuid, 'vr.author_perspective', '{"id":"df0e4638-44df-4f6a-9002-6cd47d645a8a","mode":"timed","parentId":"44557a3b-7b63-433e-b730-d349a71f2338","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage concludes ''Neither projection is universally superior,'' and notes Mercator remains standard for digital mapping due to its angle-preserving properties while the Peters projection preserves area.","difficulty":"normal","format":"mc","answer":"Neither projection is universally superior; each serves different purposes","options":["The Peters projection is superior because accuracy of area is more important than accuracy of angles","The Mercator projection is superior because it is used by major digital mapping applications","Neither projection is universally superior; each serves different purposes","Both projections are now obsolete, having been replaced by three-dimensional digital mapping"],"contentHash":"399257ba90ab540d07e8775caafb3fbfec51df08dfc3ed9c78cf051198e50c8a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1a51f438-f3ad-4f13-88ee-3324f8c0de8f', 'vr', 'timed', '1a51f438-f3ad-4f13-88ee-3324f8c0de8f'::uuid, 'vr.explicit_information', '{"id":"1a51f438-f3ad-4f13-88ee-3324f8c0de8f","mode":"timed","parentId":"c8c19eae-f5e4-4aa0-b56f-3d3d2a18bd6c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the rivers were diverted ''to irrigate cotton plantations across the Central Asian steppe — a campaign to make the Soviet Union self-sufficient in cotton production.'' The other options are not mentioned in the passage and represent fabrications.","difficulty":"normal","format":"mc","answer":"To irrigate cotton crops and make the Soviet Union self-sufficient in cotton","options":["To generate hydroelectric power for Soviet industrial expansion","To provide drinking water to growing urban populations in Central Asia","To irrigate cotton crops and make the Soviet Union self-sufficient in cotton","To prevent seasonal flooding of agricultural land near the rivers"],"contentHash":"a87eaf60bb20a461199ecf8930684670bd61a5f0ce231d25dbb8df491f2dfb5e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:d5d85a58-71fc-466f-bc30-4e2467cc9806', 'vr', 'timed', 'd5d85a58-71fc-466f-bc30-4e2467cc9806'::uuid, 'vr.explicit_information', '{"id":"d5d85a58-71fc-466f-bc30-4e2467cc9806","mode":"timed","parentId":"c8c19eae-f5e4-4aa0-b56f-3d3d2a18bd6c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the diversion ''was extraordinarily successful as an agricultural programme'' and that ''the Soviet Union became one of the world''s largest cotton producers.'' The other options contradict this — the programme was successful, not ineffective or abandoned, and the USSR became one of the largest producers, not the sole supplier.","difficulty":"normal","format":"mc","answer":"It made the Soviet Union one of the world''s largest cotton producers","options":["It had little measurable impact on Soviet cotton output","It made the Soviet Union one of the world''s largest cotton producers","It enabled the Soviet Union to become the sole global supplier of cotton","It was abandoned before any significant cotton production was achieved"],"contentHash":"757ca2d322839acde86fe4b3224b99b9022d83a54f820a479c39ecaa766f4b6e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7c4cb6a1-38f0-4aa7-b84a-5c02e21b9d1b', 'vr', 'timed', '7c4cb6a1-38f0-4aa7-b84a-5c02e21b9d1b'::uuid, 'vr.explicit_information', '{"id":"7c4cb6a1-38f0-4aa7-b84a-5c02e21b9d1b","mode":"timed","parentId":"c8c19eae-f5e4-4aa0-b56f-3d3d2a18bd6c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the exposed seabed ''became a source of toxic dust storms affecting communities across the region.'' The other options contradict the passage — the seabed was contaminated (not productive for agriculture), port towns were stranded far from the water (not flooded), and fish populations collapsed (not increased).","difficulty":"normal","format":"mc","answer":"Toxic dust storms affecting communities in the region","options":["Increased agricultural productivity in surrounding regions due to mineral-rich soil","Toxic dust storms affecting communities in the region","Flooding of former port towns as groundwater levels rose","A significant increase in fish populations in adjacent rivers"],"contentHash":"eeba407c37f1a77ca37669adcd5853419b1e950c6a617850b26cc1c1d657f85f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:baae147f-dfb9-4f28-9cd5-347997153257', 'vr', 'timed', 'baae147f-dfb9-4f28-9cd5-347997153257'::uuid, 'vr.explicit_information', '{"id":"baae147f-dfb9-4f28-9cd5-347997153257","mode":"timed","parentId":"c8c19eae-f5e4-4aa0-b56f-3d3d2a18bd6c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Kazakhstan''s dam construction in 2005, after which ''water levels in the northern Aral Sea have since recovered significantly,'' while ''no comparable recovery effort has succeeded for the southern portion, which remains largely dessicated.'' This matches the correct option.","difficulty":"hard","format":"mc","answer":"The northern portion has partially recovered while the southern portion remains largely dried out","options":["Both the northern and southern portions have been substantially restored through international intervention","The sea has almost entirely disappeared, with no recovery efforts attempted","The northern portion has partially recovered while the southern portion remains largely dried out","The sea''s surface area is now approximately half of its original 68,000 square kilometres"],"contentHash":"f891a81bfb4a6584489de3dd040d04a4cc78aa507a511d4c19ba8eeba9ae5f91"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c5b09fe3-1f18-46b3-b489-79d0daa12174', 'vr', 'timed', 'c5b09fe3-1f18-46b3-b489-79d0daa12174'::uuid, 'vr.evaluating_evidence', '{"id":"c5b09fe3-1f18-46b3-b489-79d0daa12174","mode":"timed","parentId":"d5a3b3c2-904a-40a1-bb1a-7da474ecdde7","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Crime rates fell in many American cities during the same period that did not adopt broken windows policing,'' which critics used to argue other factors were responsible.","difficulty":"normal","format":"mc","answer":"Crime rates also fell in cities that did not use broken windows policing during the same period","options":["The policing strategy was implemented inconsistently across different boroughs","Crime rates also fell in cities that did not use broken windows policing during the same period","William Bratton admitted the policy had failed to reduce serious crime","The theory was developed after the period in which it was applied"],"contentHash":"1d03d17c4e8cfc8716410ef95992e6ed24ede298dc680ef089b6788539ac264c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6ec0fe4c-43a0-4f7f-873c-679f32351feb', 'vr', 'timed', '6ec0fe4c-43a0-4f7f-873c-679f32351feb'::uuid, 'vr.explicit_information', '{"id":"6ec0fe4c-43a0-4f7f-873c-679f32351feb","mode":"timed","parentId":"d5a3b3c2-904a-40a1-bb1a-7da474ecdde7","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the theory was introduced in ''a 1982 Atlantic Monthly article.'' The other options are fabrications — the passage makes no reference to a criminology journal, NYPD report, or co-authored book.","difficulty":"normal","format":"mc","answer":"The Atlantic Monthly","options":["A peer-reviewed criminology journal","A New York City Police Department policy report","The Atlantic Monthly","A book co-authored with Mayor Giuliani"],"contentHash":"0d9719af2af9c4184a820708e7cfcc382131cd140cc9959e5092f845a759923e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:4f6c5802-7893-4918-9f58-db0f4694d3b2', 'vr', 'timed', '4f6c5802-7893-4918-9f58-db0f4694d3b2'::uuid, 'vr.evaluating_evidence', '{"id":"4f6c5802-7893-4918-9f58-db0f4694d3b2","mode":"timed","parentId":"d5a3b3c2-904a-40a1-bb1a-7da474ecdde7","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"Critics argued that broader economic and demographic factors — not broken windows policing — drove crime reductions.","difficulty":"hard","format":"mc","answer":"Evidence that cities with unchanged policing policies experienced crime reductions similar to New York''s","options":["A study showing that graffiti removal correlated with reduced vandalism in one city","Evidence that cities with unchanged policing policies experienced crime reductions similar to New York''s","Data showing that New York''s crack cocaine epidemic ended before the broken windows policy began","A survey finding that residents felt safer after minor disorder was addressed"],"contentHash":"f058c88048337b37d6b6c6821b89a29beb35afc547f778ed2631bc6da3a82be5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f31491a9-20e4-45d8-812d-37da6d63f0c0', 'vr', 'timed', 'f31491a9-20e4-45d8-812d-37da6d63f0c0'::uuid, 'vr.evaluating_evidence', '{"id":"f31491a9-20e4-45d8-812d-37da6d63f0c0","mode":"timed","parentId":"d5a3b3c2-904a-40a1-bb1a-7da474ecdde7","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the theory ''remains influential in urban policy debates but is no longer treated as settled science,'' and that academic evaluations have ''produced mixed results.'' This directly matches the correct answer.","difficulty":"normal","format":"mc","answer":"It remains influential in policy debates but its empirical basis is disputed","options":["It has been comprehensively refuted and is no longer referenced in urban policy","It is widely accepted as proven by the success of New York City''s 1990s policing","It remains influential in policy debates but its empirical basis is disputed","It is regarded as the most important development in twentieth-century criminology"],"contentHash":"827569019081aa451652e35512c640e782df420a3a1fdcd3ccb2cc26a23f05ba"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a762c5fc-e165-4f67-a881-8dd5cd2bbe10', 'vr', 'timed', 'a762c5fc-e165-4f67-a881-8dd5cd2bbe10'::uuid, 'vr.inference', '{"id":"a762c5fc-e165-4f67-a881-8dd5cd2bbe10","mode":"timed","parentId":"7933ae6b-034b-4edf-b8c7-4a49f5d83d3d","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the term was coined by Crosby ''in his 1972 book.'' 1972 is before 1980.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"3c7e02811044b4951ba7296aedfc232a5936f03e39bafdf676d6918699c045b0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f67316b7-947e-4f0e-94f1-3007d63a02da', 'vr', 'timed', 'f67316b7-947e-4f0e-94f1-3007d63a02da'::uuid, 'vr.recognising_contradictions', '{"id":"f67316b7-947e-4f0e-94f1-3007d63a02da","mode":"timed","parentId":"7933ae6b-034b-4edf-b8c7-4a49f5d83d3d","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the exchange ''was profoundly asymmetric in its biological consequences'' — Old World diseases devastated American indigenous populations, while the Americas contributed crops, not comparable disease burdens, to the Old World.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"8d9def7a96c86d94ba14a561aed05d60a64294f845d03d205741a84add585e3b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ace03186-9613-41b8-a028-f32419b99521', 'vr', 'timed', 'ace03186-9613-41b8-a028-f32419b99521'::uuid, 'vr.unsupported_claims', '{"id":"ace03186-9613-41b8-a028-f32419b99521","mode":"timed","parentId":"7933ae6b-034b-4edf-b8c7-4a49f5d83d3d","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that horses were introduced to the Americas by Europeans and that several Plains Indian nations built cultures around them, but it provides no information about the specific breeds of horses that were reintroduced.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"57965c114b8efefb4efd82f0c9c276940e6f7abd0de249f114f22ec0327a69e3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:28d338ac-c16c-4f6c-8ddc-2bce557c9b3b', 'vr', 'timed', '28d338ac-c16c-4f6c-8ddc-2bce557c9b3b'::uuid, 'vr.evaluating_evidence', '{"id":"28d338ac-c16c-4f6c-8ddc-2bce557c9b3b","mode":"timed","parentId":"7933ae6b-034b-4edf-b8c7-4a49f5d83d3d","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage explicitly states that ''Estimates of indigenous population decline vary substantially among historians'' and that ''The exact figures remain contested due to the limited documentary record.'' This directly contradicts any claim of historical consensus on mortality percentages.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"71ef29944c6dd67a243c8c67e009ce87bbb0c6e334a590a4582960b73a1d57a5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8c851ba0-2818-42ee-97f1-9956af3cce8f', 'vr', 'timed', '8c851ba0-2818-42ee-97f1-9956af3cce8f'::uuid, 'vr.recognising_contradictions', '{"id":"8c851ba0-2818-42ee-97f1-9956af3cce8f","mode":"timed","parentId":"175d553b-1aa9-4b09-9c2f-506448ef30ab","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the 1903 prize shared with Becquerel was the Nobel Prize in Physics, not Chemistry.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"983561b9b9ff816b5ffc95d4377fe2113f7898026439a5f6abb90d7f5a17a2c1"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:20f509c2-656f-495d-98ed-36970f5b728d', 'vr', 'timed', '20f509c2-656f-495d-98ed-36970f5b728d'::uuid, 'vr.qualifiers_and_scope', '{"id":"20f509c2-656f-495d-98ed-36970f5b728d","mode":"timed","parentId":"175d553b-1aa9-4b09-9c2f-506448ef30ab","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"medium","rationale":"The passage states that researchers who wish to consult the notebooks ''must sign a liability waiver,'' but does not indicate that access is denied to ordinary researchers — only that a condition is imposed before viewing.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"03e69a8581e0f80725fe94642f16aec21330525d172a65845ef4da534d6296c6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:56f28866-b2c7-4917-9b2f-eae8c424ff2c', 'vr', 'timed', '56f28866-b2c7-4917-9b2f-eae8c424ff2c'::uuid, 'vr.recognising_contradictions', '{"id":"56f28866-b2c7-4917-9b2f-eae8c424ff2c","mode":"timed","parentId":"175d553b-1aa9-4b09-9c2f-506448ef30ab","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states Pierre Curie died in 1906 ''in a street accident — he slipped on a wet cobblestone and fell beneath a horse-drawn wagon.'' This directly contradicts the claim that his death was a workplace accident related to radioactivity.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"fc04b9276814e039011520eb1666128e2a8378e57ea7af5a790c7d1f18d7d0b0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1994bb3c-ab3d-492f-849f-6d80441d77a9', 'vr', 'timed', '1994bb3c-ab3d-492f-849f-6d80441d77a9'::uuid, 'vr.qualifiers_and_scope', '{"id":"1994bb3c-ab3d-492f-849f-6d80441d77a9","mode":"timed","parentId":"175d553b-1aa9-4b09-9c2f-506448ef30ab","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states the Curie family is ''the most decorated family in Nobel Prize history,'' which is equivalent to saying no other family has won more Nobel Prizes.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"e92a4c807dbf762243e08ceef093e310cda8da3070ae171667585a71a34fca95"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:3e34f8c3-21ae-441a-8b58-9f6aad4eb8ea', 'vr', 'timed', '3e34f8c3-21ae-441a-8b58-9f6aad4eb8ea'::uuid, 'vr.explicit_information', '{"id":"3e34f8c3-21ae-441a-8b58-9f6aad4eb8ea","mode":"timed","parentId":"57f558f7-eae7-409b-b1bd-e5a64be9be0c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Its power derived principally from its control of key commodities: Baltic herring, Finnish furs, Flemish cloth, and English wool.'' It also explicitly states the League operated without a standing army.","difficulty":"normal","format":"mc","answer":"Control of key traded commodities and the economic leverage this provided","options":["A standing army maintained jointly by member cities","A formal treaty with the Holy Roman Emperor granting exclusive trading rights","Control of key traded commodities and the economic leverage this provided","Its ability to mint a common currency accepted across northern Europe"],"contentHash":"f0c46de55a9a60695f6201c1b1d7f2d66a6e196868f00619e6c1cdf3e9e04e67"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:3fb3d6d4-7fda-46aa-bdd9-64aefa6337a2', 'vr', 'timed', '3fb3d6d4-7fda-46aa-bdd9-64aefa6337a2'::uuid, 'vr.meaning_in_context', '{"id":"3fb3d6d4-7fda-46aa-bdd9-64aefa6337a2","mode":"timed","parentId":"57f558f7-eae7-409b-b1bd-e5a64be9be0c","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines Kontore as ''permanent trading outposts — in Bergen, Bruges, London, and Novgorod, which acted as enclaves of Hanseatic commerce within host nations.'' The other options describe things not mentioned in the passage or misattribute the function of other League institutions.","difficulty":"normal","format":"mc","answer":"Permanent Hanseatic trading outposts established in foreign cities","options":["Permanent Hanseatic trading outposts established in foreign cities","Periodic assemblies at which member cities debated League policy","Armed garrisons protecting Hanseatic merchant ships in foreign ports","Storage warehouses built along the Baltic coast to hold surplus grain"],"contentHash":"3d94f09a2e52dd123adaa99757e773928196783f2e745707e8d0b86c06f7a02a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ec80a257-36e1-430b-bdb4-61c75bbf1086', 'vr', 'timed', 'ec80a257-36e1-430b-bdb4-61c75bbf1086'::uuid, 'vr.explicit_information', '{"id":"ec80a257-36e1-430b-bdb4-61c75bbf1086","mode":"timed","parentId":"57f558f7-eae7-409b-b1bd-e5a64be9be0c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly identifies both factors: ''The discovery of Atlantic trade routes diverted commercial attention westward'' and ''The rise of centralised nation-states...eroded the League''s negotiating advantage.'' The other options are not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"The discovery of Atlantic trade routes and the rise of centralised nation-states","options":["A military defeat by the Danish navy that destroyed the League''s fleet","The discovery of Atlantic trade routes and the rise of centralised nation-states","An outbreak of plague that killed a significant proportion of merchant populations","The loss of Lübeck, which forced the League to operate without a meeting place"],"contentHash":"ac22bd1c5572093885c83040fc918dd1fb3070c96d7d36a43b3a7dbf5f8303ed"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b9e6aae9-5fc0-44f0-8a40-f0770d1e62d4', 'vr', 'timed', 'b9e6aae9-5fc0-44f0-8a40-f0770d1e62d4'::uuid, 'vr.explicit_information', '{"id":"b9e6aae9-5fc0-44f0-8a40-f0770d1e62d4","mode":"timed","parentId":"57f558f7-eae7-409b-b1bd-e5a64be9be0c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Hamburg and Bremen remain officially styled as Free and Hanseatic Cities under the German federal constitution to this day.'' The other options introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"They retain the Hanseatic title in their official names under the German federal constitution","options":["They were absorbed into the unified German state in 1871 and lost their Hanseatic designation","They jointly administer a museum dedicated to Hanseatic heritage, funded by the German government","They are the only cities that still hold annual Hansetag meetings to commemorate the League","They retain the Hanseatic title in their official names under the German federal constitution"],"contentHash":"920842ab16f536f6e4ea3074f11497e6091d429eb8e0a46e782bcd1054751a7e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8f27976d-0af8-4ced-9a0e-8d77b2f4c89d', 'vr', 'timed', '8f27976d-0af8-4ced-9a0e-8d77b2f4c89d'::uuid, 'vr.explicit_information', '{"id":"8f27976d-0af8-4ced-9a0e-8d77b2f4c89d","mode":"timed","parentId":"301f7d1f-9aa6-414b-983a-7334eb6f4fc6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states Galileo ''famously argued against Aristotelian physics through an imagined scenario involving objects of different masses dropped simultaneously from a tower.'' This directly confirms that the thought experiment was directed against Aristotle''s physics.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"82f419750c4adfcf01027c13fd6681b9251b1a22979ba91b9aa68c3463208fe0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b425e112-038d-4202-a160-8239d99fbbc3', 'vr', 'timed', 'b425e112-038d-4202-a160-8239d99fbbc3'::uuid, 'vr.qualifiers_and_scope', '{"id":"b425e112-038d-4202-a160-8239d99fbbc3","mode":"timed","parentId":"301f7d1f-9aa6-414b-983a-7334eb6f4fc6","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"medium","rationale":"The passage states the thought experiment ''led him toward the special theory of relativity'' and ''motivated Einstein''s subsequent theoretical work'' — it did not directly produce the theory.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"7532ae84c77da5096bfce9cfec364c75ace60ac7e3e113412c9c46eaa5ba9053"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:96f409a8-54eb-4c90-a04f-ec949845c0ec', 'vr', 'timed', '96f409a8-54eb-4c90-a04f-ec949845c0ec'::uuid, 'vr.qualifiers_and_scope', '{"id":"96f409a8-54eb-4c90-a04f-ec949845c0ec","mode":"timed","parentId":"301f7d1f-9aa6-414b-983a-7334eb6f4fc6","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage describes Thomson''s 1971 violinist thought experiment and its argument about the limits of obligatory bodily assistance, but it does not state whether this was the first thought experiment to address bodily autonomy.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"a715a69f762f81ddf0d6dc7ac4882abf3a265ce4a86b5b44973dc06eb5db9d4b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5a93b789-1193-43b8-83b3-920ea61a2b94', 'vr', 'timed', '5a93b789-1193-43b8-83b3-920ea61a2b94'::uuid, 'vr.author_perspective', '{"id":"5a93b789-1193-43b8-83b3-920ea61a2b94","mode":"timed","parentId":"301f7d1f-9aa6-414b-983a-7334eb6f4fc6","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Scenarios involving individual identifiable victims...have been shown in psychological research to elicit stronger moral concern than statistically equivalent mass harm.'' This directly supports the statement.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"74f25d0473a1a22241cb78dba2c05f01e7910558c722dab74eea84b3acfbc42a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a12fe33c-5f9d-44c2-a71c-0d32cc36d7a4', 'vr', 'timed', 'a12fe33c-5f9d-44c2-a71c-0d32cc36d7a4'::uuid, 'vr.author_perspective', '{"id":"a12fe33c-5f9d-44c2-a71c-0d32cc36d7a4","mode":"timed","parentId":"e1770a50-53bf-4854-a5e5-749af3e1485d","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states Bates ''interpreted'' the ruling as de facto recognition, but the court ruling was about jurisdiction — that it lacked authority over events beyond British territorial waters.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"3605e6ab7b193c00182e5f7444929a013a895bec8b5c741d06df80d4e8a04f37"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:9aba5023-1c9f-4ce9-afa1-c8f0f8e8a3d6', 'vr', 'timed', '9aba5023-1c9f-4ce9-afa1-c8f0f8e8a3d6'::uuid, 'vr.recognising_contradictions', '{"id":"9aba5023-1c9f-4ce9-afa1-c8f0f8e8a3d6","mode":"timed","parentId":"e1770a50-53bf-4854-a5e5-749af3e1485d","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Achenbach seizing the platform ''briefly'' before Bates retook it by helicopter.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"72aed6d6996aae3ffebc315de71c053af0314d31e3098180ffbda99a4d565a32"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fe623e50-e3c8-4de7-a2e0-6ef423731d2b', 'vr', 'timed', 'fe623e50-e3c8-4de7-a2e0-6ef423731d2b'::uuid, 'vr.unsupported_claims', '{"id":"fe623e50-e3c8-4de7-a2e0-6ef423731d2b","mode":"timed","parentId":"e1770a50-53bf-4854-a5e5-749af3e1485d","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that Achenbach ''was eventually released following negotiations involving the German government,'' but it does not specify who Germany sent, whether negotiations were conducted in person or remotely, or whether the negotiator held a senior diplomatic rank.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"ccde7dc29b8b09ec696c1073029b771114a7f1f0b598e7a19299dadbe9e9a974"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:783e8a74-504d-4585-bfe5-9d40ef012af2', 'vr', 'timed', '783e8a74-504d-4585-bfe5-9d40ef012af2'::uuid, 'vr.explicit_information', '{"id":"783e8a74-504d-4585-bfe5-9d40ef012af2","mode":"timed","parentId":"e1770a50-53bf-4854-a5e5-749af3e1485d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states that Sealand ''reportedly sells noble titles as a revenue source,'' which is distinct from currency or stamps.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"cced1a1f77e70ece1393332237420d9c50bdf02f36e44cadf1cd8b0912ece05d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:65b8045e-db99-447e-a6fd-d3f2bf0e3052', 'vr', 'timed', '65b8045e-db99-447e-a6fd-d3f2bf0e3052'::uuid, 'vr.explicit_information', '{"id":"65b8045e-db99-447e-a6fd-d3f2bf0e3052","mode":"timed","parentId":"7427de4e-8045-493c-90a2-6c53c282bdd6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the counterweight trebuchet ''could deliver consistent, repeatable force independent of the physical state of its crew,'' contrasting it with the traction trebuchet that relied on men pulling ropes.","difficulty":"normal","format":"mc","answer":"It delivered consistent, repeatable force regardless of the physical condition of its operators","options":["It could hurl projectiles over greater distances because of its larger throwing arm","It delivered consistent, repeatable force regardless of the physical condition of its operators","It required fewer personnel to operate, making it easier to deploy in remote locations","It could be constructed from locally available materials without specialist engineering knowledge"],"contentHash":"aad05bdeb53d2b710d7f20fb153d77246e3d5efdb3b4bf65f4dfbf49ae4f5ba2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f6af1b2e-cae6-499a-b5f9-a7e5f0ca04bc', 'vr', 'timed', 'f6af1b2e-cae6-499a-b5f9-a7e5f0ca04bc'::uuid, 'vr.meaning_in_context', '{"id":"f6af1b2e-cae6-499a-b5f9-a7e5f0ca04bc","mode":"timed","parentId":"7427de4e-8045-493c-90a2-6c53c282bdd6","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The largest trebuchets, sometimes called \"War Wolves,\" were capable of hurling stones weighing over a hundred kilograms distances of several hundred metres.'' The correct option directly paraphrases this.","difficulty":"normal","format":"mc","answer":"A name given to the largest trebuchets capable of hurling very heavy stones","options":["A type of projectile filled with incendiary material fired from trebuchets during sieges","A name given to the largest trebuchets capable of hurling very heavy stones","A military formation used by defenders to counter trebuchet bombardment","A class of armoured siege tower used alongside trebuchets in medieval warfare"],"contentHash":"57bb6a04ac68a94804b031b7afa614507cfaa19069c497cdb1b374b8a82082c4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:623fa24e-a97c-467f-8d51-8d3fa7ed042e', 'vr', 'timed', '623fa24e-a97c-467f-8d51-8d3fa7ed042e'::uuid, 'vr.explicit_information', '{"id":"623fa24e-a97c-467f-8d51-8d3fa7ed042e","mode":"timed","parentId":"7427de4e-8045-493c-90a2-6c53c282bdd6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states trebuchets were used to deliver ''occasionally live prisoners, in acts designed as much for psychological effect as physical damage.'' The other options are not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"To cause psychological distress, including by launching live prisoners at fortifications","options":["To deliver written surrender demands to defenders who had no other means of communication","To create fires that would illuminate defenders at night, enabling archery attacks","To cause psychological distress, including by launching live prisoners at fortifications","To test the structural weakness of specific sections of walls before a ground assault"],"contentHash":"f9f8edaede2425c0365e72be79498db5a2fd662309237ff7949c5a33da7199a5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:3e57f998-5b85-4b05-9fa9-eaf2852e68f1', 'vr', 'timed', '3e57f998-5b85-4b05-9fa9-eaf2852e68f1'::uuid, 'vr.explicit_information', '{"id":"3e57f998-5b85-4b05-9fa9-eaf2852e68f1","mode":"timed","parentId":"7427de4e-8045-493c-90a2-6c53c282bdd6","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states trebuchets continued to be used ''in situations where gunpowder was scarce or where the noise of cannon fire was strategically undesirable.'' The other options introduce reasons not stated in the passage.","difficulty":"normal","format":"mc","answer":"Because trebuchets were valued when gunpowder was scarce or when cannon noise was strategically undesirable","options":["Because trebuchets were more accurate than early cannon at targeting specific sections of fortifications","Because gunpowder was expensive and unstable, making trebuchets cheaper to maintain over long sieges","Because trebuchets were valued when gunpowder was scarce or when cannon noise was strategically undesirable","Because trebuchets could be operated in wet weather when gunpowder artillery became unreliable"],"contentHash":"3c1a708e722884b2071f0c87efdd2713e70c5e417d7c0960052293693b540316"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a3212f25-4a6c-49b8-b6e1-91246297d57d', 'vr', 'timed', 'a3212f25-4a6c-49b8-b6e1-91246297d57d'::uuid, 'vr.evaluating_evidence', '{"id":"a3212f25-4a6c-49b8-b6e1-91246297d57d","mode":"timed","parentId":"6759155b-6906-4c65-b5cb-90ec3e48e2c2","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''no consensus has emerged'' regarding the 2019 proto-Romance claim and lists multiple competing explanations without endorsing any.","difficulty":"normal","format":"mc","answer":"No consensus explanation has been established among scholars","options":["It is an elaborate hoax containing meaningless symbols","It is written in proto-Romance, an early form of Vulgar Latin","No consensus explanation has been established among scholars","It encodes a natural language using a substitution cipher"],"contentHash":"2e335b91355e49ec5fc08a9a5dba0a27561ecb83597dcd3c3bd1bd4f8c71583a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:de3491f4-bd2f-46a1-975f-98d3fdd2597a', 'vr', 'timed', 'de3491f4-bd2f-46a1-975f-98d3fdd2597a'::uuid, 'vr.evaluating_evidence', '{"id":"de3491f4-bd2f-46a1-975f-98d3fdd2597a","mode":"timed","parentId":"6759155b-6906-4c65-b5cb-90ec3e48e2c2","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''statistical properties of the text...suggest it behaves more like natural language than like a random cipher.'' This is the significance attributed to statistical analysis.","difficulty":"normal","format":"mc","answer":"It suggests the text behaves similarly to natural language rather than random symbols","options":["It proves the manuscript is written in a real language","It suggests the text behaves similarly to natural language rather than random symbols","It identified the manuscript as a constructed or artificial language","It enabled cryptanalysts to partially decode sections of the manuscript"],"contentHash":"8854add0d36454af64f81cc57a73064983c433bfa4ae0d9c5c58d6b4f8a96366"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b07aaa21-9512-491c-8a84-85e7d0ca6c68', 'vr', 'timed', 'b07aaa21-9512-491c-8a84-85e7d0ca6c68'::uuid, 'vr.explicit_information', '{"id":"b07aaa21-9512-491c-8a84-85e7d0ca6c68","mode":"timed","parentId":"6759155b-6906-4c65-b5cb-90ec3e48e2c2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''Multiple professional cryptanalysts, including teams that successfully decoded wartime German Enigma messages, have failed to decipher it.'' The other options contradict the passage: statistical analysis suggested natural language properties but did not decode anything, many professional cryptanalysts have attempted it, and the 2019 claim was met with…","difficulty":"normal","format":"mc","answer":"Teams that successfully decoded wartime Enigma messages were among those who failed to decipher it","options":["The manuscript was partially decoded using statistical analysis of character frequencies","No trained cryptanalyst has made a serious attempt to decipher the manuscript","Teams that successfully decoded wartime Enigma messages were among those who failed to decipher it","A University of Bristol researcher conclusively deciphered the manuscript in 2019"],"contentHash":"79a9807b7fed2647703712d00b120d15d8391905c63472a4f1205dd33486282d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5cf999f8-343a-4c23-9b94-71b03444ff24', 'vr', 'timed', '5cf999f8-343a-4c23-9b94-71b03444ff24'::uuid, 'vr.author_perspective', '{"id":"5cf999f8-343a-4c23-9b94-71b03444ff24","mode":"timed","parentId":"6759155b-6906-4c65-b5cb-90ec3e48e2c2","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The author presents the 2019 claim factually, notes it ''was greeted with considerable scepticism by other scholars,'' and states ''no consensus has emerged.'' This is balanced and neutral — neither endorsing nor dismissing the claim.","difficulty":"hard","format":"mc","answer":"Neutral presentation of a claim that received a mixed scholarly reception","options":["Enthusiastic endorsement of a promising breakthrough","Neutral presentation of a claim that received a mixed scholarly reception","Dismissal of an implausible theory unsupported by any evidence","Regret that scholarly scepticism prevented a valid discovery from being recognised"],"contentHash":"7b959fc6c78f9c554812f2613400c79e1047ada07cc85152f0dfd4d734707e63"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:51aef6a2-c5d6-40b2-a183-fa4d08e1dbbe', 'vr', 'timed', '51aef6a2-c5d6-40b2-a183-fa4d08e1dbbe'::uuid, 'vr.meaning_in_context', '{"id":"51aef6a2-c5d6-40b2-a183-fa4d08e1dbbe","mode":"timed","parentId":"54c9122e-b910-4380-a2df-afe4ac972bcb","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines a trophic cascade as occurring ''when changes at the top of a food chain produce ripple effects throughout the ecosystem below.'' The correct option paraphrases this directly.","difficulty":"normal","format":"mc","answer":"A chain reaction in which changes at the top of a food chain produce effects throughout the ecosystem below","options":["A chain reaction in which changes at the top of a food chain produce effects throughout the ecosystem below","The gradual migration of apex predators from one ecosystem to another over several decades","The process by which rivers change course when vegetation on their banks is removed","A rapid population increase among prey species following the local extinction of a predator"],"contentHash":"6cec57bf265295cab996419c16a7297b8d0b3a6b2d4c8f423b4381ab27e8df98"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6cdf1fd5-df27-4ffe-a9fc-294db9468978', 'vr', 'timed', '6cdf1fd5-df27-4ffe-a9fc-294db9468978'::uuid, 'vr.meaning_in_context', '{"id":"6cdf1fd5-df27-4ffe-a9fc-294db9468978","mode":"timed","parentId":"54c9122e-b910-4380-a2df-afe4ac972bcb","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the ecology of fear as a ''behavioural shift'' in which ''herds avoided lingering in open valleys and riverside areas where they were vulnerable to predation,'' which ''allowed vegetation to recover in the areas wolves most frequently patrolled.'' The correct option captures both the mechanism and the outcome.","difficulty":"normal","format":"mc","answer":"A change in elk behaviour caused by predation risk, which allowed vegetation to recover in patrolled areas","options":["The terror experienced by elk when attacked by wolves, which caused herd numbers to collapse rapidly","The reluctance of conservationists to reintroduce wolves due to fears about livestock predation","A change in elk behaviour caused by predation risk, which allowed vegetation to recover in patrolled areas","A theoretical model predicting that apex predators always suppress prey populations through fear alone"],"contentHash":"0b98b56646086d8ca42676c73307508a677c9c01b869ad13788fdb22fc364c53"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7769160a-68ca-48bf-86a6-aed1ffd12e65', 'vr', 'timed', '7769160a-68ca-48bf-86a6-aed1ffd12e65'::uuid, 'vr.explicit_information', '{"id":"7769160a-68ca-48bf-86a6-aed1ffd12e65","mode":"timed","parentId":"54c9122e-b910-4380-a2df-afe4ac972bcb","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Recovering willows and aspens attracted beavers, whose dams created ponds that provided habitat for fish, amphibians, and waterfowl.'' The other options either contradict the passage or describe unrelated effects.","difficulty":"normal","format":"mc","answer":"Beaver dams created ponds that provided habitat for fish, amphibians, and waterfowl","options":["Elk populations were forced to relocate to higher ground, reducing grazing pressure on valley floors","Beaver dams created ponds that provided habitat for fish, amphibians, and waterfowl","The increased beaver population led to significant deforestation of upland areas","River channels widened and became shallower as beaver activity disrupted existing flow patterns"],"contentHash":"0cbc7316cc91de68a9c66d2c0bfa3404e31e7a04f3033b49bf1a16823b0751bb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e2b4aa9d-7877-4202-8e72-253551435f40', 'vr', 'timed', 'e2b4aa9d-7877-4202-8e72-253551435f40'::uuid, 'vr.author_perspective', '{"id":"e2b4aa9d-7877-4202-8e72-253551435f40","mode":"timed","parentId":"54c9122e-b910-4380-a2df-afe4ac972bcb","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states critics ''point out that drought, human activity, and natural vegetation cycles may have contributed equally to river changes.'' The other options introduce claims not made by sceptics in the passage.","difficulty":"hard","format":"mc","answer":"They contend that drought, human activity, and natural vegetation cycles may have contributed equally to the observed changes","options":["They argue that wolf reintroduction had no measurable effect on the Yellowstone ecosystem","They dispute whether wolves were genuinely absent from Yellowstone for the period claimed","They maintain that the beaver population decline was caused by disease rather than loss of willows and aspens","They contend that drought, human activity, and natural vegetation cycles may have contributed equally to the observed changes"],"contentHash":"88e6198e840b8446e45255636e12ef5da1472d7f41dd00250cf981d33360dff4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e98563b2-a2f4-494d-8c8b-381604141750', 'vr', 'timed', 'e98563b2-a2f4-494d-8c8b-381604141750'::uuid, 'vr.explicit_information', '{"id":"e98563b2-a2f4-494d-8c8b-381604141750","mode":"timed","parentId":"38964db3-6e34-4401-9b12-755e96eafb1c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines the strong form as holding ''that language determines thought and that speakers of different languages literally cannot think the same thoughts.'' This directly confirms the statement, which is a close paraphrase of explicit passage content.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"fd7842f91d142377b75b976f09529166a45035da34eed93bc6d11c2a917de015"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:03e4f658-17ee-4d3c-9ac5-370bbc09a6cd', 'vr', 'timed', '03e4f658-17ee-4d3c-9ac5-370bbc09a6cd'::uuid, 'vr.qualifiers_and_scope', '{"id":"03e4f658-17ee-4d3c-9ac5-370bbc09a6cd","mode":"timed","parentId":"38964db3-6e34-4401-9b12-755e96eafb1c","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"low","rationale":"Unsupported False key: the passage compares cross-category with within-category performance and does not rule out every broader Russian-English difference.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"excludedReason":"Unsupported False key: the passage compares cross-category with within-category performance and does not rule out every broader Russian-English difference.","contentHash":"ccfd5106df1f9bbef134a217be78a812be05318eab888d2922209778cafd67cf"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8aa361ea-3b5e-499e-b840-ae279683f7a7', 'vr', 'timed', '8aa361ea-3b5e-499e-b840-ae279683f7a7'::uuid, 'vr.explicit_information', '{"id":"8aa361ea-3b5e-499e-b840-ae279683f7a7","mode":"timed","parentId":"38964db3-6e34-4401-9b12-755e96eafb1c","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''a body of experimental research supports the weak form of the hypothesis, demonstrating that certain linguistic categories can influence perceptual and cognitive tasks in measurable ways.'' This directly confirms that experimental research has supported the weak form.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"46899edc7fa0836964e5dde235da6f32cc627a61eea691fdaaa3342235d6a3fc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:27f98b04-6792-40d0-ae8f-d62fcee5bcb1', 'vr', 'timed', '27f98b04-6792-40d0-ae8f-d62fcee5bcb1'::uuid, 'vr.unsupported_claims', '{"id":"27f98b04-6792-40d0-ae8f-d62fcee5bcb1","mode":"timed","parentId":"38964db3-6e34-4401-9b12-755e96eafb1c","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes the colour perception experiment only in relation to Russian and English speakers.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"1112439e228e3b7b129c504c806abd256471430089111e7ade1295e7f3547f5d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c43fbd69-2bfc-4337-8807-cadfc5afde72', 'vr', 'timed', 'c43fbd69-2bfc-4337-8807-cadfc5afde72'::uuid, 'vr.explicit_information', '{"id":"c43fbd69-2bfc-4337-8807-cadfc5afde72","mode":"timed","parentId":"c2bf5132-f660-4c0e-ae66-94798fb55844","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states methane ''is of particular concern because its warming potential over a 20-year period is approximately 80 times greater than that of carbon dioxide.'' The other options are not stated in the passage and some directly contradict it — the passage notes methane ''breaks down more rapidly,'' implying it does not persist indefinitely.","difficulty":"normal","format":"mc","answer":"Methane has a warming potential approximately 80 times greater than carbon dioxide over a 20-year period","options":["Methane remains in the atmosphere indefinitely, unlike carbon dioxide which is absorbed by oceans","Methane is produced in greater quantities by permafrost thaw than carbon dioxide","Methane has a warming potential approximately 80 times greater than carbon dioxide over a 20-year period","Methane reacts with ozone in the upper atmosphere, causing additional environmental damage"],"contentHash":"2f4e092a38c5d8dafd4454a9f87040c80d8de49df3bcf33453d654ddf5a23569"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:382860fa-48f8-4297-b8c8-fcbb48eafcc2', 'vr', 'timed', '382860fa-48f8-4297-b8c8-fcbb48eafcc2'::uuid, 'vr.explicit_information', '{"id":"382860fa-48f8-4297-b8c8-fcbb48eafcc2","mode":"timed","parentId":"c2bf5132-f660-4c0e-ae66-94798fb55844","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Infrastructure built on permafrost — roads, pipelines, buildings — depends on the ground remaining frozen and stable.","difficulty":"normal","format":"mc","answer":"Infrastructure built on permafrost becomes unstable as the ground subsides and collapses","options":["Permafrost meltwater floods low-lying coastal settlements and disrupts shipping routes","Infrastructure built on permafrost becomes unstable as the ground subsides and collapses","Thawing permafrost releases toxic heavy metals that contaminate water supplies","The loss of permafrost exposes bedrock that is too hard to excavate for new construction"],"contentHash":"975f7a88366c85a76d0c28e4f725863d2487ff3a8e818836d71116d8d7e5e6b5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:075e497a-2697-4b75-90cb-63e7ab348cec', 'vr', 'timed', '075e497a-2697-4b75-90cb-63e7ab348cec'::uuid, 'vr.meaning_in_context', '{"id":"075e497a-2697-4b75-90cb-63e7ab348cec","mode":"timed","parentId":"c2bf5132-f660-4c0e-ae66-94798fb55844","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines thermokarst as ''irregular, waterlogged terrain characterised by sinkholes and small lakes formed by ground collapse.'' The correct option directly paraphrases this definition.","difficulty":"normal","format":"mc","answer":"Irregular, waterlogged terrain featuring sinkholes and small lakes formed by ground collapse","options":["A region of permafrost that has remained stable despite surrounding areas of thaw","Irregular, waterlogged terrain featuring sinkholes and small lakes formed by ground collapse","A landscape where permafrost thaw has exposed ancient plant and animal remains","The zone immediately above permafrost where seasonal freeze-thaw cycles occur annually"],"contentHash":"2a86c2f683fb9dea4513200af0f2dc1a1553fb253d7dc39d3b76d26d154e9693"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8bb48646-5964-45b5-8956-f76a1516ee99', 'vr', 'timed', '8bb48646-5964-45b5-8956-f76a1516ee99'::uuid, 'vr.evaluating_evidence', '{"id":"8bb48646-5964-45b5-8956-f76a1516ee99","mode":"timed","parentId":"c2bf5132-f660-4c0e-ae66-94798fb55844","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states thaw ''is uneven and difficult to model precisely'' with ''some permafrost regions...thawing faster than climate models predicted, while others have shown unexpected stability.'' The correct option captures both sides of this variability.","difficulty":"hard","format":"mc","answer":"Modelling remains imprecise, with some regions thawing faster than predicted and others showing unexpected stability","options":["Modelling is highly accurate and has consistently predicted observed thaw rates across all regions","Modelling remains imprecise, with some regions thawing faster than predicted and others showing unexpected stability","Current models are reliable for gradual thaw but cannot account for abrupt localised collapse events at all","Scientists have abandoned modelling permafrost thaw due to the complexity of the variables involved"],"contentHash":"69e341307bcf053cb0d10bf2fe6ab339a771ff7457c847c170ba653c85b1076c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:032f10a0-d4be-4942-be07-da9642e3033e', 'vr', 'timed', '032f10a0-d4be-4942-be07-da9642e3033e'::uuid, 'vr.explicit_information', '{"id":"032f10a0-d4be-4942-be07-da9642e3033e","mode":"timed","parentId":"80026856-06c7-4711-bcec-7bac00f1236f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states active sonar ''emit[s] a pulse of sound...and measure[s] the time taken for the echo to return,'' while passive sonar ''does not emit any signal; it only listens.'' The other options either introduce information not in the passage or misattribute the development timeline.","difficulty":"normal","format":"mc","answer":"Active sonar emits a sound pulse and listens for its echo, while passive sonar only listens without emitting any signal","options":["Active sonar works underwater while passive sonar operates only at the surface","Active sonar emits a sound pulse and listens for its echo, while passive sonar only listens without emitting any signal","Active sonar was developed during the First World War, while passive sonar was developed later","Active sonar can detect submarines, while passive sonar can only detect surface vessels"],"contentHash":"9432bbbcac682f08238fa6d3cf978eea2ff41ae32457663e298dc1317a8842aa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fad4be69-bb72-49ab-bc07-a9f13b1256df', 'vr', 'timed', 'fad4be69-bb72-49ab-bc07-a9f13b1256df'::uuid, 'vr.explicit_information', '{"id":"fad4be69-bb72-49ab-bc07-a9f13b1256df","mode":"timed","parentId":"80026856-06c7-4711-bcec-7bac00f1236f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states both operate on ''the same fundamental principle'' but that ''the two developed independently.'' Biological echolocation ''evolved over millions of years'' while sonar was engineered in the twentieth century.","difficulty":"hard","format":"mc","answer":"Human sonar and animal echolocation both emerged from the same fundamental acoustic principles but developed independently","options":["Human sonar and animal echolocation both emerged from the same fundamental acoustic principles but developed independently","The passage states explicitly that sonar was modelled directly on dolphin echolocation from its earliest development","Human sonar evolved alongside biological echolocation over millions of years","The passage does not discuss any relationship between sonar and animal echolocation"],"contentHash":"c2c1f9ba205ca75dfbffbf18e2a52de1a1dadfefa1edb8c4b3f6d2ca393cf113"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c3ff2279-2fb0-4c1e-ade6-1672e2785124', 'vr', 'timed', 'c3ff2279-2fb0-4c1e-ade6-1672e2785124'::uuid, 'vr.explicit_information', '{"id":"c3ff2279-2fb0-4c1e-ade6-1672e2785124","mode":"timed","parentId":"80026856-06c7-4711-bcec-7bac00f1236f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Exposure to high-intensity sonar pulses has been associated with behavioural disruption, strandings, and in some cases internal injuries'' in cetaceans.","difficulty":"normal","format":"mc","answer":"High-intensity sonar pulses have been associated with disturbance and possible injury to cetaceans","options":["Sonar signals interfere with satellite navigation systems used by commercial shipping","High-intensity sonar pulses have been associated with disturbance and possible injury to cetaceans","Passive sonar emits radiation that accumulates in fish tissue and enters the human food chain","Military sonar has made it impossible for dolphins to use echolocation for hunting"],"contentHash":"aab8f4eeea07d904432495a92b117fc0e9a7957d74fcd9c84c0b3902d460828d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8d61c690-c318-42fe-ae6c-9b981b6bff94', 'vr', 'timed', '8d61c690-c318-42fe-ae6c-9b981b6bff94'::uuid, 'vr.explicit_information', '{"id":"8d61c690-c318-42fe-ae6c-9b981b6bff94","mode":"timed","parentId":"80026856-06c7-4711-bcec-7bac00f1236f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The sophistication of biological echolocation systems continues to inform the design of artificial sonar, with engineers drawing on biological models to improve target discrimination.'' This directly matches the correct answer.","difficulty":"normal","format":"mc","answer":"Findings from studies of dolphin echolocation continue to inform improvements in artificial sonar design","options":["Sonar engineers have made no use of biological models, preferring purely mathematical approaches","Biological echolocation was itself derived from early sonar technology developed in the twentieth century","Findings from studies of dolphin echolocation continue to inform improvements in artificial sonar design","Sonar technology has now surpassed biological echolocation in sensitivity and target discrimination"],"contentHash":"c3ed0637d82aff1a59f40128d8358bf0cfdf2990ea3b2327b023731c4d5cf395"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c5205330-94f7-46a8-8193-0223fda96589', 'vr', 'timed', 'c5205330-94f7-46a8-8193-0223fda96589'::uuid, 'vr.explicit_information', '{"id":"c5205330-94f7-46a8-8193-0223fda96589","mode":"timed","parentId":"f22e27b2-5a7e-4e36-9321-bb1dad67eb47","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states synesthetic experiences are ''automatic, involuntary'' and ''consistent and specific to the individual,'' and that ''This consistency distinguishes synesthesia from imagination or metaphor.'' The correct option captures both the involuntary nature and the consistency that sets synesthesia apart.","difficulty":"hard","format":"mc","answer":"Synesthetic experiences are consistent and involuntary, whereas imagination is deliberate and variable","options":["Synesthetic experiences are always pleasant, whereas imagination can produce unpleasant associations","Synesthetic experiences are consistent and involuntary, whereas imagination is deliberate and variable","Synesthetic experiences involve only visual sensations, whereas other forms of imagination engage multiple senses","Synesthetic experiences occur only during sleep, whereas imagination is a waking phenomenon"],"contentHash":"e3a9edd6c423391a92cd5e54e73ea241c5edabce7fd12c06e72b2bab3883e3e5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0347c2bd-456b-41ef-a4de-db35741127c5', 'vr', 'timed', '0347c2bd-456b-41ef-a4de-db35741127c5'::uuid, 'vr.explicit_information', '{"id":"0347c2bd-456b-41ef-a4de-db35741127c5","mode":"timed","parentId":"f22e27b2-5a7e-4e36-9321-bb1dad67eb47","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Neuroimaging studies have shown measurable activation in visual cortex regions during auditory stimulation in synesthetes.'' This directly matches the correct option.","difficulty":"normal","format":"mc","answer":"Visual cortex regions show measurable activation during auditory stimulation in synesthetes","options":["Synesthetes show reduced activity in auditory brain regions when processing visual stimuli","Visual cortex regions show measurable activation during auditory stimulation in synesthetes","The brains of synesthetes are structurally different from non-synesthetes in the corpus callosum","Synesthetes process colour information in auditory regions rather than visual regions of the brain"],"contentHash":"3a442a15bbcd7b97edd6a4e0e7907f8f8817c300d32d77a960287339e5c17f54"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:361d21ee-1d26-491d-bc04-9d6d59aef0a3', 'vr', 'timed', '361d21ee-1d26-491d-bc04-9d6d59aef0a3'::uuid, 'vr.explicit_information', '{"id":"361d21ee-1d26-491d-bc04-9d6d59aef0a3","mode":"timed","parentId":"f22e27b2-5a7e-4e36-9321-bb1dad67eb47","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states synesthesia ''is substantially more prevalent among artists, musicians, and writers than in the general population.'' The other groups are not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"Artists, musicians, and writers","options":["Left-handed individuals and those with a family history of neurological conditions","People who learned more than two languages before the age of ten","Artists, musicians, and writers","Individuals with above-average scores on standardised spatial reasoning tests"],"contentHash":"31cdd6cf529e86ae4a9d40d2f5cd217b7ea4e772877bb9ae4b26419d1b85fc62"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:37084c5e-b181-46b7-8365-79b5f3b31033', 'vr', 'timed', '37084c5e-b181-46b7-8365-79b5f3b31033'::uuid, 'vr.explicit_information', '{"id":"37084c5e-b181-46b7-8365-79b5f3b31033","mode":"timed","parentId":"f22e27b2-5a7e-4e36-9321-bb1dad67eb47","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Synesthesia does not generally impair functioning; most synesthetes are unaware that their experiences are unusual until they compare notes with others.'' The other options either contradict this or introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"It generally does not impair functioning, and many synesthetes are unaware their experiences are unusual","options":["It causes significant perceptual confusion that impairs reading, navigation, and social interaction","It generally does not impair functioning, and many synesthetes are unaware their experiences are unusual","It produces chronic sensory overload that requires medical management in most cases","It enhances memory and learning in all areas but creates difficulties with musical pitch discrimination"],"contentHash":"9b7e0ecc16eddef4fc80a82334bcd37334bcc2152b12b74294dc930f244118fa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8c6cc80f-d847-442a-89b6-3c5796bd95e5', 'vr', 'timed', '8c6cc80f-d847-442a-89b6-3c5796bd95e5'::uuid, 'vr.evaluating_evidence', '{"id":"8c6cc80f-d847-442a-89b6-3c5796bd95e5","mode":"timed","parentId":"3c773fc1-5dd9-4c93-bdbe-c3da6739d8fc","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states scholars have ''proposed'' smallpox as the most likely cause but explicitly notes ''neither identification is certain'' and that ancient descriptions ''rarely provide sufficient specificity for definitive retrospective diagnosis.'' The word ''definitively'' in the statement directly contradicts the passage''s account of ongoing uncertainty.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"24f185182f4f83377a67f1eafbe9911beebaf39bb2286d5688ad52e80a11bd6d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a43cc9ff-390d-4329-b9d4-44736a17a31d', 'vr', 'timed', 'a43cc9ff-390d-4329-b9d4-44736a17a31d'::uuid, 'vr.recognising_contradictions', '{"id":"a43cc9ff-390d-4329-b9d4-44736a17a31d","mode":"timed","parentId":"3c773fc1-5dd9-4c93-bdbe-c3da6739d8fc","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the plague is named after ''the Antonine imperial dynasty'' of which Marcus Aurelius was a member — not because he contracted or survived the disease.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"86528aaee46bfe94d22a0098f06b6889270d14babf2184f9756d9d520ba26024"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:627ff6f5-8db2-4380-9892-c36ed579625d', 'vr', 'timed', '627ff6f5-8db2-4380-9892-c36ed579625d'::uuid, 'vr.author_perspective', '{"id":"627ff6f5-8db2-4380-9892-c36ed579625d","mode":"timed","parentId":"3c773fc1-5dd9-4c93-bdbe-c3da6739d8fc","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Some historians have argued that the Antonine Plague represented a turning point in Roman imperial history'' while ''Others are more cautious...attributing long-term historical change to a single event risks oversimplification.'' This disagreement confirms historians are divided on whether it was a decisive turning point.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"43ab0483c2d606c3c994113a1b4da4dba0926033c719abd27c6f29e2b8701335"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b539c6c1-6e18-41b3-870e-e71b231031db', 'vr', 'timed', 'b539c6c1-6e18-41b3-870e-e71b231031db'::uuid, 'vr.inference', '{"id":"b539c6c1-6e18-41b3-870e-e71b231031db","mode":"timed","parentId":"3c773fc1-5dd9-4c93-bdbe-c3da6739d8fc","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''losses among soldiers reduced the fighting capacity of the legions at a period of intensifying pressure on the empire''s northern and eastern frontiers.'' Reduced fighting capacity is detrimental to military effectiveness, and intensifying frontier pressure constitutes external threats.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"e163a9f2cff1be7fefc757c4013a17c603b25c82ff8de33916521062f56eaffb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7c498288-0335-46f2-9d08-fc4b48832c1b', 'vr', 'timed', '7c498288-0335-46f2-9d08-fc4b48832c1b'::uuid, 'vr.explicit_information', '{"id":"7c498288-0335-46f2-9d08-fc4b48832c1b","mode":"timed","parentId":"f9afb6db-449d-47e6-959e-b839fef5e0f5","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states Dreyfus was ''wrongly convicted of treason in December 1894 on the basis of a forged document purporting to show he had passed military secrets to the German embassy in Paris.'' The other options introduce evidence not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"A forged document purporting to show he had passed military secrets to the German embassy","options":["Testimony from a German embassy official who claimed to have received documents from Dreyfus","A forged document purporting to show he had passed military secrets to the German embassy","Physical evidence found in Dreyfus''s home during a search authorised by the French government","A confession obtained from Dreyfus during a closed military hearing in December 1894"],"contentHash":"6f113b0551b5a1c373a3e261d46f06762c99204848a241c516844a4de755fc39"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:cfa1b23b-8554-4ee2-b314-e5d8f70abd41', 'vr', 'timed', 'cfa1b23b-8554-4ee2-b314-e5d8f70abd41'::uuid, 'vr.inference', '{"id":"cfa1b23b-8554-4ee2-b314-e5d8f70abd41","mode":"timed","parentId":"f9afb6db-449d-47e6-959e-b839fef5e0f5","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the army ''suppressed the findings to protect its institutional reputation'' when evidence pointing to Esterhazy emerged, and that Esterhazy ''was acquitted after a military court deliberated for just three minutes.'' Together these confirm the trial illustrated institutional suppression of evidence.","difficulty":"hard","format":"mc","answer":"It demonstrated the army''s willingness to suppress evidence to protect its institutional reputation, as Esterhazy was acquitted after a three-minute deliberation","options":["It was the first public acknowledgement by the French military that Dreyfus had been wrongly convicted","It resulted in Esterhazy''s conviction and imprisonment, temporarily satisfying calls for justice","It demonstrated the army''s willingness to suppress evidence to protect its institutional reputation, as Esterhazy was acquitted after a three-minute deliberation","It prompted Émile Zola to begin compiling evidence for his open letter to the President of France"],"contentHash":"478290fc46552bfd113a7b9b41f38ef4952d7102fe24270224680158dd87d300"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b476988a-ae7b-408b-9be2-d56c8e8dd0bb', 'vr', 'timed', 'b476988a-ae7b-408b-9be2-d56c8e8dd0bb'::uuid, 'vr.explicit_information', '{"id":"b476988a-ae7b-408b-9be2-d56c8e8dd0bb","mode":"timed","parentId":"f9afb6db-449d-47e6-959e-b839fef5e0f5","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Dreyfusards, who included republicans, socialists, and intellectuals, demanded justice.'' The first option describes the anti-Dreyfusard camp as characterised in the passage.","difficulty":"normal","format":"mc","answer":"Republicans, socialists, and intellectuals who demanded justice for Dreyfus","options":["Conservative, Catholic, and nationalist constituencies who believed in the army''s honour","Republicans, socialists, and intellectuals who demanded justice for Dreyfus","A coalition of senior military officers who believed Esterhazy had fabricated the evidence","Liberal monarchists and Protestant clergy who opposed the influence of the Jesuit order"],"contentHash":"e69a499cc158cf811dba150a391c7988e9fc07a8d739a9712e7f57f6a2c56de0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:bbf620ce-db4a-4ffa-a01b-1a4a8657e944', 'vr', 'timed', 'bbf620ce-db4a-4ffa-a01b-1a4a8657e944'::uuid, 'vr.explicit_information', '{"id":"bbf620ce-db4a-4ffa-a01b-1a4a8657e944","mode":"timed","parentId":"f9afb6db-449d-47e6-959e-b839fef5e0f5","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage concludes ''The affair accelerated the passage of laws separating church and state in France and left a lasting mark on French political culture.'' The other options introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"It accelerated laws separating church and state and had a lasting impact on French political culture","options":["It led to the dissolution of the French military officer class and the establishment of a civilian-led defence ministry","It resulted in Dreyfus being awarded the Legion of Honour and appointed to a senior military command","It accelerated laws separating church and state and had a lasting impact on French political culture","It prompted France to introduce constitutional protections for religious minorities modelled on British law"],"contentHash":"919df9002d50f30d11746240309618f23f6fc3e397ed3714ac8b2dfd66dae0d9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6c7a41c4-6035-40d1-acc7-bc3f73034d84', 'vr', 'timed', '6c7a41c4-6035-40d1-acc7-bc3f73034d84'::uuid, 'vr.recognising_contradictions', '{"id":"6c7a41c4-6035-40d1-acc7-bc3f73034d84","mode":"timed","parentId":"5f0cf95c-6409-48f1-bf0d-3f8aa57cdf95","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states construction was ''carried out without wheeled vehicles, iron tools, or draft animals capable of heavy haulage.'' This directly contradicts the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"e2214a7fd0dee8f56a38eb9c0b756266f732c0f2204162f01b562c28b83bd461"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:79f4afcd-545c-4789-a6a1-7fe457ce8c14', 'vr', 'timed', '79f4afcd-545c-4789-a6a1-7fe457ce8c14'::uuid, 'vr.explicit_information', '{"id":"79f4afcd-545c-4789-a6a1-7fe457ce8c14","mode":"timed","parentId":"5f0cf95c-6409-48f1-bf0d-3f8aa57cdf95","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that bridges ''were replaced on a regular cycle — some bridges occupied the same site for centuries, with each iteration rebuilt from scratch.'' This directly confirms repeated rebuilding at the same locations over long periods.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"b8335b2a96a8e39f15ecf5d802bdde871372ef49331de802af9c3df8b15d8d51"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b2c62d6d-5cb1-432b-b1bc-168e26af783a', 'vr', 'timed', 'b2c62d6d-5cb1-432b-b1bc-168e26af783a'::uuid, 'vr.explicit_information', '{"id":"b2c62d6d-5cb1-432b-b1bc-168e26af783a","mode":"timed","parentId":"5f0cf95c-6409-48f1-bf0d-3f8aa57cdf95","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states chasquis passed ''fresh fish from the coast to the highland capital of Cusco.'' Fresh fish is a perishable food item, and the coast-to-Cusco route confirms coastal origin to capital destination.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"6a7c2136a3b33b7ecf6bd16338cde8cab5202e569dfe52ff868962051540a70e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1894669c-46f1-40fe-b7ae-45fe1a28b733', 'vr', 'timed', '1894669c-46f1-40fe-b7ae-45fe1a28b733'::uuid, 'vr.unsupported_claims', '{"id":"1894669c-46f1-40fe-b7ae-45fe1a28b733","mode":"timed","parentId":"5f0cf95c-6409-48f1-bf0d-3f8aa57cdf95","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the roads fell into disrepair ''as the Inca state that maintained them collapsed,'' attributing decline to the loss of the administrative system rather than deliberate destruction.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"7a3490c4427f85c79d09f22e453d04f499ff26c3b22060dfdb6c6383ba3398c8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:80a7a31d-cf4b-4ff3-8935-ba20846741fb', 'vr', 'timed', '80a7a31d-cf4b-4ff3-8935-ba20846741fb'::uuid, 'vr.explicit_information', '{"id":"80a7a31d-cf4b-4ff3-8935-ba20846741fb","mode":"timed","parentId":"ceac8659-926a-4d6c-b13c-7ff1f4f0ff96","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the lighthouse was ''Built during the reign of Ptolemy II Philadelphus in the third century BCE.'' This is a direct confirmation of the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"5b6f4a2a89938ec133e8abd23b82bf10dbd8b13f3df74b6bb8caf3287ec51542"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:33dccfdb-f74e-422d-8be9-1de993c23c96', 'vr', 'timed', '33dccfdb-f74e-422d-8be9-1de993c23c96'::uuid, 'vr.unsupported_claims', '{"id":"33dccfdb-f74e-422d-8be9-1de993c23c96","mode":"timed","parentId":"ceac8659-926a-4d6c-b13c-7ff1f4f0ff96","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"medium","rationale":"The passage states that when Ibn Battuta visited in 1326, the lighthouse was ''already too ruined to enter,'' meaning he himself could not enter it.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"fdbf0aaa1449dac39722ebce1c52ce02e38e3ffe3b07a72a0bbe8d2af1e9a741"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e38e5ac5-c7f0-47c9-a063-7964a921ece2', 'vr', 'timed', 'e38e5ac5-c7f0-47c9-a063-7964a921ece2'::uuid, 'vr.recognising_contradictions', '{"id":"e38e5ac5-c7f0-47c9-a063-7964a921ece2","mode":"timed","parentId":"ceac8659-926a-4d6c-b13c-7ff1f4f0ff96","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Mamluk sultan Qa''itbay ''construct[ed] a medieval fortress in 1477, which still stands today.'' The statement''s claim that the fortress no longer exists directly contradicts this.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"15bc51fed2245634521a21b74d52854a26a627f2416b342f936337d61903be61"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2184eb2c-e7db-4aba-b156-b3ea307b0894', 'vr', 'timed', '2184eb2c-e7db-4aba-b156-b3ea307b0894'::uuid, 'vr.evaluating_evidence', '{"id":"2184eb2c-e7db-4aba-b156-b3ea307b0894","mode":"timed","parentId":"ceac8659-926a-4d6c-b13c-7ff1f4f0ff96","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states height estimates from ancient accounts ''range from 100 to 140 metres'' — indicating disagreement, not consensus.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"9771e6a358ba41b421ac429e9f6af77b44240e7da258aea9da1f6aa8b1b52d6b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7bbee035-7bdc-44a0-b301-4dab8d013b92', 'vr', 'timed', '7bbee035-7bdc-44a0-b301-4dab8d013b92'::uuid, 'vr.explicit_information', '{"id":"7bbee035-7bdc-44a0-b301-4dab8d013b92","mode":"timed","parentId":"aa86dc5e-36d5-4f4a-ab34-980558eb6b7d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the programme ''ultimately distributed approximately 13 billion US dollars in aid over four years.'' The 140 billion figure refers to the contemporary equivalent, not the actual sum distributed.","difficulty":"normal","format":"mc","answer":"Approximately 13 billion dollars over four years","options":["Approximately 13 billion dollars over four years","Approximately 140 billion dollars over ten years","Approximately 13 billion dollars over two years","Approximately 50 billion dollars over four years"],"contentHash":"11724ebdac2086be28fd5a9672d89943981fac6f2b2d632892d0c89265f69bc3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:3e331132-dcd0-4b69-a70b-5031286f083a', 'vr', 'timed', '3e331132-dcd0-4b69-a70b-5031286f083a'::uuid, 'vr.author_perspective', '{"id":"3e331132-dcd0-4b69-a70b-5031286f083a","mode":"timed","parentId":"aa86dc5e-36d5-4f4a-ab34-980558eb6b7d","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The Soviet government...rejected participation...viewing the programme as an instrument of American economic and political influence.'' The other options introduce reasons not stated in the passage.","difficulty":"normal","format":"mc","answer":"Because the Soviet Union viewed the programme as an instrument of American economic and political influence","options":["Because the Soviet economy had already recovered sufficiently from the war to not require external assistance","Because the Soviet Union viewed the programme as an instrument of American economic and political influence","Because Stalin believed the plan''s trade liberalisation conditions would expose Soviet industries to Western competition","Because the Soviet Union had already secured a separate bilateral aid agreement with the United States"],"contentHash":"e4304f1879cb5c8891c6a32ec3b0bb626179a9f166615958b2f5c1341e0ba52b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:03d2a912-f4c9-4ccc-9293-27506fce252b', 'vr', 'timed', '03d2a912-f4c9-4ccc-9293-27506fce252b'::uuid, 'vr.explicit_information', '{"id":"03d2a912-f4c9-4ccc-9293-27506fce252b","mode":"timed","parentId":"aa86dc5e-36d5-4f4a-ab34-980558eb6b7d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''American policymakers also believed explicitly that economic desperation created fertile conditions for communist political movements — by raising living standards, the plan aimed to reduce the appeal of left-wing parties in countries such as France and Italy.'' The other options introduce objectives not stated in the passage.","difficulty":"normal","format":"mc","answer":"To reduce the electoral appeal of communist parties in Western European countries by improving living standards","options":["To accelerate the formation of a unified Western European political federation capable of resisting Soviet expansion","To reduce the electoral appeal of communist parties in Western European countries by improving living standards","To create permanent American military bases in Western Europe under the cover of economic reconstruction","To ensure that West Germany paid reparations to its neighbours through a US-administered fund"],"contentHash":"77a0fb55f7a4e6468cc4131eea3c4bbf2091178e8efd6c5fae4af977f9a673c4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c7523d27-bb17-4989-b37c-bf94f6a1f7e5', 'vr', 'timed', 'c7523d27-bb17-4989-b37c-bf94f6a1f7e5'::uuid, 'vr.explicit_information', '{"id":"c7523d27-bb17-4989-b37c-bf94f6a1f7e5","mode":"timed","parentId":"aa86dc5e-36d5-4f4a-ab34-980558eb6b7d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Aid recipients were required to liberalise trade among themselves, a condition that laid some of the institutional groundwork for what later became the European Union.'' The other options are not mentioned in the passage.","difficulty":"hard","format":"mc","answer":"Recipients were required to liberalise trade among themselves, laying institutional groundwork for what became the European Union","options":["Recipients were required to adopt the US dollar as a reserve currency to facilitate transatlantic trade","Recipients were required to allow American companies to establish subsidiaries in their countries","Recipients were required to liberalise trade among themselves, laying institutional groundwork for what became the European Union","Recipients were required to submit annual economic plans to a joint US-European oversight committee"],"contentHash":"af80efca8bd73492e7c28cf6ce1d5a25bc06d1d46b014f31e263c3dd4138cc38"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e3f4a5b6-3001-4c01-9c01-000000000002', 'vr', 'timed', 'e3f4a5b6-3001-4c01-9c01-000000000002'::uuid, 'vr.explicit_information', '{"id":"e3f4a5b6-3001-4c01-9c01-000000000002","mode":"timed","parentId":"e3f4a5b6-3001-4c01-9c01-000000000001","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the decree was read ''during the early months of Sultan Abdulmecid I''s reign'', directly supporting the statement.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"86486370ad81b4504205b5ec2d26d8a441928a31019d932467828c8e31e7dad7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e3f4a5b6-3001-4c01-9c01-000000000003', 'vr', 'timed', 'e3f4a5b6-3001-4c01-9c01-000000000003'::uuid, 'vr.qualifiers_and_scope', '{"id":"e3f4a5b6-3001-4c01-9c01-000000000003","mode":"timed","parentId":"e3f4a5b6-3001-4c01-9c01-000000000001","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states that while new secular courts handled commercial and criminal cases, ''family matters remained under the jurisdiction of confessional courts specific to each community'', directly contradicting the claim that all legal matters were transferred.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"dc95f80723460b04d88b0175773c11fe423881ce9253a7335768341c7ac58f7b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e3f4a5b6-3001-4c01-9c01-000000000004', 'vr', 'timed', 'e3f4a5b6-3001-4c01-9c01-000000000004'::uuid, 'vr.inference', '{"id":"e3f4a5b6-3001-4c01-9c01-000000000004","mode":"timed","parentId":"e3f4a5b6-3001-4c01-9c01-000000000001","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that ''some Muslim clerics objected'' to the reforms and that ''a number of non-Muslim community leaders argued'' the reforms interfered with their autonomy.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"0278c02cf8e1604d4bce9dbce3757fcd2b0d077ce4b3593ca76a5b9eede52af1"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e3f4a5b6-3001-4c01-9c01-000000000005', 'vr', 'timed', 'e3f4a5b6-3001-4c01-9c01-000000000005'::uuid, 'vr.unsupported_claims', '{"id":"e3f4a5b6-3001-4c01-9c01-000000000005","mode":"timed","parentId":"e3f4a5b6-3001-4c01-9c01-000000000001","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage notes that European powers welcomed the reforms and had pressed for Christian protections in various treaties, and that Ottoman reformers drew on European administrative models.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"82f1023f1163ce969c58f0314b8c829934956c846e04045801b2a3655abef3cc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:15637ded-e743-4db4-b277-4b0dd19776ba', 'vr', 'timed', '15637ded-e743-4db4-b277-4b0dd19776ba'::uuid, 'vr.author_perspective', '{"id":"15637ded-e743-4db4-b277-4b0dd19776ba","mode":"timed","parentId":"0de1cdde-cb6f-477e-a26c-b876baeb80c9","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Ostrom demonstrated communities could manage resources sustainably ''without either privatisation or government regulation — the two solutions Hardin had presented as the only alternatives to collapse.'' This identifies privatisation and government regulation as Hardin''s two proposed solutions.","difficulty":"normal","format":"mc","answer":"Privatisation or government regulation","options":["Community self-governance and binding international treaties","Privatisation or government regulation","Voluntary restraint agreements and public education campaigns","Technological innovation to increase the productivity of shared resources"],"contentHash":"4cbcebf2b9a8da5b87896d8b0265e9c133d52b809b531956d620afc6bb8006ec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6e937063-7e06-4098-a00b-62ccd74f759c', 'vr', 'timed', '6e937063-7e06-4098-a00b-62ccd74f759c'::uuid, 'vr.explicit_information', '{"id":"6e937063-7e06-4098-a00b-62ccd74f759c","mode":"timed","parentId":"0de1cdde-cb6f-477e-a26c-b876baeb80c9","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explains ''the gain in livestock value accrues entirely to them — while the cost of overgrazing is shared across all users.'' This asymmetry between private gain and socialised cost is the core mechanism, making the individual calculus always favour adding an animal.","difficulty":"normal","format":"mc","answer":"Because the full benefit of the additional animal goes to the herder while the cost of overgrazing is shared among all users","options":["Because herders do not understand the long-term ecological consequences of overgrazing","Because the full benefit of the additional animal goes to the herder while the cost of overgrazing is shared among all users","Because there is no social mechanism to make herders aware of how many animals others are adding","Because the pasture''s carrying capacity is unknown, so herders cannot calculate when overgrazing begins"],"contentHash":"326d8dc3635cc378ecd948f91c66432c42b1048d70a6b3e7c6bc72b7390a9695"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:21d04723-37d5-4ce3-86e7-fe40e6dfcf79', 'vr', 'timed', '21d04723-37d5-4ce3-86e7-fe40e6dfcf79'::uuid, 'vr.evaluating_evidence', '{"id":"21d04723-37d5-4ce3-86e7-fe40e6dfcf79","mode":"timed","parentId":"0de1cdde-cb6f-477e-a26c-b876baeb80c9","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Ostrom demonstrated her findings ''through extensive fieldwork'' and ''documented cases in Swiss alpine meadows, Japanese fishing villages, and Spanish irrigation systems where locally developed rules and social norms prevented overexploitation.'' The other options introduce methods not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"Fieldwork documenting cases in Swiss meadows, Japanese fishing villages, and Spanish irrigation systems where communities managed shared resources sustainably","options":["Laboratory experiments showing that small groups cooperate when they can communicate directly","Mathematical models demonstrating that private ownership always produces worse outcomes than collective management","Fieldwork documenting cases in Swiss meadows, Japanese fishing villages, and Spanish irrigation systems where communities managed shared resources sustainably","A re-analysis of Hardin''s original pasture data showing errors in his calculations"],"contentHash":"4c01c22eed5f79e333a44aa11286630b76721333fcc040cabc440500834a3a5c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:298d9a6b-7280-42a7-90f9-5bc75e06022c', 'vr', 'timed', '298d9a6b-7280-42a7-90f9-5bc75e06022c'::uuid, 'vr.explicit_information', '{"id":"298d9a6b-7280-42a7-90f9-5bc75e06022c","mode":"timed","parentId":"0de1cdde-cb6f-477e-a26c-b876baeb80c9","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The historical English commons...were regulated by manorial courts and customary rights, not freely accessible to all,'' directly contrasting with Hardin''s model of open-access resources.","difficulty":"hard","format":"mc","answer":"The English commons were regulated by manorial courts and customary rights, not freely accessible to all","options":["The English commons were privately owned and access was sold to individual herders by manorial lords","The English commons were regulated by manorial courts and customary rights, not freely accessible to all","The English commons were managed by elected village councils that imposed strict limits on animal numbers","The English commons were reserved exclusively for the use of tenant farmers, excluding landless labourers"],"contentHash":"d04c15707a4ca2d2d76b2c08243d77ff84762ae34cb6d6bea8d2490fb025806d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:edeef5fa-c60f-4f63-85c4-5c9b2a188fab', 'vr', 'timed', 'edeef5fa-c60f-4f63-85c4-5c9b2a188fab'::uuid, 'vr.explicit_information', '{"id":"edeef5fa-c60f-4f63-85c4-5c9b2a188fab","mode":"timed","parentId":"d7893275-cb0d-4f38-971b-631351d30124","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the Jubilee described ''debts were to be cancelled, enslaved people freed, and land returned to its original family owners.'' The correct option directly lists all three elements.","difficulty":"normal","format":"mc","answer":"Debts cancelled, enslaved people freed, and land returned to original family owners","options":["Debts cancelled, enslaved people freed, and land returned to original family owners","Taxes remitted, prisoners released, and tithes redistributed to the poor","Debts renegotiated, enslaved people given rights of appeal, and land values reassessed","Trade halted, debts deferred for ten years, and communal feasts held across all settlements"],"contentHash":"57a024cbf9b59eaeddf2673e2f4cbad73567a4b18c46abf090ee634de4e7ef93"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2cc981ca-f643-4966-b835-8cbcc421af49', 'vr', 'timed', '2cc981ca-f643-4966-b835-8cbcc421af49'::uuid, 'vr.author_perspective', '{"id":"2cc981ca-f643-4966-b835-8cbcc421af49","mode":"timed","parentId":"d7893275-cb0d-4f38-971b-631351d30124","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states advocates argued ''debt accumulation, when left unchecked, tends to concentrate wealth and produce social stratification, with indebted households gradually losing assets...to creditors'' and that ''The periodic cancellation of debts was thus conceived as a mechanism to prevent the permanent entrenchment of economic inequality.'' The correct option directly pa…","difficulty":"normal","format":"mc","answer":"The permanent entrenchment of economic inequality as indebted households gradually lost assets to creditors","options":["Inflation caused by excessive money creation when wealthy creditors reinvested their returns","The permanent entrenchment of economic inequality as indebted households gradually lost assets to creditors","The collapse of agricultural productivity as smallholders prioritised debt repayment over investment in their land","The flight of skilled workers from regions with high debt burdens to more prosperous areas"],"contentHash":"8aeefe39c51c5072b842c52ec2f1d91e18a02ea8d75293faaba71d9c990a9f6f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2865e181-83b4-44ad-92e7-f62e61706d73', 'vr', 'timed', '2865e181-83b4-44ad-92e7-f62e61706d73'::uuid, 'vr.author_perspective', '{"id":"2865e181-83b4-44ad-92e7-f62e61706d73","mode":"timed","parentId":"d7893275-cb0d-4f38-971b-631351d30124","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The campaign argued that debt repayments were absorbing funds that could otherwise be spent on healthcare, education, and infrastructure in some of the world''s poorest countries.'' The correct option directly paraphrases this.","difficulty":"normal","format":"mc","answer":"That repayments were absorbing funds that could otherwise be spent on healthcare, education, and infrastructure","options":["That repayments were causing currency depreciation that made food imports unaffordable for the poorest citizens","That repayments were absorbing funds that could otherwise be spent on healthcare, education, and infrastructure","That repayments were preventing developing nations from participating in international trade negotiations","That repayments were enriching a small class of domestic intermediaries rather than reaching international creditors"],"contentHash":"2b7abf97674995b36bfb4b6dec97c6250fc02741d49b30d2e513c97f67c768f6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:84d5c99e-0265-4052-94f5-275c874a4a33', 'vr', 'timed', '84d5c99e-0265-4052-94f5-275c874a4a33'::uuid, 'vr.meaning_in_context', '{"id":"84d5c99e-0265-4052-94f5-275c874a4a33","mode":"timed","parentId":"d7893275-cb0d-4f38-971b-631351d30124","primarySkillId":"vr.meaning_in_context","secondarySkillIds":["vr.author_perspective"],"confidence":"high","rationale":"The passage states critics argue ''unconditional relief creates moral hazard — reducing incentives for responsible fiscal management among debtor governments.'' The correct option directly paraphrases this concern.","difficulty":"hard","format":"mc","answer":"That cancellation would be perceived as a reward for fiscal mismanagement, reducing incentives for responsible governance among debtor governments","options":["That cancellation would be perceived as a reward for fiscal mismanagement, reducing incentives for responsible governance among debtor governments","That cancellation would allow corrupt officials in debtor nations to redirect saved funds into private accounts","That cancellation would create public anger in creditor nations, undermining political support for future development aid","That cancellation would set a precedent that private creditors would use to demand government bailouts during financial crises"],"contentHash":"39257b5abb615eac3ebde7acd0ef1a9d31cf25b3d22d725c13a51a27230c9da8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:60d8637f-9bd5-4d0a-863e-c240a14f7d9b', 'vr', 'timed', '60d8637f-9bd5-4d0a-863e-c240a14f7d9b'::uuid, 'vr.main_idea_and_purpose', '{"id":"60d8637f-9bd5-4d0a-863e-c240a14f7d9b","mode":"timed","parentId":"a1586754-e83b-482d-971c-74d634eda7de","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage uses the OED example to illustrate that ''the underlying practice predates the label'' — meaning crowdsourcing as a practice existed before Jeff Howe coined the term in 2006.","difficulty":"normal","format":"mc","answer":"That the underlying practice of crowdsourcing predates the coining of the term in 2006","options":["That the underlying practice of crowdsourcing predates the coining of the term in 2006","That crowdsourcing is only effective for linguistic and literary projects rather than scientific ones","That crowdsourcing was invented in the nineteenth century by British lexicographers","That volunteer contributions are always inferior in quality to those of paid specialists"],"contentHash":"ea34bca8e54031bc3d9f5844e7f1413a5233311577d658108077c59f470f5258"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5c56d4ea-1d81-4a3b-88f6-57904c664d8d', 'vr', 'timed', '5c56d4ea-1d81-4a3b-88f6-57904c664d8d'::uuid, 'vr.author_perspective', '{"id":"5c56d4ea-1d81-4a3b-88f6-57904c664d8d","mode":"timed","parentId":"a1586754-e83b-482d-971c-74d634eda7de","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Surowiecki argued crowd judgement is accurate ''when individual contributions are independent, diverse, and decentralised.'' The other options describe conditions not stated by Surowiecki, and some — such as deliberation — would undermine independence.","difficulty":"normal","format":"mc","answer":"When contributions are independent, diverse, and decentralised","options":["When all participants have access to the same information and can deliberate together before submitting their answers","When contributions are independent, diverse, and decentralised","When a moderating expert reviews and filters crowd responses before aggregation","When the crowd is large enough to include at least one genuine specialist in the relevant domain"],"contentHash":"04696643047f2bfee90cf84a7669f2b23898094e5b32faf6b78c047b2edd5fee"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1dc25be7-d764-4ced-88c4-54496b12a288', 'vr', 'timed', '1dc25be7-d764-4ced-88c4-54496b12a288'::uuid, 'vr.explicit_information', '{"id":"1dc25be7-d764-4ced-88c4-54496b12a288","mode":"timed","parentId":"a1586754-e83b-482d-971c-74d634eda7de","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Online platforms can amplify these effects through algorithmic filtering and social feedback mechanisms'' — referring to the herding and social influence effects that degrade accuracy.","difficulty":"hard","format":"mc","answer":"Algorithmic filtering and social feedback mechanisms that undermine the independence of contributions","options":["Requiring participants to register before contributing, which limits the size of the crowd","Allowing anonymous contributions that cannot be verified or attributed to identifiable individuals","Displaying questions in a randomised order that prevents participants from seeing the full context","Algorithmic filtering and social feedback mechanisms that undermine the independence of contributions"],"contentHash":"7fc441184dae126879263cab5e13bf626659c308fc4371f6a35617d9086fcfc0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1cddd04c-1b10-481f-9c60-9ccfc34c6f2c', 'vr', 'timed', '1cddd04c-1b10-481f-9c60-9ccfc34c6f2c'::uuid, 'vr.explicit_information', '{"id":"1cddd04c-1b10-481f-9c60-9ccfc34c6f2c","mode":"timed","parentId":"a1586754-e83b-482d-971c-74d634eda7de","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states these projects ''have produced results comparable to or in some cases exceeding professional analysis for specific well-defined tasks.'' The other options introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"Both produced results comparable to or exceeding professional analysis for specific well-defined tasks","options":["Both projects used crowdsourcing to generate hypotheses that professional scientists then tested in laboratories","Both were abandoned when it became clear that crowd contributors lacked the expertise to perform the tasks reliably","Both produced results comparable to or exceeding professional analysis for specific well-defined tasks","Both were funded by the same international science foundation as part of a coordinated open-science initiative"],"contentHash":"397e6c9502f6b0d59b8267cc4c6e3f478ccc780f50943826500dcf9b5062a4c4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2d29b8c9-d9db-43ca-90aa-f3c48821b1cb', 'vr', 'timed', '2d29b8c9-d9db-43ca-90aa-f3c48821b1cb'::uuid, 'vr.recognising_contradictions', '{"id":"2d29b8c9-d9db-43ca-90aa-f3c48821b1cb","mode":"timed","parentId":"34f24ad2-5952-4655-807e-8a919ea56afa","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage defines dark matter as something that ''does not interact with the electromagnetic force'' and ''neither emits, absorbs, nor reflects light,'' making it ''invisible to all forms of electromagnetic observation, from radio waves to gamma rays.'' Emitting any form of radiation — detectable or otherwise — would contradict this definition.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"ecec28b4ee23b2790f109279c40a0711a02d9b0802d4462d226961e1f13f0914"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:dc4cc314-e955-46b3-b58c-cd7ff4998109', 'vr', 'timed', 'dc4cc314-e955-46b3-b58c-cd7ff4998109'::uuid, 'vr.inference', '{"id":"dc4cc314-e955-46b3-b58c-cd7ff4998109","mode":"timed","parentId":"34f24ad2-5952-4655-807e-8a919ea56afa","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Newtonian mechanics predicts outer stars should orbit more slowly, but Rubin''s observations showed rotation velocities remain approximately constant — a discrepancy that challenged Newtonian predictions.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"7036814a45f030b742ef8ef20bd5e9f7f097b7dd87c6faef309223bfc55a1365"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:82bf5af5-dc0c-45cd-9aa4-7a43667d3e36', 'vr', 'timed', '82bf5af5-dc0c-45cd-9aa4-7a43667d3e36'::uuid, 'vr.recognising_contradictions', '{"id":"82bf5af5-dc0c-45cd-9aa4-7a43667d3e36","mode":"timed","parentId":"34f24ad2-5952-4655-807e-8a919ea56afa","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the opposite: X-ray observations showed ordinary matter had been ''slowed by the collision'' while gravitational lensing showed most of the mass had ''passed through without interaction.'' These two components ended up in different locations — the ordinary matter was slowed and the dark matter was not.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"d24dc050834388ee6e8092253e2f68c33691c0f801231df8176aea889bdea903"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ba08db8b-5438-4aae-a77f-33dc7a25363c', 'vr', 'timed', 'ba08db8b-5438-4aae-a77f-33dc7a25363c'::uuid, 'vr.explicit_information', '{"id":"ba08db8b-5438-4aae-a77f-33dc7a25363c","mode":"timed","parentId":"34f24ad2-5952-4655-807e-8a919ea56afa","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Despite extensive searches, no particle has been detected that satisfactorily accounts for dark matter,'' and lists multiple unconfirmed candidates.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"d91b041a6f54cd8778d6894a19b70628bde2408ad0c95f41bdabd8af3325c3a4"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:23774d38-ec1d-4961-bd79-6b28f636824c', 'vr', 'timed', '23774d38-ec1d-4961-bd79-6b28f636824c'::uuid, 'vr.recognising_contradictions', '{"id":"23774d38-ec1d-4961-bd79-6b28f636824c","mode":"timed","parentId":"f686a9eb-14dc-4255-b810-579d78271e44","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the mechanism was recovered from ''the wreck of a Roman cargo ship,'' not a Greek naval vessel.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t Tell"],"contentHash":"6d6402a8d2d64ad78176ed716049f8fd0b33e3acf7b89b771880c0358298c621"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:aeed9170-acc7-4625-b867-f10b612ce50f', 'vr', 'timed', 'aeed9170-acc7-4625-b867-f10b612ce50f'::uuid, 'vr.explicit_information', '{"id":"aeed9170-acc7-4625-b867-f10b612ce50f","mode":"timed","parentId":"f686a9eb-14dc-4255-b810-579d78271e44","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states that the gears ''drove a series of dials and pointers that displayed the positions of the Sun and Moon, predicted lunar and solar eclipses, and tracked the cycles of the ancient Olympic Games.'' This directly confirms that the mechanism predicted eclipses.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t Tell"],"contentHash":"24113dfe9d95f8237fb3f4ae15a859ddd7b4e471414655a7b10cdb07c8c3fb6b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:dc4e70d8-28ee-4dfa-999d-bbf0ed8cc3ac', 'vr', 'timed', 'dc4e70d8-28ee-4dfa-999d-bbf0ed8cc3ac'::uuid, 'vr.recognising_contradictions', '{"id":"dc4e70d8-28ee-4dfa-999d-bbf0ed8cc3ac","mode":"timed","parentId":"f686a9eb-14dc-4255-b810-579d78271e44","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that the Research Project''s analysis ''revealed inscriptions on the surviving fragments that served as a kind of instruction manual, describing the functions of the front and back dials.'' This directly contradicts the claim that the inscriptions were decorative — they were functional, serving as an instruction manual.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t Tell"],"contentHash":"e5f0361c5e006cc4b079fd3f222ecc58d9cf060e596560e189232c1e6d77ccf6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:41295947-2d27-48d8-a4ed-30790b9bbb26', 'vr', 'timed', '41295947-2d27-48d8-a4ed-30790b9bbb26'::uuid, 'vr.unsupported_claims', '{"id":"41295947-2d27-48d8-a4ed-30790b9bbb26","mode":"timed","parentId":"f686a9eb-14dc-4255-b810-579d78271e44","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that nothing comparable to the mechanism appeared ''until the astronomical clocks of medieval Europe in the fourteenth century,'' but it does not say whether the makers of those clocks had any knowledge of the Antikythera mechanism or were influenced by it.","difficulty":"hard","format":"tfc","answer":"Can''t Tell","options":["True","False","Can''t Tell"],"contentHash":"7ef24ef24605a9f0a5433008b6d3bb88bd2e4c6d86e26fade99d6fa35577f615"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:8dafc3e7-0152-42b2-ad77-77af7c63d195', 'vr', 'timed', '8dafc3e7-0152-42b2-ad77-77af7c63d195'::uuid, 'vr.explicit_information', '{"id":"8dafc3e7-0152-42b2-ad77-77af7c63d195","mode":"timed","parentId":"38abfe00-396d-4002-8d57-6b59a312b81e","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that when a source moves toward an observer ''successive wave crests are compressed, increasing the observed frequency,'' and when it moves away ''crests are stretched, decreasing the observed frequency.'' It then illustrates this with the ambulance siren example: ''as the vehicle approaches, the pitch appears higher than the siren''s actual frequency; as it rec…","difficulty":"normal","format":"mc","answer":"The compression of wave crests as the ambulance approaches raises the observed frequency, and their stretching as it recedes lowers it","options":["The siren''s actual frequency increases as the vehicle accelerates toward the observer","The compression of wave crests as the ambulance approaches raises the observed frequency, and their stretching as it recedes lowers it","The observer''s motion relative to a stationary siren creates the illusion of a pitch change","The Doppler effect applies only to the receding phase — the approaching siren sounds at its true pitch"],"contentHash":"6451276e23f58584c75865e088bba9b254df6e22f5a6967b90356135b5fe13e7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:28713db2-4603-41ba-9682-09523188acc8', 'vr', 'timed', '28713db2-4603-41ba-9682-09523188acc8'::uuid, 'vr.evaluating_evidence', '{"id":"28713db2-4603-41ba-9682-09523188acc8","mode":"timed","parentId":"38abfe00-396d-4002-8d57-6b59a312b81e","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Hubble observed ''that the light from distant galaxies was systematically redshifted — and that the degree of redshift correlated with distance — provided key evidence that the universe is expanding.'' The correct option directly paraphrases both elements of this observation.","difficulty":"normal","format":"mc","answer":"That the light from distant galaxies was systematically redshifted, with the degree of redshift correlating with distance","options":["That the light from distant galaxies was systematically redshifted, with the degree of redshift correlating with distance","That stars in distant galaxies were orbiting their galactic centres faster than those in nearby galaxies","That the cosmic microwave background radiation was unevenly distributed across the sky","That certain galaxies appeared to be moving toward Earth while others were moving away"],"contentHash":"283d552303f5a792f24e27dbe069e4ecdfe62309c4f6157847f8e11a2e2d115d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fed29ac6-da6d-4732-8009-948eb950cf90', 'vr', 'timed', 'fed29ac6-da6d-4732-8009-948eb950cf90'::uuid, 'vr.explicit_information', '{"id":"fed29ac6-da6d-4732-8009-948eb950cf90","mode":"timed","parentId":"38abfe00-396d-4002-8d57-6b59a312b81e","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''for light, the situation is more nuanced: the special theory of relativity requires that light''s speed remain constant in all frames of reference, so the Doppler formula for light differs from that for sound.'' The correct option directly states this reason.","difficulty":"hard","format":"mc","answer":"Because the special theory of relativity requires light''s speed to remain constant in all frames of reference","options":["Because light travels through a vacuum whereas sound requires a medium, making the wave mechanics fundamentally different","Because the frequency of light is so much higher than sound that different mathematical treatment is required","Because the special theory of relativity requires light''s speed to remain constant in all frames of reference","Because light waves are transverse while sound waves are longitudinal, producing different Doppler characteristics"],"contentHash":"49228920c857494c457f1b42da2dc5ba7bdada510e09ea1c0080a17115bcdd6c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e3eb13ae-dc85-4a0f-925e-3c7f8801fdc9', 'vr', 'timed', 'e3eb13ae-dc85-4a0f-925e-3c7f8801fdc9'::uuid, 'vr.explicit_information', '{"id":"e3eb13ae-dc85-4a0f-925e-3c7f8801fdc9","mode":"timed","parentId":"38abfe00-396d-4002-8d57-6b59a312b81e","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Doppler ultrasound ''allows clinicians to calculate flow velocity and detect abnormalities such as narrowed arteries.'' The other options introduce clinical applications not described in the passage.","difficulty":"normal","format":"mc","answer":"The flow velocity of blood and the detection of abnormalities such as narrowed arteries","options":["The structural dimensions of organs by measuring how ultrasound waves are absorbed by different tissues","The density of bone tissue by comparing emitted and reflected ultrasound frequencies","The electrical activity of the heart by measuring frequency shifts in reflected ultrasound pulses","The flow velocity of blood and the detection of abnormalities such as narrowed arteries"],"contentHash":"c4e999eda63cb53ce3ea14bd53b4fb3e8359c9ab7d67258aa87eb06c788bba53"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2c783bb6-7b62-4045-868a-8cb86931c10a', 'vr', 'timed', '2c783bb6-7b62-4045-868a-8cb86931c10a'::uuid, 'vr.explicit_information', '{"id":"2c783bb6-7b62-4045-868a-8cb86931c10a","mode":"timed","parentId":"99356696-d87c-4aef-a8ab-739e5b7365d2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states enclosure ''extinguished these common rights, consolidating scattered strips into compact individual holdings and converting commons to private ownership,'' where common rights included ''rights to graze animals on common land.'' The other options introduce rights not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"The right to graze animals on common land and hold scattered strips of open-field farmland","options":["The right to elect representatives to Parliament to negotiate land use terms with local landowners","The right to graze animals on common land and hold scattered strips of open-field farmland","The right to fish in rivers and streams that ran through privately owned estates","The right to sell surplus produce at local markets without paying tolls to the manor"],"contentHash":"57c9ccb585c443a89821729dc04cff268de141294c4f18e81bb4824c429c32e8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:69b25bc6-82ea-4aa1-81c0-646b9ee6eed7', 'vr', 'timed', '69b25bc6-82ea-4aa1-81c0-646b9ee6eed7'::uuid, 'vr.author_perspective', '{"id":"69b25bc6-82ea-4aa1-81c0-646b9ee6eed7","mode":"timed","parentId":"99356696-d87c-4aef-a8ab-739e5b7365d2","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states proponents argued that consolidated holdings ''facilitated crop rotation and selective breeding.'' The other options introduce agricultural improvements not attributed to enclosure in the passage.","difficulty":"normal","format":"mc","answer":"Crop rotation and selective breeding of livestock","options":["The introduction of irrigation systems that dramatically increased crop yields in dry regions","The use of steam-powered machinery that reduced the need for agricultural labour","Crop rotation and selective breeding of livestock","The cultivation of new crops imported from the Americas that could not be grown in open-field strips"],"contentHash":"10aa66bfff200be70658c69eded7af2928c89f67e6ffa1f8b3249f78f833e31c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b795ecf3-f75e-42ef-87a9-57daac9802e3', 'vr', 'timed', 'b795ecf3-f75e-42ef-87a9-57daac9802e3'::uuid, 'vr.meaning_in_context', '{"id":"b795ecf3-f75e-42ef-87a9-57daac9802e3","mode":"timed","parentId":"99356696-d87c-4aef-a8ab-739e5b7365d2","primarySkillId":"vr.meaning_in_context","secondarySkillIds":["vr.author_perspective"],"confidence":"high","rationale":"The passage states Thompson argued ''the Parliamentary process was controlled by landowners who had both the political power to enact enclosure and the financial means to benefit from it, while those who lost common rights...had little effective recourse.'' The other options introduce claims not made by Thompson in the passage.","difficulty":"hard","format":"mc","answer":"That the Parliamentary process was controlled by landowners who enacted enclosure in their own interests while those who lost common rights had little recourse","options":["That enclosure involved the literal theft of livestock from smallholders by armed agents of landowners","That the Parliamentary process was controlled by landowners who enacted enclosure in their own interests while those who lost common rights had little recourse","That enclosure was designed to impoverish the rural poor so they would be forced to work in factories at low wages","That the compensation paid to displaced smallholders was systematically undervalued by corrupt surveyors"],"contentHash":"b59aad6fb5284729cfbcceeae47e04c1c96baf02e2c94e8b327a98348d8bcb62"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6102a1d2-2b8d-4fac-923a-22c8af74c3bf', 'vr', 'timed', '6102a1d2-2b8d-4fac-923a-22c8af74c3bf'::uuid, 'vr.author_perspective', '{"id":"6102a1d2-2b8d-4fac-923a-22c8af74c3bf","mode":"timed","parentId":"99356696-d87c-4aef-a8ab-739e5b7365d2","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage presents proponents'' arguments (agricultural efficiency, productivity) and critics'' arguments (dispossession, social dislocation), noting ''the relative weight given to economic modernisation versus social dislocation varies considerably across the historiography.'' No verdict is reached, making this a balanced presentation.","difficulty":"normal","format":"mc","answer":"The passage presents both economic arguments in favour of enclosure and social arguments against it, without reaching a definitive conclusion","options":["The passage endorses the view that enclosure was primarily beneficial for Britain''s long-term economic development","The passage suggests the debate is now settled, with modern historians uniformly viewing enclosure as an economic necessity","The passage argues that Thompson''s characterisation of enclosure as class robbery is the most historically accurate account","The passage presents both economic arguments in favour of enclosure and social arguments against it, without reaching a definitive conclusion"],"contentHash":"6248fe7f8e45709b34a17852ea224f49fa646736a887f61ebe973338190f8199"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5bbc84a6-612b-4a91-b557-a32ec60e0fbe', 'vr', 'timed', '5bbc84a6-612b-4a91-b557-a32ec60e0fbe'::uuid, 'vr.explicit_information', '{"id":"5bbc84a6-612b-4a91-b557-a32ec60e0fbe","mode":"timed","parentId":"71e51609-9ed4-4516-993f-1e4709a80200","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The first successful public demonstration of ether anaesthesia took place on 16 October 1846 at Massachusetts General Hospital...when dentist William Morton administered ether to a patient while surgeon John Collins Warren removed a tumour from the patient''s jaw.","difficulty":"normal","format":"mc","answer":"It was the first successful public demonstration of ether anaesthesia, during which a tumour was removed without the patient expressing pain","options":["It was the first successful public demonstration of ether anaesthesia, during which a tumour was removed without the patient expressing pain","It was the first time nitrous oxide was used successfully as an anaesthetic in a public setting","It was the occasion on which Horace Wells demonstrated that nitrous oxide could replace ether in surgical procedures","It marked the first use of chloroform as an anaesthetic by James Young Simpson before a medical audience"],"contentHash":"aa274d4851be5c9c377771f06e76951d3dc804779647eaab8c3c97a6edf0790e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b230cc66-c762-49f4-84d0-93d495991925', 'vr', 'timed', 'b230cc66-c762-49f4-84d0-93d495991925'::uuid, 'vr.explicit_information', '{"id":"b230cc66-c762-49f4-84d0-93d495991925","mode":"timed","parentId":"71e51609-9ed4-4516-993f-1e4709a80200","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states Long ''did not publish his findings until 1849, after Morton''s public demonstration.'' The other options introduce reasons not stated in the passage.","difficulty":"normal","format":"mc","answer":"Long did not publish his findings until 1849, after Morton''s public demonstration","options":["Long''s records were destroyed in a fire and his claims could not be verified","Long did not publish his findings until 1849, after Morton''s public demonstration","Long''s patients had signed confidentiality agreements that prevented him from publicising his results","Long used a different form of ether that the medical community did not recognise as equivalent to Morton''s"],"contentHash":"25e78d9026941124a001fc5fb4e0fd77056dad173aa958ade9bfbdf2bd198767"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:51212e28-0c21-42e5-86ec-90f27c035d45', 'vr', 'timed', '51212e28-0c21-42e5-86ec-90f27c035d45'::uuid, 'vr.explicit_information', '{"id":"51212e28-0c21-42e5-86ec-90f27c035d45","mode":"timed","parentId":"71e51609-9ed4-4516-993f-1e4709a80200","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states chloroform ''was later found to have a narrower margin of safety — the dose required for anaesthesia was dangerously close to a lethal dose — and it eventually fell out of widespread use.'' The other options contradict the passage — chloroform produced faster unconsciousness than ether, not slower.","difficulty":"normal","format":"mc","answer":"It had a narrow margin of safety because the anaesthetic dose was dangerously close to a lethal dose","options":["It was found to cause liver damage with repeated exposure, making it unsuitable for use in long procedures","It was superseded by ether, which produced unconsciousness more quickly and reliably","It had a narrow margin of safety because the anaesthetic dose was dangerously close to a lethal dose","It was banned by medical authorities after a series of high-profile patient deaths during dental procedures"],"contentHash":"b2015c9293691d0b0128e4e9c0fd20acdb6c4017d384ac408989000387a60f9f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0e1d67ad-b419-435f-b1e9-a064a5fdbfd5', 'vr', 'timed', '0e1d67ad-b419-435f-b1e9-a064a5fdbfd5'::uuid, 'vr.explicit_information', '{"id":"0e1d67ad-b419-435f-b1e9-a064a5fdbfd5","mode":"timed","parentId":"71e51609-9ed4-4516-993f-1e4709a80200","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states surgery ''was consequently limited in scope, speed, and ambition'' and ''Surgeons were valued primarily for their speed.'' It also notes alcohol and opium offered ''imperfect and unpredictable relief,'' contradicting option C.","difficulty":"normal","format":"mc","answer":"Surgery was limited in scope and speed, with surgeons valued primarily for the swiftness with which they could complete procedures","options":["Surgery was rare and performed only in life-threatening emergencies because the risk of infection made routine operations impossible","Surgery was limited in scope and speed, with surgeons valued primarily for the swiftness with which they could complete procedures","Surgery was widely available but performed under general sedation using alcohol and opium, which provided reliable pain relief","Surgery was practised only by barber-surgeons who lacked formal medical training and performed amputations without any pain management"],"contentHash":"55516b2a1185201c6ebcb523f6565aa5d35cb09c582779fb4e1252b63c7c7d4b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:81c0a82a-4606-44e4-95eb-fffd62094172', 'vr', 'timed', '81c0a82a-4606-44e4-95eb-fffd62094172'::uuid, 'vr.explicit_information', '{"id":"81c0a82a-4606-44e4-95eb-fffd62094172","mode":"timed","parentId":"f36cf8a8-bf25-4f78-866c-ac1672ab5011","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the opium trade ''reversed what had previously been a persistent trade deficit for Britain: silver had flowed from Britain to China in exchange for tea and porcelain, but opium allowed British merchants to extract silver from China in return.'' The correct option accurately paraphrases this reversal.","difficulty":"hard","format":"mc","answer":"It caused silver to flow from China to Britain, reversing a previous trade deficit that Britain had with China","options":["It caused silver to flow from China to Britain, reversing a previous trade deficit that Britain had with China","It caused silver to flow from Britain to China, as British merchants paid Chinese officials for trading licences","It stabilised silver flows by replacing the volatile tea trade with a more predictable commodity","It eliminated silver from the trade entirely by establishing a barter system between opium and silk"],"contentHash":"b17e2cc8f6c74a91b2ce1c7a63905af04135c5b724de0000f043220a20e540bc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1e84b9bb-3a89-4050-8ab5-48455fc3ffe1', 'vr', 'timed', '1e84b9bb-3a89-4050-8ab5-48455fc3ffe1'::uuid, 'vr.explicit_information', '{"id":"1e84b9bb-3a89-4050-8ab5-48455fc3ffe1","mode":"timed","parentId":"f36cf8a8-bf25-4f78-866c-ac1672ab5011","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''In 1839, the Imperial Commissioner Lin Zexu confiscated and destroyed over 1,200 tonnes of opium belonging to British merchants in Canton, without compensation.","difficulty":"normal","format":"mc","answer":"He confiscated and destroyed over 1,200 tonnes of opium belonging to British merchants without compensation","options":["He expelled all British merchants from Canton and seized their trading licences","He confiscated and destroyed over 1,200 tonnes of opium belonging to British merchants without compensation","He imposed a total embargo on British goods entering Chinese ports","He arrested the captain of a British trading vessel and charged him with smuggling"],"contentHash":"8f0acbe0e434abe9346823dbea7d5a7ae4d2074042a1b41b76bf75066af4a2dc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5531be51-60f7-4716-8da5-5105e15f8d2a', 'vr', 'timed', '5531be51-60f7-4716-8da5-5105e15f8d2a'::uuid, 'vr.explicit_information', '{"id":"5531be51-60f7-4716-8da5-5105e15f8d2a","mode":"timed","parentId":"f36cf8a8-bf25-4f78-866c-ac1672ab5011","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the Treaty of Nanjing ''forced China to cede Hong Kong island to Britain, open five treaty ports to foreign trade, and pay an indemnity of 21 million silver dollars.'' The other options introduce terms not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"China ceded Hong Kong island to Britain, opened five treaty ports, and paid an indemnity of 21 million silver dollars","options":["China was required to legalise the opium trade and allow British warships to patrol the Yangtze River","China agreed to purchase a fixed quantity of British manufactured goods annually and to abolish internal trade tariffs","China ceded Hong Kong island to Britain, opened five treaty ports, and paid an indemnity of 21 million silver dollars","China surrendered control of its customs revenue to a joint British-Chinese commission for twenty years"],"contentHash":"0791873d4b0843feb59b511b0d2d12bec51ee5709c8c756d537c20f9b291afba"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f6fcdc42-102e-499c-9c5d-25a8e8f33502', 'vr', 'timed', 'f6fcdc42-102e-499c-9c5d-25a8e8f33502'::uuid, 'vr.meaning_in_context', '{"id":"f6fcdc42-102e-499c-9c5d-25a8e8f33502","mode":"timed","parentId":"f36cf8a8-bf25-4f78-866c-ac1672ab5011","primarySkillId":"vr.meaning_in_context","secondarySkillIds":["vr.author_perspective"],"confidence":"medium","rationale":"The passage states these treaties ''are referred to in China as the \\\"unequal treaties\\\"'' and are ''regarded in Chinese historiography as the beginning of what Chinese historians call the \\\"century of humiliation,\\\" a period of foreign exploitation lasting until 1949.'' The correct option accurately combines these two passage statements.","difficulty":"hard","format":"mc","answer":"It is a collective term for the treaties following the Opium Wars, regarded as marking the start of a period of foreign exploitation","options":["It refers to trade agreements in which China was forced to accept lower tariffs than other nations imposed on Chinese goods","It is a collective term for the treaties following the Opium Wars, regarded as marking the start of a period of foreign exploitation","It describes the asymmetry between China''s formal sovereignty and the de facto control exercised by foreign powers over treaty ports","It is a term coined by Western historians to describe agreements that violated the norms of nineteenth-century international law"],"contentHash":"672b6551da4ab397bf2f86ec1c2291b4cf077cee55929f6252d3c42c1d12f237"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:23f97f1b-b1bf-4ee9-a5fe-45ee2a854f7e', 'vr', 'timed', '23f97f1b-b1bf-4ee9-a5fe-45ee2a854f7e'::uuid, 'vr.recognising_contradictions', '{"id":"23f97f1b-b1bf-4ee9-a5fe-45ee2a854f7e","mode":"timed","parentId":"1354c494-92ae-4df0-95f8-8ad7865001ef","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states placebo administration ''triggers the release of endogenous opioids...and activates brain regions associated with pain regulation,'' concluding that ''the placebo effect in pain relief has a measurable biological substrate.'' This directly contradicts the claim that the effect involves only subjective reporting with no biological mechanism.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"f105eebf2b62051e4d312325a48773021a2d3030bb1ee25a4b307dbb06cc9f0e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f82e65b9-c315-4fcb-92a9-2ec0ca67e841', 'vr', 'timed', 'f82e65b9-c315-4fcb-92a9-2ec0ca67e841'::uuid, 'vr.qualifiers_and_scope', '{"id":"f82e65b9-c315-4fcb-92a9-2ec0ca67e841","mode":"timed","parentId":"1354c494-92ae-4df0-95f8-8ad7865001ef","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage explicitly describes open-label placebos — ''given to patients who are explicitly told the pill contains no active ingredient'' — and states they ''can still produce measurable improvements in certain conditions.'' This directly contradicts the statement.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"7eff69c932b4cf05f389dadd1ab76e4dc11170ff5f2aec64e600fff7a26066a2"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:3459a6cf-bbca-4a59-a71c-3c4bf2b51b84', 'vr', 'timed', '3459a6cf-bbca-4a59-a71c-3c4bf2b51b84'::uuid, 'vr.qualifiers_and_scope', '{"id":"3459a6cf-bbca-4a59-a71c-3c4bf2b51b84","mode":"timed","parentId":"1354c494-92ae-4df0-95f8-8ad7865001ef","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"high","rationale":"The passage states ''More invasive-seeming procedures, such as sham acupuncture or sham surgery, tend to produce larger placebo responses than pills'' — but ''tend to'' implies a general pattern, not a universal rule.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"c49271bd254982ce02fd78277be645286595f5e5dde4ee8829a4cf4915b75e60"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:93f01e12-35c7-41a1-b2ee-e5f88d2a1136', 'vr', 'timed', '93f01e12-35c7-41a1-b2ee-e5f88d2a1136'::uuid, 'vr.explicit_information', '{"id":"93f01e12-35c7-41a1-b2ee-e5f88d2a1136","mode":"timed","parentId":"1354c494-92ae-4df0-95f8-8ad7865001ef","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Patients warned of side effects are more likely to report them, even when receiving an inert substance.'' This directly confirms the statement, which is a paraphrase of the nocebo effect as described in the passage.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"7f664b0870f95c9b663f7aa7bba688d0bb77586b1cff41d0d7492e0f687eec62"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:bf61945f-8f23-4e6b-aedc-acb1c2d85314', 'vr', 'timed', 'bf61945f-8f23-4e6b-aedc-acb1c2d85314'::uuid, 'vr.recognising_contradictions', '{"id":"bf61945f-8f23-4e6b-aedc-acb1c2d85314","mode":"timed","parentId":"12cb60d0-6400-4c43-a36f-ce31bfefe1c2","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the term was coined by German geographer Ferdinand von Richthofen ''in 1877, long after the routes had ceased to function as active commercial arteries.'' 1877 is not contemporary with the routes'' active period (most active during the Han dynasty and Mongol Empire, centuries earlier), and Richthofen was a geographer, not a traveller.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"e77f02971a0e134062a2e7a30bb3ddc91d7d98350df1a5471b7d20fe69ad5978"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7198402f-4f6a-4d00-8094-f9ba0054e393', 'vr', 'timed', '7198402f-4f6a-4d00-8094-f9ba0054e393'::uuid, 'vr.recognising_contradictions', '{"id":"7198402f-4f6a-4d00-8094-f9ba0054e393","mode":"timed","parentId":"12cb60d0-6400-4c43-a36f-ce31bfefe1c2","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Polo''s account ''was treated with scepticism during his lifetime.'' This directly contradicts the claim that it was widely believed and celebrated during his lifetime.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"d3a2bf1486ddea6679748a0c4cbe827508366e9fe45c00bb430623088c030070"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e4108cc9-7ec8-4899-8239-b38bf495df7f', 'vr', 'timed', 'e4108cc9-7ec8-4899-8239-b38bf495df7f'::uuid, 'vr.unsupported_claims', '{"id":"e4108cc9-7ec8-4899-8239-b38bf495df7f","mode":"timed","parentId":"12cb60d0-6400-4c43-a36f-ce31bfefe1c2","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the overland routes were most active during the Han dynasty and again during the Mongol Empire, when the Pax Mongolica ''facilitated long-distance movement.'' However, it does not compare the volume or ease of movement between these two periods.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"2477087899ccf7f057923caadc2fd755e277e7ea957d4bb8002f980d13c717fb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:39a2bc34-a9cd-4679-b079-e2671893fbd1', 'vr', 'timed', '39a2bc34-a9cd-4679-b079-e2671893fbd1'::uuid, 'vr.explicit_information', '{"id":"39a2bc34-a9cd-4679-b079-e2671893fbd1","mode":"timed","parentId":"12cb60d0-6400-4c43-a36f-ce31bfefe1c2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The routes declined in significance following the fifteenth century, as European powers developed maritime routes to Asia that were faster, cheaper, and capable of carrying larger cargo volumes.'' This directly confirms maritime routes contributed to the overland routes'' decline.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"58c8b266f62966023b5d36104cf63ac29a78c0fc44e4b37a69d596f200decea6"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:26ca66ce-f6a1-4dbf-8a85-12cde0014040', 'vr', 'timed', '26ca66ce-f6a1-4dbf-8a85-12cde0014040'::uuid, 'vr.explicit_information', '{"id":"26ca66ce-f6a1-4dbf-8a85-12cde0014040","mode":"timed","parentId":"dd13a575-80f2-4203-94cf-feef592e9330","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The scientific consensus today is that the Tunguska event was caused by the airburst of a small asteroid or comet fragment...which entered the atmosphere and exploded at an altitude of between 5 and 10 kilometres.","difficulty":"normal","format":"mc","answer":"An airburst caused by a small asteroid or comet fragment that exploded at altitude and was largely vaporised","options":["An airburst caused by a small asteroid or comet fragment that exploded at altitude and was largely vaporised","A large meteorite struck the ground and was buried so deeply that expeditions failed to locate it","A volcanic eruption beneath the Siberian permafrost triggered by seismic activity in 1908","A collision between two large meteors above the atmosphere that scattered debris across the region"],"contentHash":"b07ca6bffee4d22fee5ca99af1237cb52a7042e858b6d78126185bd5ce721c37"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:95925f59-4594-46f8-96af-c723b77e7cc4', 'vr', 'timed', '95925f59-4594-46f8-96af-c723b77e7cc4'::uuid, 'vr.explicit_information', '{"id":"95925f59-4594-46f8-96af-c723b77e7cc4","mode":"timed","parentId":"dd13a575-80f2-4203-94cf-feef592e9330","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Kulik ''expected to find a large impact crater and substantial meteorite fragments'' but ''found a vast area of radially flattened trees...but no crater and no significant meteorite material.'' The correct option directly paraphrases both halves of this contrast.","difficulty":"normal","format":"mc","answer":"He expected a large crater and meteorite fragments; he found a pattern of radially flattened trees but no crater","options":["He expected vast wildfires still burning; he found they had already been extinguished by snowfall","He expected a large crater and meteorite fragments; he found a pattern of radially flattened trees but no crater","He expected evidence of a volcanic eruption; he found a field of glass beads consistent with a meteorite impact","He expected minor damage; he found devastation on a scale too large to have been caused by a single object"],"contentHash":"b68343280b6547afca686c541b1e7c0417503c6329e58ab133fc28f75397979f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2696abe0-c5ea-4d1d-a435-caaf8abee2d6', 'vr', 'timed', '2696abe0-c5ea-4d1d-a435-caaf8abee2d6'::uuid, 'vr.explicit_information', '{"id":"2696abe0-c5ea-4d1d-a435-caaf8abee2d6","mode":"timed","parentId":"dd13a575-80f2-4203-94cf-feef592e9330","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the energy released was ''roughly 1,000 times the energy of the atomic bomb dropped on Hiroshima.'' The other options misstate the multiplier given in the passage.","difficulty":"normal","format":"mc","answer":"Roughly 1,000 times greater than the Hiroshima bomb","options":["Approximately equal to the Hiroshima bomb in terms of total energy released","Roughly ten times greater than the Hiroshima bomb","Roughly 1,000 times greater than the Hiroshima bomb","Roughly one million times greater than the Hiroshima bomb"],"contentHash":"cc5b0632c6f585511aab772b9a88e25d8f5dd21854207e73cafdca4d5e17efbb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:55df7d42-90bf-43d3-9777-8d6bb53cfcfd', 'vr', 'timed', '55df7d42-90bf-43d3-9777-8d6bb53cfcfd'::uuid, 'vr.explicit_information', '{"id":"55df7d42-90bf-43d3-9777-8d6bb53cfcfd","mode":"timed","parentId":"dd13a575-80f2-4203-94cf-feef592e9330","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''the region''s extreme remoteness meant that the first scientific expedition to the site did not arrive until 1927.'' The other options introduce reasons not stated in the passage.","difficulty":"normal","format":"mc","answer":"The extreme remoteness of the region made it difficult to organise and fund an expedition","options":["The Soviet government initially classified the event as a military incident and restricted access to the region","The extreme remoteness of the region made it difficult to organise and fund an expedition","Early reports of the event were dismissed as exaggerated by the scientific community until photographic evidence emerged","The region remained inaccessible due to ongoing conflicts along the Trans-Siberian Railway until the late 1920s"],"contentHash":"2fee52b325e052b19ba802fbe1e28fbf8d329011fcdd427a7a7a83cdd4125b1a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:9e0debbb-ef8f-410e-9bf5-17d5791cfdaf', 'vr', 'timed', '9e0debbb-ef8f-410e-9bf5-17d5791cfdaf'::uuid, 'vr.inference', '{"id":"9e0debbb-ef8f-410e-9bf5-17d5791cfdaf","mode":"timed","parentId":"fd1a2e69-2aa1-4d97-b522-54cc06f21a5d","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''If both defect, both receive moderate sentences.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"cef210187ced9f0249d824bfbc4fe3e03fbc4d760895cc4f661c049f958ca72a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:66655be8-12e8-4b90-8974-fa13b1d86b31', 'vr', 'timed', '66655be8-12e8-4b90-8974-fa13b1d86b31'::uuid, 'vr.unsupported_claims', '{"id":"66655be8-12e8-4b90-8974-fa13b1d86b31","mode":"timed","parentId":"fd1a2e69-2aa1-4d97-b522-54cc06f21a5d","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage states game theory ''has since been applied to...evolutionary biology'' but does not specify who first applied it to that field or when.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"0f51e36f8c115b634c01f5de5456c7740f2668169c50f0e37e01d9b362bd7294"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2542ad0d-2435-4f73-9f59-0fbcbbf9bd27', 'vr', 'timed', '2542ad0d-2435-4f73-9f59-0fbcbbf9bd27'::uuid, 'vr.inference', '{"id":"2542ad0d-2435-4f73-9f59-0fbcbbf9bd27","mode":"timed","parentId":"fd1a2e69-2aa1-4d97-b522-54cc06f21a5d","primarySkillId":"vr.inference","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage describes Tit-for-Tat as a strategy that ''cooperate[s] on the first move, then mirror[s] whatever the opponent did on the previous move.'' If an opponent defects, Tit-for-Tat mirrors that defection — meaning it does retaliate.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"7801facfb3034f23a27a405cd086dee99eeb21b7f81a2d751be0b968397eb260"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f1401508-407c-4b3c-8ca9-e35d463ae7e0', 'vr', 'timed', 'f1401508-407c-4b3c-8ca9-e35d463ae7e0'::uuid, 'vr.explicit_information', '{"id":"f1401508-407c-4b3c-8ca9-e35d463ae7e0","mode":"timed","parentId":"fd1a2e69-2aa1-4d97-b522-54cc06f21a5d","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly lists ''antibiotic resistance'' among the real-world situations modelled by the Prisoner''s Dilemma.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"4a4fc5afdec5aab5c4d97abd5068efa53235a48d5bb2817101cede0cbdbf48e8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b56a7267-2f68-4f7b-b28b-98e060f3f741', 'vr', 'timed', 'b56a7267-2f68-4f7b-b28b-98e060f3f741'::uuid, 'vr.author_perspective', '{"id":"b56a7267-2f68-4f7b-b28b-98e060f3f741","mode":"timed","parentId":"512968ac-3520-49ee-a9aa-036dc3aaafa2","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Semmelweis hypothesised that \"cadaverous particles\" transferred from the autopsy room to labouring women on the unwashed hands of medical staff were responsible for the difference.'' The other options introduce explanations not mentioned in the passage, and option A describes the rival miasma theory that Semmelweis was challenging.","difficulty":"normal","format":"mc","answer":"That ''cadaverous particles'' transferred from the autopsy room on the unwashed hands of medical staff were responsible","options":["That miasmas — contaminated air from the autopsy room — drifted into the obstetric ward and infected patients","That overcrowding in the First Division reduced ventilation and increased patient susceptibility to fever","That ''cadaverous particles'' transferred from the autopsy room on the unwashed hands of medical staff were responsible","That the midwives in the Second Division used herbal treatments that incidentally protected against infection"],"contentHash":"acf2a77e49520948dac030acc8e54bd12279da88e06871bce20cf2d1696d8314"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:bbe5c80a-ff10-4ed5-ae32-6cba55b518cd', 'vr', 'timed', 'bbe5c80a-ff10-4ed5-ae32-6cba55b518cd'::uuid, 'vr.explicit_information', '{"id":"bbe5c80a-ff10-4ed5-ae32-6cba55b518cd","mode":"timed","parentId":"512968ac-3520-49ee-a9aa-036dc3aaafa2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''following the death of his friend Jakob Kolletschka from a similar illness after a scalpel wound during an autopsy, Semmelweis introduced a requirement for all medical staff to wash their hands with chlorinated lime solution.'' The other options introduce triggers not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"The death of his friend Jakob Kolletschka from a similar illness after a scalpel wound during an autopsy","options":["A ward-wide outbreak of puerperal fever that killed twelve mothers in a single week","A visit from the French physician Louis Pasteur, who shared his early findings on bacterial contamination","A directive from the hospital director requiring all staff to adopt new hygiene protocols","The death of his friend Jakob Kolletschka from a similar illness after a scalpel wound during an autopsy"],"contentHash":"6b51ed477afe6f944651aabcfa211141af8042dda40a8fc11d1a16c4d2ee0e34"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:9cd8c969-8a38-4aa4-91f8-52058be92418', 'vr', 'timed', '9cd8c969-8a38-4aa4-91f8-52058be92418'::uuid, 'vr.explicit_information', '{"id":"9cd8c969-8a38-4aa4-91f8-52058be92418","mode":"timed","parentId":"512968ac-3520-49ee-a9aa-036dc3aaafa2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''The mortality rate in the First Division fell dramatically to below 2 percent.'' The other options misstate the outcome described in the passage.","difficulty":"normal","format":"mc","answer":"It fell dramatically to below 2 percent","options":["It fell dramatically to below 2 percent","It fell to approximately the same level as the Second Division — around 4 percent","It fell modestly at first but returned to previous levels within six months","It remained unchanged, as most doctors refused to comply with the new requirement"],"contentHash":"f2e978df48bb8e5ad6ac31c517cfe035e2e3358714e6f32edc2a6173d9630973"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:9cc95659-fb43-4ca1-b317-276fecb923bb', 'vr', 'timed', '9cc95659-fb43-4ca1-b317-276fecb923bb'::uuid, 'vr.explicit_information', '{"id":"9cc95659-fb43-4ca1-b317-276fecb923bb","mode":"timed","parentId":"512968ac-3520-49ee-a9aa-036dc3aaafa2","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states his ideas ''contradicted the prevailing miasma theory of disease...and implied that physicians themselves were responsible for their patients'' deaths, a suggestion many found professionally offensive.'' The other options introduce reasons not stated in the passage.","difficulty":"hard","format":"mc","answer":"Because his findings contradicted the prevailing miasma theory of disease and implied physicians were responsible for patient deaths","options":["Because his sample size was too small to be statistically convincing and his intervention had not been tested in other hospitals","Because his findings contradicted the prevailing miasma theory of disease and implied physicians were responsible for patient deaths","Because his chlorinated lime solution was prohibitively expensive and difficult to obtain in sufficient quantities","Because he refused to submit his findings to peer review and insisted on implementing the protocol unilaterally"],"contentHash":"4d051dbacf26fb50377547dfa160a1cbe974d95061557dbcf41d18405c5c69f8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:4adb4d67-f49b-44bd-94fd-3bc1e97783dc', 'vr', 'timed', '4adb4d67-f49b-44bd-94fd-3bc1e97783dc'::uuid, 'vr.explicit_information', '{"id":"4adb4d67-f49b-44bd-94fd-3bc1e97783dc","mode":"timed","parentId":"5cb386ef-604a-43d2-91f4-5234dd952594","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states mangrove adaptations ''include specialised root structures that provide structural support in unstable sediments and facilitate gas exchange when the roots are submerged, and physiological mechanisms for excluding or excreting salt.'' The correct option directly paraphrases both categories of adaptation.","difficulty":"normal","format":"mc","answer":"Specialised root structures for support and gas exchange, and physiological mechanisms for managing salt","options":["Specialised root structures for support and gas exchange, and physiological mechanisms for managing salt","Deep root systems that anchor trees against tidal currents and thick bark that repels saltwater","Seasonal leaf shedding that reduces water loss during periods of extreme salinity","Symbiotic relationships with saltwater bacteria that neutralise toxic compounds in the sediment"],"contentHash":"687a16d2bb8b135173a0ab618e2191104767c5be869bb85dd78cede6f73ddb71"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0f78b647-1373-4a49-9e02-55489e427cfd', 'vr', 'timed', '0f78b647-1373-4a49-9e02-55489e427cfd'::uuid, 'vr.explicit_information', '{"id":"0f78b647-1373-4a49-9e02-55489e427cfd","mode":"timed","parentId":"5cb386ef-604a-43d2-91f4-5234dd952594","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''When mangroves are cleared, this stored carbon is rapidly released into the atmosphere, making mangrove destruction a significant source of greenhouse gas emissions.'' The carbon comes from ''their biomass and especially in the organic-rich sediments beneath them'' which ''accumulate over centuries.'' The correct option captures both the source and the timescale.","difficulty":"hard","format":"mc","answer":"Because clearing mangroves releases centuries of stored carbon from their biomass and especially from the sediments beneath them","options":["Because decomposing mangrove wood releases methane at a rate higher than any other forest type","Because mangrove destruction eliminates trees that would otherwise absorb large quantities of atmospheric carbon dioxide","Because clearing mangroves releases centuries of stored carbon from their biomass and especially from the sediments beneath them","Because mangrove fires produce black carbon particles that absorb solar radiation and accelerate warming"],"contentHash":"f367d9c1465961c7b3823ed931926fd0258d13b0e9ae79c008bbabcc08b8cc9c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:9adf7edf-0642-402d-800d-347cce9a8eb3', 'vr', 'timed', '9adf7edf-0642-402d-800d-347cce9a8eb3'::uuid, 'vr.explicit_information', '{"id":"9adf7edf-0642-402d-800d-347cce9a8eb3","mode":"timed","parentId":"5cb386ef-604a-43d2-91f4-5234dd952594","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Between 1980 and 2005, an estimated 20 percent of the world''s mangrove area was lost.'' The other options misstate the figure given.","difficulty":"normal","format":"mc","answer":"Approximately 20 percent","options":["Approximately 10 percent","Approximately 20 percent","Approximately 35 percent","Approximately 50 percent"],"contentHash":"c2d659c67633088aabc05f6415d57139c17fda9ff8b0ef7eaaddb3f48aeed3ec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:04d30d7e-4413-4b1f-9eaf-a62b04b928ec', 'vr', 'timed', '04d30d7e-4413-4b1f-9eaf-a62b04b928ec'::uuid, 'vr.explicit_information', '{"id":"04d30d7e-4413-4b1f-9eaf-a62b04b928ec","mode":"timed","parentId":"5cb386ef-604a-43d2-91f4-5234dd952594","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states conservation efforts have ''accelerated in recent decades, driven in part by growing recognition of mangroves'' role in climate regulation and coastal protection against storm surge and erosion.'' The correct option directly paraphrases this.","difficulty":"normal","format":"mc","answer":"Growing recognition of mangroves'' role in climate regulation and coastal protection against storm surge and erosion","options":["Declining fish stocks in offshore waters that have made the nursery function of mangroves economically critical","Advances in satellite monitoring that have made it easier to detect and penalise illegal mangrove clearance","New international treaties requiring coastal nations to maintain minimum mangrove coverage as a condition of trade agreements","Growing recognition of mangroves'' role in climate regulation and coastal protection against storm surge and erosion"],"contentHash":"688eb08ae8cd0b66414075b831c51535d47db34de3ed223bf6ecf624385b4afc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7c5d9b74-d523-434a-8093-e94e7c840dde', 'vr', 'timed', '7c5d9b74-d523-434a-8093-e94e7c840dde'::uuid, 'vr.explicit_information', '{"id":"7c5d9b74-d523-434a-8093-e94e7c840dde","mode":"timed","parentId":"abba18ee-028d-45b0-ac75-4e4db4092883","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the epidemic ''reach[ed] Europe from Central Asia via trading routes, arriving first in Sicily in October 1347 through infected rats on Genoese trading ships.'' The other options contradict or misrepresent this account.","difficulty":"normal","format":"mc","answer":"It arrived in Sicily in October 1347 on Genoese trading ships carrying infected rats","options":["It spread overland from Central Asia along trade routes used by Mongol armies","It spread northward from sub-Saharan Africa along established caravan trading routes","It was carried to Mediterranean ports by returning Crusader soldiers from the Holy Land","It arrived in Sicily in October 1347 on Genoese trading ships carrying infected rats"],"contentHash":"58ee75985c90af48b229997d2b5db3387d46807087dcfb414aa91d3c047601eb"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c02aa1ef-a370-4f22-992c-4e0b77ad4836', 'vr', 'timed', 'c02aa1ef-a370-4f22-992c-4e0b77ad4836'::uuid, 'vr.explicit_information', '{"id":"c02aa1ef-a370-4f22-992c-4e0b77ad4836","mode":"timed","parentId":"abba18ee-028d-45b0-ac75-4e4db4092883","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Surviving peasants found themselves in considerably stronger bargaining positions relative to landowners, since competition for agricultural labour drove wages upward and weakened the coercive power of the feudal system.'' The correct option directly paraphrases this.","difficulty":"hard","format":"mc","answer":"Labour shortages strengthened peasants'' bargaining position and drove wages upward, weakening the feudal system","options":["Landowners were forced to sell their estates as agricultural revenue collapsed, enabling peasants to acquire land cheaply","Labour shortages strengthened peasants'' bargaining position and drove wages upward, weakening the feudal system","Peasants moved to cities in large numbers, creating an urban labour surplus that depressed wages across all sectors","Landowners responded by mechanising agricultural production, reducing their long-term dependence on peasant labour"],"contentHash":"79c385ffd59fe7d8958467d065fbff5d7ddecb7afc64fcbecd6a2e646be00585"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:249f836d-fdde-41c6-a656-ec67d23d3167', 'vr', 'timed', '249f836d-fdde-41c6-a656-ec67d23d3167'::uuid, 'vr.explicit_information', '{"id":"249f836d-fdde-41c6-a656-ec67d23d3167","mode":"timed","parentId":"abba18ee-028d-45b0-ac75-4e4db4092883","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''attempts by Parliament to fix wages at pre-plague levels through the Statute of Labourers (1351)'' — identifying wage-fixing as the statute''s purpose in response to the labour market changes following the plague.","difficulty":"normal","format":"mc","answer":"To fix wages at pre-plague levels in response to the wage increases that followed the labour shortage","options":["To fix wages at pre-plague levels in response to the wage increases that followed the labour shortage","To regulate the working conditions of agricultural labourers by limiting the number of hours they could be required to work","To require all surviving agricultural workers to remain on the estates where they had worked before the plague","To provide compensation to landowners whose workforce had been devastated by the Black Death"],"contentHash":"b6be6c33a014bc1077520ff67462fe2d81fdb7060fded40abd9720455fd805ec"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:cc58aecb-243c-472f-a0fd-3ccef0a47570', 'vr', 'timed', 'cc58aecb-243c-472f-a0fd-3ccef0a47570'::uuid, 'vr.explicit_information', '{"id":"cc58aecb-243c-472f-a0fd-3ccef0a47570","mode":"timed","parentId":"abba18ee-028d-45b0-ac75-4e4db4092883","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The Church suffered reputational damage because the clergy, who tended to the sick, died in large numbers and because the Church''s prayers and sacraments appeared powerless against the epidemic.'' The correct option combines both reasons given.","difficulty":"normal","format":"mc","answer":"Because clergy died in large numbers tending the sick, and the Church''s prayers appeared powerless against the epidemic","options":["Because senior Church officials fled cities at the outbreak of plague, abandoning their congregations","Because the Church initially denied that the plague was occurring, contradicting observable evidence","Because clergy died in large numbers tending the sick, and the Church''s prayers appeared powerless against the epidemic","Because the Church was blamed for importing the disease from the Holy Land through pilgrim routes"],"contentHash":"e9e3cdd148522f29d95377e9fa263753719e309d29205be9ff5bd79b200133b0"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f3eaf006-a71f-4af1-9db4-c285347d39e3', 'vr', 'timed', 'f3eaf006-a71f-4af1-9db4-c285347d39e3'::uuid, 'vr.explicit_information', '{"id":"f3eaf006-a71f-4af1-9db4-c285347d39e3","mode":"timed","parentId":"4844115d-5fad-4922-b679-2885d924dfdd","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''On Earth, this effect arises from the planet''s rotation: an object moving freely above the surface is deflected to the right in the Northern Hemisphere and to the left in the Southern Hemisphere.'' The correct option directly paraphrases this.","difficulty":"normal","format":"mc","answer":"The planet''s rotation, which deflects freely moving objects to the right in the Northern Hemisphere and left in the Southern","options":["The planet''s rotation, which deflects freely moving objects to the right in the Northern Hemisphere and left in the Southern","The gravitational pull of the Moon, which deflects moving air and water masses as they cross the equator","The temperature difference between the poles and the equator, which creates rotational pressure gradients in the atmosphere","The friction between atmospheric layers at different altitudes, which imparts a rotational component to wind movement"],"contentHash":"c3b9e07dd1af68b4ff3efaba04c3d69606df144ea26a913d43044075065990be"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e0cdd0f2-0907-46e6-bea6-468ba712ef25', 'vr', 'timed', 'e0cdd0f2-0907-46e6-bea6-468ba712ef25'::uuid, 'vr.explicit_information', '{"id":"e0cdd0f2-0907-46e6-bea6-468ba712ef25","mode":"timed","parentId":"4844115d-5fad-4922-b679-2885d924dfdd","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The Coriolis force on the scale of a household sink is many orders of magnitude weaker than the effects of how the water was poured into the basin, residual currents, and the positioning of the drain.'' The correct option accurately lists the factors the passage identifies.","difficulty":"normal","format":"mc","answer":"Because the Coriolis force on the scale of a sink is many orders of magnitude weaker than factors such as the initial motion of the water, basin shape, and drain positioning","options":["Because water moves too slowly in a sink for the Coriolis force to deflect it before it exits through the drain","Because the Coriolis effect only operates on gases and not on liquids such as water","Because the Coriolis force on the scale of a sink is many orders of magnitude weaker than factors such as the initial motion of the water, basin shape, and drain positioning","Because household plumbing systems create artificial pressure gradients that overwhelm any Coriolis deflection"],"contentHash":"8b943c497dbc1dbdf2b00c97428d45dffcfa954b78190e4e0a60e873e62d5f62"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ebe8da9e-4efb-48ba-936f-d297daa9144f', 'vr', 'timed', 'ebe8da9e-4efb-48ba-936f-d297daa9144f'::uuid, 'vr.explicit_information', '{"id":"ebe8da9e-4efb-48ba-936f-d297daa9144f","mode":"timed","parentId":"4844115d-5fad-4922-b679-2885d924dfdd","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''the Coriolis effect influences the trajectory of long-range artillery shells and intercontinental ballistic missiles and must be factored into navigation and gunnery calculations for long-distance precision.'' The other options introduce applications not mentioned in the passage.","difficulty":"normal","format":"mc","answer":"In gunnery calculations for long-range artillery and in navigation of intercontinental ballistic missiles","options":["In the calibration of weather satellites and in the routing of commercial aircraft over polar regions","In the timing of rocket launches to ensure spacecraft achieve the correct orbital trajectory","In the design of naval vessels operating in high-latitude regions where the effect is strongest","In gunnery calculations for long-range artillery and in navigation of intercontinental ballistic missiles"],"contentHash":"65d174f0e7fc75b7f3c15dec749c8432e3f57f482d4b72af34f6d4af6b8ebb1a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2ffe24a6-3f3f-4986-b1a7-7b5bb5063ac2', 'vr', 'timed', '2ffe24a6-3f3f-4986-b1a7-7b5bb5063ac2'::uuid, 'vr.author_perspective', '{"id":"2ffe24a6-3f3f-4986-b1a7-7b5bb5063ac2","mode":"timed","parentId":"4844115d-5fad-4922-b679-2885d924dfdd","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''This is scientifically inaccurate'' and explains the Coriolis force at sink scale is ''many orders of magnitude weaker'' than other factors.","difficulty":"hard","format":"mc","answer":"The passage identifies the belief as scientifically inaccurate and explains why the Coriolis effect is too weak to determine sink drainage direction","options":["The passage confirms the belief is scientifically accurate but notes it is only observable in large bodies of water rather than small ones","The passage identifies the belief as scientifically inaccurate and explains why the Coriolis effect is too weak to determine sink drainage direction","The passage presents the belief as plausible and notes that laboratory experiments have confirmed it under normal household conditions","The passage is neutral on the belief, noting that evidence is mixed and further research is required"],"contentHash":"dd21cb01119958e336b72c7b328fb831490c45b683ea4b573e7595b7f00e3681"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ef01cd81-3da9-41b3-bd25-681edb0e1a64', 'vr', 'timed', 'ef01cd81-3da9-41b3-bd25-681edb0e1a64'::uuid, 'vr.unsupported_claims', '{"id":"ef01cd81-3da9-41b3-bd25-681edb0e1a64","mode":"timed","parentId":"b1bf87bc-9522-4d2b-ac87-2359d1b0abf7","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage discusses the debate about automation''s employment effects and notes that ''Modern automation displaces labour across a broader range of cognitive as well as physical tasks.'' However, it does not provide specific data on whether manufacturing employment has already experienced a net reduction in developed countries.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"3c9c460746f6f10abc8b266f44f8ada1176c972a1997cf35747674d157b0e4aa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6c2a2923-6ca4-4f24-b85b-3715e94602d6', 'vr', 'timed', '6c2a2923-6ca4-4f24-b85b-3715e94602d6'::uuid, 'vr.author_perspective', '{"id":"6c2a2923-6ca4-4f24-b85b-3715e94602d6","mode":"timed","parentId":"b1bf87bc-9522-4d2b-ac87-2359d1b0abf7","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states that on Acemoglu and Restrepo''s view, ''productivity gains from automation have increasingly accrued to capital owners rather than workers.'' This is the opposite of the statement''s claim — the passage attributes the gains to capital owners, not workers.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"264bc6cadca78dfa2dd0ecfe705d8c7693cb9519e5c76074688f7dc6e71e5744"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:85bb025b-8441-4e92-ae3c-f49514b6309d', 'vr', 'timed', '85bb025b-8441-4e92-ae3c-f49514b6309d'::uuid, 'vr.explicit_information', '{"id":"85bb025b-8441-4e92-ae3c-f49514b6309d","mode":"timed","parentId":"b1bf87bc-9522-4d2b-ac87-2359d1b0abf7","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Modern automation displaces labour across a broader range of cognitive as well as physical tasks'' — explicitly identifying this as a feature that distinguishes the current wave from earlier episodes.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"00ef89f39bccb8ed224a812cd99882a4653d5eca4e288a0f30bd0f08d9414874"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:51956905-d4b6-4b98-96a3-5432359667b0', 'vr', 'timed', '51956905-d4b6-4b98-96a3-5432359667b0'::uuid, 'vr.author_perspective', '{"id":"51956905-d4b6-4b98-96a3-5432359667b0","mode":"timed","parentId":"b1bf87bc-9522-4d2b-ac87-2359d1b0abf7","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Both perspectives agree that the pace of workforce adaptation matters'' and that rapid transitions mean ''costs fall disproportionately on older workers and those in regions most exposed to automation.'' Both sides'' agreement on pace/speed is explicitly stated, confirming the statement.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"fd932f71a77688f7b53acbaad49adf401530ff8673c701cf98a2b61a39e24723"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:4d24c10b-7cf9-4098-8704-199a8a54449b', 'vr', 'timed', '4d24c10b-7cf9-4098-8704-199a8a54449b'::uuid, 'vr.inference', '{"id":"4d24c10b-7cf9-4098-8704-199a8a54449b","mode":"timed","parentId":"90dd2d38-da4b-43a8-9a41-9e35838447e9","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Fibonacci introduced the sequence ''in his 1202 work Liber Abaci.'' 1202 CE falls within the thirteenth century (1201–1300 CE), confirming the statement is True.","difficulty":"hard","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"11c30de779d12d0982eb4b8f4d8e01014b5ad0f99a7037dc766e61cb55ff6cf3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fd53cf75-f391-4fb6-8455-c8c2379457e4', 'vr', 'timed', 'fd53cf75-f391-4fb6-8455-c8c2379457e4'::uuid, 'vr.recognising_contradictions', '{"id":"fd53cf75-f391-4fb6-8455-c8c2379457e4","mode":"timed","parentId":"90dd2d38-da4b-43a8-9a41-9e35838447e9","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the sequence ''had in fact been described centuries earlier by Indian mathematicians in the context of Sanskrit prosody.'' This directly contradicts the claim that European mathematicians described it first — Indian scholars did so centuries before Fibonacci.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"2807718b08fe5d0a2410c08906498acad8e13a792b8cb4e721e043d095f99b47"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c76c75f1-8422-45de-9816-1898279c8f75', 'vr', 'timed', 'c76c75f1-8422-45de-9816-1898279c8f75'::uuid, 'vr.explicit_information', '{"id":"c76c75f1-8422-45de-9816-1898279c8f75","mode":"timed","parentId":"90dd2d38-da4b-43a8-9a41-9e35838447e9","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states the divergence angle of approximately 137.5 degrees ''is directly derived from the golden ratio.'' This explicitly establishes a mathematical relationship between the divergence angle and the golden ratio.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"e40a8c88abd0685a3ca53e69ef4aabeda2402f405cc99430f0ef6fbfadb79a49"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f6eccde8-62c2-4f15-b344-3c371b7f1f7f', 'vr', 'timed', 'f6eccde8-62c2-4f15-b344-3c371b7f1f7f'::uuid, 'vr.evaluating_evidence', '{"id":"f6eccde8-62c2-4f15-b344-3c371b7f1f7f","mode":"timed","parentId":"90dd2d38-da4b-43a8-9a41-9e35838447e9","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":["vr.unsupported_claims"],"confidence":"medium","rationale":"The passage lists ''the chambered structure of a nautilus shell'' among examples that ''have all been cited as examples of Fibonacci numbers or the closely related golden ratio appearing in nature.'' However, the passage only says the nautilus has been cited as an example — it does not confirm or deny whether the shell follows an exact Fibonacci spiral.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"a9841d4297846c4737d6b78e50ab51310f02762eb76858b5d2c9225a00737417"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a3aa816b-ce9d-4579-9840-b064a118fa53', 'vr', 'timed', 'a3aa816b-ce9d-4579-9840-b064a118fa53'::uuid, 'vr.explicit_information', '{"id":"a3aa816b-ce9d-4579-9840-b064a118fa53","mode":"timed","parentId":"dd6e67c7-4f1b-4160-b068-3a58409d9aae","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''by 1582 the spring equinox was falling about 10 days earlier than the calendar indicated'' and that this had ''practical consequences for the Church, because the date of Easter — calculated relative to the spring equinox — was shifting away from its intended astronomical anchor.'' The correct option combines both elements.","difficulty":"hard","format":"mc","answer":"The spring equinox was falling approximately 10 days earlier than the calendar indicated, causing Easter to shift from its intended astronomical anchor","options":["The Julian calendar had accumulated so many errors that the new year was being celebrated in different seasons across different regions of Europe","Discrepancies between the Julian calendar and the Islamic lunar calendar were causing diplomatic confusion in trade negotiations","The Julian calendar''s leap year rule was causing the calendar to run faster than the solar year, making it impossible to predict harvests","The spring equinox was falling approximately 10 days earlier than the calendar indicated, causing Easter to shift from its intended astronomical anchor"],"contentHash":"bb314712451ff1068766f1b89ba1c310156b3c4b98b7d37e32b6a2d6daffd553"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:83206a78-1f9c-47ee-a202-1b75ae0c11bd', 'vr', 'timed', '83206a78-1f9c-47ee-a202-1b75ae0c11bd'::uuid, 'vr.explicit_information', '{"id":"83206a78-1f9c-47ee-a202-1b75ae0c11bd","mode":"timed","parentId":"dd6e67c7-4f1b-4160-b068-3a58409d9aae","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''century years — 1700, 1800, 1900 — are not leap years unless divisible by 400, meaning 2000 was a leap year but 1900 was not.'' The correct option directly paraphrases this rule with the same examples.","difficulty":"normal","format":"mc","answer":"Century years are not leap years unless divisible by 400, meaning 1900 was not a leap year but 2000 was","options":["Leap years now occur every five years instead of every four, reducing the annual overestimation of the solar year","Century years are not leap years unless divisible by 400, meaning 1900 was not a leap year but 2000 was","An extra leap day is added every 128 years to correct for the residual error in the four-year cycle","Leap years are now calculated astronomically each year rather than following a fixed rule"],"contentHash":"7ce45ae89c901ae599de90c5469d55a9afb9f94b03bf7c043ce0c54553e25fa5"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7cff1351-1333-49d8-9899-ee3a6eab9e94', 'vr', 'timed', '7cff1351-1333-49d8-9899-ee3a6eab9e94'::uuid, 'vr.explicit_information', '{"id":"7cff1351-1333-49d8-9899-ee3a6eab9e94","mode":"timed","parentId":"dd6e67c7-4f1b-4160-b068-3a58409d9aae","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''Protestant and Orthodox nations were reluctant to accept a reform initiated by the papacy.'' The other options introduce reasons not given in the passage.","difficulty":"normal","format":"mc","answer":"Because they were reluctant to accept a reform initiated by the papacy","options":["Because they had developed their own calendar systems that they considered more scientifically accurate","Because the reform required dropping days from October, which they feared would cause legal and financial chaos","Because they were reluctant to accept a reform initiated by the papacy","Because their astronomical observations suggested the Julian calendar was accurate and no reform was needed"],"contentHash":"e4108af2aba609cada8506d99259e5c42faafe5bd438a0a8ad2f3acb46e55203"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2a7c88f7-47d7-40a7-8dfb-b0ff8b53e3d9', 'vr', 'timed', '2a7c88f7-47d7-40a7-8dfb-b0ff8b53e3d9'::uuid, 'vr.explicit_information', '{"id":"2a7c88f7-47d7-40a7-8dfb-b0ff8b53e3d9","mode":"timed","parentId":"dd6e67c7-4f1b-4160-b068-3a58409d9aae","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states ''The Gregorian calendar accumulates an error of approximately one day every 3,030 years.'' The other options either contradict this or introduce claims not made in the passage.","difficulty":"normal","format":"mc","answer":"It accumulates an error of approximately one day every 3,030 years","options":["It accumulates an error of approximately one day every 3,030 years","It is perfectly accurate and will never require further adjustment","It accumulates an error of approximately one day per century, which is corrected by the century leap year rule","It is less accurate than the Julian calendar over periods longer than 400 years"],"contentHash":"7880edcee802056ebc80445f6bb5e802630b2fb138a415d8ff00006d3f60da03"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:45307a28-e50b-455b-9931-3d1f5e63f9e3', 'vr', 'timed', '45307a28-e50b-455b-9931-3d1f5e63f9e3'::uuid, 'vr.explicit_information', '{"id":"45307a28-e50b-455b-9931-3d1f5e63f9e3","mode":"timed","parentId":"d3179bc4-9624-4ab1-8aa1-2a4f201d8b3f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the International Military Tribunal ''was conducted by the four Allied powers: the United States, the United Kingdom, France, and the Soviet Union.'' The other options substitute incorrect nations.","difficulty":"normal","format":"mc","answer":"The United States, the United Kingdom, France, and the Soviet Union","options":["The United States, the United Kingdom, France, and Poland","The United States, the United Kingdom, France, and the Soviet Union","The United States, the United Kingdom, the Soviet Union, and China","The United States, France, the Soviet Union, and the Netherlands"],"contentHash":"ef34cfb11435da85eefc54e9f3f2a70179273de01a25ec044a9733e4cae39885"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:61496a45-ce1a-4672-be5c-0acc0cae163e', 'vr', 'timed', '61496a45-ce1a-4672-be5c-0acc0cae163e'::uuid, 'vr.author_perspective', '{"id":"61496a45-ce1a-4672-be5c-0acc0cae163e","mode":"timed","parentId":"d3179bc4-9624-4ab1-8aa1-2a4f201d8b3f","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Defence attorneys argued that the crimes charged — particularly \"crimes against peace\"...had not been established as crimes under international law at the time they were committed,'' invoking the principle of nullum crimen sine lege.","difficulty":"normal","format":"mc","answer":"That crimes against peace had not been established as crimes under international law at the time they were committed","options":["That crimes against peace had not been established as crimes under international law at the time they were committed","That the tribunal lacked jurisdiction because the defendants were civilians, not military personnel","That the defendants had acted under direct orders from Hitler and could not be held individually responsible","That the evidence presented had been obtained through coercive interrogation methods inadmissible under international law"],"contentHash":"9c51e88ed60080f17b044299db0af2a5d5bbaf4d2ebd362f20f071d335d8af25"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:572c7334-7218-4d5e-b14f-2238a7738ef3', 'vr', 'timed', '572c7334-7218-4d5e-b14f-2238a7738ef3'::uuid, 'vr.explicit_information', '{"id":"572c7334-7218-4d5e-b14f-2238a7738ef3","mode":"timed","parentId":"d3179bc4-9624-4ab1-8aa1-2a4f201d8b3f","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly states the Nuremberg Principles ''influenced the drafting of the Genocide Convention (1948) and the Universal Declaration of Human Rights (1948), and later provided the legal foundation for international criminal tribunals in Rwanda and the former Yugoslavia.'' The correct option lists all four developments mentioned.","difficulty":"hard","format":"mc","answer":"The Genocide Convention, the Universal Declaration of Human Rights, and international tribunals for Rwanda and the former Yugoslavia","options":["The establishment of the International Court of Justice and the drafting of the Vienna Convention on Diplomatic Relations","The formation of the United Nations Security Council and the adoption of the UN Charter''s provisions on collective security","The Nuclear Non-Proliferation Treaty and the Geneva Conventions on the treatment of prisoners of war","The Genocide Convention, the Universal Declaration of Human Rights, and international tribunals for Rwanda and the former Yugoslavia"],"contentHash":"77bfe0932f9006ddfb2a7801855f670c32494c07a2d8bc48cd5373f06fd0646d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f977eedd-4222-4681-b904-cb47a0d16da5', 'vr', 'timed', 'f977eedd-4222-4681-b904-cb47a0d16da5'::uuid, 'vr.meaning_in_context', '{"id":"f977eedd-4222-4681-b904-cb47a0d16da5","mode":"timed","parentId":"d3179bc4-9624-4ab1-8aa1-2a4f201d8b3f","primarySkillId":"vr.meaning_in_context","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The defence of superior orders, sometimes called the Nuremberg defence, was explicitly rejected: the fact that a defendant was ordered to commit an act by a superior did not absolve them of criminal responsibility.'' The correct option directly paraphrases both the definition and the tribunal''s ruling.","difficulty":"normal","format":"mc","answer":"The argument that superior orders absolve a defendant of criminal responsibility; the tribunal explicitly rejected this defence","options":["The argument that defendants were acting in self-defence against Soviet aggression; the tribunal accepted this argument for military defendants only","The argument that crimes committed during wartime are exempt from peacetime legal standards; the tribunal partially accepted this argument","The argument that superior orders absolve a defendant of criminal responsibility; the tribunal explicitly rejected this defence","The argument that defendants lacked knowledge of the crimes committed by subordinates; the tribunal found this argument insufficient but mitigating"],"contentHash":"5d633f2dbc71f69d6cfaaf3f703fd4140446d3e9600752d7df2800099c4c166a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:b5c3281e-35e3-4fbc-9588-b5414df2d75c', 'vr', 'timed', 'b5c3281e-35e3-4fbc-9588-b5414df2d75c'::uuid, 'vr.qualifiers_and_scope', '{"id":"b5c3281e-35e3-4fbc-9588-b5414df2d75c","mode":"timed","parentId":"20325d08-a843-4517-9463-bedbc263270b","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states ''some participants genuinely came to doubt their own perceptions; others knew the correct answer but yielded to avoid standing out.'' This shows two distinct reasons for conformity, not a universal genuine perceptual doubt.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"411f785691b5f2e596dc90f0d06e08add921f72200179c2a5f0f90b7fbea5879"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:bd406ed3-97df-4c52-b476-61814f52101d', 'vr', 'timed', 'bd406ed3-97df-4c52-b476-61814f52101d'::uuid, 'vr.inference', '{"id":"bd406ed3-97df-4c52-b476-61814f52101d","mode":"timed","parentId":"20325d08-a843-4517-9463-bedbc263270b","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''approximately 65 percent of participants delivered what they believed to be the maximum shock level of 450 volts.'' 65 percent constitutes a majority.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"2acead639e61451581f62421831aef74b8467efd83c1af9a4e22a647a98eed2e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:46cd095e-7ce9-45bf-9966-bc6d44035d0c', 'vr', 'timed', '46cd095e-7ce9-45bf-9966-bc6d44035d0c'::uuid, 'vr.unsupported_claims', '{"id":"46cd095e-7ce9-45bf-9966-bc6d44035d0c","mode":"timed","parentId":"20325d08-a843-4517-9463-bedbc263270b","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage describes Asch''s experiments as involving ''confederates — actors posing as fellow participants — who had all given the wrong answer,'' but it does not specify how many confederates were used in each trial.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"e6ddf79d85476dfa5223a9fab263d2c4059e9b203cee901cc9248dfb24dc6e1d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:ff29b3dd-8252-4e21-8dff-7e7a3ae70bba', 'vr', 'timed', 'ff29b3dd-8252-4e21-8dff-7e7a3ae70bba'::uuid, 'vr.author_perspective', '{"id":"ff29b3dd-8252-4e21-8dff-7e7a3ae70bba","mode":"timed","parentId":"20325d08-a843-4517-9463-bedbc263270b","primarySkillId":"vr.author_perspective","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage states Milgram concluded that ''ordinary people can be induced to cause serious harm through a combination of situational pressure, incremental commitment, and the diffusion of moral responsibility to an authority figure.'' This attributes obedience to situational factors, explicitly describing subjects as ''ordinary people'' — not as individuals with pre-existing vi…","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"444768cb442a50eccf6f1c053a131fd1a87c4316f4c4865a84ba74c0ab61074f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5adf1dc6-ae5c-467b-ba51-a3d002d8261d', 'vr', 'timed', '5adf1dc6-ae5c-467b-ba51-a3d002d8261d'::uuid, 'vr.explicit_information', '{"id":"5adf1dc6-ae5c-467b-ba51-a3d002d8261d","mode":"timed","parentId":"78081e11-f5fd-4cc2-a3c5-52174898bdc8","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''Because Greek was understood by European scholars, the stone provided the key that eventually unlocked the long-undeciphered Egyptian hieroglyphic writing system.'' The correct option directly paraphrases this.","difficulty":"normal","format":"mc","answer":"Greek was understood by European scholars, giving them a key to the undeciphered Egyptian scripts","options":["Greek was the official administrative language of the Egyptian empire at the time the decree was issued","Greek was understood by European scholars, giving them a key to the undeciphered Egyptian scripts","Greek used an alphabetic system identical to the Latin script familiar to Western archaeologists","Greek had already been used to transliterate Egyptian hieroglyphics in earlier bilingual inscriptions"],"contentHash":"26ec79af0387ab56a1a372e341a51cf1ac30a8fe20ba303d73de565ac71e19fa"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1c61f0ee-33bb-4d88-a687-d0692bf420ad', 'vr', 'timed', '1c61f0ee-33bb-4d88-a687-d0692bf420ad'::uuid, 'vr.explicit_information', '{"id":"1c61f0ee-33bb-4d88-a687-d0692bf420ad","mode":"timed","parentId":"78081e11-f5fd-4cc2-a3c5-52174898bdc8","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Young ''correctly identifying that some hieroglyphic signs were phonetic rather than purely symbolic, and identifying the name of Ptolemy within the cartouche.'' The correct option combines both contributions accurately.","difficulty":"hard","format":"mc","answer":"He identified that some hieroglyphic signs were phonetic and identified the name Ptolemy within a cartouche","options":["He identified that some hieroglyphic signs were phonetic and identified the name Ptolemy within a cartouche","He translated the complete text of the Rosetta Stone decree, establishing hieroglyphics as a logographic script","He proved that hieroglyphics were exclusively phonetic, representing an alphabet similar to Greek","He established the Rosetta Stone as the only artefact capable of providing a complete decipherment key"],"contentHash":"424c1f8290386e9e87be517d4d4aada5d17fa89c8ff52dc5d6461f9fda99567f"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:76ab8d45-8384-4ec0-9f26-30bc7b63dd51', 'vr', 'timed', '76ab8d45-8384-4ec0-9f26-30bc7b63dd51'::uuid, 'vr.author_perspective', '{"id":"76ab8d45-8384-4ec0-9f26-30bc7b63dd51","mode":"timed","parentId":"78081e11-f5fd-4cc2-a3c5-52174898bdc8","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The passage states ''The British Museum has declined these requests, arguing that the museum''s collection represents the shared heritage of humanity and that the stone is better preserved and more accessible in London.'' The correct option directly paraphrases both elements of the stated argument.","difficulty":"normal","format":"mc","answer":"That the museum''s collection represents the shared heritage of humanity and the stone is better preserved and more accessible in London","options":["That Egypt has not submitted a formal legal claim under the terms of any applicable international convention","That the stone was acquired legally under the terms of a military agreement and title has never been legally challenged","That the museum''s collection represents the shared heritage of humanity and the stone is better preserved and more accessible in London","That moving the stone would risk irreparable damage to its inscriptions given its age and fragility"],"contentHash":"d787605d728baca99f8bdd31d743b4b0a249db1f9cf261b119411ac3b2dd1092"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:d89c9035-9950-4815-b368-15ec412a449f', 'vr', 'timed', 'd89c9035-9950-4815-b368-15ec412a449f'::uuid, 'vr.explicit_information', '{"id":"d89c9035-9950-4815-b368-15ec412a449f","mode":"timed","parentId":"78081e11-f5fd-4cc2-a3c5-52174898bdc8","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states Champollion achieved ''the decisive breakthrough in 1822 when he demonstrated that hieroglyphics represented a combination of phonetic and logographic signs, and successfully translated extended passages.'' The cartouche identification is attributed to Young, not Champollion.","difficulty":"hard","format":"mc","answer":"Champollion demonstrated that hieroglyphics represented a combination of phonetic and logographic signs and translated extended passages","options":["Champollion established that the Rosetta Stone decree was identical in all three scripts, confirming it as a translation key","Champollion identified the royal cartouche as a device for enclosing the names of pharaohs","Champollion proved that Demotic script was a simplified form of hieroglyphics rather than a separate writing system","Champollion demonstrated that hieroglyphics represented a combination of phonetic and logographic signs and translated extended passages"],"contentHash":"3243a59fdfc66cee5d4d78acc94c72aefe450adfd69b22a4be0c513ad8b3dd25"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:15414c34-2a63-4d60-bae0-7c0f29fb9244', 'vr', 'timed', '15414c34-2a63-4d60-bae0-7c0f29fb9244'::uuid, 'vr.explicit_information', '{"id":"15414c34-2a63-4d60-bae0-7c0f29fb9244","mode":"timed","parentId":"f7c2e006-a538-4768-a708-fecb9b3288f7","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage links booming to avalanching dry grains.","difficulty":"normal","format":"mc","answer":"A moving layer of dry sand grains","options":["A moving layer of dry sand grains","A stationary wet surface exposed to wind","Any beach sand compressed underfoot","A dune composed of grains of many unrelated sizes"],"contentHash":"ec7525ffb8827ea6e17d209352693cf8de59f3cc92c49f8b6768ecf8034bf414"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:fcaecdde-6865-4b54-b3a4-d4bf72df5547', 'vr', 'timed', 'fcaecdde-6865-4b54-b3a4-d4bf72df5547'::uuid, 'vr.evaluating_evidence', '{"id":"fcaecdde-6865-4b54-b3a4-d4bf72df5547","mode":"timed","parentId":"f7c2e006-a538-4768-a708-fecb9b3288f7","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage contrasts random collisions'' many-frequency hiss with the observed coherent note.","difficulty":"normal","format":"mc","answer":"They would be expected to produce a broad hiss rather than a strong narrow tone","options":["They would be silent at all frequencies","They occur only in wet sand","They cannot happen during an avalanche","They would be expected to produce a broad hiss rather than a strong narrow tone"],"contentHash":"874dfe581397ab31fec082acb5eb613694883142293a75de5420c2da16d91014"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e8b906c8-bf62-4101-9b07-388b2297e1ff', 'vr', 'timed', 'e8b906c8-bf62-4101-9b07-388b2297e1ff'::uuid, 'vr.evaluating_evidence', '{"id":"e8b906c8-bf62-4101-9b07-388b2297e1ff","mode":"timed","parentId":"f7c2e006-a538-4768-a708-fecb9b3288f7","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The laboratory result directly challenges the necessity of a deep resonant body for generation.","difficulty":"hard","format":"mc","answer":"An entire deep dune is not always required for sound generation","options":["Natural dunes contain no subsurface layers","Wind is the only possible trigger of booming","An entire deep dune is not always required for sound generation","Grain synchronisation cannot contribute to the tone"],"contentHash":"ef25f8912afd7cddd6eaeed069eaa33ba0e4d9b299d5e1a05373bea35bf58a98"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:298e480c-c9b0-4ba3-aee7-3bb70d39a94c', 'vr', 'timed', '298e480c-c9b0-4ba3-aee7-3bb70d39a94c'::uuid, 'vr.main_idea_and_purpose', '{"id":"298e480c-c9b0-4ba3-aee7-3bb70d39a94c","mode":"timed","parentId":"f7c2e006-a538-4768-a708-fecb9b3288f7","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The final paragraph separates production of the sound from its loud natural amplification.","difficulty":"normal","format":"mc","answer":"It suggests grain-scale generation and dune-scale amplification may be distinct","options":["It declares both explanations entirely false","It suggests grain-scale generation and dune-scale amplification may be distinct","It claims grain size has no relationship to pitch","It treats beach squeaking and dune booming as identical"],"contentHash":"0628fa77326063efe3e61a338ec1c3925f1427bb40ae76dac5198feef1822164"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0d94d84c-0d0e-4aba-8dce-0ff94bad8e41', 'vr', 'timed', '0d94d84c-0d0e-4aba-8dce-0ff94bad8e41'::uuid, 'vr.explicit_information', '{"id":"0d94d84c-0d0e-4aba-8dce-0ff94bad8e41","mode":"timed","parentId":"ae26e452-56d4-4a70-9d3b-13a6bb54b93b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage identifies a seasonal mismatch between unused winter flow and spring planting needs.","difficulty":"normal","format":"mc","answer":"Water is available in winter but scarce during the spring planting period","options":["Winter streams contain too much salt for crops","Summer glacier melt arrives before fields can absorb it","Villages cannot move water downhill without electric pumps","Water is available in winter but scarce during the spring planting period"],"contentHash":"dd61f6729b3936acdf5d11717249878b3a96f617b952682990ba4da08d4ba9fc"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:aa59b44a-6e24-4425-9b89-219d7ebc8906', 'vr', 'timed', 'aa59b44a-6e24-4425-9b89-219d7ebc8906'::uuid, 'vr.explicit_information', '{"id":"aa59b44a-6e24-4425-9b89-219d7ebc8906","mode":"timed","parentId":"ae26e452-56d4-4a70-9d3b-13a6bb54b93b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly attributes the spray to pressure created by the source being above the village.","difficulty":"normal","format":"mc","answer":"The height difference from the source creates water pressure","options":["The height difference from the source creates water pressure","Freezing droplets expand inside the pipe","A solar-powered motor forces the water upward","Warm air beneath the cone pushes against the stream"],"contentHash":"b2ed63f5adfeb0070c3064f3799cc8230b9902484c1e16d8b70a434ac39ac730"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:55cadb16-a079-4310-adf4-fda2855cb6be', 'vr', 'timed', '55cadb16-a079-4310-adf4-fda2855cb6be'::uuid, 'vr.evaluating_evidence', '{"id":"55cadb16-a079-4310-adf4-fda2855cb6be","mode":"timed","parentId":"ae26e452-56d4-4a70-9d3b-13a6bb54b93b","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The proposed advantage rests on lower exposed area for a given volume, so equal effective exposure would directly challenge it.","difficulty":"hard","format":"mc","answer":"A cone and a shallow sheet of equal ice volume expose the same effective area to melting conditions","options":["Some villages decorate ice stupas with local symbols","A cone and a shallow sheet of equal ice volume expose the same effective area to melting conditions","The feeder stream runs fastest during winter nights","Horizontal reservoirs can also supply irrigation water"],"contentHash":"4ec4b117d3b49e72091628f423b20341fe8fe25ed489b72fd21d23660422b5c3"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a9cb5fd8-2729-4bd9-a4b4-1d4d66678835', 'vr', 'timed', 'a9cb5fd8-2729-4bd9-a4b4-1d4d66678835'::uuid, 'vr.author_perspective', '{"id":"a9cb5fd8-2729-4bd9-a4b4-1d4d66678835","mode":"timed","parentId":"ae26e452-56d4-4a70-9d3b-13a6bb54b93b","primarySkillId":"vr.author_perspective","secondarySkillIds":[],"confidence":"high","rationale":"The final paragraph explicitly frames them as seasonal storage whose results depend on weather, supply and construction.","difficulty":"normal","format":"mc","answer":"They shift existing water across seasons but remain dependent on local conditions","options":["They provide a weather-proof substitute for natural glaciers","They are chiefly monuments whose irrigation role is incidental","They shift existing water across seasons but remain dependent on local conditions","They eliminate the need for a continuing feeder stream"],"contentHash":"9e107d968a3720848c1e86072fc36de7db5760ee93e4a890f1552b7c3d720162"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:572d6c80-4d86-4f77-b76e-68af549663bc', 'vr', 'timed', '572d6c80-4d86-4f77-b76e-68af549663bc'::uuid, 'vr.explicit_information', '{"id":"572d6c80-4d86-4f77-b76e-68af549663bc","mode":"timed","parentId":"4bf9f3e6-f096-4dc0-a5ef-12305730dbc0","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The first paragraph explains inversion through straight-line paths crossing at the aperture.","difficulty":"normal","format":"mc","answer":"Straight-travelling rays from opposite parts of the object cross at the opening","options":["The aperture bends every ray through a curved path","Straight-travelling rays from opposite parts of the object cross at the opening","The dark wall absorbs the upper half of the scene","Diffraction rotates the image after it reaches the screen"],"contentHash":"3c46a63954a357d23cfe6d2b9f87af292200d118b1a5a2829d3003579fdcce9c"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5d2a629d-c0cd-473b-a5ca-a7473481dbc0', 'vr', 'timed', '5d2a629d-c0cd-473b-a5ca-a7473481dbc0'::uuid, 'vr.explicit_information', '{"id":"5d2a629d-c0cd-473b-a5ca-a7473481dbc0","mode":"timed","parentId":"4bf9f3e6-f096-4dc0-a5ef-12305730dbc0","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"A smaller hole restricts ray bundles and can reduce blur, but admits less light.","difficulty":"normal","format":"mc","answer":"The image may become geometrically sharper but dimmer","options":["The image may become geometrically sharper but dimmer","The image becomes brighter but always more blurred","The image is preserved for longer but loses colour","The projection becomes upright but laterally reversed"],"contentHash":"ce82218809bc08ea4ebe99f5582040c2ac72a0e92895f717c627b313d442fc86"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:13c68c4f-81e6-400e-b28f-e415430ade59', 'vr', 'timed', '13c68c4f-81e6-400e-b28f-e415430ade59'::uuid, 'vr.evaluating_evidence', '{"id":"13c68c4f-81e6-400e-b28f-e415430ade59","mode":"timed","parentId":"4bf9f3e6-f096-4dc0-a5ef-12305730dbc0","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The explanation depends on approximately straight-line propagation and selective ray paths, so arbitrary curving would undermine it.","difficulty":"hard","format":"mc","answer":"Light from each object point routinely travels around the aperture in arbitrary curved paths","options":["Artists used portable camera obscuras before photography","Lenses can increase image brightness","Light from each object point routinely travels around the aperture in arbitrary curved paths","Mirrors can alter a projected image''s orientation"],"contentHash":"34a1819ca48919500e91167f36f4ca4275836a67521b67a9393b0f3f8b8f979a"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:d2b8dba4-9dd6-41c2-b2cc-30524d6f1c03', 'vr', 'timed', 'd2b8dba4-9dd6-41c2-b2cc-30524d6f1c03'::uuid, 'vr.explicit_information', '{"id":"d2b8dba4-9dd6-41c2-b2cc-30524d6f1c03","mode":"timed","parentId":"4bf9f3e6-f096-4dc0-a5ef-12305730dbc0","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The final paragraph states this requirement directly.","difficulty":"normal","format":"mc","answer":"A light-sensitive surface and a way to fix the image","options":["A second pinhole to restore the scene''s orientation","A larger room to prevent diffraction","A mirror capable of generating its own light","A light-sensitive surface and a way to fix the image"],"contentHash":"23ad38cf00d437bebebaede9401c42cb7bb8fc0b16063efa0f34663051126462"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:7aa5db75-fe09-424b-9a01-da246ff73296', 'vr', 'timed', '7aa5db75-fe09-424b-9a01-da246ff73296'::uuid, 'vr.qualifiers_and_scope', '{"id":"7aa5db75-fe09-424b-9a01-da246ff73296","mode":"timed","parentId":"960f2165-2e9a-4a6c-8f01-5dd1292982b1","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage says the mixolimnion may circulate vigorously while only the deepest water remains isolated.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"8d51d513d64a2a74f1878cd02b07f49ed8d1b67557b833d3600f41c0ddbea115"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:69f0407d-48e3-4e56-b09b-f940bdfa3b27', 'vr', 'timed', '69f0407d-48e3-4e56-b09b-f940bdfa3b27'::uuid, 'vr.explicit_information', '{"id":"69f0407d-48e3-4e56-b09b-f940bdfa3b27","mode":"timed","parentId":"960f2165-2e9a-4a6c-8f01-5dd1292982b1","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly gives dense salty deep water beneath fresher surface water as one condition preserving separation, so the statement is entailed.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"c3fb35443db2141bb34f28567462192598c3da672102f8b43eac2d8e7652bc02"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
