INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:be71d1d6-19e5-4bf3-9238-55ea0cf9979f', 'vr', 'timed', 'be71d1d6-19e5-4bf3-9238-55ea0cf9979f'::uuid, 'vr.explicit_information', '{"id":"be71d1d6-19e5-4bf3-9238-55ea0cf9979f","mode":"timed","parentId":"960f2165-2e9a-4a6c-8f01-5dd1292982b1","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that atmospheric oxygen is not regularly carried downward and decomposition can consume what remains, leaving the lower layer anoxic.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"99e8e0c3e8edbfc2aa6e88a2be9214f0461fde04c18df681d13a48727dfff65e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
