INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6e3bffd2-f026-4f53-a649-f114eb1092cb', 'vr', 'timed', '6e3bffd2-f026-4f53-a649-f114eb1092cb'::uuid, 'vr.unsupported_claims', '{"id":"6e3bffd2-f026-4f53-a649-f114eb1092cb","mode":"timed","parentId":"22601e12-32ab-4dd1-897a-8c131df04f33","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage says the painting may have been added later and that many makers are unidentified, but it does not establish whether the binder or someone else painted this particular scene.","difficulty":"hard","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"25eb94b0ea6ca92ebc6098cef148f1337785b641192e7f88ec593448f40bb0c9"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:e8ceec88-f7bc-4616-b67f-9d91c858f79c', 'vr', 'timed', 'e8ceec88-f7bc-4616-b67f-9d91c858f79c'::uuid, 'vr.explicit_information', '{"id":"e8ceec88-f7bc-4616-b67f-9d91c858f79c","mode":"timed","parentId":"e39171df-e223-478f-93b3-ecfa86186923","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The first paragraph says fibres hindered cracks, increased toughness and slowed melting.","difficulty":"normal","format":"mc","answer":"It reduced cracking and slowed melting compared with ordinary ice","options":["It allowed the composite to generate its own refrigeration","It made the material lighter than air","It removed the need for insulation and machinery","It reduced cracking and slowed melting compared with ordinary ice"],"contentHash":"836be095ed72ad380103f2789229029c13b2f1b5e3f8d49c6e22d8d6000e7b9b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
