INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6a0f67af-919f-4e8c-a343-d3e0a3c07e8f', 'vr', 'timed', '6a0f67af-919f-4e8c-a343-d3e0a3c07e8f'::uuid, 'vr.qualifiers_and_scope', '{"id":"6a0f67af-919f-4e8c-a343-d3e0a3c07e8f","mode":"timed","parentId":"16c7f4b8-7f9d-4027-80b0-adbde51ae4da","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.unsupported_claims"],"confidence":"medium","rationale":"Tribute is one stated administrative use, but the passage also lists other uses and does not identify the original purpose of every survivor.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"57f82b40ce1c26f1214ad8a9eed5ceb33289273f071ab015dc7fd375c2ed9320"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:990a82b0-7908-442c-b941-2abafcc5d1a2', 'vr', 'timed', '990a82b0-7908-442c-b941-2abafcc5d1a2'::uuid, 'vr.explicit_information', '{"id":"990a82b0-7908-442c-b941-2abafcc5d1a2","mode":"timed","parentId":"8261574a-672e-42fa-a481-89678d76d754","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage says efficient recycling may leave little discarded cullet, so the first option is correct.","difficulty":"normal","format":"mc","answer":"It may leave little discarded cullet for archaeologists to recover","options":["It may leave little discarded cullet for archaeologists to recover","It prevents glassworking waste from surviving underground","It always produces glass with a completely uniform composition","It requires workshops to operate close to primary furnaces"],"contentHash":"4215b15768835acc9a9d8e2e4932b3c9e300112c56b0721485db35eb75e45751"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0bcc0e1e-02f3-4957-b486-b7e09b144833', 'vr', 'timed', '0bcc0e1e-02f3-4957-b486-b7e09b144833'::uuid, 'vr.evaluating_evidence', '{"id":"0bcc0e1e-02f3-4957-b486-b7e09b144833","mode":"timed","parentId":"8261574a-672e-42fa-a481-89678d76d754","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"The passage presents the combined signatures as indirect evidence that separate groups were mixed.","difficulty":"normal","format":"mc","answer":"Two previously distinct colourless glass groups may have been remelted together","options":["The vessel was made in a primary furnace beside a raw-material source","The glassworker deliberately coloured the vessel with both metals","The fragment must have come from the Iulia Felix wreck","Two previously distinct colourless glass groups may have been remelted together"],"contentHash":"dfee386529b34ec4dfc7b521b61649f3a4abc6b7916638e57aae2024580ded22"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6bd86b0a-a290-4fa5-b352-1431aeda6627', 'vr', 'timed', '6bd86b0a-a290-4fa5-b352-1431aeda6627'::uuid, 'vr.evaluating_evidence', '{"id":"6bd86b0a-a290-4fa5-b352-1431aeda6627","mode":"timed","parentId":"8261574a-672e-42fa-a481-89678d76d754","primarySkillId":"vr.evaluating_evidence","secondarySkillIds":[],"confidence":"high","rationale":"Recycling like with like can leave glass chemically uniform, directly weakening the claim.","difficulty":"hard","format":"mc","answer":"Glass of similar composition can be recycled without an obvious mixed signature","options":["Primary glass was transported in large slabs","Some workshops produced drips and failed vessels","Glass of similar composition can be recycled without an obvious mixed signature","Colourless glass could be decolourised with antimony"],"contentHash":"7a24708dafc79a7acc5cdb4d78e7885f0a576976552c60f8ae42be5074a81437"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f7ed7259-cb63-4830-bc1f-7cd8179fb310', 'vr', 'timed', 'f7ed7259-cb63-4830-bc1f-7cd8179fb310'::uuid, 'vr.main_idea_and_purpose', '{"id":"f7ed7259-cb63-4830-bc1f-7cd8179fb310","mode":"timed","parentId":"8261574a-672e-42fa-a481-89678d76d754","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The wreck carried cullet separated by colour and type, so it evidences trade in broken glass.","difficulty":"normal","format":"mc","answer":"To demonstrate direct evidence for commerce in sorted broken glass","options":["To show that raw glass was never traded by sea","To demonstrate direct evidence for commerce in sorted broken glass","To prove that all Roman vessels were recycled several times","To explain how antimony and manganese decolourised glass"],"contentHash":"6a16962be7bd1f2f5d28e372cff46fb9c879207c248225aa082c01d3fd53bf79"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:1c86ee2b-2b65-4601-84fa-fccc0f108b17', 'vr', 'timed', '1c86ee2b-2b65-4601-84fa-fccc0f108b17'::uuid, 'vr.explicit_information', '{"id":"1c86ee2b-2b65-4601-84fa-fccc0f108b17","mode":"timed","parentId":"9c3c6fb4-a905-4607-89f9-4eb22609e8de","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly makes origin in arm webs the contrast with a typical mantle-secreted shell.","difficulty":"normal","format":"mc","answer":"It is made by specialised arm webs rather than mantle tissue","options":["It is made by specialised arm webs rather than mantle tissue","It contains calcium-based material","It has a coiled external form","It can shelter developing eggs"],"contentHash":"694de35671cc20aef0c1a5e2492949051c160380fbdfd9b62efb7d1d938b39d7"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:d9971596-0831-4fc5-ae8c-bda37d46d9f7', 'vr', 'timed', 'd9971596-0831-4fc5-ae8c-bda37d46d9f7'::uuid, 'vr.explicit_information', '{"id":"d9971596-0831-4fc5-ae8c-bda37d46d9f7","mode":"timed","parentId":"9c3c6fb4-a905-4607-89f9-4eb22609e8de","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The second paragraph gives this sequence directly.","difficulty":"normal","format":"mc","answer":"She jets downward until compressed gas can balance her weight","options":["She releases the eggcase and swims beneath it","She divides the gas among sealed internal chambers","She waits for the male to alter the eggcase''s pressure","She jets downward until compressed gas can balance her weight"],"contentHash":"b1ae34ace5364f846529bbee44cbfa7b77c854a515ab398d1788e5774237b663"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:c774a4e4-e7db-4d70-94d3-094dcc8522e3', 'vr', 'timed', 'c774a4e4-e7db-4d70-94d3-094dcc8522e3'::uuid, 'vr.inference', '{"id":"c774a4e4-e7db-4d70-94d3-094dcc8522e3","mode":"timed","parentId":"9c3c6fb4-a905-4607-89f9-4eb22609e8de","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"medium","rationale":"The passage says shallow tanks may return an air-filled animal to the surface before its balance depth.","difficulty":"hard","format":"mc","answer":"The animal may not reach the depth at which pressure compresses the gas sufficiently","options":["The animal may not reach the depth at which pressure compresses the gas sufficiently","Tank water prevents the female from sealing air with her arms","The eggcase dissolves rapidly in confined water","Neutral buoyancy occurs only in fresh water"],"contentHash":"3ebf5502ec893e23d1d3cc5d6325cb4d4c220e6836e1508bafd4b7334afbceea"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:d922e5c2-35a0-46cc-a523-805d6dbd5412', 'vr', 'timed', 'd922e5c2-35a0-46cc-a523-805d6dbd5412'::uuid, 'vr.main_idea_and_purpose', '{"id":"d922e5c2-35a0-46cc-a523-805d6dbd5412","mode":"timed","parentId":"9c3c6fb4-a905-4607-89f9-4eb22609e8de","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The eggcase bears eggs and holds air that the female actively manages, so the third option captures both stated jobs.","difficulty":"normal","format":"mc","answer":"Egg brooding and behavioural control of buoyancy","options":["Camouflage and food storage","Protection from males and propulsion","Egg brooding and behavioural control of buoyancy","Sound production and temperature regulation"],"contentHash":"cf67b536b0e88e97d1002f93e81e4a9ef4c37ee09d4c5e69c9a23aacd366e67d"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:5a9774a6-0642-4b31-bf9a-d460d8617c1e', 'vr', 'timed', '5a9774a6-0642-4b31-bf9a-d460d8617c1e'::uuid, 'vr.recognising_contradictions', '{"id":"5a9774a6-0642-4b31-bf9a-d460d8617c1e","mode":"timed","parentId":"2cb44fa8-2629-4e1f-b38f-62a11e73bc7b","primarySkillId":"vr.recognising_contradictions","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly contrasts attus with beaten barkcloth: inner-bark fibres are separated, made into thread and woven.","difficulty":"normal","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"350452b879a4422a2eb367dc03ca4d1a9818b08d7d67f66fdfe462fbc8285754"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:f9b6257f-3c75-4589-814f-5cf1d77cdf28', 'vr', 'timed', 'f9b6257f-3c75-4589-814f-5cf1d77cdf28'::uuid, 'vr.qualifiers_and_scope', '{"id":"f9b6257f-3c75-4589-814f-5cf1d77cdf28","mode":"timed","parentId":"2cb44fa8-2629-4e1f-b38f-62a11e73bc7b","primarySkillId":"vr.qualifiers_and_scope","secondarySkillIds":["vr.recognising_contradictions"],"confidence":"high","rationale":"The passage says some accounts record men collecting bark, while others describe women doing so, and warns against making a universal rule.","difficulty":"hard","format":"tfc","answer":"False","options":["True","False","Can''t tell"],"contentHash":"9d3ddbc370114ac99612893eaab950df213c7b210d8b2765cc023dd448a1c45e"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6e679390-882e-43c6-af3c-94a2ffaf3eea', 'vr', 'timed', '6e679390-882e-43c6-af3c-94a2ffaf3eea'::uuid, 'vr.explicit_information', '{"id":"6e679390-882e-43c6-af3c-94a2ffaf3eea","mode":"timed","parentId":"2cb44fa8-2629-4e1f-b38f-62a11e73bc7b","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage directly states that attus supplied everyday and ceremonial clothing, so the statement is entailed.","difficulty":"normal","format":"tfc","answer":"True","options":["True","False","Can''t tell"],"contentHash":"308d8424283881c75e996dfc1ec08ce2401e69e9176ccd2e8b3430792ca17dbe"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:2dd2435a-9a52-44a0-9641-f03b35420da8', 'vr', 'timed', '2dd2435a-9a52-44a0-9641-f03b35420da8'::uuid, 'vr.unsupported_claims', '{"id":"2dd2435a-9a52-44a0-9641-f03b35420da8","mode":"timed","parentId":"2cb44fa8-2629-4e1f-b38f-62a11e73bc7b","primarySkillId":"vr.unsupported_claims","secondarySkillIds":[],"confidence":"high","rationale":"The passage says attus is durable and is now used for wallets, but it gives no comparison between the durability of modern wallets and historical robes.","difficulty":"normal","format":"tfc","answer":"Can''t tell","options":["True","False","Can''t tell"],"contentHash":"a578273bea5149495800a5615539e1486e667b2026e5b4d1d66931c9196e8f5b"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:a73c7f28-9d12-4291-8764-92bf536bf359', 'vr', 'timed', 'a73c7f28-9d12-4291-8764-92bf536bf359'::uuid, 'vr.explicit_information', '{"id":"a73c7f28-9d12-4291-8764-92bf536bf359","mode":"timed","parentId":"a0a09e36-4094-4266-bce0-aba5c94787fd","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The passage states that increasing pressure compresses and warms descending air.","difficulty":"normal","format":"mc","answer":"Compression as atmospheric pressure increases","options":["Compression as atmospheric pressure increases","Evaporation caused by falling pressure","Contact with snow on the mountain","Expansion as the air approaches the valley"],"contentHash":"2d0e68b70e8a7c3403178ad14fef81a49242924ffd1ae459f02d501e538d0dae"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:0880cac8-183a-42e9-966f-f0ca6c01e353', 'vr', 'timed', '0880cac8-183a-42e9-966f-f0ca6c01e353'::uuid, 'vr.explicit_information', '{"id":"0880cac8-183a-42e9-966f-f0ca6c01e353","mode":"timed","parentId":"a0a09e36-4094-4266-bce0-aba5c94787fd","primarySkillId":"vr.explicit_information","secondarySkillIds":[],"confidence":"high","rationale":"The first paragraph links latent-heat release and moisture removal to the later warm, dry descent.","difficulty":"normal","format":"mc","answer":"It removes moisture after condensation has released heat","options":["It adds moisture that later freezes on the lee slope","It removes moisture after condensation has released heat","It prevents air from descending the mountain","It makes atmospheric pressure fall in the valley"],"contentHash":"5f595fb96cdab39c03e286e9b556e6425c30457dde6b4d6779d9325e7cc9f718"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:6bece50e-9523-43a5-9261-e4c5d412f89a', 'vr', 'timed', '6bece50e-9523-43a5-9261-e4c5d412f89a'::uuid, 'vr.inference', '{"id":"6bece50e-9523-43a5-9261-e4c5d412f89a","mode":"timed","parentId":"a0a09e36-4094-4266-bce0-aba5c94787fd","primarySkillId":"vr.inference","secondarySkillIds":[],"confidence":"high","rationale":"The passage explicitly offers those mechanisms for dry foehn events.","difficulty":"hard","format":"mc","answer":"Mechanisms such as higher-level draw-down or turbulent mixing may have contributed","options":["The wind cannot have crossed mountainous terrain","The event must have been misclassified","Mechanisms such as higher-level draw-down or turbulent mixing may have contributed","Compression cannot have warmed the descending air"],"contentHash":"2d2aa0337d5ec93df826ffeff5e6a4f246c896d2821a28fc0354e40953263e19"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('vr:timed:46693777-8e3b-495f-ad26-0a797abf6cc4', 'vr', 'timed', '46693777-8e3b-495f-ad26-0a797abf6cc4'::uuid, 'vr.main_idea_and_purpose', '{"id":"46693777-8e3b-495f-ad26-0a797abf6cc4","mode":"timed","parentId":"a0a09e36-4094-4266-bce0-aba5c94787fd","primarySkillId":"vr.main_idea_and_purpose","secondarySkillIds":[],"confidence":"high","rationale":"The passage preserves the classic account while adding dry-foehn mechanisms, so the fourth option captures its qualification.","difficulty":"normal","format":"mc","answer":"The standard rain-and-descent account is useful but does not explain every foehn","options":["Foehn winds are always colder than windward air","Rainfall is irrelevant to every foehn event","No single mechanism has any role in more than one mountain range","The standard rain-and-descent account is useful but does not explain every foehn"],"contentHash":"bcefe2a3aa22114d61fb9e5cd5dc02d9177def1027d921b64fcec43c594ba4c8"}'::jsonb, 1, 'vr-sync-20261013154315') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.syllogisms', 'dm', '{"id":"dm.syllogisms","label":"Quantifiers and syllogisms","description":"Judge what follows from all, some, none and category relationships.","lessonRoute":"LearnDMLesson","lessonId":"syllogisms","tip":"Translate each quantifier precisely and assess each conclusion separately using only the premises."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.conditional_logic', 'dm', '{"id":"dm.conditional_logic","label":"Conditional logic","description":"Distinguish necessary and sufficient conditions, exceptions and valid contrapositives.","lessonRoute":"LearnDMLesson","lessonId":"if-then","tip":"Write the direction of each rule; reversing it is only valid when the question gives both directions."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.constraint_puzzles', 'dm', '{"id":"dm.constraint_puzzles","label":"Constraint puzzles","description":"Combine ordering, matching, allocation and numerical restrictions.","lessonRoute":"LearnDMLesson","lessonId":"logic-puzzles","tip":"Start with the fixed clues, record what each rule excludes, and test every remaining constraint."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.interpreting_information', 'dm', '{"id":"dm.interpreting_information","label":"Interpreting information","description":"Assess numerical and written evidence without adding unsupported causes or predictions.","lessonRoute":"LearnDMLesson","lessonId":"interpreting-info","tip":"Check the relevant figures or wording, then separate a supported conclusion from an assumption."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.evaluating_arguments', 'dm', '{"id":"dm.evaluating_arguments","label":"Evaluating arguments","description":"Compare evidence, relevance, scope and practical impact to identify the strongest argument.","lessonRoute":"LearnDMLesson","lessonId":"strongest-argument","tip":"Keep the proposal and its stated aim in view; compare relevance and strength of evidence, not personal agreement."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.venn_sets', 'dm', '{"id":"dm.venn_sets","label":"Venn diagrams and sets","description":"Interpret inclusive and exclusive regions, set relationships and missing totals.","lessonRoute":"LearnDMLesson","lessonId":"venn-diagrams","tip":"Translate AND, OR and NOT first, then include each relevant exclusive region once."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.probability_rules', 'dm', '{"id":"dm.probability_rules","label":"Probability rules","description":"Calculate combined, independent and complementary events and count equally likely outcomes.","lessonRoute":"LearnDMLesson","lessonId":"probability","tip":"Decide whether to add, multiply or use the complement; count all arrangements that satisfy the event."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.conditional_probability', 'dm', '{"id":"dm.conditional_probability","label":"Conditional probability","description":"Update the sample space for given information, dependent draws and weighted groups.","lessonRoute":"LearnDMLesson","lessonId":"probability","tip":"Define the group being selected from before choosing the denominator; update it after a draw without replacement."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.accuracy_precision', 'dm', '{"id":"dm.accuracy_precision","label":"Accuracy and precision","description":"Distinguish correctness of measurements from consistency of repeated measurements.","lessonRoute":"LearnDMLesson","lessonId":"data-traps","tip":"Compare correct readings for accuracy and repeated agreement for precision; one does not imply the other."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('dm.expected_value', 'dm', '{"id":"dm.expected_value","label":"Expected values","description":"Weight outcomes by their probabilities to estimate average returns or counts.","lessonRoute":"LearnDMLesson","lessonId":"probability","tip":"Multiply each possible outcome by its probability, add the results and account for any fixed cost."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:135b0433-b491-4cec-87ea-c11e7b5e534e', 'dm', 'practice', '135b0433-b491-4cec-87ea-c11e7b5e534e'::uuid, 'dm.evaluating_arguments', '{"id":"135b0433-b491-4cec-87ea-c11e7b5e534e","mode":"practice","parentId":"135b0433-b491-4cec-87ea-c11e7b5e534e","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about 20 mph Residential Limit: Should the UK government introduce a nationwide 20 mph speed limit on all residential streets to reduce child pedestrian injuries?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; drivers already find 30 mph limits too fast in school zones.","Yes; published Transport Research Laboratory data show child pedestrian injury rates fall by 41% on streets where the default limit moves from 30 mph to 20 mph.","No; residents in quiet cul-de-sacs rarely see child pedestrians near traffic.","No; some motorists would resent the change."],"contentHash":"88cf3c172f3ef96a25db8a20eb9171a3ebcafbd5887aabfd3411fb9e34c74333"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:b00575d9-b06d-4b72-af72-0902e39b29f0', 'dm', 'practice', 'b00575d9-b06d-4b72-af72-0902e39b29f0'::uuid, 'dm.accuracy_precision', '{"id":"b00575d9-b06d-4b72-af72-0902e39b29f0","mode":"practice","parentId":"b00575d9-b06d-4b72-af72-0902e39b29f0","primarySkillId":"dm.accuracy_precision","secondarySkillIds":[],"confidence":"high","rationale":"Separates correctness from repeatability in Accuracy vs Precision: Two laboratory pH meters are compared. Meter 1 gives the true pH correctly in 85 out of 100 tests. Meter 2 gives the true pH correctly in 92 out…","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Meter 1 is more accurate but Meter 2 is more precise.","Meter 2 is more accurate but Meter 1 is more precise.","Meter 2 is both more accurate and more precise.","Meter 1 is both more accurate and more precise."],"contentHash":"e22d9a422fe722fc32696ed383f55b1a9a419de383b961ea1375cfaac710a021"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
