INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:c18aacbf-d7fb-4608-8b8e-55541ea335b8', 'dm', 'practice', 'c18aacbf-d7fb-4608-8b8e-55541ea335b8'::uuid, 'dm.evaluating_arguments', '{"id":"c18aacbf-d7fb-4608-8b8e-55541ea335b8","mode":"practice","parentId":"c18aacbf-d7fb-4608-8b8e-55541ea335b8","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Automated Gallery Tours: Should a gallery replace all staffed tours with automated audio tours to reduce operating costs without reducing visitor access?","difficulty":"hard","format":"multiple_choice","answer":"D","options":["Yes; audio devices can use the gallery''s new logo.","Yes; many visitors already own headphones.","No; some guides would miss speaking to visitors.","No; an independent access test found that 27% of participants needing hearing, cognitive or navigation adjustments could not complete the automated route, whereas staff adapted the tour for every participant."],"contentHash":"d4d8a6fb7dda20e5910ed094134edcef58609ec4abafb2f6e0656da8a7799872"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
