INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:add317e5-acdd-4893-9dca-d2d48cd2fb77', 'dm', 'practice', 'add317e5-acdd-4893-9dca-d2d48cd2fb77'::uuid, 'dm.evaluating_arguments', '{"id":"add317e5-acdd-4893-9dca-d2d48cd2fb77","mode":"practice","parentId":"add317e5-acdd-4893-9dca-d2d48cd2fb77","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Compulsory First Aid at Work: Should basic first-aid training be compulsory for all new hires in high-risk industries to reduce workplace fatalities?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; Health and Safety Executive data show workplaces where at least 50% of staff are first-aid trained record 30% fewer on-site fatalities from heart attacks and severe bleeds, so mandatory training in high-risk sectors directly addresses the leading causes of workplace death.","Yes; it would make employees feel more confident and cared for at work.","No; small firms in high-risk industries may struggle with the training costs.","No; first-aid training only covers emergencies, not the prevention of accidents."],"contentHash":"1fd1b064b6311010c2256cdfe9028f3306407c6dc5d5736aa14b42a76c2f29b1"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:6ebed39e-f33b-4233-b0c0-aa4b4c966c37', 'dm', 'practice', '6ebed39e-f33b-4233-b0c0-aa4b4c966c37'::uuid, 'dm.evaluating_arguments', '{"id":"6ebed39e-f33b-4233-b0c0-aa4b4c966c37","mode":"practice","parentId":"6ebed39e-f33b-4233-b0c0-aa4b4c966c37","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Compulsory Modern Languages: Should pupils in English secondary schools be required to study a modern foreign language until age 16 to improve their later employability?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; most European countries already require it, and pupils in those countries tend to be happier in school.","Yes; a 2021 CBI employer survey found 73% of UK firms rate candidates with a second language more highly in hiring, so extending compulsory study to age 16 gives more school leavers this advantage.","No; pupils are already under exam pressure and adding another compulsory subject would worsen stress.","No; many jobs in the UK can be done in English alone."],"contentHash":"b432563237b92a144028f9c0fc4fb217d90e938aec207d33793d3da474305849"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
