INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:3c0dab80-8f10-4336-b9b6-44b5918bf31a', 'dm', 'practice', '3c0dab80-8f10-4336-b9b6-44b5918bf31a'::uuid, 'dm.evaluating_arguments', '{"id":"3c0dab80-8f10-4336-b9b6-44b5918bf31a","mode":"practice","parentId":"3c0dab80-8f10-4336-b9b6-44b5918bf31a","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about E-Scooter Helmet Law: Should helmets be made legally mandatory for adults riding e-scooters to reduce serious head injuries?","difficulty":"normal","format":"multiple_choice","answer":"C","options":["Yes; most commuters support the rule.","No; cyclists are not legally required to wear helmets in the UK, so e-scooter riders should not be either.","Yes; a published hospital-admissions review found that e-scooter riders without helmets were around four times as likely to sustain a serious head injury as those wearing helmets.","No; riders who have to carry a helmet may ride their scooters less often."],"contentHash":"3be93747b38fd0d9b494300482461f8f49c94bced1039d605a874990aa3609b6"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:d2b525f5-15cf-4989-b8d4-c653cdecf2b5', 'dm', 'practice', 'd2b525f5-15cf-4989-b8d4-c653cdecf2b5'::uuid, 'dm.evaluating_arguments', '{"id":"d2b525f5-15cf-4989-b8d4-c653cdecf2b5","mode":"practice","parentId":"d2b525f5-15cf-4989-b8d4-c653cdecf2b5","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about E-Scooter Pavement Ban: Should e-scooters be banned from city centre pavements to improve pedestrian safety?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; transport authority data from five UK cities showed pedestrian injuries fell by 42% after pavement e-scooter bans, directly improving pedestrian safety.","Yes; many pedestrians report feeling uncomfortable sharing pavements with e-scooters.","No; e-scooter riders need somewhere safe to travel, and pavements are often the safest option.","No; pavement cyclists cause similar safety problems, so banning only e-scooters would not fix the wider issue."],"contentHash":"e6015dab8a919695d719c8dccc89300b517afaa02c3728fb65911263e117f3bd"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
