INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:05de0870-8885-4569-9ee5-80fa7551d8b7', 'dm', 'practice', '05de0870-8885-4569-9ee5-80fa7551d8b7'::uuid, 'dm.evaluating_arguments', '{"id":"05de0870-8885-4569-9ee5-80fa7551d8b7","mode":"practice","parentId":"05de0870-8885-4569-9ee5-80fa7551d8b7","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Four-Day School Week: Should secondary schools introduce a four-day school week to improve student well-being?","difficulty":"hard","format":"multiple_choice","answer":"A","options":["Yes; trials in two Scottish secondary schools reported student-reported anxiety scores fell 18 per cent after a four-day week was introduced, with no change in academic results.","Yes; teachers will benefit from having an extra day off each week.","No; parents with full-time jobs may struggle to arrange childcare for the extra day.","No; students already have long summer breaks, so adding another day off is unnecessary."],"contentHash":"012d4cf41ad4d7ff927931c3c677ca594d0108059c04a07faedeb0fd2717a630"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
