INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:f8761f71-79c0-4a27-8bb4-7e5ddad0e3fa', 'dm', 'practice', 'f8761f71-79c0-4a27-8bb4-7e5ddad0e3fa'::uuid, 'dm.evaluating_arguments', '{"id":"f8761f71-79c0-4a27-8bb4-7e5ddad0e3fa","mode":"practice","parentId":"f8761f71-79c0-4a27-8bb4-7e5ddad0e3fa","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Four-day Working Week: Should companies be required to offer all employees a four-day working week to improve employee mental health?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; many employees would welcome more time off.","Yes; a 2023 Icelandic trial reported a 33% reduction in burnout symptoms among staff switched to a four-day week, with no loss of productivity, directly improving measured mental-health scores.","No; small businesses would struggle to cover the same workload in fewer days.","No; mental-health issues can also be caused by home life, not just working hours."],"contentHash":"164d57782c0d95afcb64a6fa05e35ad57af27fce7fe2eb14f4f7d710816cb23a"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
