INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:e5e539d1-f545-4aac-b6fb-d7ce78aae71e', 'dm', 'practice', 'e5e539d1-f545-4aac-b6fb-d7ce78aae71e'::uuid, 'dm.evaluating_arguments', '{"id":"e5e539d1-f545-4aac-b6fb-d7ce78aae71e","mode":"practice","parentId":"e5e539d1-f545-4aac-b6fb-d7ce78aae71e","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Free Bus Travel for Under-18s: Should free bus travel be introduced for all under-18s in the UK to reduce the number of family car journeys?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; teenagers often don''t have money for bus fares, so paying is a barrier.","Yes; a Department for Transport pilot in Scotland found that offering free bus travel to under-22s cut car-based school runs by around 18%, so a UK-wide scheme is likely to produce a similar reduction.","No; many families live too far from bus routes to benefit.","No; buses emit carbon, so filling them with schoolchildren still pollutes."],"contentHash":"a51d7849b34a8dbaa77d4664daa01df0ae9e8a409aab8396684593a1099aa556"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:738c3cb6-3d20-48af-88ff-99a290edca6a', 'dm', 'practice', '738c3cb6-3d20-48af-88ff-99a290edca6a'::uuid, 'dm.evaluating_arguments', '{"id":"738c3cb6-3d20-48af-88ff-99a290edca6a","mode":"practice","parentId":"738c3cb6-3d20-48af-88ff-99a290edca6a","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Free Gym Memberships for Under-25s: Should the UK government fund free gym memberships for all under-25s to reduce adult obesity rates in later life?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; young people enjoy exercising with peers.","Yes; a 2021 longitudinal study of 18,000 UK young adults found that those averaging at least two gym sessions a week between ages 18 and 24 had a 26% lower obesity rate at age 40.","No; many young adults prefer to exercise outdoors rather than in gyms.","No; the cost of the scheme would take money from other public services."],"contentHash":"965fa0450861a6bd98e13918326a4d663aa13f9e83d162a48e026a4e763c7006"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
