INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:8f4fecdf-4094-4658-8d42-9f4486f147ac', 'dm', 'practice', '8f4fecdf-4094-4658-8d42-9f4486f147ac'::uuid, 'dm.evaluating_arguments', '{"id":"8f4fecdf-4094-4658-8d42-9f4486f147ac","mode":"practice","parentId":"8f4fecdf-4094-4658-8d42-9f4486f147ac","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Live Ferry Occupancy Updates: Should the harbour publish live ferry occupancy estimates to reduce passenger waiting and missed sailings?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; during an eight-week controlled trial, terminals displaying the estimates recorded 24% less average waiting and 19% fewer missed sailings than matched terminals without them.","Yes; digital display boards make a harbour appear modern.","No; some passengers enjoy deciding at the last minute.","No; the harbour timetable already uses blue lettering."],"contentHash":"8606b07d7277acd00b15cdb58ec8eab4c770970495333bb28650fad3d10b2465"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:e8f93408-4b64-4b5a-83ae-bfde0d082900', 'dm', 'practice', 'e8f93408-4b64-4b5a-83ae-bfde0d082900'::uuid, 'dm.evaluating_arguments', '{"id":"e8f93408-4b64-4b5a-83ae-bfde0d082900","mode":"practice","parentId":"e8f93408-4b64-4b5a-83ae-bfde0d082900","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Longer Lunch Break: Should office employees be given a one-hour lunch break, up from thirty minutes, to increase afternoon productivity?","difficulty":"hard","format":"multiple_choice","answer":"A","options":["Yes; a controlled trial at a similar-sized office found afternoon output rose by 8% when employees switched from a 30-minute to a 60-minute lunch break.","Yes; workers who feel rested during the day are happier at work.","No; early finishing times tend to improve afternoon productivity more than longer lunch breaks do.","No; lengthening the lunch break would push the contracted working day out by thirty minutes for every employee."],"contentHash":"b1c2652b4bd9ad58698ed10d66b24c745e78fed10abd479e0b73b195ecf6308e"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:77023809-710f-4817-bc9a-9c7f1995b958', 'dm', 'practice', '77023809-710f-4817-bc9a-9c7f1995b958'::uuid, 'dm.evaluating_arguments', '{"id":"77023809-710f-4817-bc9a-9c7f1995b958","mode":"practice","parentId":"77023809-710f-4817-bc9a-9c7f1995b958","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Loud Fireworks Ban: Should the UK ban the retail sale of loud (above 80 dB) fireworks to the general public to reduce noise-related distress among pets and farm animals?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; a government-commissioned RSPCA report found that bans on loud retail fireworks in three comparable European countries reduced recorded pet distress incidents on fireworks nights by around 70%.","Yes; fireworks are dangerous and many people injure themselves with them each year.","No; large professional displays would still produce enough noise to cause animal distress.","No; fireworks are an important part of British cultural celebrations."],"contentHash":"94ce592cd130b471ef64cbfc7b50e69fbb20669fa3c3601baea6424720448635"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:1eba2b9f-9da3-4a96-8c96-cc95985ad8ae', 'dm', 'practice', '1eba2b9f-9da3-4a96-8c96-cc95985ad8ae'::uuid, 'dm.interpreting_information', '{"id":"1eba2b9f-9da3-4a96-8c96-cc95985ad8ae","mode":"practice","parentId":"1eba2b9f-9da3-4a96-8c96-cc95985ad8ae","primarySkillId":"dm.interpreting_information","secondarySkillIds":[],"confidence":"high","rationale":"Checks conclusions against the supplied evidence in Low-Traffic Neighbourhoods: A city council reports that since low-traffic neighbourhoods (LTNs) were introduced in 2021, air-pollution measurements on affected streets have…","difficulty":"normal","format":"yes_no_statements","answer":"[object Object]","statementAnswers":["Yes","No","No","Yes","No"],"contentHash":"02517d0eecec335b14b13337130be6d2f789ae9ae08f45251888b866daa4babb"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:1eef2cc5-e0d2-4f6d-9b11-d3d9833cf081', 'dm', 'practice', '1eef2cc5-e0d2-4f6d-9b11-d3d9833cf081'::uuid, 'dm.accuracy_precision', '{"id":"1eef2cc5-e0d2-4f6d-9b11-d3d9833cf081","mode":"practice","parentId":"1eef2cc5-e0d2-4f6d-9b11-d3d9833cf081","primarySkillId":"dm.accuracy_precision","secondarySkillIds":[],"confidence":"high","rationale":"Separates correctness from repeatability in Luggage Scanner Comparison: Two luggage scanners are tested at an airport. When a scanner is shown a bag containing a prohibited item, Scanner X correctly flags it 91 times…","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Scanner X is both more accurate and more precise.","Scanner X is more accurate but Scanner Y is more precise.","Scanner Y is both more accurate and more precise.","Scanner X is more precise but Scanner Y is more accurate."],"contentHash":"fe7f11c200ab62c853feae61dbe2eef5165685a99e7c1217b6102cd15c951a1c"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:7c526657-fc73-4fa8-b348-f3afa1893de5', 'dm', 'practice', '7c526657-fc73-4fa8-b348-f3afa1893de5'::uuid, 'dm.evaluating_arguments', '{"id":"7c526657-fc73-4fa8-b348-f3afa1893de5","mode":"practice","parentId":"7c526657-fc73-4fa8-b348-f3afa1893de5","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Mandatory Cycle Helmets: Should cycle helmets be made legally mandatory for all cyclists in the UK to reduce cycling-related head injuries?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; peer-reviewed studies show helmet use reduces cycling-related head-injury risk by around 60%, and modelling based on UK cycling volumes suggests a mandatory law would prevent around 2,000 head injuries per year.","Yes; many cyclists are reckless and need to be forced to protect themselves.","No; helmets are uncomfortable and awkward to carry around when the cyclist is not on the bike.","No; individuals should have the freedom to decide whether to wear a helmet."],"contentHash":"9848e9befcc8efd9db1fc5563c274ea4832b7da1a94a552bd13f1ec86737162e"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:f382afc9-502c-4dcd-8fd6-12f9bd93b212', 'dm', 'practice', 'f382afc9-502c-4dcd-8fd6-12f9bd93b212'::uuid, 'dm.evaluating_arguments', '{"id":"f382afc9-502c-4dcd-8fd6-12f9bd93b212","mode":"practice","parentId":"f382afc9-502c-4dcd-8fd6-12f9bd93b212","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Mandatory First Aid Training: Should workplace first aid training be made mandatory for all UK employees to reduce the severity of workplace injuries?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; many employees report feeling more confident at work after completing first aid training.","Yes; a 2023 HSE analysis of UK workplaces found that sites with trained first aiders saw 30% fewer injuries escalate to hospital admission, directly reducing injury severity.","No; some industries rarely see serious workplace injuries, making the training redundant for those workers.","No; mandatory training would take time away from productive work tasks for every employee."],"contentHash":"1877fea564689f7b19f8b27b632e0c1528427e8590bd43384b63542314b548cb"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:a30e127b-01bc-4ebb-8129-a94857efd20e', 'dm', 'practice', 'a30e127b-01bc-4ebb-8129-a94857efd20e'::uuid, 'dm.evaluating_arguments', '{"id":"a30e127b-01bc-4ebb-8129-a94857efd20e","mode":"practice","parentId":"a30e127b-01bc-4ebb-8129-a94857efd20e","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Mandatory Flu Vaccinations: Should all hospital staff be required to receive annual flu vaccinations to reduce patient infection rates?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; a trial across three UK teaching hospitals found that wards with over 90 per cent staff vaccination recorded 35 per cent fewer patient flu cases than wards below 70 per cent.","Yes; most nurses already feel morally obliged to protect their patients.","No; mandating vaccinations removes individual staff choice.","No; some staff experience side effects that limit their working availability."],"contentHash":"4796bd3058656cb378fe44f4192123c934aaf0686dd0b1d6182f79ca3e9c50ba"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
