INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:34903a69-3f0a-4784-8306-f7135d92449b', 'dm', 'practice', '34903a69-3f0a-4784-8306-f7135d92449b'::uuid, 'dm.evaluating_arguments', '{"id":"34903a69-3f0a-4784-8306-f7135d92449b","mode":"practice","parentId":"34903a69-3f0a-4784-8306-f7135d92449b","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Prescription Charges for Over-60s: Should NHS prescription charges be abolished for all adults over the age of 60 to improve long-term health outcomes in this age group?","difficulty":"hard","format":"multiple_choice","answer":"B","options":["Yes; pharmacists report that older patients frequently ask for cheaper alternatives to prescribed medicines.","Yes; a 2024 health-economics study found that in OECD countries where prescription charges were abolished for over-60s, hospital admissions in that age group fell by 12%, directly improving long-term health outcomes.","No; adults over 60 are not the age group with the poorest long-term health outcomes in the UK.","No; abolishing charges would reduce NHS funding available for other essential services."],"contentHash":"6722cb7d582129473536b7a01695555054f0278ed415b06adb0ddac85fe312ba"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
