INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:5813cd78-68ab-4943-8c8b-654b8c9028bd', 'dm', 'practice', '5813cd78-68ab-4943-8c8b-654b8c9028bd'::uuid, 'dm.evaluating_arguments', '{"id":"5813cd78-68ab-4943-8c8b-654b8c9028bd","mode":"practice","parentId":"5813cd78-68ab-4943-8c8b-654b8c9028bd","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Single-Use Coffee Cup Ban: Should single-use coffee cups be banned in UK cafés to reduce landfill waste?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; Environment Agency audits estimate that single-use coffee cups account for roughly 2.5 billion items reaching UK landfill annually, and switching cafés to reusable cups would eliminate this stream directly.","Yes; many customers say ceramic cups feel nicer to drink from.","No; some small cafés would struggle with the washing-up costs and staffing needed for reusable cups.","No; the government should focus on bigger sources of landfill rather than coffee cups."],"contentHash":"b04940df5f12671581be4467fcd7eadf75793cb16689b42982608fc525bae73f"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
