INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:0cde9322-2c8e-4f63-b340-98b2f918c2a6', 'dm', 'practice', '0cde9322-2c8e-4f63-b340-98b2f918c2a6'::uuid, 'dm.evaluating_arguments', '{"id":"0cde9322-2c8e-4f63-b340-98b2f918c2a6","mode":"practice","parentId":"0cde9322-2c8e-4f63-b340-98b2f918c2a6","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Sugar Tax on Snacks: Should the government extend the sugar tax from soft drinks to all packaged snack foods to reduce childhood obesity?","difficulty":"hard","format":"multiple_choice","answer":"B","options":["Yes; households with young children already buy fewer sugary soft drinks since the 2018 tax, so extending it will make them buy fewer snacks too.","Yes; data from the UK soft drink levy shows a 10% reduction in sugar consumption among children since 2018, and NHS modelling predicts a similar tax on snacks would cut childhood obesity rates by 5–7% over ten years.","No; food manufacturers would simply reformulate products to avoid the tax, so the tax would collect little revenue.","No; childhood obesity is caused by low physical activity, not by diet."],"contentHash":"d64223c73cbc0c42c4a9e46fc9ccbd2701ddb689458b0da8db54b8400fb8a984"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:9c256236-770a-45db-8c48-165262a663f1', 'dm', 'practice', '9c256236-770a-45db-8c48-165262a663f1'::uuid, 'dm.evaluating_arguments', '{"id":"9c256236-770a-45db-8c48-165262a663f1","mode":"practice","parentId":"9c256236-770a-45db-8c48-165262a663f1","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Sugary Drinks Warning Labels: Should sugary soft drinks be required to carry prominent warning labels to reduce the rate of childhood obesity in the UK?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes; many parents are unsure whether fizzy drinks are unhealthy.","Yes; a 2022 trial of warning labels on sugary drinks in Chilean schools reduced total sugar consumption by primary-age children by 24%, directly lowering the leading dietary driver of childhood obesity.","No; warning labels might be ignored by shoppers who have always bought the same drinks.","No; childhood obesity also depends on exercise and genetics, which warning labels cannot change."],"contentHash":"a3628ba422c513e27ad72f9d43d6637e4ef2798196cbcd89c963a2d7deb1e7cf"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
