INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:practice:82b75804-ad91-4713-96d6-ee72b6349972', 'dm', 'practice', '82b75804-ad91-4713-96d6-ee72b6349972'::uuid, 'dm.evaluating_arguments', '{"id":"82b75804-ad91-4713-96d6-ee72b6349972","mode":"practice","parentId":"82b75804-ad91-4713-96d6-ee72b6349972","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Universal Basic Income Trial: Should the UK government run a national universal basic income trial to reduce the rate of in-work poverty?","difficulty":"hard","format":"multiple_choice","answer":"B","options":["Yes; everyone deserves a guaranteed income to live with dignity, regardless of their employment situation.","Yes; pilot trials in Finland, Spain and Wales each found a statistically significant decrease in recipient in-work poverty rates within 18 months, and a national UK trial would generate the UK-specific evidence needed to confirm whether the same effect would scale.","No; the cost of a national basic income trial would significantly increase taxes for working households across the UK.","No; some in-work poverty stems from regional housing costs, which a basic income alone would not address."],"contentHash":"d064832dc6aed2ba7bb4d4d3c55b91bdeaff60f26f91a74b7f1e47698eb90d8e"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
