INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:11b2edbd-4fc8-4da0-bd06-aa9ce3402591', 'dm', 'timed', '11b2edbd-4fc8-4da0-bd06-aa9ce3402591'::uuid, 'dm.evaluating_arguments', '{"id":"11b2edbd-4fc8-4da0-bd06-aa9ce3402591","mode":"timed","parentId":"11b2edbd-4fc8-4da0-bd06-aa9ce3402591","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Introducing Four-Day Work Weeks: Should companies be required to offer a four-day work week to all employees?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["No; some employees prefer working five days with shorter hours and value the routine, and a mandatory four-day week removes the flexibility for individual companies to accommodate diverse employee preferences.","Yes; trials in Iceland involving over 2,500 workers showed that productivity remained the same or improved with a four-day week, while employee wellbeing scores increased significantly, reducing sick leave by 20%.","No; requiring all companies to adopt a four-day week would disproportionately affect service industries such as healthcare and hospitality where continuous staffing is essential, potentially increasing costs by 25% due to the need for additional hires.","Yes; people work too much these days and deserve more rest."],"contentHash":"d7e4f6452a5eff4f415cbeee0bbbc679696c3e7115ab1cae4f3a3b490dd44ebd"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
