INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:01624ca5-f350-443f-8bd9-bdb28b4643f2', 'dm', 'timed', '01624ca5-f350-443f-8bd9-bdb28b4643f2'::uuid, 'dm.evaluating_arguments', '{"id":"01624ca5-f350-443f-8bd9-bdb28b4643f2","mode":"timed","parentId":"01624ca5-f350-443f-8bd9-bdb28b4643f2","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Taxing Ultra-Processed Foods: Should the government introduce a tax on ultra-processed foods?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; Mexico''s 2014 tax on sugar-sweetened beverages led to an 8% reduction in purchases within two years, and extending a similar approach to all ultra-processed foods could meaningfully reduce consumption and associated NHS costs from diet-related diseases.","No; a tax on ultra-processed foods would disproportionately affect low-income families who spend a larger proportion of their budget on food, effectively acting as a regressive tax that increases inequality without guaranteeing healthier dietary choices.","Yes; people eat too much junk food and something needs to change.","No; the government should not interfere with what people choose to eat."],"contentHash":"2580fe7163ca94bf40577e699c460bf5b4ec25ffcdf548d98b764c27dea7c4f9"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
