INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:627f93e9-2a35-45ea-bead-c9f654752e0e', 'dm', 'timed', '627f93e9-2a35-45ea-bead-c9f654752e0e'::uuid, 'dm.evaluating_arguments', '{"id":"627f93e9-2a35-45ea-bead-c9f654752e0e","mode":"timed","parentId":"627f93e9-2a35-45ea-bead-c9f654752e0e","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Compulsory Cooking Lessons: Should cooking be a compulsory subject in secondary schools to reduce obesity rates among young people?","difficulty":"normal","format":"multiple_choice","answer":"D","options":["No; schools already have overcrowded curricula and adding another compulsory subject would reduce time available for core academic subjects.","Yes; learning to cook is a valuable life skill that every young person should have.","No; obesity is primarily driven by socioeconomic factors such as income and access to affordable healthy food, and teaching cooking skills alone does not address these root causes, meaning compulsory lessons are unlikely to produce a significant reduction in youth obesity rates.","Yes; research from schools that have introduced compulsory cooking programmes shows that students who complete these courses make significantly healthier dietary choices and have lower rates of obesity compared to control groups, demonstrating a direct link between cooking education and reduced obesity."],"contentHash":"4009c398f0e4d6ae42a46ed2b23c3d5bb7ff5f0d615c8155689779e58a05ed2e"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
