INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:b9ab007b-4234-4a94-a024-e4a1cf7c4f9a', 'dm', 'timed', 'b9ab007b-4234-4a94-a024-e4a1cf7c4f9a'::uuid, 'dm.evaluating_arguments', '{"id":"b9ab007b-4234-4a94-a024-e4a1cf7c4f9a","mode":"timed","parentId":"b9ab007b-4234-4a94-a024-e4a1cf7c4f9a","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Mandatory Cycling Helmets: Should wearing cycling helmets be made mandatory for all cyclists to reduce cycling-related head injuries?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes; studies in regions that have introduced mandatory helmet laws have shown a measurable reduction in the severity and frequency of cycling-related head injuries, suggesting that a legal requirement would directly contribute to lowering head injury rates.","No; some cyclists find helmets uncomfortable and this could discourage people from cycling altogether, which would be bad for public health.","Yes; helmets are relatively inexpensive and widely available, so most people could easily buy one.","No; mandatory helmet laws in some jurisdictions have led to significant decreases in cycling participation without a proportionate reduction in head injury rates per cyclist, indicating the policy may not effectively achieve its goal of reducing head injuries."],"contentHash":"bcd25d9c2c56edbcfe200348682abf45da18cbc15260b1c7d0243e9ff5ff7fdf"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
