INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:28da56d9-e1ee-44be-a830-36bff05d2aca', 'dm', 'timed', '28da56d9-e1ee-44be-a830-36bff05d2aca'::uuid, 'dm.constraint_puzzles', '{"id":"28da56d9-e1ee-44be-a830-36bff05d2aca","mode":"timed","parentId":"28da56d9-e1ee-44be-a830-36bff05d2aca","primarySkillId":"dm.constraint_puzzles","secondarySkillIds":["dm.conditional_logic"],"confidence":"high","rationale":"Combines explicit constraints to solve Research Team Inference: Exactly three of Asha, Ben, Cora, Dina, Ewan and Farid are selected for a research team. Asha and Ben cannot both be selected. Exactly one of Cora…","difficulty":"hard","format":"multiple_choice","answer":"A","options":["Exactly one of Asha and Ben is selected.","Cora and Farid are always selected together.","Ewan is selected whenever Cora is selected.","Dina can be selected without Farid."],"contentHash":"3406c160da41f2e515dbddbce7c0be41e4d504c6df9b1eff5b2ae75dd9dec89c"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:b9daef8f-d433-4d21-9cbb-0c8870a7bde4', 'dm', 'timed', 'b9daef8f-d433-4d21-9cbb-0c8870a7bde4'::uuid, 'dm.constraint_puzzles', '{"id":"b9daef8f-d433-4d21-9cbb-0c8870a7bde4","mode":"timed","parentId":"b9daef8f-d433-4d21-9cbb-0c8870a7bde4","primarySkillId":"dm.constraint_puzzles","secondarySkillIds":[],"confidence":"high","rationale":"Combines explicit constraints to solve Sample Bench Allocation: Four samples J, K, L and M are divided between Red and Blue benches, with exactly two samples at each bench. J and K must be at the same bench. L…","difficulty":"normal","format":"multiple_choice","answer":"C","options":["J","K","M","Cannot be determined"],"contentHash":"b4c92f8c0f4b952c75be80bb329f2173976cd8d0d6f1e0245728034c3dd76a73"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:23eadbde-62f2-48af-ad4b-34dc103308fc', 'dm', 'timed', '23eadbde-62f2-48af-ad4b-34dc103308fc'::uuid, 'dm.evaluating_arguments', '{"id":"23eadbde-62f2-48af-ad4b-34dc103308fc","mode":"timed","parentId":"23eadbde-62f2-48af-ad4b-34dc103308fc","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Shared Workshop Induction: A shared workshop is deciding whether all new members should complete a short machine-safety induction before booking powered equipment. Which…","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes, because local incident records show that 14 of the last 18 machine near-misses involved new members who had not received the current safety briefing.","Yes, because the equipment manufacturer recommends induction before using comparable powered machines at shared facilities with a broadly similar range of tools.","No, because experienced members completed 2,300 powered-equipment bookings last year without a recorded injury under the workshop''s existing voluntary training system.","No, because a weekly induction would remove one bookable machine hour, and the affected period currently operates at 62% average capacity."],"contentHash":"f487f01606a06905d49279f29e5a1990cfd4683a1ca3efcb79286c99780a259f"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:baf8e627-683f-428a-b860-9d9e4f5275f1', 'dm', 'timed', 'baf8e627-683f-428a-b860-9d9e4f5275f1'::uuid, 'dm.constraint_puzzles', '{"id":"baf8e627-683f-428a-b860-9d9e4f5275f1","mode":"timed","parentId":"baf8e627-683f-428a-b860-9d9e4f5275f1","primarySkillId":"dm.constraint_puzzles","secondarySkillIds":["dm.conditional_logic"],"confidence":"high","rationale":"Combines explicit constraints to solve Six-Relay Control Panel: A control panel has six relays P, Q, R, S, T and U. Exactly three relays are on. P and Q always have the same state. R and S cannot both be on. T…","difficulty":"hard","format":"multiple_choice","answer":"C","options":["P, Q and R","P, Q and T","R, T and U","S, T and U"],"contentHash":"e48d5c8d2d4dc9f6a6319e4fb47e00cc55471a9d96baa54855b118a67a88203a"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:cbafbe28-de5f-40df-909d-e59f2b41190d', 'dm', 'timed', 'cbafbe28-de5f-40df-909d-e59f2b41190d'::uuid, 'dm.venn_sets', '{"id":"cbafbe28-de5f-40df-909d-e59f2b41190d","mode":"timed","parentId":"cbafbe28-de5f-40df-909d-e59f2b41190d","primarySkillId":"dm.venn_sets","secondarySkillIds":["dm.constraint_puzzles"],"confidence":"high","rationale":"Maps category combinations to diagram regions in Survey Route Flags: The diagram classifies survey routes by five flags, and every shown number is an exclusive-region count. The Priority-only count is hidden by ?.…","difficulty":"hard","format":"diagram_interpretation","answer":"C","options":["9","14","15","21"],"contentHash":"26f98c317c4bb8af364e1fcf875611075ae7a47c00d34473f0cd3c1c4b9707da"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:4a98e878-3ad1-4229-b71e-4420660ed1e1', 'dm', 'timed', '4a98e878-3ad1-4229-b71e-4420660ed1e1'::uuid, 'dm.evaluating_arguments', '{"id":"4a98e878-3ad1-4229-b71e-4420660ed1e1","mode":"timed","parentId":"4a98e878-3ad1-4229-b71e-4420660ed1e1","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Theatre Captioning Trial: A community theatre is deciding whether to trial captioned performances on two evenings. Which option gives the strongest argument?","difficulty":"normal","format":"multiple_choice","answer":"B","options":["Yes, because captioned performances at a theatre in another region sold 18% more tickets than its other shows and attracted many first-time visitors.","Yes, because local booking records show repeated access requests, and a two-evening trial would measure actual uptake before any permanent programming commitment.","No, because technicians estimate that each captioned performance requires 15 additional setup minutes and GBP 90 of extra staffing across the trial.","No, because every captionless performance last season sold out, with waiting lists recorded for three shows under the theatre''s existing booking arrangements."],"contentHash":"fa438061ce4472ccec5dbfb0d69a60c78dce10a1afeb35a88d9a006d7e65c36f"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:57a6d42b-09fd-4eb6-bd18-6ab009488896', 'dm', 'timed', '57a6d42b-09fd-4eb6-bd18-6ab009488896'::uuid, 'dm.venn_sets', '{"id":"57a6d42b-09fd-4eb6-bd18-6ab009488896","mode":"timed","parentId":"57a6d42b-09fd-4eb6-bd18-6ab009488896","primarySkillId":"dm.venn_sets","secondarySkillIds":[],"confidence":"high","rationale":"Maps category combinations to diagram regions in Trail Route Categories: A guide lists 28 trails. Eight are express but not scenic, seven are scenic but not express, four are both express and scenic, and nine are closed…","difficulty":"normal","format":"diagram_selection","answer":"A","options":["A","B","C","D"],"contentHash":"ab672b71f4fb9f4384f94659e42c44221361897dc3c0a27d93e7068b49d4aff9"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:7555bf10-b697-4545-879b-6dd33a740044', 'dm', 'timed', '7555bf10-b697-4545-879b-6dd33a740044'::uuid, 'dm.evaluating_arguments', '{"id":"7555bf10-b697-4545-879b-6dd33a740044","mode":"timed","parentId":"7555bf10-b697-4545-879b-6dd33a740044","primarySkillId":"dm.evaluating_arguments","secondarySkillIds":[],"confidence":"high","rationale":"Compares the relevance and evidential support of arguments about Wayfinding Sign Proposal: A town is deciding whether to replace faded pedestrian wayfinding signs. Which option gives the strongest argument?","difficulty":"normal","format":"multiple_choice","answer":"A","options":["Yes, because a local audit found 38% of sampled signs unreadable at the required distance, directly measuring the failure replacement is intended to solve.","Yes, because 620 visitors rated the proposed colour scheme highly after viewing mock-ups, with similar preferences reported across every surveyed age group.","No, because a contractor estimated repainting would cost 32% less than replacement and could be completed two weeks sooner than installing new signs.","No, because replacement would close two footpaths for one weekday each and create temporary detours averaging 180 metres for affected pedestrians."],"contentHash":"6e2946baccae1ebaaf786febaa8cc0eaaa9a5e9b70fcb14a7aeb2a6866ffbbde"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('dm:timed:74a98d3e-61f3-471e-b226-a85b9dbaf580', 'dm', 'timed', '74a98d3e-61f3-471e-b226-a85b9dbaf580'::uuid, 'dm.syllogisms', '{"id":"74a98d3e-61f3-471e-b226-a85b9dbaf580","mode":"timed","parentId":"74a98d3e-61f3-471e-b226-a85b9dbaf580","primarySkillId":"dm.syllogisms","secondarySkillIds":[],"confidence":"high","rationale":"Checks quantified category relationships in Workshop Badge Logic: At a fictional workshop: all mentor badges are green; some green badges are magnetic; no magnetic badge is paper; every visitor badge is paper;…","difficulty":"normal","format":"yes_no_statements","answer":null,"statementAnswers":["Yes","Yes","No","Yes","No"],"contentHash":"123bf43e9b22eb5a116ebbe979099d480c020933326071b29f2c48f646d02410"}'::jsonb, 1, 'dm-sync-20261013154351') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.data_interpretation', 'qr', '{"id":"qr.data_interpretation","label":"Reading and comparing data","description":"Select relevant values, compare groups, find missing totals and recognise when information is insufficient.","lessonRoute":"LearnQRLesson","lessonId":"table-questions","tip":"Read the row, column, axis and unit before calculating. Check that the information really supports an answer."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.percentage_change', 'qr', '{"id":"qr.percentage_change","label":"Percentage change","description":"Calculate increases, decreases, percentage-point gaps, reverse changes and successive percentage changes.","lessonRoute":"LearnQRLesson","lessonId":"percentages","tip":"Identify the original value. For percentage change, divide the change by that original value; multiply successive changes rather than adding them."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.fractions_percentages', 'qr', '{"id":"qr.fractions_percentages","label":"Fractions and percentage shares","description":"Find a fraction or percentage of a quantity, recover a whole from a known share and compare parts with the right whole.","lessonRoute":"LearnQRLesson","lessonId":"fractions-decimals","tip":"Write down which quantity represents the whole before dividing. Keep part-of-total percentages separate from percentage changes."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.ratio_proportion', 'qr', '{"id":"qr.ratio_proportion","label":"Ratios and proportion","description":"Simplify and compare ratios, divide quantities into parts and scale recipes, populations or material requirements.","lessonRoute":"LearnQRLesson","lessonId":"ratios-proportions","tip":"Find one part or one unit first, then scale. For an area scale, square the length scale."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.speed_rates', 'qr', '{"id":"qr.speed_rates","label":"Speed, rates and density","description":"Use quantities per unit, combine work or flow rates and calculate speed from total distance and total time.","lessonRoute":"LearnQRLesson","lessonId":"speed-rates","tip":"Write the rate with its units, then multiply or divide. For a combined speed, use total distance divided by total time."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.unit_conversion', 'qr', '{"id":"qr.unit_conversion","label":"Units and conversions","description":"Convert time, length, mass, volume, currency units and compound units consistently.","lessonRoute":"LearnQRLesson","lessonId":"units-conversions","tip":"Convert to matching units before calculating. Minutes are fractions of 60, and squared or cubed units need squared or cubed conversion factors."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.averages_range', 'qr', '{"id":"qr.averages_range","label":"Averages and spread","description":"Calculate means, weighted means, medians and ranges, and recover missing values from a mean.","lessonRoute":"LearnQRLesson","lessonId":"averages-range","tip":"Check whether every value has equal weight. For a missing value, recover the total from mean × count first."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.geometry', 'qr', '{"id":"qr.geometry","label":"Geometry and measurement","description":"Find area, perimeter, surface area and volume, including composite shapes and scale models.","lessonRoute":"LearnQRLesson","lessonId":"geometry","tip":"Sketch the relevant dimensions. Separate area from perimeter, and use radius rather than diameter in circle formulas."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.formula_algebra', 'qr', '{"id":"qr.formula_algebra","label":"Formulas and algebra","description":"Substitute into given formulas, apply caps or inequalities and rearrange equations to find an unknown.","lessonRoute":"LearnQRLesson","lessonId":"algebra","tip":"Write the formula before entering numbers. When working backwards, undo operations in reverse order."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.costs_budgets', 'qr', '{"id":"qr.costs_budgets","label":"Costs, revenue and pricing bands","description":"Combine fees, revenue and costs, apply pricing bands and compare complete costs or budgets.","lessonRoute":"LearnQRLesson","lessonId":"progressive-rates","tip":"List each charge separately. Apply a band only to the amount inside it, then include fixed charges and the stated tax or discount."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('qr.routes_time', 'qr', '{"id":"qr.routes_time","label":"Routes and elapsed time","description":"Compare connected routes, add journey stages and breaks, and calculate elapsed or arrival times.","lessonRoute":"LearnQRLesson","lessonId":"word-problems","tip":"List each journey stage and each break. Check route connections and count gaps between events carefully."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:93685217-d6c0-4bae-9d96-430c256e7868', 'qr', 'practice', '93685217-d6c0-4bae-9d96-430c256e7868'::uuid, 'qr.data_interpretation', '{"id":"93685217-d6c0-4bae-9d96-430c256e7868","mode":"practice","parentId":"4f306801-24c7-45e4-91a5-b8a32e0383f8","primarySkillId":"qr.data_interpretation","secondarySkillIds":[],"confidence":"high","rationale":"Reading and comparing data: Sum the 2024 bars: 180 + 160 + 140 + 220 + 120 = 820.","difficulty":"hard","format":"bar_chart","answer":"C","options":[{"label":"A","text":"30"},{"label":"B","text":"55"},{"label":"C","text":"75"},{"label":"D","text":"85"},{"label":"E","text":"95"}],"contentHash":"935745e65701adc48ed6851a6115746275c573287eb4f24290581da5411a7017"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:9b4d813e-1185-4855-9e6b-66f6e7f28b28', 'qr', 'practice', '9b4d813e-1185-4855-9e6b-66f6e7f28b28'::uuid, 'qr.percentage_change', '{"id":"9b4d813e-1185-4855-9e6b-66f6e7f28b28","mode":"practice","parentId":"4f306801-24c7-45e4-91a5-b8a32e0383f8","primarySkillId":"qr.percentage_change","secondarySkillIds":[],"confidence":"high","rationale":"Percentage change: Percentage change = (new − old) ÷ old × 100, using the 2024 value as the base.","difficulty":"hard","format":"bar_chart","answer":"C","options":[{"label":"A","text":"14.3%"},{"label":"B","text":"15.0%"},{"label":"C","text":"16.7%"},{"label":"D","text":"30.0%"},{"label":"E","text":"85.7%"}],"contentHash":"d052ff2a47f16e057ff95355ce30f4c5d288c2a04026feb4ca401e73ece413b3"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:0cd2dbfb-cd45-494a-bf96-2dc351454033', 'qr', 'practice', '0cd2dbfb-cd45-494a-bf96-2dc351454033'::uuid, 'qr.percentage_change', '{"id":"0cd2dbfb-cd45-494a-bf96-2dc351454033","mode":"practice","parentId":"4f306801-24c7-45e4-91a5-b8a32e0383f8","primarySkillId":"qr.percentage_change","secondarySkillIds":[],"confidence":"high","rationale":"Percentage change: 2024 total = 180 + 160 + 140 + 220 + 120 = 820.","difficulty":"hard","format":"bar_chart","answer":"C","options":[{"label":"A","text":"8.4%"},{"label":"B","text":"8.5%"},{"label":"C","text":"9.1%"},{"label":"D","text":"9.4%"},{"label":"E","text":"10.0%"}],"contentHash":"8452747f40c1c7ba1e9ca093c36e7d58ea99fb61d2ee49be09c2de29f4d65686"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
