INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:cdab715d-d2c1-4c4d-8b65-b501758b795e', 'qr', 'practice', 'cdab715d-d2c1-4c4d-8b65-b501758b795e'::uuid, 'qr.geometry', '{"id":"cdab715d-d2c1-4c4d-8b65-b501758b795e","mode":"practice","parentId":"12f0d469-4c64-48cd-ad0b-372de990619c","primarySkillId":"qr.geometry","secondarySkillIds":[],"confidence":"high","rationale":"Geometry and measurement: Outer rectangle area = 12 × 8 = 96 m². Notch area = 4 × 3 = 12 m². Wall area = 96 − 12 = 84 m². The answer is 84 m².","difficulty":"normal","format":"geometry_diagram","answer":"C","options":[{"label":"A","text":"72 m²"},{"label":"B","text":"80 m²"},{"label":"C","text":"84 m²"},{"label":"D","text":"88 m²"},{"label":"E","text":"96 m²"}],"contentHash":"fb603283e57ed140ac2cc107f050b0a62bd33f8bda10fc7392b84cc071bacb29"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
