INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:2d5256ec-bd99-4d9e-a097-0b39453c5fef', 'qr', 'practice', '2d5256ec-bd99-4d9e-a097-0b39453c5fef'::uuid, 'qr.data_interpretation', '{"id":"2d5256ec-bd99-4d9e-a097-0b39453c5fef","mode":"practice","parentId":"606a30ac-635d-42cd-8322-45b56d5e880c","primarySkillId":"qr.data_interpretation","secondarySkillIds":[],"confidence":"high","rationale":"Reading and comparing data: The x-axis is in £000s, so £10,000 corresponds to an x-value of 10. Count the labelled points with an x-value of 10 or greater: Fern (15), Glen (18), Holt (22). That gives 3 stores. The answer is 3.","difficulty":"normal","format":"scatter_plot","answer":"C","options":[{"label":"A","text":"1"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"},{"label":"E","text":"5"}],"contentHash":"91ae30ce6833f51a7cc753762d6646b22dac77b02ec12a4ef1e106e63ddcac2a"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:9ab7485a-7deb-4a1a-b74d-eb31896ba9d0', 'qr', 'practice', '9ab7485a-7deb-4a1a-b74d-eb31896ba9d0'::uuid, 'qr.costs_budgets', '{"id":"9ab7485a-7deb-4a1a-b74d-eb31896ba9d0","mode":"practice","parentId":"d80f4258-ca13-4c2d-a0fd-860165fb030f","primarySkillId":"qr.costs_budgets","secondarySkillIds":[],"confidence":"high","rationale":"Costs, revenue and pricing bands: Basic cost = £180 + (50 × £6.40) + £95 = £180 + £320 + £95 = £595. The answer is £595.","difficulty":"normal","format":"multi","answer":"C","options":[{"label":"A","text":"£560"},{"label":"B","text":"£575"},{"label":"C","text":"£595"},{"label":"D","text":"£615"},{"label":"E","text":"£690"}],"contentHash":"26f62e7bc4752d9226386b7825f4c61588a19d026cbe804f3e941b3b9fae1bc4"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:612708aa-2ae6-4b75-af6f-501349202355', 'qr', 'practice', '612708aa-2ae6-4b75-af6f-501349202355'::uuid, 'qr.costs_budgets', '{"id":"612708aa-2ae6-4b75-af6f-501349202355","mode":"practice","parentId":"d80f4258-ca13-4c2d-a0fd-860165fb030f","primarySkillId":"qr.costs_budgets","secondarySkillIds":["qr.percentage_change"],"confidence":"high","rationale":"Costs, revenue and pricing bands: Before VAT = £120 + (80 × £7.20) + £60 = £756. Including VAT = £756 × 1.20 = £907.20. The answer is £907.20.","difficulty":"normal","format":"multi","answer":"D","options":[{"label":"A","text":"£756.00"},{"label":"B","text":"£847.20"},{"label":"C","text":"£882.00"},{"label":"D","text":"£907.20"},{"label":"E","text":"£921.60"}],"contentHash":"3319fa532defe82c322d0ffb23c7489bd4bbc679c3586cbbb9101681088c6291"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:2bd3e77f-2a01-46aa-8c45-329af7ac40bc', 'qr', 'practice', '2bd3e77f-2a01-46aa-8c45-329af7ac40bc'::uuid, 'qr.formula_algebra', '{"id":"2bd3e77f-2a01-46aa-8c45-329af7ac40bc","mode":"practice","parentId":"d80f4258-ca13-4c2d-a0fd-860165fb030f","primarySkillId":"qr.formula_algebra","secondarySkillIds":["qr.costs_budgets"],"confidence":"high","rationale":"Formulas and algebra: Basic = £275 + £6.40h and Rapid = £390 + £5.80h. Rapid is cheaper when 390 + 5.80h < 275 + 6.40h, so 115 < 0.60h and h > 191.666.... The minimum whole area is 192 ha. The answer is 192 ha.","difficulty":"hard","format":"multi","answer":"C","options":[{"label":"A","text":"190 ha"},{"label":"B","text":"191 ha"},{"label":"C","text":"192 ha"},{"label":"D","text":"193 ha"},{"label":"E","text":"195 ha"}],"contentHash":"e083df2fdcc3cbb284f28bf04a77f6a2317bc089a55afa3e80e5bf17844e3d22"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
