INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:7ea3d380-968d-4b36-a0d5-2710706f699d', 'qr', 'practice', '7ea3d380-968d-4b36-a0d5-2710706f699d'::uuid, 'qr.fractions_percentages', '{"id":"7ea3d380-968d-4b36-a0d5-2710706f699d","mode":"practice","parentId":"293d285d-8561-4d8b-a796-d8e92776859e","primarySkillId":"qr.fractions_percentages","secondarySkillIds":[],"confidence":"high","rationale":"Fractions and percentage shares: The 75% target applied to the Cat 1 total = 0.75 × 300 = 225 calls within 7 minutes.","difficulty":"hard","format":"table","answer":"B","options":[{"label":"A","text":"10"},{"label":"B","text":"15"},{"label":"C","text":"20"},{"label":"D","text":"25"},{"label":"E","text":"30"}],"contentHash":"be362165e2cb815c8b0e21e898eb71209ec745602199f890bb803f45cec96428"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:90deaa71-8bc1-463c-a7ec-dd60533fa7ad', 'qr', 'practice', '90deaa71-8bc1-463c-a7ec-dd60533fa7ad'::uuid, 'qr.routes_time', '{"id":"90deaa71-8bc1-463c-a7ec-dd60533fa7ad","mode":"practice","parentId":"2d4df775-4e17-4dbc-a857-1aba3e7c4491","primarySkillId":"qr.routes_time","secondarySkillIds":[],"confidence":"high","rationale":"Routes and elapsed time: The direct Camp–Wadi path is 5.2 km each way. Round trip = 2 × 5.2 = 10.4 km. The answer is 10.4 km.","difficulty":"normal","format":"network_diagram","answer":"D","options":[{"label":"A","text":"5.2 km"},{"label":"B","text":"8.1 km"},{"label":"C","text":"9.6 km"},{"label":"D","text":"10.4 km"},{"label":"E","text":"11.7 km"}],"contentHash":"58404879d5de8a28fb2a514960ee91082f9b0ef8bbf88d80b0001a5c2ee0118d"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:ef6f8743-f59a-42d7-96ca-8eb86f7d8e7b', 'qr', 'practice', 'ef6f8743-f59a-42d7-96ca-8eb86f7d8e7b'::uuid, 'qr.percentage_change', '{"id":"ef6f8743-f59a-42d7-96ca-8eb86f7d8e7b","mode":"practice","parentId":"2d4df775-4e17-4dbc-a857-1aba3e7c4491","primarySkillId":"qr.percentage_change","secondarySkillIds":["qr.routes_time"],"confidence":"high","rationale":"Percentage change: The added detour is 25% of 3.6 km: 0.25 × 3.6 = 0.9 km, so Ridge–Tell becomes 4.5 km. Revised route distance = 4.8 + 4.5 + 4.1 = 13.4 km. No rounding is needed. The answer is 13.4 km.","difficulty":"normal","format":"network_diagram","answer":"D","options":[{"label":"A","text":"12.5 km"},{"label":"B","text":"12.9 km"},{"label":"C","text":"13.0 km"},{"label":"D","text":"13.4 km"},{"label":"E","text":"14.3 km"}],"contentHash":"df18269d127d6f3dd3032e33bd48a857c79bca21227961daf2d5b7c59e60ac3e"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
