INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:d72a0f08-7461-46f8-b157-ea62e76a5b37', 'qr', 'practice', 'd72a0f08-7461-46f8-b157-ea62e76a5b37'::uuid, 'qr.fractions_percentages', '{"id":"d72a0f08-7461-46f8-b157-ea62e76a5b37","mode":"practice","parentId":"c3d65128-63bc-473c-af12-a9716f3a9890","primarySkillId":"qr.fractions_percentages","secondarySkillIds":[],"confidence":"high","rationale":"Fractions and percentage shares: Indigo mixture volume = 18 + 102 = 120 L. Concentrate percentage = 18 / 120 × 100 = 15%. The answer is 15%.","difficulty":"normal","format":"table","answer":"B","options":[{"label":"A","text":"12%"},{"label":"B","text":"15%"},{"label":"C","text":"17.6%"},{"label":"D","text":"18%"},{"label":"E","text":"20%"}],"contentHash":"6cfdd980d66165de892c1421bcc31302ed2045e30a5a3f3c323233ab0c40e89f"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
