INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:01868a83-2c89-492a-98a4-e077a8a102e0', 'qr', 'practice', '01868a83-2c89-492a-98a4-e077a8a102e0'::uuid, 'qr.fractions_percentages', '{"id":"01868a83-2c89-492a-98a4-e077a8a102e0","mode":"practice","parentId":"c3d65128-63bc-473c-af12-a9716f3a9890","primarySkillId":"qr.fractions_percentages","secondarySkillIds":[],"confidence":"high","rationale":"Fractions and percentage shares: Existing defects = 12 + 9 + 15 + 7 = 43 and existing panels = 600 + 450 + 750 + 525 = 2,325. Including the new work gives 45 defects among 2,500 panels. Percentage = 45 / 2,500 × 100 = 1.8%. The answer is 1.8%.","difficulty":"hard","format":"table","answer":"C","options":[{"label":"A","text":"1.6%"},{"label":"B","text":"1.7%"},{"label":"C","text":"1.8%"},{"label":"D","text":"1.9%"},{"label":"E","text":"2.0%"}],"contentHash":"c52594c1a1418ffde6b2fa7238037fe2181a885b8479d74518149f44c98afb4a"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:practice:2c8c2fd3-2bfd-46a6-9683-31ab0c0b03b1', 'qr', 'practice', '2c8c2fd3-2bfd-46a6-9683-31ab0c0b03b1'::uuid, 'qr.fractions_percentages', '{"id":"2c8c2fd3-2bfd-46a6-9683-31ab0c0b03b1","mode":"practice","parentId":"9cf5099f-1160-432b-9d85-6d966830f398","primarySkillId":"qr.fractions_percentages","secondarySkillIds":[],"confidence":"high","rationale":"Fractions and percentage shares: The charge rises from 20% to 80%, a gain of 60 percentage points. Stored energy added = 0.60 x 0.75 kWh = 0.45 kWh. The answer is 0.45 kWh.","difficulty":"normal","format":"text","answer":"C","options":[{"label":"A","text":"0.30 kWh"},{"label":"B","text":"0.375 kWh"},{"label":"C","text":"0.45 kWh"},{"label":"D","text":"0.50 kWh"},{"label":"E","text":"0.60 kWh"}],"contentHash":"5177032c10b0c53f3026ee73a4988d116ba991980e293c21170c6d4f7ce961c6"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
