INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:62436299-2d20-49e1-91a6-9cae566c1098', 'qr', 'timed', '62436299-2d20-49e1-91a6-9cae566c1098'::uuid, 'qr.data_interpretation', '{"id":"62436299-2d20-49e1-91a6-9cae566c1098","mode":"timed","parentId":"189f0537-9ec8-4eea-a36d-53d57b28a8d5","primarySkillId":"qr.data_interpretation","secondarySkillIds":[],"confidence":"high","rationale":"Reading and comparing data: In Cycle 1, Sensor A deviated by 2 µm and Sensor B by 7 µm. The difference is 7 − 2 = 5 µm. The answer is 5 µm.","difficulty":"normal","format":"line_graph","answer":"D","options":[{"label":"A","text":"2 µm"},{"label":"B","text":"3 µm"},{"label":"C","text":"4 µm"},{"label":"D","text":"5 µm"},{"label":"E","text":"7 µm"}],"contentHash":"ec4f6af1b7714326094cd76763d88eb7b44fb4878f60e5fed3812de45588d047"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
