INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:91e58952-653a-48d8-9e63-19c58953a54f', 'qr', 'timed', '91e58952-653a-48d8-9e63-19c58953a54f'::uuid, 'qr.ratio_proportion', '{"id":"91e58952-653a-48d8-9e63-19c58953a54f","mode":"timed","parentId":"013e9928-a525-422a-befa-a400615c4545","primarySkillId":"qr.ratio_proportion","secondarySkillIds":[],"confidence":"high","rationale":"Ratios and proportion: Flights required = 54 hectares ÷ 9 hectares per flight = 6 flights. The answer is 6.","difficulty":"normal","format":"text","answer":"C","options":[{"label":"A","text":"4"},{"label":"B","text":"5"},{"label":"C","text":"6"},{"label":"D","text":"7"},{"label":"E","text":"8"}],"contentHash":"8b4d5ee69659a47a7ebc49299463701c478c9111282dfaf4ad21ba28667b5283"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
