INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:44bc31be-a226-4121-aa51-9534c1113c6a', 'qr', 'timed', '44bc31be-a226-4121-aa51-9534c1113c6a'::uuid, 'qr.speed_rates', '{"id":"44bc31be-a226-4121-aa51-9534c1113c6a","mode":"timed","parentId":"013e9928-a525-422a-befa-a400615c4545","primarySkillId":"qr.speed_rates","secondarySkillIds":["qr.fractions_percentages","qr.unit_conversion"],"confidence":"medium","rationale":"Speed, rates and density: Original data = 54 × 1.8 = 97.2 GB. Compressed data = 97.2 × 0.40 = 38.88 GB. Upload time = 38.88 ÷ 12 = 3.24 hours = 3 hours 14.4 minutes, which rounds to 3 hours 14 minutes. The answer is 3 hours 14 minutes.","difficulty":"normal","format":"text","answer":"C","options":[{"label":"A","text":"2 hours 42 minutes"},{"label":"B","text":"3 hours"},{"label":"C","text":"3 hours 14 minutes"},{"label":"D","text":"3 hours 24 minutes"},{"label":"E","text":"8 hours 6 minutes"}],"contentHash":"37b96406ee6c8c360db67ac0224a6e242b0ff7f740d4a981fb33fc0e9ce7d5bb"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
