INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:48529b87-35de-45b0-b778-62bd80e4d2f2', 'qr', 'timed', '48529b87-35de-45b0-b778-62bd80e4d2f2'::uuid, 'qr.speed_rates', '{"id":"48529b87-35de-45b0-b778-62bd80e4d2f2","mode":"timed","parentId":"7424c66c-e1d1-4b05-b67f-f2722fce1409","primarySkillId":"qr.speed_rates","secondarySkillIds":[],"confidence":"high","rationale":"Speed, rates and density: Objects per minute are A: 18 ÷ 10 = 1.8; B: 24 ÷ 15 = 1.6; D: 35 ÷ 25 = 1.4; F: 46 ÷ 35 = 1.31; H: 55 ÷ 45 = 1.22. The greatest rate is 1.8 objects per minute at A. The answer is A.","difficulty":"normal","format":"scatter_plot","answer":"A","options":[{"label":"A","text":"A"},{"label":"B","text":"B"},{"label":"C","text":"D"},{"label":"D","text":"F"},{"label":"E","text":"H"}],"contentHash":"4676bd36128a290ab2dbc13ad294c6903d8bcc75f2c7e00d818812dbcb687f07"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:92a5a40e-179d-426e-a85a-a1ec243c1b4c', 'qr', 'timed', '92a5a40e-179d-426e-a85a-a1ec243c1b4c'::uuid, 'qr.speed_rates', '{"id":"92a5a40e-179d-426e-a85a-a1ec243c1b4c","mode":"timed","parentId":"7424c66c-e1d1-4b05-b67f-f2722fce1409","primarySkillId":"qr.speed_rates","secondarySkillIds":[],"confidence":"high","rationale":"Speed, rates and density: For exposures of at least 25 minutes, the rates are D: 35 ÷ 25 = 1.40, E: 38 ÷ 30 = 1.27, F: 46 ÷ 35 = 1.31, G: 44 ÷ 40 = 1.10 and H: 55 ÷ 45 = 1.22 objects per minute. Only D and F meet at least 1.3, giving 35 + 46 = 81…","difficulty":"normal","format":"scatter_plot","answer":"C","options":[{"label":"A","text":"73"},{"label":"B","text":"79"},{"label":"C","text":"81"},{"label":"D","text":"90"},{"label":"E","text":"136"}],"contentHash":"b7292376b75a1112722b83e962f3bdc20ed2ac8e99f9cb06aa457f4c78a35217"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:9c8ab0cf-c9b3-4706-ba7a-b5666c678806', 'qr', 'timed', '9c8ab0cf-c9b3-4706-ba7a-b5666c678806'::uuid, 'qr.geometry', '{"id":"9c8ab0cf-c9b3-4706-ba7a-b5666c678806","mode":"timed","parentId":"9a400fc4-1ab9-4083-a336-b0cbb2a48b20","primarySkillId":"qr.geometry","secondarySkillIds":[],"confidence":"high","rationale":"Geometry and measurement: Area of a trapezium = ½ × (sum of parallel sides) × perpendicular height. Therefore, area = ½ × (8 + 12) × 5 = 50 m². The answer is 50 m².","difficulty":"normal","format":"geometry_diagram","answer":"C","options":[{"label":"A","text":"40 m²"},{"label":"B","text":"45 m²"},{"label":"C","text":"50 m²"},{"label":"D","text":"60 m²"},{"label":"E","text":"100 m²"}],"contentHash":"b6ce38be247954c44491d1173e0342c3b659ff341430cd4605185fcb39a4de78"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:3679d80c-68ce-49de-855e-807eb87d25cf', 'qr', 'timed', '3679d80c-68ce-49de-855e-807eb87d25cf'::uuid, 'qr.geometry', '{"id":"3679d80c-68ce-49de-855e-807eb87d25cf","mode":"timed","parentId":"9a400fc4-1ab9-4083-a336-b0cbb2a48b20","primarySkillId":"qr.geometry","secondarySkillIds":[],"confidence":"high","rationale":"Geometry and measurement: Perimeter = 8 + 12 + 5.4 + 5.4 = 30.8 m. The answer is 30.8 m.","difficulty":"normal","format":"geometry_diagram","answer":"C","options":[{"label":"A","text":"25.4 m"},{"label":"B","text":"28.0 m"},{"label":"C","text":"30.8 m"},{"label":"D","text":"33.4 m"},{"label":"E","text":"35.8 m"}],"contentHash":"e8837b065e4def7042b7628d268884e4eec6d419924bf48e4aa00596ef43db49"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('qr:timed:ef456bbd-f649-4973-8582-d9b0701545e7', 'qr', 'timed', 'ef456bbd-f649-4973-8582-d9b0701545e7'::uuid, 'qr.geometry', '{"id":"ef456bbd-f649-4973-8582-d9b0701545e7","mode":"timed","parentId":"9a400fc4-1ab9-4083-a336-b0cbb2a48b20","primarySkillId":"qr.geometry","secondarySkillIds":["qr.ratio_proportion","qr.unit_conversion"],"confidence":"medium","rationale":"Geometry and measurement: The real area is 50 m² = 500,000 cm². A 1:25 length scale gives an area scale of 1:25² = 1:625. Model area = 500,000 ÷ 625 = 800 cm². The answer is 800 cm².","difficulty":"normal","format":"geometry_diagram","answer":"D","options":[{"label":"A","text":"80 cm²"},{"label":"B","text":"200 cm²"},{"label":"C","text":"500 cm²"},{"label":"D","text":"800 cm²"},{"label":"E","text":"2,000 cm²"}],"contentHash":"c5ef03b6d085c4ff3419e42494f18cc2dfcc6ef6a9b245ca4fa282b8d6cce537"}'::jsonb, 1, 'qr-sync-20261013154324') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.autonomy', 'sj', '{"id":"sj.autonomy","label":"Autonomy and consent","description":"Recognise informed decisions, capacity, consent and the right to refuse.","lessonRoute":"LearnSJLesson","lessonId":"capacity-consent","tip":"Check understanding and capacity, explain options, and respect the patient''s decision."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.confidentiality', 'sj', '{"id":"sj.confidentiality","label":"Confidentiality","description":"Protect personal information and choose appropriate information-sharing routes.","lessonRoute":"LearnSJLesson","lessonId":"confidentiality-privacy","tip":"Check who needs the information, whether sharing is authorised, and whether the setting is private."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.honesty', 'sj', '{"id":"sj.honesty","label":"Honesty and integrity","description":"Recognise accurate records, academic integrity and openness about mistakes.","lessonRoute":"LearnSJLesson","lessonId":"honesty-integrity","tip":"Look for truthful records and an open response to errors, even when honesty is uncomfortable."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.patient_safety', 'sj', '{"id":"sj.patient_safety","label":"Patient safety and safeguarding","description":"Identify immediate risks, prevent avoidable harm and recognise safeguarding concerns.","lessonRoute":"LearnSJLesson","lessonId":"patient-safety-first","tip":"Identify who could be harmed and whether action is needed before the situation continues."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.raising_concerns', 'sj', '{"id":"sj.raising_concerns","label":"Raising concerns","description":"Choose a timely, proportionate response and the right person to involve.","lessonRoute":"LearnSJLesson","lessonId":"escalation-seeking-help","tip":"Match the urgency and reporting route to the risk; do not let seniority prevent a concern being raised."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.role_limits', 'sj', '{"id":"sj.role_limits","label":"Role and competence","description":"Recognise personal limits, appropriate supervision and accountability.","lessonRoute":"LearnSJLesson","lessonId":"role-limits","tip":"Separate what you can do safely from what needs supervision or another professional."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.teamwork', 'sj', '{"id":"sj.teamwork","label":"Teamwork and reliability","description":"Coordinate tasks, share responsibility and maintain effective handovers.","lessonRoute":"LearnSJLesson","lessonId":"teamwork-professionalism","tip":"Agree who will act, communicate clearly, and follow through on the shared plan."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.communication', 'sj', '{"id":"sj.communication","label":"Communication and empathy","description":"Listen, respond sensitively and support accessible patient understanding.","lessonRoute":"LearnSJLesson","lessonId":"communication-empathy","tip":"Acknowledge the concern, ask what matters, and check that your explanation is understood."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.fairness', 'sj', '{"id":"sj.fairness","label":"Fairness and respect","description":"Recognise discrimination, dignity, inclusive treatment and fair process.","lessonRoute":"LearnSJLesson","lessonId":"colleague-behaviour","tip":"Consider the effect on others and distinguish respectful challenge from blame or public humiliation."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.boundaries', 'sj', '{"id":"sj.boundaries","label":"Boundaries and conflicts","description":"Maintain professional relationships and recognise conflicts of interest.","lessonRoute":"LearnSJLesson","lessonId":"boundaries-conflicts-interest","tip":"Identify personal benefits or relationships that could affect professional judgement."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_skills (id, section, metadata) VALUES ('sj.wellbeing', 'sj', '{"id":"sj.wellbeing","label":"Wellbeing and fitness to practise","description":"Recognise impairment, fatigue and support needs in yourself and colleagues.","lessonRoute":"LearnSJLesson","lessonId":"fitness-to-practise","tip":"Consider safe working and supportive help together, using the urgency described in the scenario."}'::jsonb) ON CONFLICT (id) DO UPDATE SET metadata = EXCLUDED.metadata;
INSERT INTO public.performance_question_tags (id, section, mode, question_id, primary_skill_id, metadata, taxonomy_version, corpus_run_id) VALUES ('sj:practice:048f5d5e-4fb4-4391-95a1-e3155f7d7e58', 'sj', 'practice', '048f5d5e-4fb4-4391-95a1-e3155f7d7e58'::uuid, 'sj.autonomy', '{"id":"048f5d5e-4fb4-4391-95a1-e3155f7d7e58","mode":"practice","parentId":"c23bf7bd-1691-44af-8e51-19203d95c00e","primarySkillId":"sj.autonomy","secondarySkillIds":[],"confidence":"high","rationale":"Tests autonomy and consent when judging: Tomas asks the partner to step outside and then asks the patient again, in private, whether she is ''completely sure'' she does not want blood, in case she would change her mind without her partner present.","difficulty":"normal","format":"appropriateness","answer":"Inappropriate, but not awful","options":["A very appropriate thing to do","Appropriate, but not ideal","Inappropriate, but not awful","A very inappropriate thing to do"],"labelSet":2,"contentHash":"b8cad9c5034941804bb2248f22bf32550abf38d91b9c9e7738f07217d577cf9b"}'::jsonb, 1, 'sj-sync-20261013154350') ON CONFLICT (section, mode, question_id) DO UPDATE SET primary_skill_id = EXCLUDED.primary_skill_id, metadata = EXCLUDED.metadata, taxonomy_version = EXCLUDED.taxonomy_version, corpus_run_id = EXCLUDED.corpus_run_id, reviewed_at = now();
